// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 보정
// 북잡이 · 전술가 · 부여술사 · 분대장 · 진법가
// 보정: 사냥당하는 쪽의 박자를 지킨다 — 이쪽보다 영리한 것들의 사냥터에서
// ==========================================

// ------------------------------------------
// 북잡이 · 자원 없음
// ------------------------------------------
kJob('drummer', 'S', [

{ at:'S', t:'어둠 — 둘이 뛰는 심장',
  x:`불을 다 껐다. 여기서 빛은 미끼다. 어둠 속에 다섯이 등을 붙이고 앉았다.<br><br>
    북잡이 귀는 어둠에서도 박을 센다. 다섯 심장이 다섯 박으로 뛴다. 겁먹은 박이다. 빠르다.<br>
    그 다섯 사이에 여섯째 박이 있다. 아주 느리다. 사람 심장은 저렇게 느리게 못 뛴다. 그리고 가까워진다. 한 박마다 반 걸음씩.<br><br>
    저것은 심장 소리를 듣고 온다. 빠른 심장부터.`,
  o:[
    { l:'① 제일 빠른 심장 옆에 붙어 손가락으로 느린 박을 짚어 준다.', k:'fix', dc:25, wake:1,
      ok:`제일 빠른 심장은 둘째 것이었다. 둘째 손목을 잡고 손가락으로 박을 짚었다. 톡. 톡. 사람이 잘 때 뛰는 빠르기로.<br><br>심장은 귀가 없어도 손끝 박을 따라온다. 둘째 박이 느려졌다. 셋째 것도, 넷째 것도. 손목에서 손목으로 옮겨 가며 다 짚었다. 다섯 박이 잠든 박이 됐다.<br>여섯째 박이 멈춰 섰다. 깨어 있는 심장이 없다. 먹을 것이 없는 어둠이다. 느린 박이 한참 제자리를 돌다가 멀어졌다.<br><br>북 없이 박을 옮긴 건 처음이다. 손가락 두 개면 심장도 북이 된다. 겁은 귀로 못 다스려도 맥으로는 다스려진다. 손끝이 그 길을 외웠다.`,
      ng:`둘째 손목을 짚는데 이쪽 심장이 먼저 빨라졌다. 여섯째 박이 어느새 등 뒤에 있었다.<br><br>짚는 손가락이 이쪽 박을 옮겼다. 둘째 심장이 더 빨라진다. 어둠 속에서 무엇이 길게 숨을 들이켰다. 맛을 보듯.<br>다섯이 벽을 더듬으며 달렸다. 여섯째 박이 한참 따라오다 끊겼다. 둘째는 그 뒤로 이쪽이 손을 잡으려 하면 움찔한다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 넷을 숨 참게 하고 제 심장만 남긴다.', k:'steady', dc:24,
      ok:`손짓으로 넷을 숨 참게 했다. 가슴을 눌러 심장까지 죽이라는 시늉. 넷이 웅크렸다.<br><br>이쪽 심장만 남았다. 일부러 느리게 뛰게 했다. 숨을 길게. 여섯째 박이 이쪽으로 왔다. 하나뿐인 박. 늙고 느린 박. 병든 먹잇감 소리다.<br>저것은 병든 것을 안 먹는다. 영리한 것들은 가려 먹는다. 느린 박 앞에서 한참 서 있다가 돌아갔다.`,
      ng:`넷은 참았는데 셋째 숨이 터졌다. 헉. 한 번.<br><br>여섯째 박이 단숨에 빨라졌다. 사냥의 박이다. 다섯이 흩어져 뛰었다. 어둠 속에서 셋째 어깨가 무언가에 쓸렸다.<br>다시 모였을 때 셋째 어깨가 네 줄로 찢어져 있었다. 스친 것만으로.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-30, spirit:-20 } },
    { l:'③ 느린 박이 오는 방향과 걸음 수를 세어 둔다.', k:'sense', dc:23,
      ok:`박과 박 사이를 셌다. 반 걸음에 한 박. 열두 박이면 여기다.<br><br>방향은 물 냄새 쪽. 낮게 깔려 온다. 네 발이다. 어깨가 바닥에 가깝다.<br>여덟 박째에 다섯을 반대쪽 틈으로 밀어 넣었다. 열두 박째에 방금 앉았던 자리에서 돌 갈리는 소리가 났다. 턱이 바닥을 긁는 소리였다.`,
      ng:`박을 세는데 박이 둘로 갈라졌다. 두 마리다. 양쪽에서 온다.<br><br>셈이 늦었다. 가운데로 뛰었다. 등 뒤에서 두 숨이 엇갈렸다. 서로 부딪치는 소리. 그 틈에 빠져나왔다.<br>하나였으면 물렸다. 둘이라 살았다. 그런 셈은 다시 하고 싶지 않다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'S', t:'긴 길 — 네 발의 박',
  x:`긴 길이다. 숨을 데가 없다. 걷는 수밖에 없다.<br><br>
    뒤에서 발소리가 따라온다. 네 발. 둥둥, 쉼, 둥둥. 네 발 짐승의 박은 두 쌍으로 온다.<br>
    박 간격으로 보폭이 나온다. 보폭으로 키가 나온다. 어깨가 이쪽 머리 위다.<br><br>
    따라오기만 한다. 거리를 안 좁힌다. 영리한 것은 지치기를 기다린다.`,
  o:[
    { l:'① 발소리로 저것의 걸음 수를 세어 쉼이 오는 자리를 읽는다.', k:'sense', dc:24,
      ok:`네 발의 박에도 쉼이 있다. 마흔 걸음에 한 번, 반 박. 발을 바꾸는 쉼이다.<br><br>그 쉼에는 저것이 못 뛴다. 디딤발이 비어 있으니. 마흔 걸음을 세고 쉼에 맞춰 다섯을 옆 틈으로 꺾었다.<br>등 뒤에서 디딤을 놓친 발이 바닥을 긁었다. 길게. 다시 박이 설 때쯤 다섯은 틈 깊이 들어와 있었다.`,
      ng:`마흔 걸음을 셌는데 쉼이 안 왔다. 쉰 걸음. 예순.<br><br>저것이 쉼을 숨겼다. 세는 걸 안다. 박을 고르게 눌러 걸었다. 세어지는 걸 아는 짐승은 처음이다.<br>꺾는 자리를 들켰다. 어깨 위로 바람이 지나갔다. 턱이 닫히는 소리가 귀 바로 뒤에서 났다. 목덜미에 침이 한 방울 떨어져 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 벽 틈에 다섯을 세우고 저것이 지나가는 박을 기다린다.', k:'hide', dc:25,
      doom:{ title:'틈을 보는 눈', what:'네 발의 것에게 발목을 물려 어둠 속으로 끌려갑니다', dc:19, sec:45,
        text:`틈에 다섯을 세웠다. 숨을 죽였다. 네 발의 박이 다가온다. 지나간다. 지나가는 줄 알았다.<br><br>박이 틈 앞에서 끊겼다. 쉼이 아니다. 멈춤이다. 어둠 속에서 콧김이 틈 안으로 들어온다. 더운 바람이 발끝을 훑는다.<br>맨 앞에 선 이쪽 발목에 무엇이 감겼다. 이빨이다. 아프지 않게 문다. 들어 올린다. 물건 집듯.<br><br>끌고 간다. 틈 밖으로. 박이 다시 시작된다. 네 발과, 끌리는 두 발.`,
        dieText:`틈 안의 넷은 박이 멀어지는 걸 끝까지 들었다. 네 발의 박. 둥둥, 쉼, 둥둥.<br><br>끌리는 소리는 중간에 그쳤다. 박만 남았다.<br>그 뒤로 넷은 긴 길에서 발소리를 들으면 걸음부터 센다. 세는 법은 북잡이가 가르쳐 줬다. 마흔까지 세는 동안 아무도 입을 안 연다.` },
      ok:`틈에 다섯을 세웠다. 숨을 죽였다. 네 발의 박이 다가온다.<br><br>틈 앞에서 박이 흐려졌다. 킁킁대는 숨. 이쪽은 발끝으로 바닥의 돌 하나를 길 안쪽으로 밀었다. 또르르. 작은 박 하나가 길을 굴러갔다.<br>네 발이 그 박을 쫓았다. 영리한 것도 구르는 소리는 못 참는다. 박이 멀어진 사이 틈 반대쪽으로 빠졌다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'쉬는 자리 — 숨의 지휘',
  x:`쉬어야 한다. 다리가 풀린 지 오래다. 그런데 이 어둠에서는 숨소리도 발자국이다.<br><br>
    다섯이 쉬면 다섯 숨이 제각각 돈다. 제각각인 숨은 멀리서 들으면 한 무리다. 수가 세어진다.<br>
    북잡이는 숨을 포갤 줄 안다. 다섯 숨을 한 숨으로. 한 숨은 한 마리다. 작은 한 마리.<br><br>
    문제는 겁이다. 겁먹은 숨은 포개지지 않는다.`,
  o:[
    { l:'① 손바닥을 천천히 올렸다 내리며 다섯 숨을 한 숨으로 포갠다.', k:'fix', dc:24, wake:1,
      ok:`손바닥을 들었다. 올리면 들이쉬고, 내리면 내쉰다. 소리 없는 지휘.<br><br>처음엔 셋만 따라왔다. 넷째는 숨이 짧아 반 박 늦는다. 넷째 눈을 보며 손을 조금 늦췄다. 다섯이 맞았다. 다섯 가슴이 같이 부풀고 같이 꺼진다.<br>멀리서 킁킁대던 숨이 한참 맴돌다 갔다. 한 마리 치고는 작고, 다섯 마리 치고는 고요했을 것이다. 셈이 안 맞는 먹잇감은 영리한 것일수록 피한다.<br><br>북채 없이 손바닥으로 다섯을 지휘했다. 박은 소리가 아니라 오르내림이다. 그걸 몸으로 안 밤이었다.`,
      ng:`손을 올리는데 넷째가 손 대신 어둠을 봤다. 숨이 어긋났다. 다섯 숨이 한 숨 반이 됐다.<br><br>한 숨 반은 이상한 수다. 멀리서 맴돌던 것이 다가왔다. 셈이 안 맞으면 피하는 것도 있고, 확인하러 오는 것도 있다. 이건 오는 쪽이었다.<br>쉬기를 포기하고 자리를 옮겼다. 두 번. 새벽에야 눈을 붙였다. 다들 꿈에서도 숨을 셌다고 했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 제일 겁먹은 하나를 품에 안고 등을 두드려 재운다.', k:'bond', dc:23,
      ok:`넷째를 끌어다 등을 맞대게 앉혔다. 손바닥으로 등을 두드렸다. 느리게. 둥. 둥.<br><br>등으로 듣는 박은 귀로 듣는 박보다 깊이 들어간다. 넷째 숨이 길어졌다. 잠들었다. 잠든 숨은 겁이 없다.<br>하나가 자니 둘이 자고, 둘이 자니 다 잤다. 이쪽만 깨어 등을 두드렸다. 밤새. 손목이 굳었지만 숨은 끝까지 하나였다.`,
      ng:`등을 두드리는데 넷째가 흠칫 깨며 소리를 질렀다. 짧게. 한 번.<br><br>어둠이 일제히 조용해졌다. 벌레 소리까지. 조용해지는 건 다들 숨는다는 뜻이다. 숨는 건 무엇이 온다는 뜻이다.<br>다섯이 밤새 번갈아 깼다. 아무것도 안 왔다. 안 온 것이 더 지치게 했다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'물방울 — 떨어지는 박 사이로',
  x:`천장에서 물이 떨어진다. 똑. 똑. 고른 박이다. 길은 그 밑을 지난다.<br><br>
    저 앞 어둠에 무엇이 엎드려 있다. 숨소리가 바닥에 깔려 있다. 잔다. 아마.<br>
    자는 것의 귀는 박이 깨우지 않는다. 박을 깨뜨리는 소리가 깨운다. 물방울 사이에 낀 발소리 같은 것.<br><br>
    물방울과 물방울 사이는 두 박. 두 박 안에 한 걸음씩.`,
  o:[
    { l:'① 물방울에 걸음을 묻어 한 사람씩 지나보낸다.', k:'fix', dc:24,
      ok:`첫째 손목을 잡고 박을 짚어 줬다. 똑, 걸음, 똑, 걸음. 물방울이 떨어지는 순간에 발이 바닥에 닿게.<br><br>같은 순간의 두 소리는 한 소리로 들린다. 첫째가 건넜다. 둘째, 셋째. 넷째는 박이 급해 한 번 어긋났다. 어긋난 발을 이쪽이 헛기침으로 덮었다. 물 떨어지는 소리와 같은 높이로.<br>다섯이 다 건넜다. 엎드린 숨은 끝까지 고르게 깔려 있었다.`,
      ng:`넷째 발이 물웅덩이를 밟았다. 첨벙. 물방울 소리와는 다른 소리.<br><br>엎드린 숨이 끊겼다. 깼다. 다섯이 그대로 굳었다. 어둠 속에서 큰 것이 몸을 뒤집는 소리가 났다. 벽이 조금 울렸다.<br>다시 잠들 때까지 반 시진을 선 채로 기다렸다. 무릎이 떨리는 사람 무릎을 손으로 눌러 가며.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 박을 안 믿고 저것의 숨이 깊어질 때만 움직인다.', k:'evade', dc:25,
      ok:`숨에도 박이 있다. 들숨 끝에 몸이 가장 무겁다. 그때만 움직였다.<br><br>들숨에 세 걸음, 날숨에 멈춤. 다섯이 메뚜기처럼 끊어 걸었다. 오래 걸렸다. 속은 탔지만 발은 정확했다.<br>다 건너고 돌아보니 엎드린 것의 꼬리가 길을 반이나 덮고 있었다. 걸음이 조금만 길었어도 밟았다.`,
      ng:`들숨을 기다리는데 숨이 갑자기 멎었다. 자는 것들도 숨을 참는다. 꿈에서 사냥할 때.<br><br>멈춘 숨 속에서 넷째가 그만 발을 옮겼다. 바스락. 꼬리가 바닥을 쓸며 돌았다. 다섯이 벽에 몸을 던졌다.<br>꼬리 끝이 둘째 옆구리를 스쳤다. 스친 자리가 갈비뼈까지 멍들었다. 잠결의 꼬리가 그 정도였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-32, spirit:-18 } }
  ] },

{ at:'S', t:'행렬 — 다섯 박에 들어온 여섯째 발',
  x:`다섯이 줄지어 걷는다. 북잡이는 늘 하듯 발의 박을 센다. 다섯 박, 쉼. 다섯 박, 쉼.<br><br>
    쉼 자리에 발 하나가 들어와 있다. 가볍고, 발톱이 돌에 닿는 소리가 섞였다.<br>
    D의 어둠에서도 이런 일은 있었다. 그때 그것은 쉼에 숨는 게 고작이었다. 이것은 다르다. 이것은 다섯 박 안에도 들어왔다 나갔다 한다. 둘째 발소리에 포개졌다가, 넷째 발소리에 포개졌다가.<br><br>
    박 안에 숨을 줄 아는 것. 사냥을 배운 것이다. 이쪽 걸음에서.`,
  o:[
    { l:'① 박을 통째로 버리고 다섯을 제멋대로 걷게 한다.', k:'fix', dc:25, wake:1,
      ok:`손짓했다. 줄 버려. 박 버려. 제멋대로 걸어.<br><br>다섯이 어리둥절한 채 흩어져 걸었다. 보폭도 빠르기도 제각각. 박이 없는 걸음은 포갤 자리도 없다. 발톱 소리가 갈 곳을 잃고 드러났다. 혼자. 한가운데에.<br>다섯이 일제히 그쪽을 봤다. 보이지 않아도 들렸으니. 들킨 것은 머뭇대다 물러났다. 영리한 것은 들킨 사냥을 버린다.<br><br>북잡이는 박을 세우는 사람인 줄 알았다. 박을 부수는 것도 북잡이 일이다. 세운 것에 숨는 놈한테는 부순 것이 그물이다. 두 가지를 다 쥐니 손이 넓어졌다.`,
      ng:`박을 버리게 했는데 몸에 밴 박은 안 버려진다. 다섯 걸음이 금세 다시 맞았다.<br><br>발톱 소리가 그 박에 올라탔다. 이번엔 이쪽 발소리에 포개졌다. 바로 뒤. 돌아보면 어둠뿐이다.<br>길이 끝날 때까지 업힌 박을 떼지 못했다. 신발을 벗어 확인했다. 뒤축에 발톱 자국이 세 줄 나 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 쉼 자리에 맞춰 뒤로 창을 내지른다.', k:'break', dc:26,
      doom:{ title:'박을 아는 턱', what:'박에 숨던 것에게 창째 물려 끌려갑니다', dc:20, sec:40,
        text:`다섯 박, 쉼. 쉼에 맞춰 몸을 틀며 창을 내질렀다. 창끝이 무언가에 닿았다. 가죽. 단단하다.<br><br>닿는 순간 알았다. 저것은 쉼을 기다리고 있었다. 이쪽이 쉼에 찌를 줄 알고. 창대가 옆으로 꺾인다. 턱이 창을 물었다. 창을 쥔 손째.<br>당긴다. 놓으면 된다. 손가락이 안 펴진다. 창은 북 다음으로 오래 쥔 물건이다.<br><br>어둠 속으로 끌려간다. 등 뒤에서 넷의 박이 흩어지는 소리가 난다.`,
        dieText:`창은 사흘 뒤 길 한가운데서 발견됐다. 창대에 이빨 자국이 박자처럼 고르게 나 있었다.<br><br>넷은 그 창을 두고 왔다. 아무도 줍자고 하지 않았다.<br>그 뒤로 넷은 걸을 때 쉼을 두지 않는다. 다섯 박이 아니라 넷 박으로, 쉼 없이. 그 걸음은 북잡이가 남긴 걸음이다.` },
      ok:`다섯 박, 쉼. 쉼에 맞춰 몸을 틀며 창을 냈다. 그러나 찌르지 않고 창대를 가로로 후렸다.<br><br>찌르기는 한 점이고 후리기는 한 줄이다. 박을 아는 놈은 점을 피해도 줄은 못 피한다. 창대가 무언가의 콧등을 후려쳤다.<br>캥, 하는 소리. 개도 아니고 새도 아닌 소리. 발톱 소리가 쉼 밖으로 굴러 떨어지더니 멀어졌다. 그 뒤로 쉼 자리는 비어 있었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'북 가죽 — 치지 않은 북이 운다',
  x:`걷는데 허리에 찬 북이 운다. 웅. 아주 낮게. 치지 않았는데.<br><br>
    가죽은 귀보다 낮은 소리를 듣는다. 땅으로 오는 소리. 크고 무거운 것이 아주 멀리서 걸으면 귀에는 안 들리고 가죽에 먼저 닿는다.<br>
    손바닥을 가죽에 얹었다. 웅. 사이를 셌다. 웅. 걸음이다. 한 걸음이 세 박 길이. 보폭이 집채만 하다.<br><br>
    울림이 조금씩 굵어진다. 이쪽으로 온다.`,
  o:[
    { l:'① 가죽의 울림으로 저것의 길을 그려 비켜 세운다.', k:'sense', dc:24,
      ok:`북을 벗어 바닥에 놓고 가죽에 손가락을 얹었다. 울림이 굵어지는 쪽, 가늘어지는 쪽. 저것의 길이 손끝에 그려진다.<br><br>길은 이 길이다. 곧장. 비킬 쪽은 바람 반대편 둔덕. 다섯을 그리로 올렸다.<br>세 박 걸음이 지나갔다. 바닥이 울렁였다. 두고 온 북이 저 혼자 울었다. 웅, 웅, 웅. 지나가고 나서 주우러 갔더니 가죽이 미지근했다.`,
      ng:`울림을 읽는데 울림이 둘로 갈라졌다. 큰 것 뒤에 큰 것이 하나 더 있다.<br><br>첫째 길은 피했다. 둘째 길이 피한 자리로 왔다. 큰 것들은 길을 나눠 걷는다. 그것도 셈이다.<br>다섯이 둔덕 아래로 굴렀다. 머리 위로 배가 지나갔다. 배에서 늪 냄새가 났다. 한참 아무도 못 일어났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 울림이 제일 굵어지는 순간 다섯을 엎드리게 한다.', k:'steady', dc:24,
      ok:`울림이 굵어진다. 셌다. 셋, 둘, 하나. 손바닥을 바닥으로 내리쳤다. 엎드려.<br><br>다섯이 바닥에 붙었다. 세 박 걸음이 바로 옆을 지나갔다. 땅이 뛰었다. 몸이 손가락 하나만큼 떠올랐다 떨어졌다.<br>큰 것 눈은 높은 데 있다. 바닥에 붙은 것은 돌이다. 돌 다섯 개 옆을 산이 지나갔다.`,
      ng:`셋, 둘— 하나를 세기 전에 넷째가 뛰었다. 못 참고.<br><br>높은 눈이 움직이는 것을 잡았다. 걸음이 꺾였다. 이쪽으로. 땅이 발밑에서 접혔다.<br>넷째 뒷덜미를 잡아 구덩이로 던지고 같이 굴렀다. 머리 위에서 턱 닫히는 소리가 났다. 바위 깨지는 소리와 같았다. 넷째 어깨가 빠져 있었다. 끼워 넣는 동안 넷째는 소리도 못 질렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-34, mind:-16 } }
  ] },

{ at:'S', t:'목소리 — 말의 박이 틀리다',
  x:`어둠 저쪽에서 셋째 목소리가 났다. 여기야. 이쪽이야.<br><br>
    셋째는 바로 옆에 있다. 입을 다물고. 제 목소리를 제가 듣고 하얗게 질려 있다.<br>
    목소리는 똑같다. 높이도 떨림도. 그런데 북잡이 귀에는 박이 틀리다. 셋째는 말끝을 흐린다. 여기야, 하고 반 박 처진다. 저것은 말끝이 반듯하다. 자로 잰 박.<br><br>
    사람 말은 박이 흐트러져서 사람 말이다.`,
  o:[
    { l:'① 저것이 흉내 못 낼 말을 시킨다 — 다 같이 엇박 노래.', k:'fix', dc:25, wake:1,
      ok:`다섯에게 노래를 시켰다. 고향 모심기 노래. 일부러 엇박으로. 서로 반 박씩 어긋나게.<br><br>어둠 저쪽 목소리가 따라 불렀다. 처음 한 소절은 그럴듯했다. 엇박이 꼬이는 둘째 소절에서 무너졌다. 박을 자로 재는 것은 어긋남을 못 잰다. 노래가 톱니 긁는 소리로 변했다.<br>소리가 제 소리에 성이 나서 캑캑댔다. 사람 목에서 안 나는 소리가 나기 시작했다. 다섯은 노래를 부르며 뒷걸음으로 그 자리를 떴다.<br><br>어긋남이 사람의 증거다. 반듯한 박만 좇던 귀가 오늘 어긋남 쪽에 섰다. 박을 세우는 손과 흩트리는 손, 북잡이는 이제 양손잡이다.`,
      ng:`엇박 노래를 시켰는데 넷째가 박을 못 놓는다. 성실한 사람이라 자꾸 맞춰 부른다.<br><br>맞는 박 하나를 타고 저것의 목소리가 노래 속으로 들어왔다. 여섯째 목소리. 누구 목소리인지 아무도 구별 못 했다.<br>노래를 끊고 뛰었다. 등 뒤에서 노래가 혼자 이어졌다. 다섯 목소리로. 다섯 다 이 자리에 있는데.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 목소리 쪽을 응시해 입이 어디 달렸는지 본다.', k:'gaze', dc:24,
      ok:`소리 나는 쪽을 오래 봤다. 어둠이 눈에 익자 윤곽이 잡혔다.<br><br>입은 목에 달려 있지 않았다. 가슴 한가운데가 세로로 열리며 말하고 있었다. 열릴 때마다 갈비뼈 같은 것이 벌어진다. 목소리는 그 안의 젖은 주름에서 나왔다.<br>입 위치를 알면 못 듣는 귀 위치도 나온다. 저것은 말하는 동안 못 듣는다. 가슴이 열려 말할 때마다 세 걸음씩 물러났다. 목소리가 멀어질 때까지.`,
      ng:`윤곽을 잡으려 한 발 다가섰다. 목소리가 뚝 끊겼다.<br><br>말하기를 그만둔 것은 듣기 시작한 것이다. 이쪽 발소리를. 어둠 속에서 가슴 열리는 소리가 났다. 이번엔 말이 아니라 숨을 들이켰다. 길게. 냄새를 가슴으로 맡는 것이다.<br>다섯이 바람 반대로 뛰었다. 등 뒤에서 셋째 목소리가 울었다. 가지 마. 셋째는 이를 악물고 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S', t:'달아나기 — 보폭의 구령',
  x:`들켰다. 뒤에서 수풀이 통째로 넘어가는 소리가 온다. 뛰는 수밖에 없다.<br><br>
    다섯이 제 빠르기로 뛰면 줄이 늘어진다. 늘어진 줄의 맨 끝은 떨어져 나간다. 사냥하는 것들은 늘 맨 끝을 문다.<br>
    보폭을 맞추면 줄이 안 늘어진다. 제일 느린 발에 맞추되, 그 발이 낼 수 있는 가장 빠른 박으로.<br><br>
    숨이 턱에 닿는 속에서 박을 세는 것이 북잡이 일이다.`,
  o:[
    { l:'① 뛰면서 혀로 박을 찬다 — 맨 뒤 발에 맞춰.', k:'fix', dc:24,
      ok:`혀를 입천장에 차며 박을 냈다. 똑. 똑. 손은 못 쓴다. 팔을 저어야 하니. 혀가 북채다.<br><br>맨 뒤는 둘째다. 둘째 발이 땅에 닿는 순간마다 혀를 찼다. 다섯 발이 한 발이 됐다. 줄이 안 늘어진다.<br>뒤쫓는 것이 맨 끝을 몇 번 노리다 말았다. 한 덩어리로 뛰는 다섯은 맨 끝이 없다. 큰 바위 뒤로 꺾어 들어가 소리를 죽였다. 쫓던 소리가 지나쳐 갔다.`,
      ng:`혀를 차는데 숨이 모자라 박이 끊겼다. 끊긴 박에 둘째가 반 걸음 처졌다.<br><br>반 걸음이면 충분했다. 뒤에서 온 것이 둘째 등짐을 채 갔다. 등짐만. 끈이 끊어지며 둘째가 앞으로 넘어졌고, 그래서 살았다.<br>등짐 뜯기는 소리가 어둠 속에서 한참 났다. 안에 든 건 사흘 치 먹을 것이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 박이 끊긴 하나를 데리러 되돌아 뛴다.', k:'bond', dc:25,
      doom:{ title:'늘어진 줄의 끝', what:'처진 일행과 함께 수풀 속으로 끌려 들어갑니다', dc:19, sec:40,
        text:`넷째 발소리가 박에서 떨어져 나갔다. 돌아봤다. 넷째가 반 마장 뒤에서 절고 있다.<br><br>되돌아 뛰었다. 넷째 팔을 어깨에 걸었다. 둘이 한 박으로 뛰기 시작한 순간, 수풀이 양옆에서 닫혔다.<br>기다린 것이다. 되돌아오는 발을. 영리한 것들은 처진 놈이 아니라 데리러 오는 놈을 문다. 한 번에 둘이니까.<br><br>넷째와 이쪽 다리에 하나씩, 턱이 감긴다. 수풀 안쪽으로 끌려 들어간다. 둘이 같은 박으로 끌린다.`,
        dieText:`셋은 바위 뒤에서 수풀이 잦아드는 것을 지켜봤다. 들어갈 수 없었다. 수풀 전체가 숨 쉬고 있었다.<br><br>새벽에 수풀 가장자리에서 북이 발견됐다. 가죽이 찢긴 데 없이 멀쩡했다.<br>셋 중 하나가 북을 멨다. 칠 줄은 모른다. 그래도 멨다. 메고 있으면 박을 세던 사람 생각이 나서, 걸음이 저절로 맞았다.` },
      ok:`넷째 발소리가 박에서 떨어졌다. 되돌아 뛰며 소리쳤다. 서지 마, 기어서라도 와.<br><br>넷째한테 닿기 전에 멈췄다. 두 걸음 앞. 수풀이 양옆에서 너무 고요했다. 고요한 수풀은 찬 수풀이다. 돌을 주워 수풀 왼쪽에 던졌다.<br>왼쪽이 먼저 닫혔다. 헛물을 켠 수풀이 출렁이는 사이 오른쪽으로 넷째를 끌어냈다. 어깨에 걸치고 박을 다시 세웠다. 이번엔 이쪽 숨이 끊길 때까지 혀를 찼다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'멈춤 — 움직임을 보는 눈',
  x:`길 한가운데서 그것과 마주쳤다. 스무 걸음. 서로 봤다.<br><br>
    그런데 저것의 눈이 이쪽을 못 잡는다. 고개를 갸웃댄다. 눈이 흐린 것이 아니다. 저 눈은 움직임만 본다. 멈춘 것은 바위와 같다.<br>
    다섯이 돌이 됐다. 문제는 사람 몸이다. 사람은 완전히는 못 멈춘다. 숨이 어깨를 들썩이고, 떨림이 손끝을 흔든다.<br><br>
    저것이 한 걸음 다가온다. 확인하러.`,
  o:[
    { l:'① 떨림까지 박으로 다스린다 — 숨 넷에 한 번만 깜빡이게.', k:'steady', dc:25, wake:1,
      ok:`몸은 못 멈춰도 박은 멈춘 척을 만든다. 숨을 넷으로 쪼개 어깨 대신 배로 쉬게 했다. 눈 깜빡임은 숨 넷에 한 번. 그마저 다섯이 제각각 다른 숨에.<br><br>움직임이 박 밑으로 가라앉았다. 저 눈에 잡히는 건 출렁임인데, 박으로 눌린 몸은 출렁이지 않는다. 흐른다. 바위에 이끼 자라듯.<br>저것이 코앞까지 와서 콧김을 뿜었다. 앞머리가 날렸다. 머리칼은 움직여도 된다. 바람에 풀도 눕는다. 저것은 풀 다섯 포기를 지나쳐 갔다.<br><br>박은 소리에만 있는 줄 알았다. 멈춤에도 박이 있다. 숨 넷에 깜빡임 하나. 그 박을 쥔 몸은 바위도 되고 풀도 된다.`,
      ng:`숨을 넷으로 쪼개는데 넷째 속눈썹이 제 박에 떨렸다. 파르르.<br><br>저 눈이 그 떨림을 잡았다. 머리가 획 돌았다. 콧등이 넷째 얼굴 앞에 멈췄다.<br>넷째는 기절하는 쪽을 골랐다. 쓰러지는 건 큰 움직임인데, 쓰러진 다음은 완전한 멈춤이다. 저것이 쓰러진 넷째를 한참 굴려 보다 흥미를 잃었다. 넷째는 반나절 뒤에 깨어 그날 일을 하나도 기억 못 했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 돌 하나를 멀리 던져 움직임을 그쪽에 준다.', k:'evade', dc:24,
      ok:`손가락만 움직여 돌을 쥐었다. 손목의 박 하나로 던졌다. 돌이 저쪽 비탈을 굴렀다.<br><br>움직임을 보는 눈에 구르는 돌은 도망가는 짐승이다. 저것이 머리부터 그쪽으로 쏟아졌다. 땅이 울렸다.<br>다섯은 반대쪽으로 흘렀다. 뛰지 않고. 뛰면 움직임이다. 빠르게 걷는 돌 다섯이 길을 벗어났다.`,
      ng:`돌을 던지는 팔이 너무 컸다. 저 눈이 돌이 아니라 던진 팔을 잡았다.<br><br>팔부터 왔다. 몸을 비틀어 피했다. 어깨가 바람에 쓸렸다. 바람만으로 옷이 찢어졌다.<br>다섯이 흩어져 구르고 기었다. 저것은 움직임 다섯을 번갈아 쫓다가 제자리를 돌았다. 그 틈에 바위 밑으로 기어들었다. 어깨에서 피가 한참 흘렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-34, mind:-14 } }
  ] },

{ at:'S', t:'알 자리 — 맥박을 듣는 알',
  x:`움푹한 자리에 알이 놓여 있다. 여남은 개. 가죽 같은 껍데기가 숨 쉬듯 오르내린다.<br><br>
    길은 알 사이를 지난다. 돌아갈 길은 무너졌다.<br>
    알 하나에 손을 대 봤던 넷째가 속삭인다. 알이 뛴대. 제 심장이랑 같은 박으로.<br>
    알은 귀가 없다. 대신 맥을 듣는다. 가까운 심장의 박을. 빠른 맥이 지나가면 알이 깬다. 어미를 부르면서.<br><br>
    어미는 멀리 있지 않을 것이다.`,
  o:[
    { l:'① 다섯 맥을 알의 박에 맞춰 느리게 가라앉히고 지난다.', k:'fix', dc:25,
      ok:`알의 박을 먼저 들었다. 느리다. 사람 심장의 반. 그 박으로 다섯 맥을 끌어내려야 한다.<br><br>한 사람씩 가슴에 손바닥을 얹고 눌렀다. 숨을 길게. 더 길게. 맥이 알의 박에 포개질 때 그 사람을 알 사이로 들여보냈다.<br>알 사이를 지나는 동안 알들이 오르내림을 멈추지 않았다. 제 식구의 맥이 지나가는 줄 아는 것이다. 다섯이 다 건넜다. 마지막에 건넌 이쪽 맥이 제일 오래 안 돌아왔다.`,
      ng:`넷째 맥이 알 한가운데서 튀었다. 알 하나가 넷째 발 옆에서 쩍 소리를 냈다.<br><br>금 간 틈으로 젖은 것이 꿈틀댔다. 다섯이 맥이고 뭐고 내달렸다. 등 뒤에서 알들이 차례로 터지는 소리.<br>갓 깬 것들은 다리가 서툴러 못 쫓아왔다. 대신 울었다. 가늘고 높게. 멀리서 낮고 굵은 울음이 대답했다. 그 울음이 등에 닿기 전에 골짜기를 빠져나왔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 맥이고 뭐고 숨 한 번에 내달려 건넌다.', k:'luck', dc:26,
      doom:{ title:'깨어난 자리', what:'알 자리 한가운데서 어미에게 물려 둥지 안쪽으로 끌려갑니다', dc:20, sec:35,
        text:`숨을 크게 쉬고 내달렸다. 알 사이로. 빠른 맥 다섯이 한꺼번에 알밭을 지났다.<br><br>알들이 일제히 뛰기 시작했다. 사람 맥을 받아서. 터지지는 않았다. 대신 다 같이 울렸다. 둥, 둥, 둥. 알밭 전체가 북이 됐다. 어미를 부르는 북.<br>그늘이 하늘을 덮었다. 위에서 온다. 맨 뒤를 달리던 이쪽 어깨에 발톱이 감긴다.<br><br>알밭 너머 둥지 쪽으로 끌려간다. 발이 땅에서 떨어진다. 알들이 밑에서 둥, 둥, 환영하듯 운다.`,
        dieText:`넷은 알밭 끝 바위 틈에서 밤을 샜다. 둥지 쪽에서 북 치는 소리 같은 것이 밤새 들렸다.<br><br>새벽에 그 소리가 그쳤다.<br>넷은 그 뒤로 빠른 박을 들으면 손부터 가슴에 얹는다. 맥을 내리라고 배운 대로. 가르친 사람은 이제 없는데 버릇만 남아서, 그 버릇이 넷을 몇 번이고 살렸다.` },
      ok:`숨을 크게 쉬고 내달렸다. 운이 좋았다. 알밭 한가운데 마른 물길이 있었다. 알이 안 놓인 줄.<br><br>그 줄로 다섯이 꿰어 달렸다. 알과 알 사이 제일 먼 길. 맥이 닿기엔 먼 거리.<br>알 두엇이 뒤늦게 꿈틀댔지만 깨지는 않았다. 다 건너고 나서 다리가 풀려 주저앉았다. 운으로 건넌 길은 두 번 못 건넌다. 다들 알았다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'S', t:'두 갈래 — 메아리로 재는 길',
  x:`길이 두 갈래다. 왼쪽은 바람이 나오고, 오른쪽은 고요하다.<br><br>
    바람 나오는 쪽이 뚫린 길이다. 보통은. 여기서는 보통을 믿으면 안 된다. 숨구멍에서도 바람은 나온다. 큰 것의 숨구멍에서도.<br>
    북잡이는 길을 소리로 잰다. 테를 한 번 치면 메아리가 돌아온다. 빈 길은 메아리가 길고 맑다. 막힌 길은 짧고 둔하다. 그리고 산 것이 있는 길은— 메아리가 중간에 한 번 먹힌다.<br><br>
    두 번 칠 수는 없다. 치는 소리도 소리다.`,
  o:[
    { l:'① 테를 한 번만 치고 두 메아리를 귀 하나씩 나눠 듣는다.', k:'sense', dc:25,
      ok:`갈림목 한가운데 서서 테를 쳤다. 딱. 한 번. 왼 귀는 왼 길, 오른 귀는 오른 길.<br><br>왼쪽 메아리는 길고 맑다가 끝이 젖었다. 물이다. 오른쪽은 짧다. 그리고 돌아오는 중간에 한 번 먹혔다. 무엇이 서 있다. 소리를 삼키는 부피가.<br>왼쪽으로 들었다. 발목까지 물이 찼지만 길은 뚫려 있었다. 오른쪽 길에서는 한참 뒤에 테 치는 소리가 났다. 딱. 똑같이. 따라 치고 있었다.`,
      ng:`테를 쳤다. 딱. 메아리가 오기 전에 오른쪽 길이 먼저 대답했다. 딱.<br><br>메아리가 아니다. 메아리는 반 박 늦는다. 이건 같은 박이었다. 기다리고 있다가 포개 친 것이다.<br>왼쪽으로 뛰었다. 물길이었다. 허리까지 빠지며 건넜다. 등 뒤에서 딱, 딱, 테 치는 소리가 물가까지 따라왔다 멈췄다. 물을 싫어하는 것이었다. 그것만이 그날의 운이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 소리 내지 않고 운에 맡겨 고요한 쪽을 고른다.', k:'luck', dc:24,
      ok:`치지 않았다. 고요한 오른쪽을 골랐다. 바람 나오는 길의 바람에서 비린내가 났기 때문이다. 그게 다였다.<br><br>오른길은 좁고 말라 있었다. 중간에 갈비뼈 같은 기둥들이 줄지어 선 데를 지났다. 돌이었다. 아마 돌이었을 것이다.<br>다 지나고 나서 왼길 쪽에서 길게 숨 내쉬는 소리가 들렸다. 바람이 아니었던 것이다. 다섯이 서로 안 보고 걸음만 빨리했다.`,
      ng:`고요한 쪽을 골랐다. 고요한 이유가 있었다. 다 먹혀서 고요했다.<br><br>길바닥이 뼈였다. 잔뼈가 발밑에서 바스락댔다. 바스락 소리마다 어둠 속 깊은 데서 무엇이 자세를 고쳤다.<br>돌아 나올 수도 없어 끝까지 갔다. 마지막 스무 걸음은 다들 눈을 감고 걸었다. 뼈를 안 보려고. 나와서 보니 신발이 하얗게 가루를 뒤집어썼다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S1', t:'통풍구 — 관을 타고 오는 박',
  x:`표본실 구역은 복도가 다 잠겼다. 길은 통풍구뿐이다. 네 발로 기는 쇠 관.<br><br>
    관에 들어가기 전에 손바닥으로 관 벽을 쳤다. 둥. 소리가 관을 타고 달려갔다 돌아온다.<br>
    돌아온 소리에 다른 박이 묻어 왔다. 긁는 박. 똑, 끼익. 똑, 끼익. 관 어딘가에서 무엇이 긴다. 발톱이 쇠에 닿는 소리.<br><br>
    관은 소리의 길이다. 이쪽 박도 저쪽에 닿는다.`,
  o:[
    { l:'① 다섯의 기는 박을 하나로 포개 한 마리 소리로 만든다.', k:'fix', dc:25, wake:1,
      ok:`기기 전에 박을 정했다. 오른손, 왼무릎, 왼손, 오른무릎. 다섯이 같은 순서, 같은 박으로.<br><br>관 속에서 다섯이 기면 스무 점의 소리가 난다. 포개면 네 점이다. 큰 것 한 마리. 긁는 박이 멈추고 듣는 기척이 왔다. 한참 듣더니 물러갔다. 저보다 큰 것 소리였으니.<br>갈림 관에서 마른 바람이 나오는 쪽으로 꺾었다. 관을 다 빠져나와 세어 보니 손바닥이 다 까져 있었다. 박을 지키느라 아픈 데를 못 골랐다.<br><br>스무 점을 네 점으로 줄이는 셈. 소리를 지우는 게 아니라 소리의 수를 속이는 법. 관이 가르쳐 준 것을 손바닥이 외웠다.`,
      ng:`박을 포개 기는데 둘째 무릎이 이음매 턱에 걸렸다. 쿵. 박에 없는 소리.<br><br>긁는 박이 뚝 멈췄다. 그리고 빨라졌다. 이쪽으로. 똑끼익똑끼익. 네 점이 아니라는 걸 들킨 것이다.<br>옆 갈림 관으로 다섯이 쑤셔 들어갔다. 본 관을 무엇이 지나갔다. 비린 바람이 발바닥을 훑었다. 꼬리 끝이 신발 바닥을 긁고 갔다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-26, mind:-18 } },
    { l:'② 긁는 박의 빠르기로 저것의 크기와 거리를 잰다.', k:'sense', dc:24,
      ok:`똑, 끼익. 사이가 길다. 보폭이 길다는 뜻. 몸이 관에 꽉 찬다는 뜻이다. 꽉 찬 것은 좁은 갈림 관에 못 든다.<br><br>거리는 메아리 끝이 뭉개지는 정도로 쟀다. 세 굽이 너머. 이쪽이 좁은 갈림 관까지 가는 동안 못 닿는 거리다.<br>좁은 관으로 다섯을 먼저 보내고 마지막에 들어갔다. 본 관에서 큰 몸이 지나가는 소리가 났다. 쇠가 배를 쓸며 우는 소리. 관 하나를 사이에 두고 그 소리를 다 들었다.`,
      ng:`사이를 재는데 긁는 박이 둘 됐다. 앞에서 하나, 뒤에서 하나. 관 양 끝이다.<br><br>크기고 뭐고 가운데 갈림 관으로 다섯을 밀어 넣었다. 수직 관이었다. 미끄럼틀처럼 떨어졌다.<br>아래층 바닥에 포개져 떨어졌다. 위 관에서 두 긁는 박이 만나는 소리가 났다. 싸우는 소리. 서로 잡아먹는 소리였다. 그 소리가 제일 오래 귀에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'S1', t:'표본실 — 유리병의 공명',
  x:`표본실이다. 선반마다 유리병. 절반은 금이 갔고 몇 개는 비었다.<br><br>
    남은 병 속에는 아직 잠긴 것들이 떠 있다. 웅크린 것, 입만 있는 것, 사람 손 비슷한 것.<br>
    바닥을 디디자 병들이 운다. 징— 하고. 걸음의 울림이 선반을 타고 병을 울린다. 병이 울면 속엣것들이 눈을 뜬다. 금 간 병이 그 울림에 버틸지는 병만 안다.<br><br>
    북잡이 귀에는 병마다 제 소리가 있다. 우는 박이 다 다르다.`,
  o:[
    { l:'① 병이 안 우는 박을 찾아 그 걸음으로 다섯을 통과시킨다.', k:'fix', dc:25,
      ok:`발꿈치를 들고 한 걸음씩 박을 바꿔 디뎌 봤다. 빠른 박엔 작은 병이 울고 느린 박엔 큰 병이 운다. 그 사이, 어느 병도 안 우는 박이 있다. 좁은 박이다.<br><br>그 박을 손짓으로 넷에게 옮겼다. 반 박 걷고 멈춤, 반의반 박 걷고 멈춤. 절름발이 걸음 같은 박.<br>다섯이 그 박으로 선반 사이를 지났다. 병들은 끝까지 잠잠했다. 속엣것 하나가 지나가는 이쪽을 눈 없이 따라 돌았지만, 병이 울지 않으니 그뿐이었다.`,
      ng:`좁은 박을 넷에게 옮기다 셋째가 제 박을 냈다. 한 걸음. 큰 병 하나가 징— 울었다.<br><br>금 간 자리가 자랐다. 쩍. 병물이 바닥에 쏟아졌다. 쏟아진 것이 물만이 아니었다.<br>웅크렸던 것이 바닥에서 펴졌다. 젖은 채로 첫 숨을 쉬었다. 다섯은 그것이 숨 고르는 사이 표본실을 가로질렀다. 등 뒤에서 첫 발소리가 났다. 갓 깬 것 치고 너무 반듯한 박이었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 우는 병 하나를 손바닥으로 감싸 소리를 죽인다.', k:'break', dc:24,
      ok:`걸음마다 우는 병이 하나 있었다. 제일 금이 간 병. 그 병만 죽이면 나머지는 버틴다.<br><br>병 몸통을 두 손바닥으로 감쌌다. 울림이 손바닥으로 들어와 살에서 죽었다. 북 가죽을 눌러 소리 죽이는 손 그대로.<br>감싼 채로 넷을 먼저 보냈다. 손바닥 안에서 속엣것이 돌아누우며 유리 너머로 이쪽 체온을 더듬었다. 넷이 다 지나고 손을 뗐다. 병은 끝내 안 울었다. 손바닥에 소름이 병 모양으로 돋아 있었다.`,
      ng:`병을 감싸는데 속엣것이 손바닥 쪽으로 몸을 던졌다. 쿵. 안에서.<br><br>울림을 죽이려던 손이 울림을 만들었다. 옆 병이 울고, 그 옆 병이 울었다. 노래가 번지듯.<br>다섯이 뛰었다. 등 뒤에서 병 터지는 소리가 둘, 셋. 문을 닫고 빗장까지 질렀다. 문 너머에서 젖은 것들이 바닥을 치는 소리가 밤새 났다. 박자를 맞춰 가면서.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 병들의 음을 응시해 빈 병이 어느 선반인지 가려낸다.', k:'gaze', dc:24,
      ok:`병을 하나하나 봤다. 우는 음이 다 다르다. 찬 것이 든 병은 음이 둔하다. 빈 병은 맑다.<br><br>맑은 음이 네 개. 네 마리가 밖에 있다는 뜻이다. 빈 병의 마개를 봤다. 안쪽에서 녹았다. 산이다. 속엣것이 제 피로 마개를 녹이고 나갔다.<br>네 병의 크기를 외웠다. 주먹만 한 것 셋, 팔뚝만 한 것 하나. 복도에서 무엇을 만나든 크기는 안다. 아는 만큼 덜 무섭다. 아주 조금.`,
      ng:`음을 가리는데 한 병의 음이 이상했다. 맑지도 둔하지도 않다. 반쯤 빈 음.<br><br>들여다봤다. 속엣것이 반만 있었다. 아래 반. 위 반은— 마개가 안에서 녹아 있었다.<br>위 반이 어디 있는지는 생각하지 않기로 했다. 그날 밤 천장에서 물방울이 떨어졌는데 아무도 고개를 들지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S1', t:'경보 — 고장난 사이렌의 박자',
  x:`복도 천장에서 경보가 운다. 몇 년을 혼자 울었는지 소리가 반쯤 쉬었다.<br><br>
    왜앵— 쉼. 왜앵— 쉼. 고장난 채로 도는 박. 복도의 것들은 이 박에 익었다. 경보는 저들에게 바람 소리다.<br>
    바람 소리에 몸을 실으면 발소리가 지워진다. 왜앵에 걷고 쉼에 멈추고.<br><br>
    쉼의 길이가 매번 조금씩 다르다는 것만 빼면 좋은 길이다.`,
  o:[
    { l:'① 사이렌의 어긋나는 쉼을 몸에 익혀 그 박으로 복도를 건넌다.', k:'fix', dc:25, wake:1,
      ok:`쉼을 열 번 들었다. 다 다르다. 그런데 어긋남에도 결이 있다. 길고 짧고 길고 길고. 쉰 목이 기침하는 결. 그 결째로 외웠다.<br><br>왜앵에 다섯 걸음, 쉼에 벽. 결을 아니까 쉼이 길어져도 안 당황한다. 복도 가운데서 쉼이 가장 길게 늘어졌을 때, 모퉁이에서 긴 머리통이 나와 복도를 훑었다. 벽에 붙은 다섯은 소리가 없었다. 머리통이 들어갔다. 왜앵. 다섯 걸음.<br><br>고른 박은 누구나 탄다. 어긋나는 박을 타는 건 다른 일이다. 어긋남의 결을 외우는 귀. 그 귀가 오늘 생겼다. 고장난 것들의 박자가 다 길로 보이기 시작한다.`,
      ng:`결을 외웠다고 믿었다. 열한 번째 쉼이 결을 벗어났다. 끝없이 길어졌다.<br><br>쉼 한가운데 다섯이 복도 복판에 떠 있었다. 모퉁이에서 머리통이 나왔다. 이번엔 훑지 않고 멈췄다. 이쪽을 향해.<br>왜앵. 사이렌이 다시 울었다. 머리통이 소리 쪽으로 돌아간 반 박 사이에 다섯이 문틀 안으로 쏟아져 들어갔다. 둘째 발꿈치가 문에 찍혔다. 발톱이 아니라 문에. 그게 다행이라고 서로 말했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 경보가 멎은 순간의 정적에 숨어 간다.', k:'hide', dc:26,
      doom:{ title:'정적을 걷는 것', what:'소리 없는 복도에서 목덜미를 물려 통풍구 안으로 끌려 들어갑니다', dc:20, sec:40,
        text:`열두 번째 왜앵이 끝나고 사이렌이 아주 죽었다. 몇 년 만의 정적.<br><br>정적도 길이다. 소리가 없으면 발소리만 죽이면 된다. 벽에 붙어 반 복도를 갔다.<br>그때 알았다. 복도의 것들이 경보에 익은 게 아니었다. 경보를 피해 있었던 것이다. 정적이 오자 통풍구 덮개들이 차례로 밀려 열린다. 저들의 시간이 온 것이다.<br><br>등 뒤 통풍구에서 나온 것이 이쪽 목덜미를 문다. 끌어 올린다. 관 속으로. 정적 속이라 그 소리가 유난히 컸다.`,
        dieText:`사이렌이 다시 울기 시작한 건 한참 뒤였다. 왜앵— 쉼.<br><br>넷은 그 박에 맞춰 복도를 마저 건넜다. 배운 대로. 왜앵에 걷고 쉼에 멈추고.<br>통풍구 앞을 지날 때마다 쉼이 유난히 길게 느껴졌지만, 결을 외운 귀가 넷을 끝까지 끌고 갔다. 가르친 사람 몫까지.` },
      ok:`열두 번째 왜앵이 끝나고 사이렌이 죽었다. 정적.<br><br>움직이지 않았다. 몇 년을 운 소리가 그냥 죽지 않는다. 이건 쉼이 아니라 숨 고르기다. 벽에 붙어 기다렸다.<br>통풍구 덮개 하나가 삐걱 열리다가— 왜앵. 사이렌이 되살아났다. 덮개가 황급히 닫혔다. 저들도 이 박에 매여 산다. 다섯은 되살아난 왜앵을 타고 복도를 마저 건넜다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'숙주 — 가슴 속의 두 박',
  x:`셋째가 자꾸 가슴을 문지른다. 체한 것 같다고 한다. 표본실 구역에서 넘어져 뭘 들이마신 뒤부터다.<br><br>
    잠든 셋째 가슴에 귀를 댔다. 북잡이 귀는 박을 포개 듣는 귀다. 포개진 것은 떼어서도 듣는다.<br>
    심장 박 밑에 작은 박이 하나 더 있다. 반 박 늦게. 심장이 둥 하면 그 그늘에서 둑. 아주 작다. 아직은.<br><br>
    셋째는 모른다. 말해야 하나. 말하면 셋째 심장이 빨라질 텐데, 저 작은 박은 빠른 박을 먹고 자라는 것 같다.`,
  o:[
    { l:'① 말하지 않고 셋째 심장을 며칠 내내 느린 박에 묶어 둔다.', k:'fix', dc:25,
      ok:`말하지 않았다. 대신 셋째 곁에서 안 떨어졌다. 걸을 때 셋째 보폭에 혀를 차 주고, 쉴 때 손목을 짚어 주고, 잘 때 등을 두드렸다. 느리게. 내내 느리게.<br><br>작은 박은 심장이 뛰어야 같이 큰다. 느린 심장 밑에서 작은 박이 사흘을 굶었다. 나흘째 아침, 셋째가 가슴이 시원하다며 크게 트림을 했다. 귀를 댔다. 둑이 없다. 굶어 마른 것이다.<br>셋째는 아직도 그 며칠을 북잡이가 유난히 살가웠던 날들로 기억한다. 그러라고 뒀다.`,
      ng:`느린 박에 묶는다고 묶었는데, 밤에 셋째가 악몽을 꿨다. 심장이 뛰었다. 묶은 박이 끊겼다.<br><br>작은 박이 하룻밤에 배로 자랐다. 둑이 아니라 둥. 심장과 맞먹는 박. 셋째가 식은땀을 흘리며 가슴을 쥐었다.<br>결국 말했다. 셋째는 울지 않았다. 치유 아는 일행이 올 때까지 사흘, 셋째 심장을 느리게 묶는 일에 다섯이 다 매달렸다. 그 사흘 동안 아무도 셋째와 눈을 오래 못 맞췄다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 사실대로 말하고 둘이서 숨 고르기를 함께 한다.', k:'bond', dc:24,
      ok:`아침에 조용히 말했다. 가슴에 박이 하나 더 있다. 자라기 전에 굶기자.<br><br>셋째 심장이 당연히 뛰었다. 뛰는 심장을 둘이서 붙잡았다. 마주 앉아 숨을 맞췄다. 이쪽이 들이쉬면 셋째가 들이쉬고. 심장은 혼자 두면 겁에 먹히지만 둘이면 박이 선다.<br>닷새를 그렇게 했다. 엿새째, 작은 박이 사라졌다. 셋째가 말했다. 혼자였으면 미쳤을 거라고. 둘이어서 박이 됐다고.`,
      ng:`말하자 셋째가 그 자리서 토하려 들었다. 손가락을 목에 넣고. 꺼내겠다고.<br><br>그건 목이 아니라 가슴에 있다. 손가락이 닿을 데가 아니다. 말리는 사이 셋째 심장이 널뛰었다. 작은 박이 신나게 받아먹었다.<br>셋째를 진정시키는 데 밤을 다 썼다. 작은 박은 눈에 띄게 굵어져 있었다. 말한 것이 잘못이 아니라 말하는 법이 잘못이었다. 그 차이를 비싸게 배웠다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S1', t:'에어록 — 펌프의 들숨 날숨',
  x:`구역 사이 에어록이다. 문 두 짝. 안쪽 문이 열리려면 바깥 문이 닫히고 바람이 다 빠져야 한다.<br><br>
    펌프가 낡아 제멋대로 돈다. 슉— 들이켜고, 푸— 뱉고. 그래도 박은 있다. 들숨 여섯 박, 날숨 넷 박.<br>
    문틈 너머 안쪽 복도에 긴 것이 산다. 아까 유리창 너머로 꼬리를 봤다. 펌프가 뱉는 날숨 넷 박 동안만 안쪽 문이 열린다.<br><br>
    넷 박. 다섯 사람. 셈이 빠듯하다.`,
  o:[
    { l:'① 펌프의 박을 세어 날숨마다 한 사람씩 넘긴다.', k:'fix', dc:24,
      ok:`들숨 여섯을 세고, 날숨 첫 박에 첫째를 밀었다. 둘째 박에 통과, 셋째 박에 벽 뒤, 넷째 박에 문이 닫혔다.<br><br>다섯 번을 반복했다. 사람마다 걸음이 달라 미는 박을 반 박씩 당기고 늦췄다. 넷째는 겁이 많아 들숨 다섯째 박에 미리 등을 밀어 뒀다.<br>마지막으로 이쪽이 건넜다. 닫히는 문에 북끈이 물렸다. 끈을 끊고 북만 챙겼다. 문 너머에서 긴 것이 복도를 지나는 소리가 났다. 다섯이 벽 뒤에 포개져 숨을 참았다. 펌프의 박에 맞춰서.`,
      ng:`넷째를 미는 박이 늦었다. 날숨 셋째 박. 넷째가 문틈에 끼었다.<br><br>문은 사람을 안 봐준다. 셋이 달라붙어 넷째를 안쪽으로 뽑아냈다. 어깨가 쓸려 피가 났다.<br>피 냄새가 안쪽 복도에 퍼졌다. 긴 것이 오는 소리가 났다. 벽 뒤에 포개져 한 시진을 숨었다. 긴 것이 피 묻은 문틀을 핥는 소리를 다 들으면서.`,
      win:{ exp:20, dream:3, item:'맑은 물' }, lose:{ hp:-28, mind:-16 } },
    { l:'② 닫히려는 바깥 문을 몸으로 받쳐 넷 박을 늘린다.', k:'steady', dc:26,
      doom:{ title:'문이 삼키는 바람', what:'터진 바람에 빨려 바깥 어둠으로 날아갑니다', dc:20, sec:35,
        text:`날숨 넷 박이 모자라다. 바깥 문틀에 어깨를 끼워 닫히는 문을 받쳤다.<br><br>문이 어깨를 민다. 펌프가 비명을 질렀다. 막힌 들숨이 관 어딘가에서 터졌다. 바람이 거꾸로 분다. 에어록 안의 공기가 통째로 바깥으로 쏟아진다.<br>발이 바닥에서 떨어진다. 바람이 이쪽을 빨아 간다. 바깥 어둠 쪽으로. 그 어둠에서 아까부터 무엇이 기다리고 있었다. 바람이 먹이를 배달하는 걸 아는 것이다.<br><br>문틀을 잡은 손가락이 하나씩 펴진다.`,
        dieText:`바람이 멎은 뒤 에어록은 아무 일 없었다는 듯 돌았다. 슉— 푸—.<br><br>넷은 날숨 넷 박에 하나씩 건넜다. 미는 손 없이. 박은 각자 세야 했다.<br>건너편에서 넷이 제일 먼저 한 일은 바깥 어둠 쪽 유리창에 등을 돌리고 서는 것이었다. 그 창은 그 뒤로 아무도 안 봤다.` },
      ok:`문틀에 어깨를 끼웠다. 문이 민다. 버텼다. 한 박. 두 박.<br><br>그 두 박에 넷째와 다섯째가 같이 넘어갔다. 어깨를 빼자 문이 쾅 닫혔다. 펌프가 성난 소리를 냈지만 돌기는 돌았다.<br>다음 날숨에 이쪽이 건넜다. 어깨뼈가 밤새 욱신댔다. 문과 힘겨루기를 한 어깨다. 문이 이기는 걸 두 박 늦춘 어깨.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'깊은 층 — 바닥 밑의 느린 둥',
  x:`깊은 층으로 내려갈수록 바닥이 운다. 둥. 아주 느리고 아주 크다. 몇 박에 한 번씩.<br><br>
    여왕이다. 뭐라 부르든, 이 시설의 것들을 낳는 것. 그 심장인지 숨인지가 바닥을 타고 올라온다.<br>
    복도의 것들이 다 그 둥에 맞춰 움직인다. 둥에 걷고, 사이에 멈춘다. 시설 전체가 한 박으로 숨 쉰다.<br><br>
    그 박에 섞이면 안 보인다. 그 박을 거스르면 시설 전체가 돌아본다.`,
  o:[
    { l:'① 여왕의 둥에 걸음을 포개 시설의 박 속으로 숨는다.', k:'fix', dc:26, wake:1,
      ok:`둥을 열 번 들었다. 몸에 새겼다. 둥에 다섯 걸음, 사이에 정지. 시설의 모든 것이 걷는 박 그대로.<br><br>복도에서 긴 것과 마주 걸었다. 같은 박이라 서로 스쳤다. 저들은 눈이 아니라 박으로 식구를 안다. 같은 박이면 식구다. 비린 어깨가 이쪽 어깨를 치고 지나갔다. 사람인 걸 끝까지 몰랐다.<br>갈림에서 둥이 두 번 쉬는 사이 옆 계단으로 빠졌다. 손바닥이 땀으로 흥건했다. 식구인 척한 값이다.<br><br>남의 박에 숨는 것은 해 봤다. 괴물의 박에 숨은 것은 처음이다. 박 앞에서는 사람과 괴물이 같다는 것. 그걸 안 귀는 전으로 못 돌아간다.`,
      ng:`둥에 포개 걷는데 넷째 걸음이 사이에 떨어졌다. 한 번. 시설의 박을 거스른 한 걸음.<br><br>복도 전체가 멈췄다. 모든 발소리가. 그리고 일제히 이쪽을 향해 돌았다. 박이 다른 것이 섞였다고, 시설 전체가 안 것이다.<br>계단까지 내리 뛰었다. 등 뒤에서 둥이 빨라졌다. 여왕이 박을 올린 것이다. 사냥의 박으로. 문 셋을 닫고서야 둥이 다시 느려졌다. 다들 한동안 제 심장 소리도 무서워했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 둥이 울리는 바닥을 피해 배관 위로 걷는다.', k:'evade', dc:25,
      ok:`바닥이 울리면 바닥을 버리면 된다. 벽을 따라 지나는 배관 위로 올라섰다.<br><br>배관은 둥을 안 탄다. 대신 좁고 둥글다. 다섯이 외줄 타듯 걸었다. 팔을 벌리고.<br>아래 복도로 것들이 지나다녔다. 둥에 맞춰서. 위는 안 본다. 박에 사는 것들은 박이 없는 데를 안 본다. 배관이 끝나는 데까지 반 시진. 종아리가 돌이 됐지만 바닥엔 한 번도 안 닿았다.`,
      ng:`배관이 낡았다. 가운데쯤에서 받침 하나가 둥에 맞춰 삐걱댔다. 배관도 결국 둥을 탔던 것이다.<br><br>삐걱이 박을 거슬렀다. 아래 것들이 일제히 위를 봤다. 박 없는 데서 박이 났으니.<br>배관을 버리고 천장 틈으로 기었다. 뒤에서 배관이 통째로 뜯기는 소리가 났다. 다섯 중 셋이 손바닥에 녹물 든 상처를 얻었다. 그 상처는 이상하게 오래 쑤셨다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'S1', t:'산성혈 — 천장에서 듣는 피',
  x:`복도 천장에 무엇이 죽어 걸려 있다. 저들끼리 싸웠는지, 반쯤 뜯긴 채다.<br><br>
    그 피가 떨어진다. 똑. 바닥에 닿은 자리마다 쇠가 끓는다. 치익. 구멍이 늘어 간다.<br>
    피는 박으로 떨어진다. 상처가 셋, 박이 셋. 빠른 똑, 느린 똑, 가끔 오는 큰 똑.<br>
    세 박이 겹치는 자리와 비는 자리가 있다. 비는 자리가 길이다.<br><br>
    바닥의 구멍들이 어디가 겹치는 자리였는지 가르쳐 준다.`,
  o:[
    { l:'① 세 박을 한 번에 세며 비는 사이로 다섯을 건넨다.', k:'fix', dc:25,
      ok:`세 박을 따로 세다 포개 셌다. 빠른 똑 셋에 느린 똑 하나, 큰 똑은 그 일곱 번째마다. 포개면 긴 한 박이다. 그 박의 쉼이 길이다.<br><br>쉼마다 한 사람씩. 발 디딜 자리는 구멍 없는 데로 미리 짚어 줬다. 넷이 건넜다.<br>이쪽 차례에 큰 똑이 박을 어겼다. 시체가 식으며 박이 늘어진 것이다. 반 박 미뤄 건넜다. 등 뒤 바닥에서 치익, 방금 선 자리가 끓었다. 늘어지는 박까지 듣는 귀가 아니었으면 발이 끓었다.`,
      ng:`박을 포개 세는데 천장의 시체가 움직였다. 죽은 게 아니었다. 죽어 가는 중이었다.<br><br>뒤척임에 상처가 벌어졌다. 박이 넷이 됐다. 새 박은 셈에 없다.<br>넷째 소매에 한 방울이 닿았다. 소매를 그 자리서 찢어 버렸다. 팔뚝에 닿기 반 박 전이었다. 찢은 소매가 바닥에서 연기가 되는 걸 다섯이 말없이 봤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 떨어지는 핏방울 사이를 몸놀림으로 빠져 지난다.', k:'evade', dc:26,
      ok:`박을 머리에 넣고 몸에 맡겼다. 빠른 똑을 어깨로 비끼고, 느린 똑 앞에서 반 박 멈추고, 큰 똑이 오기 전에 세 걸음을 벌었다.<br><br>혼자 먼저 건너 길을 몸으로 그려 보였다. 여기서 비끼고, 여기서 멈추고.<br>넷이 그 춤을 따라 건넜다. 춤이라 부른 건 넷째다. 끓는 바닥 위에서 추는 춤도 춤이냐고 둘째가 받았다. 다 건넌 다음이라 웃을 수 있었다.`,
      ng:`빠른 똑을 비끼다 느린 똑의 자리에 어깨가 들어갔다. 박이 몸보다 빨랐다.<br><br>한 방울이 어깨에 닿았다. 옷이 연기를 냈다. 둘째가 달려들어 옷을 찢고 물을 부었다.<br>살까지는 반 겹 남기고 멎었다. 어깨에 동전만 한 흉이 남았다. 만지면 아직도 뜨거운 것 같다고, 이쪽은 가끔 거짓말이 아닌 소리를 한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, spirit:-16 } }
  ] },

{ at:'S2', t:'울타리 — 때리는 것들의 박자',
  x:`정원 가장자리는 높은 울타리다. 쇠 그물에 돌기둥. 오래됐지만 서 있다.<br><br>
    밤마다 그것들이 울타리를 때린다. 쿵. 쿵쿵. 쿵. 아무 데나 때리는 것 같지만 북잡이 귀에는 아니다.<br>
    박이 있다. 때리고, 옆 기둥으로 옮겨 때리고, 울림이 긴 데를 두 번 때린다. 울림이 길다는 건 속이 삭았다는 것. 저들은 귀로 울타리를 고르고 있다.<br><br>
    두 번 맞는 기둥이 늘어 간다. 고르기가 끝나 간다는 뜻이다.`,
  o:[
    { l:'① 때리는 박을 받아 적어 저들이 고른 기둥을 먼저 찾는다.', k:'fix', dc:25, wake:1,
      ok:`밤새 박을 받아 적었다. 땅바닥에 금을 그어 가며. 기둥 서른둘, 맞은 수, 울림 길이.<br><br>두 번 맞는 기둥이 셋으로 줄더니 끝밤엔 하나가 됐다. 동쪽 아홉째. 저들의 답이 나온 것이다. 이쪽 답도 같았다. 받아 적은 박이 가리키는 기둥.<br>다섯이 그 기둥에 돌을 쌓고 쇠 그물을 겹으로 묶었다. 그 밤 저들이 왔다. 아홉째를 때렸다. 울림이 짧아져 있었다. 저들이 어리둥절해 서로 우는 소리를 냈다. 답안지를 바꿔치기당한 쪽의 울음이었다.<br><br>박을 받아 적으면 저쪽의 생각이 적힌다. 때리는 박이 글이 되는 것을 처음 봤다. 북잡이는 이제 박을 읽는다.`,
      ng:`받아 적는 밤, 저들 중 하나가 박을 바꿨다. 아무 기둥이나 때리기 시작했다. 엉터리 박.<br><br>적던 금이 엉켰다. 새벽에야 알았다. 엉터리로 때린 건 한 마리고, 나머지는 그 소리에 숨어 서쪽 담을 넘고 있었다.<br>박으로 속이는 짐승이라니. 서쪽 담 안 발자국을 보며 다섯이 말을 잃었다. 그날부터 밤길에 보초가 둘로 늘었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 저들이 고른 기둥 앞에 서서 올 때까지 버틴다.', k:'steady', dc:25,
      ok:`동쪽 아홉째 앞에 섰다. 횃불 둘을 양옆에 꽂고. 저들이 왔다. 그물 너머에서 눈 여섯이 횃불을 받아 번들댔다.<br><br>때리러 온 기둥 앞에 선 것이 버티고 있으면, 저들 셈에 새 줄이 하나 는다. 값이 비싸진다.<br>맨 앞 것이 그물을 한 번 밀어 보고, 이쪽이 안 물러나는 걸 확인하고, 돌아섰다. 오늘 값이 아니라고 판 것이다. 등이 땀으로 다 젖어 있었다. 값을 치를 생각은 이쪽도 없었다.`,
      ng:`기둥 앞에 섰는데 저들이 둘로 갈라졌다. 셋은 이쪽 눈앞에 서고, 둘은 어둠으로 사라졌다.<br><br>눈앞의 셋이 박을 맞춰 그물을 밀었다 놨다 했다. 쿵, 쿵. 눈을 못 떼게.<br>사라진 둘은 열한째 기둥을 조용히 타 넘고 있었다. 뒤에서 일행 비명이 났다. 달려가 횃불을 휘둘러 쫓았다. 셋째 팔뚝에 발톱 고랑이 석 줄 패었다. 셈에서 진 밤이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, mind:-16 } }
  ] },

{ at:'S2', t:'잠긴 양치밭 — 물결의 박',
  x:`양치잎이 물 위로 솟은 벌판이다. 허리까지 잠긴다. 건너는 데 백 걸음.<br><br>
    바람이 불 때마다 잎이 쓸리고 물결이 간다. 사락— 하고. 그 물결에는 박이 있다. 바람의 박.<br>
    사람이 걸어도 물결이 간다. 사람의 박. 물속에 사는 큰 것은 그 차이를 읽는다. 바람의 물결은 흘리고 사람의 물결에만 온다.<br><br>
    그러니 바람이 될 것. 바람의 박으로 걸을 것.`,
  o:[
    { l:'① 바람이 이는 박에만 걷고 잦아들면 선 채로 잠긴다.', k:'fix', dc:25,
      ok:`바람을 등으로 들었다. 등에 닿고 반 박 뒤에 잎이 쓸린다. 그 반 박을 세어, 잎이 쓸릴 때만 걸었다.<br><br>사락— 세 걸음. 고요— 선 채로 숨만. 물이 겨드랑이까지 와도 박을 어기지 않았다.<br>벌판 가운데서 큰 등줄기가 스무 걸음 옆을 지나갔다. 물결을 읽으며. 다섯의 물결은 바람 속에 녹아 있었다. 등줄기가 지나간 자리의 물이 한참 뒤에야 제자리로 돌아왔다. 그만한 부피였다.`,
      ng:`바람이 죽었다. 벌판 한가운데서. 박이 없는 물에 다섯이 서 있었다.<br><br>넷째 다리가 저려 반 걸음 옮겼다. 물결 한 겹이 갔다. 사람의 박으로.<br>물 밑에서 큰 것이 방향을 틀었다. 물이 통째로 밀려왔다. 다섯이 잎 무더기를 끌어안고 숨었다. 콧등 하나가 잎 사이로 지나갔다. 집채만 한 콧등이. 콧김에 물이 끓듯 일었다. 바람이 다시 분 건 반 시진 뒤였다.`,
      win:{ exp:20, dream:3, item:'민물고기' }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 물결이 가라앉기 전에 단숨에 몰아 건넌다.', k:'evade', dc:26,
      doom:{ title:'물결을 읽는 입', what:'물 밑의 큰 것에게 다리를 물려 양치잎 밑으로 가라앉습니다', dc:20, sec:35,
        text:`큰바람이 벌판을 통째로 쓸었다. 물결이 다 섞였다. 지금뿐이다. 뛰어. 다섯이 물을 갈랐다.<br><br>여든 걸음까지 갔다. 바람이 생각보다 먼저 죽었다. 다섯 물결만 벌판에 남았다. 선명하게.<br>물이 발밑에서 꺼졌다. 큰 것이 입을 벌린 것이다. 맨 뒤에 있던 이쪽 다리가 무언가에 감겼다. 이빨이라기엔 부드럽고 혀라기엔 억셌다.<br><br>양치잎들이 머리 위에서 닫힌다. 물속으로. 물결이 박을 세듯 가지런히 번져 나간다.`,
        dieText:`물결이 다 가라앉은 뒤 벌판은 처음처럼 고요했다.<br><br>넷은 벌판을 빙 돌아 이틀 길로 건넜다. 아무도 서두르자고 안 했다.<br>그 뒤로 넷은 물가에서 바람을 기다리는 버릇이 생겼다. 바람이 불면 걷고, 죽으면 선다. 박을 세던 사람이 두고 간 걸음법이다.` },
      ok:`큰바람이 벌판을 쓸었다. 물결이 다 섞였다. 지금이다. 다섯이 물을 갈랐다.<br><br>바람이 죽는 결이 등에 먼저 닿았다. 바람 끝의 박. 멈춰, 소리치며 잎 무더기를 끌어안았다.<br>물결이 가라앉았다. 다섯 숨도. 물 밑의 큰 것이 벌판을 한 바퀴 돌고 제자리로 갔다. 다음 바람에 남은 스무 걸음을 건넜다. 뭍에 오르자 넷째가 무릎으로 주저앉았다. 아무도 안 웃었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'웅덩이 — 동심원의 간격',
  x:`뭍길인데 웅덩이가 줄지어 있다. 걸을 만하다. 그런데 웅덩이마다 물이 떤다.<br><br>
    동심원이 인다. 가운데부터 가장자리로. 잦아들고, 다시 인다.<br>
    큰 것의 걸음이다. 아직 소리는 안 들린다. 땅이 먼저 알고 물이 받아 적는 것이다.<br><br>
    동심원의 간격이 좁아지면 가까워지는 것. 북잡이는 그 간격을 박으로 잰다.`,
  o:[
    { l:'① 동심원의 박을 재어 큰 것의 길과 빠르기를 읽는다.', k:'sense', dc:24,
      ok:`웅덩이 셋을 골라 봤다. 앞엣것, 가운뎃것, 뒤엣것. 동심원이 이는 순서가 길을 그린다.<br><br>앞에서 뒤로. 이 길과 나란히 온다. 간격은 다섯 박에서 넉 박으로. 빨라진다. 사냥 걸음이다. 다만 쫓는 건 이쪽이 아니다. 물결 가운데가 이 길을 비껴 있다.<br>다섯을 길 옆 바위 뒤로 물렸다. 큰 것이 지나갔다. 다른 짐승 하나를 몰면서. 몰리는 짐승의 비명이 멀어질 때까지 아무도 바위에서 등을 안 뗐다.`,
      ng:`간격을 재는데 동심원이 두 겹으로 일었다. 큰 박 사이에 작은 박들. 큰 것 발치에 작은 것들이 따라붙어 온다.<br><br>큰 것 길은 비꼈는데 작은 것들이 길을 훑으며 왔다. 몰이꾼들이다.<br>바위 뒤가 들켰다. 셋이 바위 위로, 둘이 틈으로 흩어졌다. 작은 것 하나가 틈에 머리를 들이밀다 둘째 지팡이에 콧등을 맞고 물러났다. 큰 것이 부르는 울음에 작은 것들이 아쉬운 듯 따라갔다. 틈 속 둘은 반나절을 더 숨어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 동심원이 멎을 때까지 다섯을 그 자리에 세워 둔다.', k:'steady', dc:25,
      ok:`간격이 좁아진다. 뛰어 봤자 큰 것 걸음이 빠르다. 손을 들었다. 전원 정지.<br><br>웅덩이 물이 끓듯 떨었다. 땅이 울렁였다. 넷째 눈이 뛰자고 소리치고 있었다. 손을 안 내렸다.<br>큰 것이 길 저쪽을 가로질러 갔다. 움직이는 건 쫓고 멈춘 건 지나치는 눈이었다. 동심원이 넓어지고, 멀어지고, 물이 다시 하늘만 비췄다. 손을 내렸다. 다섯이 한꺼번에 숨을 토했다.`,
      ng:`손을 들었는데 넷째가 반 박 늦게 봤다. 두 걸음을 더 뗀 뒤였다.<br><br>그 두 걸음의 울림이 땅으로 갔다. 동심원 간격이 단숨에 반으로 줄었다. 이쪽으로 꺾은 것이다.<br>그때부터는 서는 게 아니라 뛰는 셈이었다. 벼랑 틈에 다섯이 구겨져 들어가고 세 박 뒤에 큰 머리가 틈 밖을 막았다. 콧김이 들이쳤다. 밤새 틈 안에서 들숨 날숨을 세며 버텼다. 새벽에야 머리가 치워졌다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-30, mind:-18 } }
  ] },

{ at:'S2', t:'묻고 답하는 울음',
  x:`해 질 녘부터 울음이 오간다. 동쪽에서 꾸우— 하면 서쪽에서 꾸, 꾸— 하고 받는다.<br><br>
    새소리 같지만 아니다. 박이 말이다. 묻고, 답하고, 가끔 셋째 자리에서 짧게 끼어드는 소리가 있다.<br>
    묻는 것과 답하는 것 사이에 이쪽 길이 있다. 저들은 울음으로 이쪽 자리를 주고받는 중이다. 몰이의 박이다.<br><br>
    북잡이는 남의 박에 끼어드는 법을 안다.`,
  o:[
    { l:'① 답하는 울음의 박을 훔쳐 가짜 답을 끼워 넣는다.', k:'fix', dc:26, wake:1,
      ok:`답하는 박을 열 번 들었다. 꾸, 꾸—. 앞이 짧고 뒤가 처진다. 북 가죽을 손바닥으로 눌러 비비면 비슷한 소리가 난다.<br><br>동쪽이 물었다. 서쪽이 답하기 반 박 전에 이쪽이 먼저 답했다. 북 가죽으로. 엉뚱한 자리에서.<br>박이 꼬였다. 서쪽이 뒤늦게 답하자 동쪽이 성을 냈다. 둘의 울음이 서로를 향해 날카로워졌다. 몰이가 말다툼이 됐다. 다섯은 다투는 소리를 등지고 길을 벗어났다.<br><br>박에 끼어드는 것은 북잡이의 오랜 재주다. 짐승의 말에도 박이 있고, 박이 있으면 끼어들 자리가 있다. 가죽을 비비던 손바닥이 새 악기를 하나 얻었다.`,
      ng:`가짜 답을 끼웠는데 동쪽이 속지 않았다. 울음이 뚝 그쳤다.<br><br>박을 아는 것들이었다. 가짜 박은 저들에게도 가짜로 들린 것이다. 그리고 가짜가 난 자리는 정확히 들렸다.<br>양쪽 울음이 동시에 일었다. 이번엔 묻지도 답하지도 않았다. 그냥 왔다. 다섯이 밤 숲을 내리 뛰었다. 가시에 긁히고 뿌리에 걸리며. 물가에 닿아서야 울음이 등 뒤에서 멎었다. 물은 저들의 금 밖이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-20 } },
    { l:'② 울음과 울음 사이 고요한 띠를 따라 숨어 빠진다.', k:'hide', dc:25,
      ok:`묻는 소리와 답하는 소리의 가운데가 몰이의 눈이다. 눈은 소리의 빈 데. 그 빈 데가 띠처럼 길게 누워 있다.<br><br>띠를 따라 걸었다. 몸을 낮추고, 울음이 날 때만 움직이고. 저들의 말소리가 저들의 귀를 막는 때니까.<br>띠 끝이 바위 비탈에 닿았다. 비탈을 올라 몰이 밖으로 나왔다. 돌아보니 울음 두 줄기가 아까 그 자리를 조여들고 있었다. 빈 주머니를 조이는 끈처럼.`,
      ng:`띠를 따라가는데 셋째 자리의 짧은 울음이 가까워졌다. 끼어들던 그 소리. 셋째 울음꾼은 띠 안에 있었다.<br><br>몰이의 눈 속에 하나를 심어 두는 것이다. 그물 속의 송곳처럼.<br>수풀이 터지며 그것이 덮쳤다. 다섯이 흩어졌다. 둘째 등짐이 찢겨 날았다. 바위 비탈로 구르듯 올라 따돌렸다. 짐과 함께 사흘 치 소금을 잃었다. 산 것이 남는 장사라고 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-18 } }
  ] },

{ at:'S2', t:'숲 — 소리가 꺼지는 순서',
  x:`정원의 숲은 소리로 가득하다. 벌레, 물소리, 잎 비비는 소리. 살아 있는 것들의 박.<br><br>
    그 소리가 꺼진다. 한 뼘씩. 저쪽 구석부터 이쪽으로. 벌레가 먼저 입을 닫고, 다음 줄의 벌레가 닫고.<br>
    소리의 어둠이 번져 오는 것이다. 무엇이 걸어오는 길을 따라.<br><br>
    꺼지는 순서를 읽으면 오는 길이 나온다. 살려 달라고 외치는 소리보다 입 닫는 고요가 더 정확한 지도다.`,
  o:[
    { l:'① 고요가 번지는 결을 읽어 오는 길과 빠르기를 긋는다.', k:'sense', dc:25,
      ok:`눈을 감았다. 소리의 벌판을 귀로 봤다. 꺼진 데가 혀처럼 길쭉하다. 혀끝이 길을 따라 온다. 빠르기는 느긋한 네 발.<br><br>혀가 닿기 전에 다섯을 길 밖 바위 등걸로 올렸다. 소리가 발밑까지 꺼졌다. 둘레가 통째로 숨을 참았다.<br>그것이 지나갔다. 보이지는 않았다. 지나간 자리의 벌레들이 한 뼘씩 다시 울기 시작하는 것으로 알았다. 고요가 걷히는 순서는 번지는 순서의 거꾸로였다. 끝까지 정확한 지도였다.`,
      ng:`결을 읽는데 고요가 두 갈래로 번졌다. 두 마리. 한 갈래는 길을 따라, 한 갈래는 길을 질러.<br><br>지르는 쪽을 늦게 봤다. 바위 등걸로 오르는 중에 고요가 발밑에 닿았다.<br>맨 아래 있던 넷째 발꿈치를 무엇이 스쳤다. 신발 뒤축이 통째로 뜯겨 나갔다. 등걸 위에서 밤을 샜다. 발밑의 고요가 걷힐 때까지. 넷째는 맨발 한 짝으로 이틀을 걸었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 꺼진 소리의 한가운데 먹을 것을 놓고 운에 건다.', k:'luck', dc:24,
      ok:`고요의 혀끝에 짐 속 고기 반 덩이를 던져 놓고 반대로 뛰었다.<br><br>고요가 그 자리에서 멈췄다. 오래. 씹는 동안은 고요도 서는 법이다.<br>그 사이 숲을 벗어났다. 운이 좋았던 건 그다음이다. 숲 끝 개울가에 저들이 먹다 둔 사냥감이 있었다. 윗동은 못 쓰게 됐지만 아랫동은 멀쩡했다. 던진 반 덩이보다 많이 거뒀다. 숲에 셈을 치르고 거스름을 받은 꼴이다.`,
      ng:`고기를 던졌는데 고요가 멈추지 않았다. 지나쳤다. 먹을 것보다 급한 일이 있는 걸음이었다.<br><br>그 급한 일이 뭔지는 금방 알았다. 숲 반대편에서 다른 고요와 마주 번지고 있었다. 영역 싸움. 이쪽 길이 그 한복판이었다.<br>두 고요 사이 좁은 소리 띠로 다섯이 내달렸다. 등 뒤에서 두 고요가 부딪치는 소리가 났다. 고요끼리 부딪치면 그런 소리가 난다는 걸 처음 알았다. 산이 우는 소리.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 감아올리는 박자',
  x:`정원을 나가는 길은 낡은 승강기뿐이다. 쇠 바구니에 밧줄 도르래. 손으로 감아올리는 식이다.<br><br>
    감으면 도르래가 운다. 끼익. 끼익. 그 소리가 정원 끝까지 간다. 저녁마다 울타리를 때리던 것들이 이 소리를 모를 리 없다.<br>
    도르래 소리와 숲의 소리를 포개면 된다. 바람이 크게 불 때, 물소리가 높을 때, 그때만 감는 것이다.<br><br>
    다만 그렇게 감으면 오래 걸린다. 바구니는 셋이 타면 찬다. 두 번에 나눠야 한다.`,
  o:[
    { l:'① 바람과 물소리의 박에 맞춰 감고 멈추기를 지휘한다.', k:'fix', dc:25,
      ok:`바람이 일 때 세 바퀴, 죽으면 손 묶기. 물소리가 높을 때 두 바퀴. 감는 손 둘에게 박을 손짓으로 줬다.<br><br>첫 바구니가 셋을 싣고 올랐다. 끼익 소리가 바람 속에 녹았다. 반 시진 걸릴 길이 한 시진 걸렸다. 느린 만큼 조용했다.<br>빈 바구니가 내려오고 남은 둘이 탔다. 마지막 열 바퀴는 위에서 셋이 감았다. 바구니가 턱에 걸리는 순간까지 숲은 이쪽을 몰랐다. 두 번째 바구니에서 내린 둘째가 도르래에 절을 했다. 농이 아니었다.`,
      ng:`물소리 박에 감는데 바람이 갑자기 죽었다. 끼익 소리 반 토막이 맨숨으로 났다.<br><br>숲이 들었다. 멀리서 울음 하나가 일어 그 소리를 짚었다. 받는 울음이 더 가까운 데서 났다.<br>남은 바퀴를 박이고 뭐고 내리 감았다. 바구니가 올라붙는 것과 울타리 쪽 수풀이 터지는 것이 같은 박이었다. 바구니 바닥에 발톱이 긁고 간 고랑 네 줄이 남았다. 신발 바닥 반 뼘 아래였다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 도르래를 부수고 밧줄을 몸으로 당겨 올린다.', k:'break', dc:26,
      doom:{ title:'우는 쇠가 부른 것', what:'터진 도르래 소리에 온 것들에게 바구니째 수풀로 끌려갑니다', dc:19, sec:40,
        text:`우는 도르래가 문제면 도르래를 버리면 된다. 축을 쳐서 빼고 밧줄을 맨손으로 당기기로 했다.<br><br>축을 치는 쇳소리가 생각보다 컸다. 깡. 한 번. 정원 전체에 금이 가는 소리.<br>숲이 일제히 고요해졌다. 그 고요가 이쪽으로 번져 온다. 전속력으로. 바구니에 셋을 밀어 넣고 밧줄을 당겼다. 반도 못 올렸는데 수풀이 터졌다.<br><br>바구니가 옆으로 채였다. 밧줄이 손에서 탄다. 바구니째 수풀 속으로 끌려 들어간다. 안의 셋과 함께. 밧줄 끝을 이쪽이 아직 쥐고 있다. 같이 끌린다.`,
        dieText:`밧줄은 서른 걸음 끌려가다 끊겼다. 끊긴 자리를 넷이 끝내 찾았고, 바구니도 찾았다. 비어 있었다.<br><br>도르래 축을 다시 끼우는 데 이틀이 걸렸다. 넷은 바람이 불 때만 감았다. 세 바퀴, 묶고. 두 바퀴, 묶고.<br>배운 박이었다. 그 박대로만 했다. 올라가는 내내 아무것도 오지 않았다.` },
      ok:`축을 빼기 전에 생각을 바꿨다. 쇳소리가 날 것이다. 대신 도르래에 짐 속 기름 한 줌을 다 먹였다.<br><br>끼익이 끄응 정도로 줄었다. 그 소리면 물소리에 묻힌다.<br>기름 먹은 도르래로 두 번에 나눠 올랐다. 올라와서 보니 손바닥이 밧줄 결대로 벗겨져 있었다. 다섯 다 그랬다. 정원이 받은 마지막 통행세라고 치기로 했다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'밤의 정원 — 재우는 북',
  x:`정원에서의 마지막 밤이다. 내일이면 승강기 턱에 닿는다. 오늘 밤만 넘기면 된다.<br><br>
    그런데 아무도 못 잔다. 울타리 밖에서 그것들이 밤새 돌고, 먼 물에서 큰 것이 뒤척이고. 눈 감으면 소리가 더 크다.<br>
    못 잔 몸은 내일 박을 못 지킨다. 박을 못 지키는 몸은 여기서 제일 먼저 죽는 몸이다.<br><br>
    재우는 것도 북잡이 일이다. 소리를 낼 수 없는 밤에.`,
  o:[
    { l:'① 북을 눕혀 베개 삼게 하고 가죽에 손박을 넣어 준다.', k:'fix', dc:24,
      ok:`북을 눕혀 넷째 머리맡에 뒀다. 가죽에 손바닥을 얹고 박을 눌러 넣었다. 소리가 아니라 떨림으로. 둥, 이 아니라 둥의 그림자만.<br><br>가죽의 떨림이 베갯머리로 간다. 어미 가슴에 얹힌 아기 머리가 듣는 그 박이다. 넷째가 먼저 잠들고, 차례로 다 잠들었다.<br>밤새 손바닥으로 박을 눌렀다. 울타리 밖 도는 소리가 가까워지면 박을 조금 깊게. 멀어지면 얕게. 새벽에 보니 다섯이 다 북 쪽으로 머리를 두고 자고 있었다. 꽃이 해 보듯.`,
      ng:`박을 눌러 넣다가 이쪽이 먼저 졸았다. 손바닥이 가죽에서 미끄러지며 북 테를 쳤다. 딱.<br><br>밤의 정원에서 사람이 낸 첫 소리였다. 울타리 밖 도는 발이 멈췄다.<br>다섯이 깨서 무기를 쥐고 새벽까지 앉아 있었다. 발소리는 울타리를 두 바퀴 더 돌고 갔다. 아무도 이쪽을 탓하지 않았다. 그게 더 뼈아팠다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 번을 서며 깬 사람마다 손목의 맥을 짚어 다시 재운다.', k:'bond', dc:24,
      ok:`하나가 깰 때마다 곁에 가 손목을 짚었다. 맥이 빠르면 아직 꿈 바깥이 무서운 것이다. 맥 위에 손가락으로 느린 박을 얹었다.<br><br>말은 안 했다. 밤에 말소리는 멀리 간다. 박만 줬다. 맥이 가라앉으면 손을 뗐다.<br>그 밤 넷이 번갈아 깼고 넷 다 다시 잠들었다. 아침에 셋째가 말했다. 밤에 누가 손을 잡아 준 꿈을 꿨다고. 꿈 아니라고는 안 했다.`,
      ng:`셋째 손목을 짚는데 셋째가 잠결에 소리를 질렀다. 모르는 손이 무서웠던 것이다.<br><br>비명이 짧게 정원을 갔다. 먼 물에서 큰 것이 몸을 세우는 소리가 받았다.<br>그 뒤로는 재우기는커녕 다 깨어 밤을 샜다. 낮에 걸으며 졸았다. 조는 박만큼 걸음이 어긋났고, 어긋난 걸음을 이쪽이 밤새 다시 세워야 했다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-18, spirit:-22 } }
  ] }

]);

// ------------------------------------------
// 전술가 · 자원 없음
// ------------------------------------------
kJob('tactician', 'S', [

{ at:'S', t:'돌판 — 저쪽의 첫 수',
  x:`쉬기 전에 돌판을 깔았다. 돌 다섯. 하나가 한 사람. 늘 하던 대로.<br><br>
    이번엔 판을 사냥꾼 눈으로 봤다. 저것이라면 어느 돌부터 집을까.<br>
    답이 금방 나왔다. 맨 뒤 왼쪽. 짐이 무겁고 어둠에 가깝고 돌아봐 줄 돌이 멀다. 이쪽이 사냥꾼이라도 그 돌이다.<br><br>
    답이 나오는 판은 틀린 판이다. 답이 안 나올 때까지 다시 짜야 한다.`,
  o:[
    { l:'① 어느 돌을 집어도 답이 안 되게 판을 다시 짠다.', k:'fix', dc:25, wake:1,
      ok:`맨 뒤 왼쪽 돌을 가운데로 넣고, 짐을 셋으로 나누고, 어둠에 가까운 자리는 비웠다. 다시 사냥꾼 눈으로 봤다. 답이 없다. 어느 돌을 집어도 두 돌이 닿는 판.<br><br>그 판대로 자고 그 판대로 걸었다. 밤에 무엇이 다섯 둘레를 세 바퀴 돌았다. 발소리가 자꾸 멈췄다. 고르는 소리다. 끝내 못 골랐다.<br>새벽에 발소리가 떠났다. 굶은 걸음으로.<br><br>판은 이쪽이 쓰려고 짜는 것이었다. 오늘은 저쪽이 못 쓰라고 짰다. 같은 돌로 두 가지 판이 짜진다. 막는 판을 짜는 손은 오늘 처음 쓴 손인데, 쓰자마자 손에 붙었다.`,
      ng:`판을 다시 짰는데 짐 나누기에서 다툼이 났다. 둘째가 제 짐을 안 내놨다. 소중한 것이 들었다며.<br><br>다툼 소리가 어둠에 갔다. 밤에 발소리가 왔다. 고르는 멈춤이 없었다. 다툰 둘 사이, 벌어진 자리로 곧장.<br>횃불을 던져 쫓았다. 둘째 짐이 찢겨 소중하다던 것이 쏟아졌다. 죽은 아우의 신발 한 짝이었다. 아무도 더 말을 안 했다. 판보다 사람이 늘 어렵다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 저것이 고를 돌 자리에 숨어 기다려 본다.', k:'gaze', dc:24,
      ok:`맨 뒤 왼쪽 자리에 짐 무더기를 사람처럼 눕히고, 이쪽은 그 옆 어둠에 엎드렸다. 답안지를 미끼로 깔았다.<br><br>밤중에 그것이 왔다. 과연 그 자리로. 짐 무더기 앞에서 오래 냄새를 맡았다. 이쪽은 그것의 생김을 눈에 다 담았다. 앞다리의 낫, 접히는 목, 귀가 없는 머리.<br>그것이 속은 걸 알고 떠난 뒤에야 숨을 쉬었다. 생김을 아는 사냥꾼과 모르는 사냥꾼은 다른 적이다. 내일부터는 아는 적이다.`,
      ng:`그 자리에 엎드렸는데 그것이 오지 않았다. 대신 반대쪽에서 비명이 났다.<br><br>저것도 이쪽 수를 읽은 것이다. 답이 뻔한 자리는 저쪽에게도 뻔했다. 뻔한 자리에 숨은 이쪽만 자리를 비운 셈이 됐다.<br>달려갔을 때 넷째 어깨에서 피가 흐르고 있었다. 물고 갔으면 끝이었는데 맛만 보고 갔다. 고른 것이다. 다음에 먹을 것을.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-20 } }
  ] },

{ at:'S', t:'몰이 — 열어 준 길',
  x:`사흘째 같은 일이 벌어진다. 가려는 길마다 그것들이 나타나고, 한 길만 비어 있다.<br><br>
    비어 있는 길은 늘 낮은 쪽. 물 냄새가 나는 쪽이다.<br>
    판으로 그려 보면 선명하다. 이건 몰이다. 막는 수 셋에 여는 수 하나. 열린 길 끝에 무엇이 기다리는지는 그려 보지 않아도 안다.<br><br>
    몰이의 약점은 하나다. 모는 쪽 벽이 벽인 척하는 것들로 되어 있다는 것.`,
  o:[
    { l:'① 열린 길을 버리고 막는 벽의 제일 얇은 자리를 뚫는다.', k:'fix', dc:26,
      ok:`막는 수 셋을 다시 셌다. 왼쪽 길의 것은 울음만 컸다. 울음이 큰 것은 몸이 안 오는 자리를 맡은 놈이다. 거기가 얇은 벽이다.<br><br>다섯을 모아 왼쪽 길로 정면으로 밀었다. 울음이 비명처럼 커지더니, 몸이 없는 울음이라 길이 그냥 열렸다. 수풀 뒤에서 작은 것 하나가 울음통만 부풀리고 있다가 달아났다.<br>몰이꾼들이 뒤늦게 판을 접고 쫓아왔지만 몰이가 깨진 사냥은 느리다. 물 냄새가 등 뒤로 멀어졌다.`,
      ng:`얇은 벽이라 읽은 왼쪽에 몸이 있었다. 울음 큰 놈 뒤에 조용한 놈이 겹으로 서 있던 것이다.<br><br>정면으로 민 다섯이 정면으로 받혔다. 셋째가 튕겨 구르고 둘째 창이 부러졌다.<br>흩어져 바위 틈으로 빠졌다. 몰이는 피했는데 값이 셌다. 겹으로 세우는 벽이라니. 판 짜는 놈이 저쪽에도 있다. 그날 밤 돌판을 처음부터 다시 그렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 열린 길로 전속력으로 내달려 몰이보다 빨리 끝에 닿는다.', k:'luck', dc:25,
      doom:{ title:'길 끝에서 기다리는 것', what:'열린 길 끝의 입에게 물려 물가로 끌려갑니다', dc:20, sec:40,
        text:`몰이보다 빠르면 몰이가 아니다. 다섯이 열린 길을 내리 달렸다.<br><br>길 끝은 물가였다. 그리고 비어 있었다. 이긴 줄 알았다.<br>물가가 비어 있던 건 기다리는 것이 물속에 있어서였다. 몰이의 끝은 길 끝이 아니라 물속이었다. 맨 앞을 달리던 이쪽 허리에 물에서 나온 턱이 감긴다.<br><br>끌려 들어간다. 뒤따르던 넷의 발이 물가 진흙에서 멈추는 게 보인다. 물이 귀를 덮는다.`,
        dieText:`물가에는 거품이 오래 일었다. 넷은 물에 못 들어갔다. 들어갈 수 없는 물이었다.<br><br>넷은 왔던 길을 거슬러 몰이꾼들 사이를 뚫고 나갔다. 잃을 게 없는 걸음은 벽도 비킨다.<br>그 뒤로 넷은 열린 길을 믿지 않는다. 길이 열려 있으면 먼저 묻는다. 누가 열었나. 묻는 법을 가르친 사람은 물속에 있다.` },
      ok:`다섯이 열린 길을 내리 달렸다. 다만 길 끝 쉰 걸음 앞에서 이쪽이 먼저 멈춰 섰다.<br><br>길 끝은 물가. 몰이의 끝이 마른 땅일 리 없다. 돌을 주워 물에 던졌다. 물이 돌을 받아먹었다. 크게.<br>물가를 비껴 비탈로 꺾었다. 몰이꾼들이 뒤에서 울었다. 길 끝의 것도 물속에서 울었다. 배달이 안 온 자들의 울음이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'불침번 — 외워진 순서',
  x:`불침번은 늘 같은 순서였다. 이쪽, 둘째, 셋째, 넷째, 다섯째. 두 시진씩.<br><br>
    오늘 새벽 넷째 번에 그것이 울타리 밖까지 왔다 갔다. 발자국이 남았다. 그제 새벽에도 넷째 번이었다.<br>
    넷째가 제일 눈이 어둡다. 저것이 그걸 안다. 순서를 외운 것이다. 번을 서는 다섯 중 누가 제일 무른지까지.<br><br>
    외워진 판은 죽은 판이다.`,
  o:[
    { l:'① 번 순서를 밤마다 제비로 바꾸고 바꾼 티를 안 낸다.', k:'fix', dc:25, wake:1,
      ok:`저녁마다 돌 다섯을 주머니에서 뽑아 순서를 정했다. 뽑기는 어둠이 못 외운다. 이쪽도 내일 순서를 모르니까.<br><br>그리고 한 가지 더. 누가 서든 넷째의 헛기침을 흉내 내게 했다. 밖에서 듣기엔 매일 밤 같은 순서로 들리게.<br>사흘째 새벽, 그것이 넷째 번인 줄 알고 왔다. 서 있던 건 눈 밝은 다섯째였다. 횃불이 정통으로 날아갔다. 그것은 눈썹을 태우고 달아났다. 외운 답이 틀리는 밤, 저것들은 시험을 포기한다.<br><br>판을 바꾸는 것만으론 모자란다. 바뀐 걸 숨겨야 수가 된다. 겉은 그대로 두고 속만 바꾸는 수. 오늘 그 수를 처음 놓아 봤다.`,
      ng:`제비로 바꿨는데 바꾼 티가 났다. 목소리가, 발소리가, 밤마다 달랐으니.<br><br>저것은 순서 외우기를 포기하는 대신 더 단순한 수로 왔다. 매일 밤 오기.<br>닷새 연속 울타리 밖에서 발소리가 돌았다. 다섯이 다 못 잤다. 못 잔 다섯은 낮에 느렸다. 느려진 걸음을 저것이 바위 위에서 내려다보고 있었다. 서두르지 않는 눈으로.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 넷째 번 그대로 두고 그 시간에 둘이 서게 한다.', k:'steady', dc:25,
      doom:{ title:'외워진 시간', what:'넷째 번 시간에 울타리 틈으로 끌려 나갑니다', dc:19, sec:45,
        text:`순서는 안 바꿨다. 넷째 번에 이쪽이 몰래 겹으로 섰다. 어둠 쪽에 숨어서.<br><br>그것이 왔다. 넷째만 보고. 울타리 틈으로 낫 같은 앞다리가 들어와 넷째 발목을 긁어 당겼다. 이쪽이 뛰쳐나가 넷째 허리를 잡았다.<br>그런데 저것이 놓지 않는다. 둘인 걸 알고도 놓지 않는다. 둘이어도 당길 만하다고 센 것이다. 넷째와 이쪽이 같이 울타리 틈으로 끌린다.<br><br>틈이 좁아 둘이 같이는 안 나간다. 저것이 그걸 깨닫고 하나를 고르는 중이다.`,
        dieText:`울타리 틈에는 긁힌 자국과 뜯긴 옷자락이 남았다. 넷째는 안쪽에 남았다. 겹으로 선 사람이 바깥쪽이 된 것이다.<br><br>넷은 울타리 틈을 돌로 다 메웠다. 밤새.<br>번 순서는 그날로 제비뽑기가 됐다. 겹으로 서자던 사람의 수는 반만 맞았다. 겹으로 서되, 숨지 말고 둘 다 보이게. 넷은 그렇게 고쳐 썼다.` },
      ok:`순서는 안 바꿨다. 넷째 번에 이쪽이 겹으로 섰다. 숨지 않고, 횃불 둘을 켜고, 둘이 나란히.<br><br>그것이 왔다가 울타리 밖에서 멈췄다. 외운 판과 다르다. 하나여야 할 자리에 둘, 어두워야 할 자리에 불.<br>저것은 외운 것과 다른 판 앞에서 수를 다시 세는 종류였다. 세는 동안 새벽이 왔다. 저것들의 시간이 끝났다. 발자국이 왔던 길로 돌아가 있었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'짐의 셈 — 제일 느린 하나',
  x:`쫓기는 무리에서 사냥감이 되는 건 제일 느린 하나다. 저것들은 무리를 안 잡는다. 하나를 잡는다.<br><br>
    느린 하나를 만드는 건 다리가 아니라 짐이다. 짐을 판에 올려 봤다. 둘째 짐이 돌덩이다. 물과 연장을 혼자 지고 있다.<br>
    둘째는 말이 없는 사람이라 무겁다고 안 했다. 판에는 그게 다 보인다.<br><br>
    제일 느린 하나가 없는 무리. 그게 이 판의 답이다.`,
  o:[
    { l:'① 짐을 다섯 등에 다시 셈해 걸음 빠르기를 고르게 맞춘다.', k:'fix', dc:24,
      ok:`짐을 다 풀어 바닥에 깔았다. 무게가 아니라 걸음으로 나눴다. 다리 긴 다섯째가 물을, 어깨 넓은 이쪽이 연장을, 둘째에게는 가볍고 소중한 것만.<br><br>둘째가 사양했다. 판을 보여 줬다. 네가 느리면 네가 아니라 무리가 죽는다. 둘째가 짐을 내놨다.<br>그날 오후 그것들이 한 번 따라붙었다. 무리 꼬리를 재는 눈으로. 꼬리가 없었다. 다섯 걸음이 똑같았다. 반 시진을 따라오다 값이 안 맞는 사냥이라 접고 갔다.`,
      ng:`짐을 다시 나눴는데 넷째가 물통을 맡고 반나절 만에 지쳤다. 걸음이 고르긴 한데 다 같이 느려졌다.<br><br>고른 걸음과 빠른 걸음은 다르다. 느리고 고른 무리는 그냥 느린 밥이다.<br>해 지기 전에 바위 지대까지 못 닿았다. 밤을 벌판에서 났다. 밤새 둘레를 도는 발소리를 들으며, 짐 셈을 처음부터 다시 했다. 이번엔 걸음과 힘을 둘 다 판에 올렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 둘째에게 짐이 무거운지 바로 묻는다.', k:'bond', dc:23,
      ok:`판을 접고 그냥 물었다. 무겁지. 둘째가 한참 있다 고개를 끄덕였다.<br><br>어깨끈 자국이 속옷에 피로 배어 있었다. 사흘째였다고 한다. 말하면 짐이 남에게 가니까 말을 안 한 것이다.<br>짐을 나누고, 상처에 약초를 붙였다. 둘째 걸음이 그날로 돌아왔다. 판이 못 읽는 것이 있다. 짐을 지겠다고 거짓말하는 마음 같은 것. 그건 물어야 나온다.`,
      ng:`물었더니 둘째가 안 무겁다고 했다. 두 번 물어도 같았다.<br><br>판은 무겁다는데 입은 아니라니, 입을 믿어 줬다. 그게 틀렸다. 이틀 뒤 둘째가 비탈에서 무릎이 꺾였다.<br>구르는 둘째를 넷이 달려들어 잡았다. 물통이 혼자 비탈을 다 굴러 내려가 바위에서 터졌다. 물 없는 이틀이 시작됐다. 입보다 판을 믿었어야 했다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'미끼 수 — 수를 읽는 놈',
  x:`외길 어귀에 그것이 자리를 잡았다. 비키지 않는다. 힘으로는 안 될 크기다.<br><br>
    미끼를 쓰기로 했다. 왼쪽 수풀에 소리를 내서 시선을 떼고 오른쪽으로 빠지는, 늘 쓰던 수.<br>
    돌을 던지기 전에 손이 멈췄다. 저것 눈이 이미 오른쪽을 보고 있다. 이쪽 판을 먼저 읽은 것이다.<br><br>
    수를 읽는 놈에게는 읽힐 수를 하나 더 얹어야 한다.`,
  o:[
    { l:'① 읽힐 가짜 수 위에 진짜 수를 한 겹 더 짠다.', k:'fix', dc:26, wake:1,
      ok:`왼쪽에 돌을 던졌다. 저것이 안 속고 오른쪽을 본다. 여기까지가 저것의 셈.<br><br>다섯이 오른쪽으로 달리는 척 세 걸음을 떼자 저것이 오른쪽으로 몸을 날렸다. 그 순간 다섯이 왼쪽으로 꺾었다. 던진 돌 쪽으로. 읽은 놈은 읽은 대로 움직인다. 움직인 몸은 비운 자리를 못 지킨다.<br>왼쪽 수풀을 뚫고 외길에 올랐다. 등 뒤에서 저것이 두 수 늦은 걸 깨닫고 울었다.<br><br>한 수는 읽힌다. 읽힌 수를 믿게 하고 그 믿음을 딛는 두 번째 수. 가짜 밑에 진짜를 까는 판. 오늘부터 이쪽 판은 두 겹이다.`,
      ng:`가짜 위에 진짜를 짰는데 저것이 두 겹을 다 읽었다. 몸을 안 날리고 외길 복판에 그대로 섰다.<br><br>수 싸움에서 지면 힘 싸움이 남는다. 힘 싸움은 처음부터 안 되는 판이었다.<br>물러나 반나절을 돌았다. 벼랑 허리의 좁은 턱으로. 둘째가 턱에서 미끄러져 팔꿈치가 깨졌다. 저것은 외길 어귀에서 이쪽이 돌아가는 걸 끝까지 지켜봤다. 눈이 마주칠 때마다 수를 세는 눈이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 좁은 어귀로 유인해 바위를 무너뜨려 덮친다.', k:'break', dc:26,
      doom:{ title:'덫을 되밟는 발', what:'제가 판 덫 자리에서 그것에게 뒷덜미를 물려 끌려갑니다', dc:20, sec:40,
        text:`어귀 위 비탈에 바위를 괴어 덫을 놨다. 밑으로 유인해 괸 돌을 빼는 수. 이쪽이 미끼를 맡았다.<br><br>저것이 따라왔다. 덫 자리 바로 앞에서 멈췄다. 코를 들어 괴어 둔 바위 냄새를 맡는다. 사람 손 냄새가 나는 돌을.<br>그리고 돌아서 비탈 위로 올라갔다. 괸 돌을 빼는 넷째 쪽으로. 덫을 아는 놈은 덫 놓은 손부터 문다.<br>이쪽이 비탈을 거슬러 뛰었지만 저것이 빨랐다. 아니, 저것은 처음부터 이쪽을 기다렸다. 덫 주인이 덫을 살리러 올 것까지 읽은 것이다. 뒷덜미가 물린다. 끌려간다. 제가 놓은 덫 밑을 지나서.`,
        dieText:`괸 바위는 그대로 남았다. 아무도 못 건드렸다. 저것이 그 밑을 제집 문턱처럼 드나들었기 때문이다.<br><br>넷은 벼랑 허리로 돌았다. 이틀 길이었다.<br>돌판은 넷째가 물려받았다. 서툴게나마 밤마다 깐다. 첫 줄은 늘 같다. 덫을 놓으면 덫 옆에 서지 말 것. 물려받은 판의 첫 가르침이다.` },
      ok:`어귀 위 비탈에 바위를 괴었다. 다만 사람 냄새를 지웠다. 괸 자리에 그것들의 똥을 문질러 두고, 괸 돌 빼는 줄을 길게 늘여 바람 반대편까지 뺐다.<br><br>이쪽이 미끼로 어귀를 지났다. 저것이 따라붙었다. 덫 자리에서 코를 들었다. 제 무리 냄새뿐이다. 한 걸음 더.<br>줄을 당겼다. 바위가 쏟아졌다. 깔리진 않았다. 저것들은 빠르다. 그래도 어귀가 바위로 메워졌다. 길과 저것이 바위벽으로 갈라졌다. 그거면 충분했다.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 수 싸움을 접고 저것이 자리를 비우는 때를 기다린다.', k:'luck', dc:24,
      ok:`수가 안 먹히면 때를 사는 수밖에. 바위 뒤에 숨어 한나절을 기다렸다.<br><br>해 질 녘에 멀리서 울음이 났다. 저것들의 말로 뭔가 급한 울음. 외길의 그것이 일어나 울음 쪽으로 달려갔다.<br>그 틈에 외길을 내달렸다. 운이 산 때였다. 다 건너고 나서 뒤를 보니 저것이 외길 저쪽 끝에 돌아와 서 있었다. 비운 사이 지나간 걸 아는 눈으로. 다음엔 안 비울 것이다. 다음이 없기를 빌었다.`,
      ng:`한나절을 기다렸는데 저것이 안 비웠다. 밤이 됐다. 밤은 저것들의 시간이다.<br><br>어둠 속에서 저것 눈이 바위 뒤 이쪽을 정확히 향했다. 처음부터 알고 있었다. 기다리기 싸움을 받아 준 것뿐이다.<br>밤길을 되돌아 뛰었다. 벼랑 허리 턱에서 밤을 났다. 벼랑은 저것들도 밤엔 안 탄다. 그것만 믿고 매달려 잤다. 손가락이 아침까지 안 펴졌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S', t:'좁은 목 — 지나는 순서',
  x:`바위 틈 좁은 목이다. 한 사람씩만 지난다. 지나는 데 스무 숨.<br><br>
    틈 너머는 안 보인다. 틈 이쪽은 트인 벌판. 뒤에서는 아까부터 그것들이 거리를 재며 따라온다.<br>
    한 사람이 틈에 든 동안 밖의 넷이 벌판을 등져야 한다. 마지막 하나는 혼자 남는다.<br><br>
    순서가 전부인 판이다. 누가 먼저 들고 누가 마지막에 남나.`,
  o:[
    { l:'① 창 긴 순서로 남기고 눈 밝은 순서로 들여보낸다.', k:'fix', dc:25,
      ok:`틈 너머가 안 보이니 먼저 드는 쪽도 사지일 수 있다. 눈 밝은 다섯째를 먼저. 틈 너머에서 괜찮다는 휘파람이 왔다.<br><br>다음은 다친 둘째, 그다음 짐 무거운 순. 밖에는 창 긴 이쪽과 넷째가 남아 벌판을 등졌다. 그것들이 거리를 반으로 줄였다. 창 둘이 버티는 동안 셋이 다 들어갔다.<br>넷째를 들여보내고 이쪽이 마지막으로 틈에 등부터 들어갔다. 창끝을 벌판으로 둔 채 뒷걸음으로. 그것들이 틈 앞까지 와서 코만 들이밀다 말았다. 창끝 하나 거리를 끝까지 못 좁힌 것이다.`,
      ng:`눈 밝은 다섯째를 먼저 보냈는데 틈 너머에서 비명이 왔다. 너머에도 기다리는 것이 있었다.<br><br>순서가 다 엉켰다. 둘이 틈으로 쑤셔 들어가고 셋이 벌판을 등지고.<br>틈 너머의 것은 작은 놈이라 다섯째가 창대로 버텨 냈다. 벌판의 것들은 엉킨 틈을 보고 달려들었다. 마지막 둘이 틈에 몸을 구겨 넣는데 발톱이 장딴지를 긁었다. 양쪽에 적을 둔 틈새에서 순서란 참 사치였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, spirit:-16 } },
    { l:'② 틈에 다섯째만 세우고 넷이 벌판에서 그것들을 맞받는다.', k:'evade', dc:25,
      ok:`도망치는 등은 물기 좋은 등이다. 거꾸로 했다. 다섯째만 틈을 지키고 넷이 벌판에 부채꼴로 섰다. 맞서는 낯으로.<br><br>그것들이 멈췄다. 쫓던 사냥감이 돌아서면 저들 판이 깨진다. 몰이는 등을 모는 수지 낯을 모는 수가 아니니까.<br>맞선 채로 한 발씩 물러나 차례로 틈에 들었다. 등을 끝까지 안 보였다. 그것들은 벌판 끝에서 낯만 노려보다 돌아갔다.`,
      ng:`부채꼴로 맞섰는데 한 놈이 판을 깨고 덮쳤다. 어린 놈. 몰이를 아직 덜 배운.<br><br>덜 배운 수가 제일 어렵다. 읽을 판이 없으니. 넷이 뒤엉켜 구르고 창대가 부러졌다.<br>어린 놈이 코피를 흘리며 물러난 틈에 다들 틈으로 쏟아져 들어갔다. 마지막 사람 신발 한 짝이 벌판에 남았다. 어린 놈이 그걸 물고 흔드는 소리가 틈 안까지 들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, mind:-14 } }
  ] },

{ at:'S', t:'판 위의 판 — 발자국이 그리는 수',
  x:`길에 그것들 발자국이 어지럽다. 다들 피해 갈 생각만 한다.<br><br>
    전술가 눈에는 발자국이 수다. 두 줄이 나란히 가다 한 줄이 꺾이고, 꺾인 자리에 기다린 자국이 깊다.<br>
    이건 몰이 연습이다. 저들이 쓰는 수가 땅에 다 적혀 있다. 모는 수, 막는 수, 기다리는 수.<br><br>
    적의 판을 공으로 얻는 자리다. 읽을 수만 있다면.`,
  o:[
    { l:'① 발자국을 따라 걸으며 저들의 몰이 수를 통째로 외운다.', k:'gaze', dc:25, wake:1,
      ok:`발자국 위에 발을 포개며 저들의 수를 따라 걸었다. 모는 놈은 크게 돌고, 막는 놈은 미리 가 있고, 기다리는 놈은 바람 밑에 엎드린다.<br><br>세 수를 다 외웠다. 그리고 보였다. 이 수의 구멍. 기다리는 놈은 늘 바람 밑이다. 바람 위로 몰리면 저들의 판에 기다리는 수가 없다.<br>이틀 뒤 저들이 진짜 몰이를 걸어 왔다. 다섯은 바람 위 비탈로만 돌았다. 몰이가 반나절 헛돌다 흩어졌다.<br><br>적의 연습장을 읽은 것이다. 판은 종이에만 적히지 않는다. 땅에도, 발자국에도 적힌다. 세상이 다 기보로 보이기 시작했다.`,
      ng:`발자국을 따라 걷다 너무 깊이 들어갔다. 연습장이 아니라 사냥터 한복판이었다.<br><br>기다린 자국이 깊다 했는데, 그 자국에 아직 주인이 엎드려 있었다.<br>바람 밑에서 그것이 일어섰다. 다섯이 사방으로 흩어졌다. 수를 읽으러 갔다가 수에 들어가 앉은 꼴이다. 바위 지대까지 쫓기며 넷째 등짐이 찢겼다. 판 읽기에도 거리라는 게 있다는 걸 몸으로 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 발자국의 깊이로 저들의 수와 몸집부터 가늠한다.', k:'sense', dc:24,
      ok:`자국 깊이를 쟀다. 손가락 두 마디. 몸집은 황소만 하다. 보폭으로 다리 길이, 꺾임의 각으로 몸놀림까지.<br><br>수는 여섯. 큰 놈 하나에 작은 놈 다섯. 큰 놈 자국만 안 꺾인다. 큰 놈은 몰지 않는다. 받기만 한다.<br>그 셈을 다섯에게 알렸다. 여섯이 오면 큰 놈 반대로 뛸 것. 사흘 뒤 그 셈이 둘째 목숨을 구했다. 큰 놈 반대편 수풀이 비어 있었던 것이다. 셈대로.`,
      ng:`깊이를 재러 쪼그린 사이 바람이 돌았다. 이쪽 냄새가 발자국 주인들 쪽으로 갔다.<br><br>멀리서 울음이 한 번. 받는 울음이 두 번. 자국이나 재던 다섯이 쫓기는 수가 됐다.<br>개울을 거슬러 뛰어 냄새를 끊었다. 신발이 다 젖고 해가 졌다. 몸집 셈은 맞았다. 황소만 한 여섯이 개울가에서 반나절을 서성이다 갔으니. 맞은 셈 치고는 비싸게 치렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'상처 — 피 흘리는 판',
  x:`셋째가 허벅지를 베였다. 싸매도 피 냄새는 싸매지지 않는다.<br><br>
    이 어둠에서 피 냄새는 봉화다. 바람이 부는 쪽마다 피 냄새가 깃발처럼 나부낀다.<br>
    판에 올리면 이렇다. 다섯 중 하나가 봉화를 지고 걷는다. 봉화를 버릴 수는 없다. 봉화째 움직이는 판을 짜야 한다.<br><br>
    피 냄새도 수로 쓸 수 있을까. 그 생각이 먼저 든 게 조금 무서웠다.`,
  o:[
    { l:'① 바람을 등지고 걷게 진형을 반 시진마다 틀어 짠다.', k:'fix', dc:25,
      ok:`냄새는 바람의 길로만 간다. 셋째를 늘 바람 꼬리에 세웠다. 냄새가 지나온 길로만 가게.<br><br>바람이 돌면 진형도 돌렸다. 반 시진마다. 걷는 길이 지렁이처럼 굽었지만 냄새는 늘 등 뒤로만 흘렀다.<br>저녁에 바위산에 닿았다. 뒤따르던 것들은 냄새의 길을 거슬러 갔다. 이쪽이 지나온 빈 길을. 봉화를 지고도 봉화가 안 보이는 판. 짜 놓고도 신기했다.`,
      ng:`바람 꼬리에 세운다고 세웠는데 골짜기 바람은 책대로 안 분다. 소용돌이쳤다.<br><br>냄새가 사방으로 흩어졌다. 사방에서 울음이 받았다.<br>그때부턴 판이고 뭐고 뜀박질이었다. 바위 턱에 다섯이 올라붙고 나서야 셋째 상처가 다시 터진 걸 알았다. 지혈을 새로 하며 밤을 났다. 골짜기에선 바람부터 읽을 것. 판 귀퉁이에 그렇게 새겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 피 밴 천을 미끼로 반대쪽에 묻어 둔다.', k:'heal', dc:24,
      ok:`상처를 새로 싸매고, 피 밴 헌 천을 챙겼다. 반 마장 반대쪽 바위 밑에 묻었다. 얕게. 바람이 파 주게.<br><br>그것들이 그 봉화로 몰렸다. 바위 밑을 파헤치는 소리가 밤바람에 실려 왔다.<br>그 밤 다섯은 반대쪽으로 조용히 걸었다. 셋째 상처는 새 약초 덕에 아침까지 마른 채였다. 피는 짐이지만, 흘린 피는 수가 된다. 셋째가 제 피값을 했다며 처음으로 웃었다.`,
      ng:`천을 묻으러 간 길에 이쪽 냄새가 더 남았다. 산 사람 냄새가 죽은 피 냄새보다 짙었던 것이다.<br><br>그것들이 천을 지나쳐 발자국을 따라왔다. 미끼를 놓으러 간 길이 미끼가 됐다.<br>개울로 뛰어들어 냄새를 끊고 한 바퀴를 돌아 일행과 만났다. 흠뻑 젖은 이쪽을 보고 아무도 안 물었다. 셋째만 미안한 낯으로 제 허벅지를 내려다봤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'포위 — 세 방향과 선물',
  x:`밤 벌판에서 포위당했다. 북에 둘, 동에 하나, 서에 하나. 남쪽만 비었다.<br><br>
    남쪽은 완만한 내리막이다. 달빛도 밝다. 달리기 좋은 길.<br>
    판에 올리면 셈이 안 맞는 포위다. 넷이서 셋을 막고 하나를 비웠다. 비운 게 아니라 내준 것이다. 선물이다.<br><br>
    선물 받은 쪽이 값을 치른다. 늘.`,
  o:[
    { l:'① 선물을 사양하고 북쪽 둘 사이를 쐐기로 뚫는다.', k:'fix', dc:26, wake:1,
      ok:`제일 두터운 데가 제일 방심한 데다. 둘이 선 북쪽은 저들 셈에 이쪽이 절대 안 올 방향. 그래서 둘 사이가 벌어져 있다.<br><br>다섯을 쐐기로 짰다. 창 둘이 날, 셋이 몸통. 함성 없이, 신호 없이, 달빛이 구름에 든 한 숨에 내달렸다.<br>둘 사이를 지나는 데 다섯 숨. 저들이 상황을 깨닫는 데 열 숨. 쫓아오는 발소리가 벌어진 채 안 좁혀졌다. 포위한 자리에서 다시 모이는 데 시간을 쓴 것이다. 선물을 걷어찬 값으로 산 시간이었다.<br><br>포위의 셈은 빈 데가 아니라 두터운 데서 푼다. 거꾸로 읽는 판. 오늘 밤 그 독법을 몸에 넣었다.`,
      ng:`북쪽 둘 사이로 쐐기를 박았는데 둘 사이가 벌어진 게 아니라 벌려 둔 것이었다.<br><br>선물이 두 개였던 판이다. 남쪽 큰 선물, 북쪽 작은 선물. 둘 사이에 든 다섯 위로 양쪽 턱이 닫혔다.<br>쐐기가 흩어졌다. 각자 구르고 베고 빠져나왔다. 다섯이 다 성한 데가 없었다. 벌판을 벗어나 세어 보니 그래도 다섯이었다. 수를 두 겹 쓰는 짐승들과의 첫 판. 진 판인데 다 살았으니 반쯤 이긴 걸로 쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-18 } },
    { l:'② 남쪽 내리막으로 달리되 중간에 방향을 꺾는다.', k:'hide', dc:26,
      doom:{ title:'선물의 값', what:'내리막 끝 구덩이에서 기다리던 것에게 끌려 들어갑니다', dc:20, sec:38,
        text:`내리막을 받되 끝까지 안 가는 수. 중간의 바위 무더기에서 꺾어 숨기로 했다.<br><br>다섯이 내리막을 달렸다. 등 뒤의 셋이 쫓는다. 바위 무더기가 보였다. 꺾었다.<br>바위 뒤가 구덩이였다. 파 놓은 지 오래된, 뼈가 깔린 구덩이. 꺾을 자리까지 셈에 넣은 판이었다. 선물의 값은 내리막 끝이 아니라 중간에 있었다.<br><br>구덩이 속에서 기다리던 것이 이쪽 발목을 감아 당긴다. 뼈들 사이로. 위에서 쫓던 셋의 머리가 구덩이 가장자리에 나란히 걸린다. 구경하는 낯으로.`,
        dieText:`구덩이 쪽에서는 한참 아무 소리도 안 났다. 그게 제일 나빴다.<br><br>넷은 내리막을 끝까지 달려 벌판을 벗어났다. 끝에는 아무것도 없었다. 선물은 처음부터 중간에 있었으니까.<br>넷은 그 뒤로 꺾을 자리를 고를 때 꼭 묻는다. 이 자리, 저들도 골라 둔 자리 아닌가. 묻는 버릇은 구덩이에 두고 온 사람 몫이다.` },
      ok:`내리막을 받되 끝까지 안 가는 수. 다만 꺾을 자리를 이쪽이 고르지 않았다. 좋아 보이는 바위 무더기는 저들도 셈에 넣었을 테니.<br><br>아무것도 없는 맨비탈 중간에서 꺾었다. 숨을 데 없는 데라 셈에 안 들어간 자리.<br>다섯이 풀에 납작 엎드렸다. 쫓던 셋이 바위 무더기부터 둘러쌌다. 거기 숨었다고 센 것이다. 빈 바위를 뒤지는 사이 다섯은 풀밭을 기어 벌판을 빠져나왔다. 무릎이 다 까졌지만 셈값으론 쌌다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'잠든 사이 — 바뀐 판',
  x:`아침에 돌판을 보고 숨이 멎었다. 돌이 움직여 있다.<br><br>
    다섯 돌이 흩어지고, 그 둘레에 잔돌 일곱이 반달꼴로 놓였다. 이쪽 다섯을 안쪽에 두고.<br>
    사람 장난이 아니다. 잔돌마다 긴 발가락 자국이 찍혀 있다.<br><br>
    저것들 중 하나가 밤에 와서, 이쪽 판 위에 저쪽 판을 두고 갔다. 수를 아는 놈이 수를 보낸 것이다. 읽으라고.`,
  o:[
    { l:'① 반달꼴의 뜻을 끝까지 읽어 낸다.', k:'gaze', dc:26,
      ok:`반달꼴을 뜯어 봤다. 일곱 잔돌의 사이가 고르지 않다. 한 사이만 넓다. 서남쪽.<br><br>포위도가 아니다. 이건 몰이도다. 일곱이 반달로 몰고 서남쪽으로 빠지게 하는. 즉 내일 서남쪽은 길이 아니라 아가리다.<br>거꾸로 갔다. 반달의 등을 넘는 쪽으로. 가장 험하고 가장 안전한 길. 이틀 뒤 서남쪽 골짜기에서 다른 짐승의 뼈가 새로 널린 걸 멀리서 봤다. 초대에 응한 것의 뼈였다.`,
      ng:`반달꼴을 반나절 들여다봤다. 뜻이 안 잡혔다. 포위인지 몰이인지 경고인지.<br><br>읽다 지쳐 그냥 동쪽으로 갔다. 동쪽 비탈에서 저것들과 정통으로 마주쳤다. 일곱. 반달꼴 그대로.<br>판을 보냈는데 안 읽고 엉뚱한 데로 온 이쪽을, 맨 앞 놈이 가만히 봤다. 한심해하는 눈 같았다. 싸움 없이 비켜 주긴 했다. 글 모르는 짐승은 사냥감 축에도 못 드는 모양이었다. 그게 제일 치욕이었다고, 전술가는 두고두고 말했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 답판을 짜서 같은 자리에 두고 떠난다.', k:'fix', dc:26, wake:1,
      ok:`읽기만 하면 받기만 하는 판이다. 답을 두기로 했다. 잔돌 일곱 반달 맞은편에 돌 다섯을 쐐기꼴로 박았다. 반달의 가장 두터운 데를 겨눠서.<br><br>뜻은 하나다. 몰리지 않는다. 치면 가운데로 받아친다.<br>그 밤 발소리가 와서 판 앞에 오래 머물다 갔다. 다음 날도, 그다음 날도 몰이가 없었다. 수를 아는 놈들은 수를 안 받아 주는 상대를 가장 꺼린다. 값이 안 나오니까.<br><br>판으로 말을 주고받았다. 사람 아닌 것과. 수담이라는 말을 이런 데 쓰게 될 줄 몰랐다. 판이 말이 되는 경지의 문턱 하나를 넘었다.`,
      ng:`답판을 짰는데 너무 잘 짰다. 쐐기꼴에 허세가 아니라 진심이 담겼다. 이쪽 진짜 진형이.<br><br>다음 몰이에서 저들이 그 쐐기를 깨는 수로 들어왔다. 날을 먼저 꺾는 수. 답판이 답안지를 내준 꼴이 됐다.<br>창 둘이 부러지고 나서야 진형을 버리고 흩어져 빠졌다. 적에게 보내는 판에는 가짜를 담을 것. 수담에도 거짓말이 필요하다는 걸, 부러진 창값으로 배웠다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-18 } }
  ] },

{ at:'S', t:'물러나는 수 — 땅을 팔아 시간을 산다',
  x:`동굴 어귀를 지키는 판이 밤새 밀리고 있다. 그것들이 번갈아 치고 빠진다. 지치게 하는 수다.<br><br>
    새벽까지 버티면 저들이 물러날 것이다. 문제는 새벽까지 다섯 팔이 남아나질 않겠다는 것.<br>
    판을 바꿔야 한다. 어귀를 버리고 안쪽 좁은 목으로. 땅을 팔아 시간을 사는 수.<br><br>
    물러나는 수가 제일 어렵다. 등을 보이는 순간이 꼭 한 번은 오니까.`,
  o:[
    { l:'① 하나씩 교대로 물러나는 차례를 짜서 등을 지운다.', k:'fix', dc:25,
      ok:`둘이 치는 동안 하나가 물러나고, 물러난 하나가 자리 잡으면 다음 하나. 차례를 다섯 번 짰다.<br><br>등을 보이는 사람 앞에는 늘 창 둘이 있었다. 등이 있는데 등이 안 보이는 판.<br>좁은 목까지 다섯이 다 물러났다. 그것들이 어귀를 차지하고 들어왔다가 좁은 목 앞에서 멈췄다. 하나씩만 들어올 수 있는 데서는 번갈아 치는 수가 안 선다. 새벽까지 좁은 목은 조용했다. 땅값을 제대로 받은 밤이었다.`,
      ng:`차례를 짰는데 세 번째 교대에서 넷째가 차례를 어기고 먼저 뛰었다. 등이 났다.<br><br>그 등으로 하나가 날아들었다. 둘째 창이 그걸 옆에서 받았다. 창대가 부러지며 둘째 손바닥이 찢어졌다.<br>엉킨 채로 좁은 목까지 밀려 들어갔다. 판은 지켰는데 손이 하나 상했다. 차례는 머리가 아니라 겁이 어긴다. 다음부터 겁 많은 순서를 차례 첫머리에 뒀다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 어귀에 횃불 벽을 세워 물러나는 등을 가린다.', k:'bond', dc:24,
      ok:`마른 가지를 어귀에 한 줄로 쌓게 했다. 치고 빠지는 사이사이, 다섯이 조금씩.<br><br>물러날 때가 되자 한꺼번에 불을 질렀다. 불의 벽. 그 뒤로 다섯이 등을 돌렸다.<br>불 너머에서 그것들이 울었다. 불은 저들 눈에 벽보다 단단하다. 좁은 목에 닿을 때까지 아무것도 불을 안 넘었다. 새벽에 재만 남은 어귀에 발자국이 어지러웠다. 재 앞에서 밤새 서성인 자국이었다.`,
      ng:`가지를 쌓는 사이사이가 저들 눈에 띄었다. 수를 들킨 것이다.<br><br>불을 지르기 전에 저들이 먼저 쳤다. 쌓은 가지를 흩뜨리며. 불 없는 맨 어귀에서 마지막 교대가 엉켰다.<br>셋째 어깨가 긁히고 나서야 좁은 목에 다 들었다. 수는 맞았는데 손이 느렸다. 판 짜는 시간도 판에 넣어야 한다는 것. 그 밤의 셈서리에 적혔다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'도면 — 수가 안 맞는 환풍구',
  x:`벽에 시설 도면이 붙어 있다. 바래고 찢겼지만 읽힌다. 복도, 방, 환풍구.<br><br>
    도면의 환풍구는 구역마다 넷. 걸어오며 센 덮개는 다섯이었다.<br>
    도면에 없는 관이 하나 있다. 나중에 뚫린 관. 사람이 안 뚫은 관.<br><br>
    도면과 땅이 다를 때, 그 다름이 가장 중요한 정보다.`,
  o:[
    { l:'① 덮개를 다 세어 도면에 없는 관을 찾아 표시한다.', k:'sense', dc:25, wake:1,
      ok:`구역을 되짚으며 덮개를 다 셌다. 도면에 없는 건 늘 구석, 그늘, 눈이 덜 가는 자리에 있었다. 뚫은 쪽이 사람 눈을 아는 것이다.<br><br>없는 관 셋을 찾아 도면에 그려 넣었다. 그러자 보였다. 셋이 다 한 방향으로 모인다. 깊은 층. 저들의 길은 저들의 집으로 모이는 법이다.<br>그날부터 다섯은 없는 관 밑을 지날 때만 창을 세웠다. 있는 관은 바람 길이고 없는 관이 저들 길이니까.<br><br>도면은 종이가 아니라 어긋남을 읽는 물건이다. 종이와 땅의 차이에 적이 산다. 세는 눈이 한 겹 깊어졌다.`,
      ng:`덮개를 세며 걷는데 다섯째 덮개 밑에서 걸음이 너무 오래 멈췄다. 그리는 데 정신이 팔려서.<br><br>덮개가 소리 없이 들렸다. 위에서 긴 것이 반쯤 내려왔다. 둘째가 소리쳤다.<br>구른 자리로 발톱이 바닥을 긁었다. 불꽃이 튀었다. 복도 끝까지 내리 뛰었다. 도면에 관 하나는 그려 넣었다. 하마터면 도면에 이쪽 이름이 적힐 뻔했지만.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 도면에서 저들 관이 못 닿는 방을 골라 쉴 자리로 잡는다.', k:'fix', dc:24,
      ok:`도면 위에 없는 관까지 다 그려 넣고 거꾸로 봤다. 관이 안 지나는 방이 어디냐.<br><br>딱 하나 있었다. 두꺼운 벽으로 둘러싸인 네모난 방. 문도 쇠문이다. 전에 귀한 걸 두던 방인 듯했다.<br>다섯이 그 방에서 이틀 만에 처음 다리를 뻗고 잤다. 천장에서 긁는 소리가 밤새 오갔지만 이 방 위로는 지나는 관이 없다. 도면이 보증한 잠이었다.`,
      ng:`관이 안 닿는 방을 골랐는데 도면이 낡은 게 문제였다. 벽 하나가 이미 뚫려 있었다. 산에 녹은 구멍.<br><br>한밤에 그 구멍으로 작은 것이 들어왔다. 다행히 다섯째가 깨어 있었다.<br>소동 끝에 쫓아내고 구멍을 쇠 선반으로 막았다. 도면은 종이고 산 것들은 산을 쓴다. 종이가 못 따라가는 속도로. 그 뒤로 방을 고르면 벽부터 두드려 봤다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S1', t:'에어록 — 둘씩 넘기는 순서',
  x:`에어록은 한 번에 둘까지다. 문이 돌고 바람이 빠지는 데 쉰 숨.<br><br>
    다섯이니 세 번. 쉰 숨씩 세 번이면 백쉰 숨. 복도 끝에서 발톱 소리가 다가오는데.<br>
    누가 먼저 넘고 누가 마지막에 남나. 마지막 조는 발톱 소리와 가장 가깝게 선다.<br><br>
    짝 짓기가 전부다. 판 중의 판이다.`,
  o:[
    { l:'① 싸울 둘을 마지막에, 다친 하나를 첫째에 넣어 짝을 짠다.', k:'fix', dc:25, wake:1,
      ok:`첫째 조는 다친 셋째와 눈 밝은 다섯째. 둘째 조는 짐꾼 둘. 마지막 조는 창 쥔 이쪽과 둘째.<br><br>마지막 쉰 숨 동안 발톱 소리가 복도 모퉁이를 돌았다. 창 둘이 문을 등지고 섰다. 보이는 적과 세는 숨. 마흔아홉, 쉰. 문이 열렸고 둘이 뒷걸음으로 들었다.<br>닫히는 문틈으로 발톱이 하나 들어왔다 끼였다. 문이 더 세게 닫혔다. 잘린 발톱이 바닥에 굴렀다. 유리 너머에서 그것이 제 발을 들여다보는 걸, 다섯이 다 봤다.<br><br>순서는 힘센 순도 빠른 순도 아니다. 마지막에 설 수 있는 순이다. 그 순서를 읽는 눈이 판의 반이다.`,
      ng:`짝은 잘 짰는데 둘째 조에서 틈이 났다. 짐꾼 둘이 짐 때문에 문에 걸린 것이다.<br><br>문이 짐을 물고 안 돌았다. 쉰 숨이 백 숨이 됐다. 복도의 발톱 소리는 그만큼 가까워졌다.<br>짐 하나를 포기하고서야 문이 돌았다. 마지막 조는 숨이 턱에 닿은 채 넘었다. 짐도 판에 넣을 것. 사람 수만 세는 판은 반쪽 판이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 쉰 숨을 줄이려 바람 빼는 관을 창대로 열어 둔다.', k:'steady', dc:25,
      ok:`쉰 숨의 절반은 바람 빠지기를 기다리는 숨이다. 옆 벽의 바람 관 덮개를 창대로 비틀어 열었다. 바람이 양쪽으로 빠지니 문 도는 틈이 반으로 줄었다.<br><br>쉰 숨이 스물다섯 숨. 세 번이 일흔다섯 숨.<br>발톱 소리가 복도 모퉁이를 돌았을 때 마지막 조가 이미 문 안에 있었다. 유리 너머로 그것이 빈 복도를 두리번대는 게 보였다. 셈이 빨랐던 쪽이 이긴 것뿐이다.`,
      ng:`관 덮개를 비트는데 관이 삭아 통째로 부러졌다. 바람이 쇳소리를 내며 뿜어 나왔다.<br><br>복도 끝 발톱 소리가 그 쇳소리를 듣고 내달려 왔다.<br>세 번 넘을 순서를 두 번으로 구겨 넣었다. 셋이 한 번에 끼어 넘는 반칙. 문이 삐걱대며 겨우 돌았다. 마지막 조가 넘을 때 유리에 그것의 낯이 눌렸다. 문 하나 사이였다. 쉰 숨을 아끼려다 다섯 목숨을 걸었던 셈이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S1', t:'표본 장부 — 빈 병의 셈',
  x:`기록실에 장부가 남아 있다. 표본 번호, 들어온 날, 상태. 마지막 장은 글씨가 흐트러져 있다.<br><br>
    장부의 표본은 마흔둘. 표본실에서 센 성한 병이 스물여섯, 깨진 병이 열하나.<br>
    셈이 안 맞는다. 다섯이 빈다. 깨지지도 남지도 않은 다섯. 마개를 녹이고 저 발로 나간 것들이다.<br>
    복도에서 지금껏 마주친 건 셋.<br><br>
    둘이 남는다. 장부가 말하는 것은 그것이다. 아직 둘이 더 있다.`,
  o:[
    { l:'① 장부의 상태 칸을 읽어 남은 둘의 생김을 가려낸다.', k:'gaze', dc:25,
      ok:`빈 병 다섯의 번호를 장부에서 찾았다. 셋은 이미 만난 것들과 크기가 맞다. 남은 둘. 하나는 "유체, 수중 적응". 하나는 "성체, 천장 보행, 접근 금지"에 밑줄 셋.<br><br>물과 천장. 남은 둘의 집이 나온 것이다.<br>그날부터 물가에선 물을 보고 복도에선 천장을 봤다. 사흘 뒤 천장 것과 마주쳤을 때, 다섯은 올려다보며 걷던 중이라 반 숨 먼저 흩어질 수 있었다. 반 숨이 전부였고, 반 숨이면 충분했다.`,
      ng:`장부를 읽는 데 너무 오래 머물렀다. 기록실은 조용하고 의자는 멀쩡해서.<br><br>천장 환기구에서 긴 것이 소리 없이 내려오고 있었다. "천장 보행"을 읽던 바로 그 순간에.<br>다섯째가 던진 램프가 그것의 머리에 맞았다. 불이 붙자 그것이 비명을 지르며 관으로 되올라갔다. 장부는 챙겨 나왔다. 읽을 곳은 골라야 한다. 정보가 있는 방은 저들도 아는 방이니까.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-18 } },
    { l:'② 장부째 챙기고 깨진 병 열하나의 번호도 마저 센다.', k:'luck', dc:24,
      ok:`장부를 통째로 챙겼다. 그리고 깨진 병 번호까지 다 맞춰 봤다. 깨진 열하나 중 둘이 "먹이용 소동물" 칸이었다.<br><br>먹이용이 깨졌다는 건 누가 먹었다는 것. 즉 근처에 먹은 놈이 산다는 것. 그 구역을 크게 돌아갔다.<br>돌아간 길의 창고에서 밀봉된 생수 상자를 찾았다. 장부에 적힌 비품 창고였다. 셈은 끝까지 맞춰 보는 쪽이 늘 상을 받는다.`,
      ng:`번호를 세는데 장부 마지막 장의 흐트러진 글씨가 자꾸 눈에 밟혔다. 읽어 버렸다.<br><br>"문이 안에서 열렸다. 세는 걸 멈추면 안 된다. 마흔둘, 마흔셋, 마흔넷—" 장부의 표본은 마흔둘까지다.<br>마흔셋과 마흔넷이 무엇인지는 적혀 있지 않았다. 그 밤 다섯은 번갈아 깨며 서로의 수를 셌다. 다섯. 다섯. 밤새 다섯이었는데도 세기를 멈출 수 없었다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'S1', t:'배전반 — 불과 문의 셈',
  x:`배전반이 반쯤 살아 있다. 남은 전기로 돌릴 수 있는 건 둘 중 하나. 복도 불이거나, 구역 문이거나.<br><br>
    불을 켜면 길이 보인다. 대신 문이 다 열린 채다. 문을 돌리면 구역이 잠긴다. 대신 어둠 속을 걷는다.<br>
    판에 올리면 이건 맞바꿈이다. 눈과 벽. 둘 다는 없다.<br><br>
    저들은 어둠에서 눈이 밝고, 열린 문을 길로 쓴다. 어느 쪽을 내주나.`,
  o:[
    { l:'① 눈을 내주고 벽을 산다 — 문을 돌려 구역을 등 뒤로 잠근다.', k:'fix', dc:25,
      ok:`불을 포기했다. 지나온 구역 문이 차례로 잠기게 전기를 문 쪽으로 몰았다.<br><br>어둠 속을 손끝으로 벽을 짚으며 걸었다. 느렸다. 무서웠다. 대신 등 뒤에서 쿵, 쿵, 문 닫히는 소리가 따라왔다. 세상에서 제일 든든한 소리였다.<br>뒤쫓던 발톱 소리가 세 번째 문에서 끊겼다. 긁는 소리가 한참 나다 멎었다. 눈은 빌려 쓸 수 있다. 손끝으로, 귀로. 벽은 빌릴 데가 없다. 그래서 벽을 샀다. 판은 맞았다.`,
      ng:`문 쪽으로 전기를 몰았는데 낡은 배전반이 셈을 어겼다. 문이 등 뒤만 잠기지 않고 앞길까지 잠겼다.<br><br>어둠 속, 잠긴 문 앞에 다섯이 갇혔다. 뒤에서는 발톱 소리.<br>배전반까지 되돌아 뛰어 전기를 다시 돌렸다. 문이 열리는 순서를 이번엔 손으로 하나씩 돌렸다. 느린 셈이 정확한 셈이었다. 앞문이 열리고 뒷문이 닫히기까지, 복도 하나를 사이에 두고 발톱 소리와 같이 걸었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 불도 문도 아닌 세 번째 줄을 찾는다 — 승강 설비.', k:'break', dc:26,
      doom:{ title:'내려간 바구니', what:'전기 먹은 승강 바구니에 실려 깊은 층으로 내려갑니다', dc:19, sec:45,
        text:`배전반 구석에 세 번째 줄이 있었다. 승강 설비. 아래층으로 곧장 내려가는 길.<br><br>줄을 올리자 복도 끝 쇠 바구니가 웅 하고 살아났다. 다섯이 탔다. 단추를 눌렀다.<br>바구니가 내려간다. 눌렀던 층을 지나친다. 단추가 말을 안 듣는다. 전기가 남은 쪽으로 가는 것이다. 전기를 제일 많이 쓰는 데로. 깊은 층으로.<br><br>바구니 틈새로 깊은 층의 더운 바람이 올라온다. 비린 바람. 바구니가 마중 나온 것들 한가운데로 실려 내려간다.`,
        dieText:`바구니는 한참 뒤에 혼자 올라왔다. 비어 있었다. 바닥이 긁혀 있었다.<br><br>넷은 승강 줄을 내리고 계단을 찾았다. 사흘이 걸렸다.<br>그 뒤로 넷은 전기가 어디로 흐르는지부터 센다. 흐르는 끝에 뭐가 사는지도. 편한 길의 값을 먼저 묻는 버릇. 바구니에 실려 간 사람이 남긴 버릇이다.` },
      ok:`배전반 구석에 세 번째 줄이 있었다. 승강 설비. 올리기 전에 줄을 끝까지 눈으로 따라갔다.<br><br>줄이 깊은 층 표시까지 이어져 있다. 전기는 낮은 데로 고인다. 바구니를 타면 깊은 층까지 실려 갈 판이었다.<br>승강 줄은 버리고, 그 옆 비상 계단의 잠금만 전기로 땄다. 계단은 제 발로 걷는 길이라 셈이 어긋날 데가 없다. 걸어 내려가는 두 층이 바구니 한 층보다 멀고, 훨씬 가까웠다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'살아남은 자 — 셈이 안 맞는 사람',
  x:`창고 구석에서 사람을 찾았다. 연구복 차림. 살아 있다. 이름을 대고, 물을 받아 마시고, 운다.<br><br>
    반가움은 반 숨이고 셈이 먼저 돌았다. 장부 옆에 있던 근무 명단, 서른하나. 복도에서 센 죽은 사람 자국, 서른.<br>
    하나가 남는 셈은 맞다. 그런데 착륙 뒤 석 달이다. 물도 먹을 것도 없는 창고에서 석 달.<br><br>
    셈이 안 맞는 건 수가 아니라 시간이다.`,
  o:[
    { l:'① 먹을 것을 건네며 석 달의 셈을 조용히 맞춰 본다.', k:'fix', dc:26,
      ok:`마른 고기를 건네며 지나가듯 물었다. 물은 어디서 구했소. 그가 벽의 배관을 가리켰다. 이슬이 맺힌다고. 먹을 건. 그가 선반 밑 쥐덫들을 가리켰다. 녹슨 덫에 털이 엉겨 있었다.<br><br>배관엔 정말 이슬이 맺혔고 덫은 정말 쓰던 덫이었다. 셈이 맞아 들어갔다. 다만 하나, 그가 고기를 받아 문 순간 확인했다. 씹는 박자. 사람은 겁에 질려도 어금니로 씹는다. 그도 어금니로 씹었다. 울면서.<br>셈이 다 맞는 사람이었다. 다섯이 여섯이 됐다. 석 달을 버틴 사람의 길눈은 도면 열 장 값을 했다.`,
      ng:`셈을 맞춰 보는 눈길이 너무 셈이었다. 그가 알아챘다. 당신들 날 의심하는군.<br><br>그가 입을 닫았다. 석 달 버틴 사람의 길눈이 입과 함께 닫혔다.<br>이틀을 데면데면 걸은 뒤에야 둘째가 제 몫의 물을 건네며 겨우 풀었다. 그는 수로 다뤄질 때 제일 아픈 게 사람이라고 했다. 판에 사람을 올릴 때는 올리는 걸 들키지 말 것. 아픈 가르침이었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 그의 눈동자와 손톱 밑을 가까이서 응시한다.', k:'gaze', dc:25,
      ok:`부축하는 척 가까이서 봤다. 눈동자는 사람 눈이다. 다만 손톱 밑이 까맣다. 기름때가 아니라 긁어 모은 흙과 녹.<br><br>그리고 소매 안쪽, 팔뚝에 제 손톱으로 그은 금이 빼곡했다. 날짜 셈. 아흔두 줄.<br>석 달을 하루하루 세어 버틴 사람이었다. 셈하는 사람은 셈하는 사람을 알아본다. 그 금들이 어떤 증명서보다 확실했다. 그를 부축한 손에 처음으로 힘이 들어갔다.`,
      ng:`들여다보는 눈이 길었다. 그가 움찔하며 물러났다. 그 바람에 선반이 넘어가며 요란한 소리가 났다.<br><br>복도 저쪽에서 긴 것이 대답했다. 쇠 긁는 소리로.<br>여섯이 창고 뒷문으로 쏟아져 나와 내달렸다. 그는 뛰면서 길을 외치고 있었다. 왼쪽, 배관 밑, 둘째 문. 석 달의 길눈이었다. 의심은 그 복도에 두고 왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'여왕의 방 — 두 길의 셈',
  x:`깊은 층의 끝. 나가는 승강 통로는 여왕의 방 건너편이다. 길은 둘뿐이다.<br><br>
    아래 길. 알 사이를 지나는 바닥 길. 넓고 평평하고, 알이 깨는 철이 아니라면 비어 있다.<br>
    위 길. 천장에 매달린 쇠 발판 길. 좁고 삭았고, 여왕의 눈높이를 지난다.<br><br>
    돌판에 두 길을 올렸다. 아래는 때의 셈, 위는 무게의 셈. 어느 셈이 더 믿을 만한가.`,
  o:[
    { l:'① 알 깨는 철을 셈해 아래 길의 때를 잡는다.', k:'fix', dc:26, wake:1,
      ok:`깨진 알 껍데기들을 봤다. 마른 정도가 다 다르다. 제일 최근 것이 보름 전. 장부의 번식 기록은 마흔 날 간격. 다음 깸까지 스무닷새가 남은 셈이다.<br><br>바닥 길은 지금이 가장 비는 때다. 다섯이 알 사이를 한 줄로 지났다. 알들은 돌처럼 고요했고 여왕은 천장 그늘에서 제 알만 굽어봤다. 바닥을 기는 것들은 알을 밟지만 않으면 여왕의 눈 밖이다.<br>건너편 승강 통로에 닿아 돌아봤다. 알밭이 달빛 아래 과수원 같았다. 셈만 맞으면 지옥도 지나는 길이 된다.<br><br>때를 세는 판은 처음 짜 봤다. 땅의 판, 수의 판, 그리고 때의 판. 판이 세 겹이 됐다.`,
      ng:`껍데기 셈이 틀렸다. 마른 정도는 보름인데, 깊은 층은 덥고 축축해서 겉마름이 빠른 것이다.<br><br>알밭 한가운데서 알 하나가 몸을 떨었다. 둘이 더 떨었다. 깨는 철이 코앞이었다.<br>다섯이 알 사이를 내달렸다. 여왕이 천장에서 몸을 틀었다. 통로에 구겨져 들어가는 마지막 사람 등 뒤로 알밭이 일제히 금 가는 소리가 났다. 셈에 땅의 더움까지 넣을 것. 살아서 배웠으니 싼 값이다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 위 발판 길로 숨어 여왕의 눈높이를 지난다.', k:'hide', dc:26,
      doom:{ title:'눈높이의 길', what:'여왕에게 발판째 걷어 올려져 둥지 위로 끌려갑니다', dc:20, sec:35,
        text:`쇠 발판에 올랐다. 한 사람씩, 소리 없이. 여왕의 눈높이. 눈만 안 마주치면 되는 길.<br><br>반을 건넜을 때 발판이 울었다. 삭은 쇠가 무게의 셈을 어긴 것이다. 끼익. 길게.<br>여왕의 머리가 돌았다. 눈이 발판을 훑는다. 어둠에 붙어 숨을 죽였지만 여왕의 눈은 어둠을 빼고 본다.<br>긴 팔이 올라온다. 발판 끝을 쥔다. 발판째 걷어 올린다. 그 위에 엎드린 이쪽까지. 둥지 위로. 알들이 내려다보이는 높이로.`,
        dieText:`발판은 둥지 가장자리에 구겨진 채 얹혔다. 쇠가 종잇장 같았다.<br><br>넷은 바닥 길로 내려가 알 사이를 내달렸다. 여왕이 위를 보는 동안 바닥은 비어 있었다. 그 길을 두고 위로 간 셈이 마지막 셈이었다.<br>통로에 닿은 넷은 오래 말이 없었다. 판을 짜던 사람 없이 짜는 첫 판이 시작된 것이다.` },
      ok:`쇠 발판에 오르기 전에 무게의 셈부터 했다. 발판 하나에 한 사람. 삭은 이음매는 창대로 미리 짚어 가며.<br><br>제일 삭은 넷째 칸은 뛰어넘게 했다. 한 사람씩, 여왕이 알 쪽으로 고개를 숙이는 숨에만 한 칸씩.<br>다 건너는 데 한 시진이 걸렸다. 여왕은 끝까지 위를 안 봤다. 위 길은 무게의 셈이 전부고, 셈은 어긋나지 않았다. 내려선 다섯의 무릎이 다 떨리고 있었다는 것만 빼면.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'유인 — 한 구역의 경보',
  x:`나가는 길목을 긴 것 둘이 지킨다. 치울 수 없으면 비우게 해야 한다.<br><br>
    멀리 떨어진 구역의 경보를 울리는 수. 고전이다. 문제는 저들이 고전을 안다는 것이다.<br>
    지난번 소리 미끼에 저들은 하나만 보냈다. 하나는 보고 하나는 남는다. 미끼를 한 번 먹어 본 짐승은 반만 문다.<br><br>
    반만 무는 놈에게는 미끼를 두 겹으로 던진다.`,
  o:[
    { l:'① 경보를 울리고, 남은 하나 몫의 두 번째 미끼를 잇달아 터뜨린다.', k:'fix', dc:26,
      ok:`먼 구역 경보를 울렸다. 하나가 떠났다. 하나는 남았다. 여기까지 저들의 셈.<br><br>쉰 숨 뒤, 반대쪽 구역에서 쇠 선반이 무너졌다. 미리 괴어 두고 줄을 걸어 둔 선반. 남은 하나의 귀가 그쪽으로 섰다. 한 번은 미끼라도 두 번은 사고다. 저들 셈에도 그렇다.<br>남은 하나가 자리를 떴다. 비워진 길목을 다섯이 지났다. 돌아오는 발소리가 등 뒤에서 났을 때 다섯은 이미 문 두 개 너머였다. 미끼는 수가 아니라 겹이 전부다.`,
      ng:`경보를 울렸는데 아무도 안 떠났다. 둘 다 남았다. 미끼를 두 번 먹어 본 놈들은 아예 안 문다.<br><br>두 번째 선반까지 무너뜨렸는데도 귀만 까딱했다.<br>결국 그 밤 길목은 포기했다. 이틀을 돌아 바람 관으로 지났다. 좁고 긴 이틀이었다. 미끼의 수명은 두 번. 장부 귀퉁이에 그렇게 적었다. 다음 어둠에서 쓸 셈이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 미끼 없이 저들의 교대 때를 기다려 틈에 지나간다.', k:'evade', dc:25,
      ok:`지키는 것들에게도 교대가 있다. 이틀을 지켜봤다. 깊은 밤, 여왕의 둥이 느려지는 때에 둘이 번갈아 자리를 비운다. 물 마시러 가는 것이다.<br><br>둘이 겹치게 비는 틈은 없다. 하나가 비는 틈이 두 번 있을 뿐.<br>첫 틈에 셋을, 둘째 틈에 둘을 보냈다. 남은 하나의 눈이 닿지 않는 벽 쪽으로만. 미끼 없이 지나간 길이라 뒤가 조용했다. 저들은 아직도 길목이 뚫린 걸 모를 것이다. 모르는 채로 지키는 보초처럼 허망한 것도 없다.`,
      ng:`교대 틈에 셋을 보냈는데 둘째 틈이 오지 않았다. 그날따라 물을 안 마시러 갔다.<br><br>길목 양쪽에 둘과 셋으로 갈라진 채 반나절. 갈라진 판은 약한 판이다.<br>결국 남은 둘이 풀무 같은 숨을 죽이고 벽 그늘을 반 시진 걸려 기었다. 보초의 꼬리 곁을 지날 때 그 꼬리가 잠결에 한 번 뒤척였다. 다섯이 다시 모였을 때 아무도 입을 못 뗐다. 한참 뒤 넷째가 울었다. 조용히.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S2', t:'울타리 도면 — 모이는 표시',
  x:`정원 울타리를 한 바퀴 돌며 도면을 그렸다. 기둥 서른둘. 그것들이 시험한 자국을 표시했다.<br><br>
    긁은 자국, 민 자국, 이로 집은 자국. 표시가 도면 위에 점점이 찍힌다.<br>
    찍고 보니 자국들이 흩어져 있지 않다. 동쪽 세 기둥으로 몰린다. 날짜가 갈수록 더.<br><br>
    저들은 답을 좁혀 가는 중이다. 시험이 끝나면 본 시험이 온다.`,
  o:[
    { l:'① 저들보다 먼저 동쪽 세 기둥을 보강하고 함정을 겹친다.', k:'fix', dc:25, wake:1,
      ok:`동쪽 세 기둥에 돌을 쌓고 그물을 겹으로 묶었다. 그리고 한 가지 더. 기둥 안쪽에 발 빠지는 구덩이를 팠다. 뚫는 데 성공해도 첫발이 빠지게.<br><br>그 밤 저들이 왔다. 본 시험이었다. 가운데 기둥이 밀리고— 버텼다. 보강한 만큼. 한 놈이 그물 위로 넘어 들어왔다가 구덩이에 앞발이 빠졌다.<br>빠진 놈이 비명을 지르자 나머지가 물러났다. 저들 장부에 적혔을 것이다. 이 울타리는 답이 둘이다. 벽과, 벽 뒤의 셈.<br><br>막는 수와 받아치는 수를 한 자리에 겹쳐 심었다. 겹진 판은 뚫려도 이긴다. 그 이치를 손이 먼저 알았다.`,
      ng:`동쪽을 보강하는 사흘 동안 서쪽이 비었다. 저들이 그걸 봤다.<br><br>본 시험은 서쪽으로 왔다. 시험 자국이 동쪽으로 몰린 것 자체가 이쪽 눈을 묶는 수였는지, 아니면 그저 셈을 바꾼 것인지는 알 수 없다.<br>서쪽 그물이 뜯기고 한 놈이 들어왔다. 횃불 넷으로 몰아 내쫓는 데 밤 반을 썼다. 셋째 팔이 긁혔다. 적의 표시도 수라는 것. 도면에 그 밤의 값으로 적어 넣었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-18 } },
    { l:'② 세 기둥 앞에 번을 겹으로 세우고 본 시험을 정면으로 받는다.', k:'steady', dc:25,
      ok:`동쪽 세 기둥 앞에 창 둘과 횃불 둘을 세웠다. 숨기지 않았다. 너희 답을 안다는 걸 보이는 수.<br><br>저들이 왔다가 불빛 끝에 멈췄다. 답안지가 읽힌 시험은 저들에게도 본 시험이 아니다.<br>사흘을 그렇게 세웠다. 시험 자국이 더는 늘지 않았다. 저들은 답을 좁히는 데 들인 공을 버리고 다른 사냥감 쪽으로 돌았다. 보이는 준비는 반쯤은 겁주기다. 그 반이 먹혔다.`,
      ng:`겹으로 세운 번이 나흘째에 지쳤다. 밤마다 두 사람씩 서는 번은 낮의 걸음을 깎아 먹었다.<br><br>닷새째 밤, 번 서던 둘이 선 채로 졸았다. 저들은 그 밤을 골랐다. 지치기를 기다리는 것도 저들 수였던 것이다.<br>가운데 기둥이 뚫리고 한바탕 소동이 났다. 다 쫓아내고 세어 보니 먹을 것 자루 하나가 없어졌다. 사람이 아니라 자루를 노린 밤이었다. 저들은 이쪽 곳간 사정까지 셈에 넣고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'S2', t:'물길 — 깊이의 판',
  x:`잠긴 벌판을 건너야 한다. 물빛은 어디나 같은데 깊이는 같지 않다.<br><br>
    물풀이 깊이를 말해 준다. 끝이 물 위로 솟은 데는 얕고, 잎이 수면에 누운 데는 한 길, 아무것도 없는 맨물은 바닥 모를 데다.<br>
    판에 올리면 길이 보인다. 얕은 턱이 구불구불 벌판을 가로지른다.<br>
    그런데 그 턱이 한 군데서 끊긴다. 맨물 스무 걸음.<br><br>
    끊긴 자리가 하필 너무 반듯하다. 길이라면 누가 끊었고, 끊었다면 왜.`,
  o:[
    { l:'① 맨물 스무 걸음을 피해 먼 턱으로 크게 돌아 짠다.', k:'fix', dc:25,
      ok:`반듯하게 끊긴 길은 길이 아니라 아가리다. 물속 것들도 길목을 안다. 얕은 턱을 다니는 것들이 있으면 그 턱이 끊기는 데서 기다리면 되니까.<br><br>도면을 다시 짰다. 북쪽으로 반나절 돌면 턱이 끊기지 않고 잇닿는 데가 있다.<br>반나절을 돌았다. 돌아온 턱에서 벌판 가운데 맨물 쪽을 봤다. 수면이 한 번, 길게 밀렸다. 기다리던 것이 자리를 트는 물결이었다. 스무 걸음을 아끼려다 치를 뻔한 값이 그 물결에 다 적혀 있었다.`,
      ng:`북쪽으로 도는 길에 비가 왔다. 물이 불었다. 얕던 턱이 한 뼘씩 가라앉았다.<br><br>판이 물에 지워졌다. 허리까지 오던 물이 가슴까지 왔다.<br>짐을 머리에 이고 더듬더듬 건넜다. 넷째가 한 번 턱을 헛디뎌 맨물에 빠졌다가 둘째 창대를 잡고 올라왔다. 물속에서 뭔가 넷째 신발을 벗겨 갔다. 신발만. 그게 경고인지 입맛 다심인지 아무도 몰랐고, 알고 싶지도 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 무거운 것을 맨물에 던져 기다리는 것의 수를 먼저 본다.', k:'sense', dc:24,
      ok:`짐에서 못 쓰게 된 솥을 꺼내 맨물 한가운데 던졌다. 풍덩.<br><br>물이 끓었다. 솥이 가라앉기도 전에 밑에서 치받는 것이 있었다. 하나가 아니다. 셋. 맨물 스무 걸음에 셋이 포개 기다리고 있었다.<br>수를 보고 나니 판이 쉬웠다. 돌아가는 반나절이 하나도 안 아까웠다. 보이지 않는 적은 셈이 안 되지만, 솥 하나면 보이는 적이 된다. 낡은 솥의 마지막 일로는 과분한 공이었다.`,
      ng:`솥을 던졌는데 물이 고요했다. 비었나 싶어 턱 끝까지 가 봤다.<br><br>고요했던 건 기다림이 깊어서였다. 솥 따위에 몸을 보이는 것들이 아니었다.<br>턱 끝에 선 이쪽 발밑으로 물이 갈라지며 긴 몸이 지나갔다. 스치지도 않고, 그저 지나가 보이기만 했다. 너를 안다는 인사. 다섯이 뒷걸음으로 턱을 물러났다. 그날은 더 못 걸었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S2', t:'무리의 수 — 보이는 둘',
  x:`벌판 가장자리에 그것들 둘이 나타났다. 숨지도 않고, 거리를 둔 채 나란히 걷는다.<br><br>
    보이라고 보이는 것이다. 사냥하는 것들이 몸을 보일 때는 보이는 게 일일 때뿐이다.<br>
    눈을 묶는 수. 그럼 묶인 눈 바깥에 진짜 수가 있다. 발자국 셈으로 이 무리는 다섯이었다. 보이는 둘, 숨은 셋.<br><br>
    숨은 셋이 어디로 올지. 그게 이 판의 전부다.`,
  o:[
    { l:'① 보이는 둘을 등지고 바람 밑 수풀부터 겨눈다.', k:'fix', dc:26, wake:1,
      ok:`숨어 오는 것들은 바람 밑으로 온다. 제 냄새를 감추는 길은 그쪽뿐이니까. 보이는 둘에게 등을 돌리고 바람 밑 수풀에 창 셋을 겨눴다.<br><br>수풀이 멈칫했다. 흔들리다 만 잎이 그 증거였다. 묶으려던 눈이 제 쪽을 보고 있으면 숨은 수는 못 나온다.<br>한참을 그렇게 섰다. 보이는 둘이 먼저 지쳐 울음을 냈고, 수풀 속 셋이 답하며 물러났다. 다섯이 다 모여 떠나는 발소리. 판이 깨진 무리는 미련이 없다.<br><br>보이는 적은 적이 아니라 손가락이다. 손가락이 가리키는 데를 안 보는 눈. 그 눈이 생기면 몰이는 절반이 깨진 것이다.`,
      ng:`바람 밑을 겨눴는데 셋 중 하나가 바람 위로 왔다. 냄새를 버리고 빠르기를 고른 놈.<br><br>등 뒤에서 보이는 둘이 달려들고 바람 위에서 하나가 덮쳤다. 세 방향.<br>둘째가 구르며 창을 휘둘러 길을 텄다. 다섯이 바위 쪽으로 몰려 등을 붙였다. 저들은 반 시진을 노리다 갔다. 바람 밑만 셈한 판의 값으로 다섯 팔뚝에 긁힌 금이 하나씩 났다. 수업료 치고는 균등했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 보이는 둘에게 창을 던져 수를 먼저 깬다.', k:'break', dc:26,
      doom:{ title:'묶인 눈의 값', what:'수풀에서 나온 셋에게 다리를 물려 끌려갑니다', dc:20, sec:38,
        text:`보이는 둘부터 지우면 몰이가 안 선다. 창을 고쳐 쥐고 둘에게 마주 달렸다.<br><br>둘이 물러난다. 거리가 안 좁혀진다. 그제야 알았다. 저 둘의 일은 보이는 게 아니라 끌어내는 것이었다. 이쪽 하나를 무리에서.<br>수풀이 등 뒤에서 터졌다. 숨은 셋. 달려 나온 이쪽과 남은 넷 사이로 정확히.<br><br>다리에 턱이 감긴다. 수풀 안쪽으로 끌려 들어간다. 보이던 둘이 그제야 거리를 좁혀 온다. 구경하는 걸음으로.`,
        dieText:`수풀은 금세 고요해졌다. 넷은 바위에 등을 붙인 채 그 고요를 끝까지 들었다.<br><br>그 뒤로 넷은 수를 셈할 때 꼭 한 줄을 보탠다. 보이는 적의 일이 무엇인가.<br>보이는 건 미끼고, 무리를 쪼개는 게 일이다. 그 줄을 적어 넣은 값이 너무 컸다.` },
      ok:`보이는 둘에게 마주 달리다 열 걸음에서 뚝 멈췄다. 둘이 물러서는 걸 봤기 때문이다.<br><br>싸울 놈들이 물러선다는 건 끌어내는 수라는 것. 그 자리에서 창만 던졌다. 한 발. 맞히려는 창이 아니라 재는 창.<br>창이 땅에 박히자 수풀 세 군데가 동시에 움찔했다. 숨은 셋의 자리가 다 드러났다. 다섯이 그 세 자리를 피하는 쪽으로 물러났다. 창 한 자루 값으로 산 지도였다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'썩은 다리 — 무게의 차례',
  x:`골짜기에 외나무다리가 걸려 있다. 반쯤 썩었다. 밑은 물. 물속엔 아까부터 그림자 하나가 다리 밑을 왔다 갔다 한다.<br><br>
    다리가 버틸 무게는 한 사람. 삭은 가운데 세 걸음이 고비다.<br>
    무게 순서, 짐 나누기, 간격. 셈할 것이 셋이다.<br><br>
    그림자는 서두르지 않는다. 다리가 셈을 틀리기를 기다리는 것이다.`,
  o:[
    { l:'① 가벼운 순서로 건너되 짐은 줄에 매달아 따로 보낸다.', k:'fix', dc:25,
      ok:`사람과 짐을 갈랐다. 짐은 줄에 매달아 다리 밑으로— 는 물이 있으니 안 되고, 다리 위로 끌어 보냈다. 사람 따로, 무게 따로.<br><br>가벼운 넷째부터. 삭은 세 걸음은 발을 다리 양 가장자리 심에만 딛게 했다. 가운데 살은 죽었어도 심은 산 나무다.<br>다섯이 다 건너고 짐 꾸러미 셋도 건넜다. 물속 그림자가 다리 밑에서 길게 한 바퀴 돌고 가라앉았다. 셈이 안 틀리는 사냥감 밑에서 기다림은 공치는 일이다.`,
      ng:`짐을 줄로 끌다가 꾸러미 하나가 다리 가운데서 걸렸다. 흔들어 빼다가 삭은 살이 부서졌다.<br><br>꾸러미가 물로 떨어졌다. 물이 꾸러미를 받아 삼켰다. 소금과 약초가 든 꾸러미였다.<br>그림자는 꾸러미를 뱉지도 않았다. 남은 넷이 심만 딛고 마저 건넜다. 잃은 건 짐 하나인데 물속에 뭐가 사는지 다 본 다음이라, 건너는 발이 두 배로 무거웠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 }, },
    { l:'② 다리를 포기하고 물이 좁아지는 하류를 믿고 걷는다.', k:'luck', dc:24,
      ok:`썩은 다리와 물속 그림자. 둘 다 셈이 안 서는 판은 접는 게 수다. 하류로 걸었다.<br><br>한나절 만에 물이 무릎으로 줄었다. 바닥이 자갈이라 그림자가 숨을 데도 없다.<br>건너는 길에 여울에서 팔뚝만 한 민물고기 두 마리를 작살로 건졌다. 저녁이 두둑해졌다. 돌아가는 길이 늘 손해는 아니다. 판을 접을 줄 아는 것도 판이다.`,
      ng:`하류로 걸었는데 물이 안 좁아졌다. 오히려 벌어졌다. 이 물은 하류가 늪이었다.<br><br>해가 지고 있었다. 결국 썩은 다리로 되돌아왔다. 한나절을 버린 셈.<br>어스름 속에서 심만 딛고 건넜다. 그림자는 어둑한 물에서 더 대담해져 다리 바로 밑까지 떠올라 따라왔다. 마지막 사람이 건널 땐 물 위로 등지느러미 같은 것이 나와 있었다. 다리 널 반 뼘 밑에.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S2', t:'미끼 고기 — 두 사냥꾼의 셈',
  x:`저들이 먹다 만 사냥감이 수풀에 남아 있다. 반 넘게 성하다.<br><br>
    이 고기는 세 가지로 쓸 수 있다. 먹거나, 지고 가거나, 미끼로 쓰거나.<br>
    지고 가면 피 냄새를 지고 가는 것이다. 미끼로 쓰면— 이 정원엔 사냥꾼이 둘이다. 무리와, 물가의 큰 것.<br>
    미끼 하나에 사냥꾼 둘. 판이 저절로 그려진다.<br><br>
    둘이 같은 미끼를 물면 둘은 서로를 문다.`,
  o:[
    { l:'① 고기를 무리 길과 큰 것 길이 겹치는 자리로 끌어다 둔다.', k:'fix', dc:26, wake:1,
      ok:`무리의 발자국 길과 큰 것이 물에서 오르는 길을 도면에 겹쳤다. 겹치는 자리가 한 군데 있다. 물가 모래톱.<br><br>고기를 줄에 묶어 끌어다 모래톱에 뒀다. 끈 자국은 물로 지웠다.<br>해 질 녘에 무리가 먼저 닿았고, 첫 입을 떼기 전에 물이 터졌다. 큰 것. 그 밤 정원의 두 사냥꾼은 서로를 사냥했다. 울음과 물소리가 밤새 갔다. 다섯은 그 소란을 등지고 벌판 반을 건넜다. 정원에 온 뒤 가장 먼 밤길이었다.<br><br>적과 적을 겹치는 판. 미끼 하나로 두 판을 지웠다. 싸움 없이 이기는 수가 제일 큰 수라던 옛말이, 이 지옥에서도 통했다.`,
      ng:`모래톱에 고기를 두고 물러나는 길에 바람이 돌았다. 고기 냄새에 이쪽 손 냄새가 섞여 갔다.<br><br>무리가 모래톱에 닿기 전에 냄새를 갈랐다. 죽은 고기와 산 손. 저들은 산 쪽을 골랐다.<br>밤 숲을 반 시진 쫓겼다. 가시덤불을 세 번 꿰고서야 떨어졌다. 미끼에 손 냄새를 남기다니. 초보 덫꾼도 안 하는 실수의 값을 가시가 받아 갔다. 온몸으로.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-16 } },
    { l:'② 성한 데만 떠서 챙기고 나머지는 그 자리에 둔다.', k:'sense', dc:24,
      ok:`욕심을 반으로 접었다. 뒷다리 성한 데만 떠서 잎에 싸고, 나머지는 그대로 뒀다. 저들 눈에 제 사냥감이 그대로인 것처럼.<br><br>피는 개울물로 씻어 하류로 흘렸다. 지고 가는 건 고기지 냄새가 아니게.<br>그날 저녁 다섯은 정원에 온 뒤 처음으로 배불리 먹었다. 불은 바위 틈에서 연기를 갈라 피웠다. 미끼로 쓸 수 있는 걸 저녁으로 쓴 셈이지만, 배부른 다섯이 배곯은 다섯보다 센 것도 판의 셈이다.`,
      ng:`뒷다리를 뜨는 사이 수풀 저쪽에서 울음이 났다. 주인들이 돌아오는 소리.<br><br>고기를 버리고 뛸까, 들고 뛸까. 반 숨 망설인 게 셈을 어겼다. 들고 뛰었다.<br>피 냄새가 따라왔다. 개울에 고기째 던지고서야 떨어졌다. 빈손에 신발만 젖었다. 사냥감 앞에서 반 숨 넘게 셈하지 말 것. 배가 셈을 이기면 그날이 마지막 셈이다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S2', t:'승강기 — 기다리는 쪽의 진형',
  x:`낡은 승강기는 세 사람이 끝이다. 두 번에 나눠야 한다.<br><br>
    오르는 쪽보다 남는 쪽이 문제다. 바구니가 오르내리는 반 시진, 남은 둘은 정원 바닥에 서 있어야 한다.<br>
    도르래 소리는 저들을 부르는 소리다. 남는 쪽은 소리 한가운데 서는 셈이다.<br><br>
    누가 남고, 남은 둘은 어디에 어떻게 서나. 마지막 판이다.`,
  o:[
    { l:'① 남는 둘의 자리를 벼랑 턱 모서리로 짜고 등을 바위에 붙인다.', k:'fix', dc:25,
      ok:`남는 자리부터 짰다. 승강기 바로 밑은 안 된다. 소리 한가운데니까. 열 걸음 옆 벼랑 턱. 등 뒤는 바위, 양옆은 낭떠러지. 길이 정면 하나뿐인 자리.<br><br>이쪽과 창 긴 둘째가 남았다. 정면에 창 둘을 겨누고 반 시진을 섰다.<br>도르래 소리에 그것들이 왔다. 정면 하나뿐인 자리는 저들 셈에도 비싼 자리다. 수풀 끝에서 어른대기만 하다가, 빈 바구니가 내려오자 둘은 뒷걸음으로 탔다. 마지막까지 창끝은 정면을 떠나지 않았다. 올라가는 바구니 밑에서 그것들이 뒤늦게 모래톱을 긁는 소리가 났다.`,
      ng:`벼랑 턱을 골랐는데 반 시진이 한 시진이 됐다. 위에서 도르래 줄이 엉킨 것이다.<br><br>한 시진은 저들 셈에도 긴 시간이다. 값을 치르고도 남을 시간.<br>수풀에서 둘이 나와 정면을 눌러 왔다. 창 둘로 번갈아 찌르며 버텼다. 바구니가 내려왔을 때 둘 다 창대가 반으로 줄어 있었다. 물어뜯긴 것이다. 턱 밑까지 온 머리통을 창끝으로 밀어내며 탔다. 올라가는 내내 밑에서 바구니 바닥을 치받는 소리가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-16 } },
    { l:'② 남는 둘이 버티는 동안 바구니를 두 번 대신 한 번으로 줄인다.', k:'steady', dc:26,
      doom:{ title:'한 번에 다섯', what:'끊어진 바구니와 함께 정원 바닥으로 떨어져 어둠 속으로 끌려갑니다', dc:20, sec:36,
        text:`두 번 나누는 반 시진이 더 위험하다고 셈했다. 다섯이 한 번에 탔다. 바구니가 버티는지는 바구니만 안다.<br><br>반을 올랐을 때 밧줄이 울기 시작했다. 끼긱. 소리가 셈을 알려 준다. 못 버틴다.<br>바구니가 기울고 밧줄 한 가닥이 끊겼다. 다섯이 뒤엉킨 채 바구니째 미끄러져 내렸다. 바닥에 부딪히는 소리를 정원이 다 들었다.<br><br>수풀이 사방에서 밀려온다. 뒤집힌 바구니 밑에서 다리 하나가 먼저 끌려 나간다. 이쪽 다리다.`,
        dieText:`바구니는 사흘 뒤에도 뒤집힌 채였다. 넷은 밧줄을 고쳐 꼬아 두 번에 나눠 올랐다. 처음 셈 그대로.<br><br>남는 둘은 벼랑 턱에 섰고, 오르는 셋은 숨을 죽였다.<br>무게의 셈을 어기면 어떻게 되는지 넷은 봤다. 그래서 그 뒤로는 어떤 바구니든 적힌 수에서 하나를 뺀 수만 태운다. 뺀 하나는 그 사람 몫이다.` },
      ok:`다섯이 한 번에 타는 셈도 해 봤다. 바구니 바닥 널을 뜯어 봤다. 삭았다. 셈이 바로 나왔다. 안 된다.<br><br>대신 반 시진을 줄이는 쪽으로 머리를 돌렸다. 빈 바구니를 미리 반쯤 내려 두고, 오르는 조가 중간 턱에서 갈아타는 식으로 도르래 길이를 반으로.<br>반 시진이 쉰 숨이 됐다. 남는 둘이 버틸 만한 시간. 두 번째 조가 오를 때 수풀이 움직였지만, 움직임이 닿기 전에 바구니가 턱을 넘었다. 셈을 어기지 않고 셈을 줄였다. 그게 판 짜는 사람의 일이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'발자국 산수 — 담보다 큰 보폭',
  x:`진흙 벌에 발자국이 찍혀 있다. 세 발가락. 자국 하나가 가마솥만 하다.<br><br>
    보폭을 걸음으로 쟀다. 열여섯 걸음. 자국 깊이는 정강이까지.<br>
    셈을 해 봤다. 이 보폭, 이 무게면 키는 정원 담의 갑절이다. 담의 갑절이면— 이 정원에 담을 넘어 들어올 수 있는 것은 없다. 그렇게 믿고 있었다.<br><br>
    넘어온 게 아니라면, 이것은 여기서 태어나 여기서 이만큼 자란 것이다. 이 정원은 생각보다 오래된 우리다.`,
  o:[
    { l:'① 자국의 묵은 정도로 저것의 다니는 길과 때를 가린다.', k:'sense', dc:25,
      ok:`자국들을 짚어 봤다. 마른 것, 축축한 것, 물이 고인 것. 묵은 차례가 길을 그린다.<br><br>저것은 이틀에 한 번 물가와 벌판을 오간다. 길은 늘 같다. 큰 것들은 제 길을 아낀다. 몸이 크면 길을 새로 내는 것도 일이니까.<br>그 길과 때를 도면에 적었다. 남은 날 동안 다섯은 저것의 길을 한 번도 안 밟았다. 마주치지 않은 것이 아니라 마주칠 수 없게 걸은 것이다. 제일 큰 적과는 그렇게 싸운다. 안 만나는 수로.`,
      ng:`자국을 짚으며 벌을 반쯤 들어갔을 때 발밑 진흙이 울렸다.<br><br>이틀에 한 번이라는 셈은 맞았다. 오늘이 그 한 번인 걸 몰랐을 뿐이다.<br>갈대밭에 다섯이 엎어졌다. 열여섯 걸음짜리 보폭이 벌을 가로질렀다. 자국 하나가 넷째 바로 옆에 찍혔다. 튄 진흙에 넷째가 반쯤 묻혔다. 지나간 뒤 넷째를 파내며 아무도 말을 안 했다. 셈은 반만 맞으면 안 맞은 것만 못하다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 저것이 피해 다니는 땅이 어딘지 거꾸로 셈한다.', k:'gaze', dc:26,
      ok:`도면에 자국 없는 데를 칠해 봤다. 자국이 한 번도 안 찍힌 땅. 바위 지대와, 늙은 양치나무 숲.<br><br>바위는 발이 아파서일 테고, 숲은— 가서 보니 알았다. 나무 사이가 좁다. 저 몸은 못 들어온다.<br>그날부터 다섯의 길은 양치나무 숲으로만 났다. 제일 큰 것이 못 오는 땅은 작은 것들에게도 금 그어진 땅인지, 숲은 내내 고요했다. 가장 큰 적의 그늘이 가장 안전한 그늘이 되는 셈. 판이란 가끔 이렇게 뒤집혀야 맞는다.`,
      ng:`자국 없는 땅을 골라 양치나무 숲으로 들었는데, 없는 이유가 하나 더 있었다.<br><br>숲 안쪽은 무리의 둥지였다. 큰 것이 못 오는 땅이라 저들이 새끼를 치는 것이다.<br>새끼 울음이 나기 전에 알아채고 물러났다. 반 걸음 차이였다. 빈 땅엔 빈 이유가 있고, 그 이유는 하나가 아닐 수 있다. 도면 귀퉁이가 또 한 줄 늘었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } }
  ] }

]);

// ------------------------------------------
// 부여술사 · 마력
// ------------------------------------------
kJob('enchanter', 'S', [

{ at:'S', t:'어둠 — 냄새라는 발자국',
  x:`여기 것들은 눈보다 코로 사냥한다. 걸어온 길을 돌아보면 보인다. 냄새의 발자국이.<br><br>
    부여술사 눈에는 냄새도 겹이다. 살갗 위에 땀의 겹, 그 위에 두려움의 겹. 사람은 걸을 때마다 제 겹을 공기에 흘리고 다닌다.<br>
    흘린 겹은 바닥에 눕는다. 끊기지 않는 줄로. 저들에게 그 줄은 밥상까지 그어진 금이다.<br><br>
    겹을 흘리지 않게 봉할 수 있다. 다섯 몸을 다.`,
  o:[
    { l:'① 마력으로 다섯 살갗에 지워짐을 입혀 냄새 줄을 끊는다.', k:'fix', dc:25, cost:{ mana:30 },
      ok:`한 사람씩 목덜미에 손을 얹고 지워짐을 입혔다. 살갗의 겹이 밖으로 새지 않게. 얇게, 숨구멍은 막지 않게.<br><br>다섯이 걸어도 냄새 줄이 안 그어진다. 뒤따르던 콧김 소리가 갈림길에서 길을 잃었다. 왔다 갔다. 줄이 끊긴 자리를 몇 번이고 되밟는 소리.<br>반나절을 벌었다. 입힌 겹은 해 질 녘에 걷혔다. 걷히는 순간 다섯 몸에서 하루 치 냄새가 한꺼번에 풍겼다. 그 전에 물가에 닿아 있었다. 겹의 수명까지가 셈이다.`,
      ng:`지워짐을 입히는데 넷째 겹이 자꾸 밀어냈다. 땀이 너무 많았다. 겹은 젖은 데 잘 안 앉는다.<br><br>넷째 자리만 냄새가 샜다. 다섯 줄 중 한 줄만 그어진 길. 저들에게는 그게 더 읽기 쉬운 금이었다.<br>밤에 넷째 쪽 수풀만 집요하게 어른대는 기척이 있었다. 넷째를 가운데 눕히고 넷이 둘러 잤다. 아무도 그 이유를 입 밖에 안 냈다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 바람의 길을 읽어 냄새가 등 뒤로만 흐르게 걷는다.', k:'sense', dc:24,
      ok:`마력을 아끼는 길도 있다. 바람이다. 풀잎 끝과 볼의 솜털로 바람 길을 읽으며 늘 바람을 낯으로 받고 걸었다.<br><br>냄새는 등 뒤로만 흘렀다. 지나온 길로만. 저들이 줄을 찾아도 그 줄은 늘 이쪽의 과거다.<br>저녁에 한 번 바람이 돌았지만 돌기 전에 볼이 먼저 알았다. 바위 뒤에 숨어 바람이 제자리를 찾을 때까지 기다렸다. 공짜 길은 느리다. 대신 끝까지 공짜였다.`,
      ng:`골짜기에서 바람이 미쳤다. 오른볼로 받던 바람이 한 숨에 왼볼로 돌았다.<br><br>냄새가 앞질러 갔다. 이쪽이 갈 길로. 마중 나온 기척이 길 앞에 깔렸다.<br>길을 버리고 비탈로 붙었다. 반나절 돌아가는 길. 바람은 믿는 것이 아니라 빌리는 것이다. 빌린 것은 언제든 돌려 달라 한다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 고약한 것을 주워 다섯 발에 문질러 냄새를 덮는다.', k:'luck', dc:23,
      ok:`저들 똥 무더기가 길가에 있었다. 코를 막고 그걸 신발 바닥마다 문질렀다.<br><br>사람 냄새 위에 저들 냄새. 겹을 입히는 건 마력만이 아니다.<br>그 길로 이틀을 걸었다. 마주친 작은 것 하나가 코를 벌름대다 비켜 갔다. 식구 냄새가 나는 것은 안 문다. 밤에 다 같이 신발을 벗어 바위 밑에 뒀다. 냄새 덕에 살고 냄새 탓에 저녁맛은 잃었다.`,
      ng:`주운 것이 하필 묵은 것이었다. 묵은 냄새는 죽은 냄새다.<br><br>죽은 식구 냄새를 달고 다니는 다섯을, 지나던 큰 놈이 수상쩍어했다. 걸음을 따라오며 코를 박았다.<br>개울을 만나 신발째 뛰어들고서야 떨어졌다. 겹을 입히려면 산 겹을 입혀야 한다. 마력이든 똥이든 같은 이치였다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'무뎌지는 날 — 겹을 핥는 것',
  x:`아침마다 창날이 무뎌져 있다. 갈아도 하루를 못 간다. 숫돌 탓이 아니다.<br><br>
    부여술사 눈에는 보인다. 날 위의 날카로움 겹이 밤새 얇아진다. 누가 벗겨 가는 것이다.<br>
    쇠는 멀쩡하다. 겹만 사라진다. 이 어둠에는 입힌 것을 먹고 사는 무언가가 있다.<br><br>
    오늘 밤은 날을 세워 두고 지켜보기로 했다.`,
  o:[
    { l:'① 밤새 응시해 겹을 먹는 것의 정체를 본다.', k:'gaze', dc:25, wake:1,
      ok:`삼경에 왔다. 나방 같기도 하고 아지랑이 같기도 한 것들. 창날에 내려앉아 날카로움을 핥는다. 핥린 자리가 뿌예진다.<br><br>쫓지 않고 봤다. 저것들은 겹만 먹는다. 쇠도 살도 안 건드린다. 그리고 진한 겹에 먼저 꼬인다.<br>다음 날부터 저녁마다 돌멩이 하나에 날카로움을 겹겹이 입혀 멀찍이 던져 뒀다. 저것들은 밤새 돌만 핥았다. 창날은 아침까지 시퍼랬다.<br><br>겹을 먹는 것이 있다는 것. 그러면 겹은 미끼도 된다는 것. 입히는 손만 알던 부여가 오늘 밤 낚시를 배웠다.`,
      ng:`삼경까지 버티다 깜빡 졸았다. 깨 보니 창날만이 아니라 이쪽 소매의 질김까지 벗겨져 있었다.<br><br>옷이 삭은 천처럼 변했다. 걸을 때마다 어깨가 나왔다.<br>더 나쁜 건 그다음이다. 겹이 벗겨진 자리에는 겹이 잘 안 앉는다. 핥린 창날은 사흘을 다시 입혀서야 겨우 겹을 물었다. 저것들 침이 그런 모양이었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마력을 들여 날카로움을 밤마다 새로 입는다.', k:'fix', dc:24, cost:{ mana:28 },
      ok:`아침에 벗겨지면 저녁에 입힌다. 다섯 자루 날에 번갈아. 품은 들지만 셈은 선다.<br><br>사흘째부터 요령이 생겼다. 자기 전에 입히지 않고 새벽에 입혔다. 핥는 것들은 밤에만 돈다. 새벽 겹은 하루를 꼬박 산다.<br>날 다섯이 늘 시퍼런 무리가 됐다. 나흘째 길목에서 작은 것 하나가 덤볐다가 첫 창에 깊이 베이고 달아났다. 베인 자리를 보고 저들끼리 뭔가 셈을 고친 듯, 그 뒤로 길목이 조용했다.`,
      ng:`밤마다 입히다 마력이 바닥을 보였다. 닷새째 새벽엔 손끝이 떨려 겹이 고르게 안 앉았다.<br><br>얼룩진 겹은 안 입힌 것만 못하다. 날이 물건을 가려 베었다. 수풀은 베고 뼈는 튕기고.<br>하루를 쉬며 마력을 채웠다. 그동안 창 대신 돌과 몽둥이를 썼다. 부여는 곳간 살림이다. 쓸 데와 아낄 데를 가르는 것부터가 부여라는 걸, 빈 곳간이 가르쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'발소리 — 신발에 입히는 고요',
  x:`자갈밭을 지나야 한다. 밟으면 소리 안 나는 돌이 없는 길. 반 마장.<br><br>
    자갈밭 건너 바위 그늘에 그것이 산다. 낮잠이 깊지만 귀는 깊지 않다.<br>
    신발에 고요를 입히면 된다. 바닥 겹으로. 다만 자갈은 신발끼리 소리를 내는 게 아니라 돌끼리 소리를 낸다. 신발만 입혀서는 반이다.<br><br>
    발 디딘 자리의 돌까지 이어 입혀야 온이 된다.`,
  o:[
    { l:'① 마력으로 신발 바닥에 고요를 입히고 디딜 때마다 돌로 흘린다.', k:'fix', dc:26, cost:{ mana:32 },
      ok:`신발 바닥에 고요를 두껍게 입혔다. 그리고 요령 하나. 겹의 자락을 길게 늘어뜨렸다. 발이 돌에 닿는 순간 겹이 돌까지 흘러내리게.<br><br>첫발을 디뎠다. 돌이 구르는데 소리가 안 난다. 구르는 모양만 있다. 기이한 광경이라 다들 제 발밑을 자꾸 내려다봤다.<br>반 마장을 소리 없이 건넜다. 바위 그늘의 숨소리는 끝까지 고른 낮잠이었다. 다 건너고 겹을 걷자 마지막 자갈 하나가 뒤늦게 또르르 소리를 냈다. 다섯이 그 소리에 제일 놀랐다.`,
      ng:`겹 자락을 늘어뜨리는 셈이 반 발 늦었다. 둘째 발밑에서 돌 하나가 맨소리로 굴렀다. 딱.<br><br>낮잠의 숨이 멎었다. 다섯이 자갈밭 복판에서 돌이 됐다. 바위 그늘에서 머리가 나와 길게 훑었다.<br>고요 입힌 신발이 그나마 값을 했다. 선 자리에서는 아무 소리도 안 샜으니. 머리가 들어가고도 쉰 숨을 더 서 있었다. 다리가 후들거려서 나머지 반은 기다시피 건넜다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 소리 안 나는 큰 돌만 골라 딛고 춤추듯 건넌다.', k:'evade', dc:25,
      ok:`박힌 돌은 안 운다. 구르는 돌이 운다. 반쯤 묻힌 큰 돌만 눈으로 이어 길을 그렸다.<br><br>돌에서 돌로. 보폭이 제각각이라 춤이 됐다. 앞사람 발자국 돌만 밟게 하니 뒤로 갈수록 수월했다.<br>마지막 세 걸음은 돌 사이가 멀어 뛰어야 했다. 한 사람씩, 그것의 숨이 깊어지는 박에 맞춰. 다 건너고 나니 종아리가 남아나질 않았지만 마력은 한 톨도 안 썼다. 아낀 마력은 그날 밤 값을 했다.`,
      ng:`큰 돌만 딛는다고 디뎠는데 하나가 겉만 큰 돌이었다. 밑이 비어 있었다.<br><br>덜컹. 돌이 주저앉으며 옆 자갈을 쏟았다. 와르르.<br>낮잠이 깼다. 다섯이 자갈밭을 그냥 내달렸다. 소리고 뭐고. 바위 그늘에서 나온 것이 자갈밭 가장자리에서 멈췄다. 발바닥이 자갈에 쓸리는 걸 싫어하는 몸이었다. 그 운 하나로 살았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S', t:'벌어진 상처 — 닫힘의 겹',
  x:`둘째 옆구리 상처가 아물다 말고 자꾸 벌어진다. 걸음마다 조금씩 피가 밴다.<br><br>
    피 한 방울이 이 어둠에서는 봉화 한 자루다. 싸매도 스민다. 스민 냄새는 천을 뚫는다.<br>
    상처에 닫힘을 입힐 수 있다. 살이 아니라 상처 자리에. 다만 닫힘은 아묾이 아니다. 겹이 걷히면 상처는 그대로다.<br><br>
    치유가 아니라 봉인이다. 그걸 둘째에게 먼저 말해야 한다.`,
  o:[
    { l:'① 상처에 닫힘을 입혀 피와 냄새를 함께 봉한다.', k:'fix', dc:25, wake:1,
      ok:`둘째에게 먼저 일렀다. 아무는 게 아니다. 잠그는 거다. 둘째가 고개를 끄덕였다.<br><br>상처 자리에 손을 얹고 닫힘을 입혔다. 가장자리부터 가운데로, 뚜껑 덮듯. 피가 멎고 냄새가 끊겼다.<br>이틀을 벌었다. 그 사이 약초 아는 일행이 제대로 치료했다. 겹을 걷을 때 상처가 처음처럼 벌어졌지만 이번엔 싸맬 손이 준비돼 있었다.<br><br>부여로 시간을 산 것이다. 낫게 하는 재주는 없어도 낫는 때까지 버티게 하는 재주. 치유와 부여 사이의 길이 하나 보였다. 좁지만 분명한 길이.`,
      ng:`닫힘을 입혔는데 둘째가 참지 못하고 걸음을 서둘렀다. 겹 밑에서 상처가 제 혼자 벌어졌다.<br><br>겉은 닫혔는데 속이 고였다. 저녁에 둘째 낯빛이 흙색이 됐다.<br>겹을 급히 걷었다. 고인 것이 쏟아졌다. 밤새 짜내고 씻어 내고 다시 싸맸다. 닫힘은 멈춤이지 치료가 아니다. 뚜껑 덮은 솥도 불 위에 있으면 끓는다. 그걸 둘째 몸으로 배우게 한 게 두고두고 미안했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 피 밴 천들을 들고 물가로 가서 빨아 없앤다.', k:'luck', dc:25,
      doom:{ title:'물가의 긴 기다림', what:'핏물 푼 물속의 것에게 손목을 물려 끌려 들어갑니다', dc:19, sec:45,
        text:`피 밴 천을 모아 물가로 갔다. 혼자. 다섯이 움직일 일이 아니라서.<br><br>천을 물에 담그자 핏물이 풀렸다. 연기처럼. 물길을 따라 흘러갔다.<br>핏물은 물속에서도 봉화였다. 하류 쪽 물이 거슬러 밀려온다. 천을 쥔 손목을 물속에서 무언가 감았다. 미끄럽고 억센 것이.<br><br>당긴다. 물가의 돌을 다른 손으로 긁는다. 돌이 하나씩 빠진다. 핏물 풀린 물속으로 끌려 들어간다. 제가 푼 핏물 속으로.`,
        dieText:`물가에는 빨다 만 천들이 가지런히 남아 있었다. 물에 젖은 돌에 손톱 자국 다섯 줄.<br><br>넷은 그 천을 태웠다. 빨지 않고.<br>그 뒤로 넷은 피 밴 것을 물에 안 빤다. 태우거나 묻는다. 물은 냄새를 지우는 데가 아니라 퍼뜨리는 데라는 것. 물가에 간 사람이 남긴 마지막 가르침이다.` },
      ok:`피 밴 천을 모아 물가로 갔다. 다만 물에 담그기 전에 반 숨 멈췄다. 핏물이 풀리면 물길 전체가 봉화가 된다.<br><br>물가를 파서 모래 구덩이에 천을 묻었다. 물이 아니라 물가의 모래에. 냄새는 모래가 느리게 먹는다.<br>묻고 돌아서는데 물속에서 무언가 길게 지나갔다. 담갔으면 만났을 것이다. 반 숨의 셈이 목숨값이었다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'S', t:'내리막 틈 — 밧줄의 질김',
  x:`길이 끊겼다. 아래로 한 길 반. 내려서면 길이 다시 이어진다.<br><br>
    가진 밧줄은 낡았다. 올이 삭아 여기저기 부풀었다. 사람 하나 무게가 고비다.<br>
    밧줄에 질김을 입히면 된다. 다만 삭은 올은 겹을 잘 안 문다. 부푼 자리마다 겹이 미끄러진다.<br><br>
    아래 어둠에서 아까부터 젖은 숨소리가 올라온다. 내려서면 바로 걸어야 한다.`,
  o:[
    { l:'① 마력을 올마다 먹여 밧줄 전체에 질김을 입힌다.', k:'fix', dc:25, cost:{ mana:34 },
      ok:`서두르지 않았다. 부푼 자리마다 침을 발라 올을 눕히고, 눕힌 올에 질김을 한 뼘씩 먹였다. 밧줄 전체를 손으로 훑으며.<br><br>다 입히자 낡은 밧줄이 뱀 가죽처럼 탱탱해졌다. 다섯이 차례로 내려섰다. 넷째가 중간에 미끄러져 출렁 매달렸는데도 올 하나 안 울었다.<br>젖은 숨소리 쪽으로는 눈길만 주고 바로 걸었다. 밧줄은 걷어서 챙겼다. 질김이 밴 밧줄은 이 어둠에서 창 다음가는 재산이다.`,
      ng:`올을 훑는 손이 급했다. 부푼 자리 하나를 건너뛰었다.<br><br>셋째가 내려설 때 그 자리가 터졌다. 밧줄이 반 토막 나며 셋째가 떨어졌다. 한 길을.<br>발목을 접질렸다. 젖은 숨소리가 빨라졌다. 남은 밧줄로 둘이 급히 내려가 셋째를 부축해 뛰었다. 숨소리가 등 뒤 어둠에서 한참 따라오다 돌아갔다. 접질린 발목은 열흘을 갔다. 건너뛴 한 뼘의 값이었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 밧줄을 반으로 접어 두 겹으로 쓰고 제일 무거운 순서로 내린다.', k:'steady', dc:24,
      ok:`마력 없이 셈으로 풀었다. 밧줄을 반으로 접어 두 겹. 길이는 반이 되지만 심은 배가 된다.<br><br>모자란 길이는 이쪽 몸으로 이었다. 바위에 버티고 서서 두 겹 밧줄을 어깨로 걸었다. 제일 무거운 짐꾼부터. 무거운 것이 버티는 힘이 제일 남았을 때 내려가야 하니까.<br>다섯이 다 내려서고 마지막으로 이쪽이 바위 모서리를 타고 내렸다. 어깨에 밧줄 자국이 지렁이처럼 부풀었지만 올은 하나도 안 터졌다.`,
      ng:`두 겹으로 접으니 길이가 모자랐다. 마지막 반 길은 뛰어내려야 했다.<br><br>넷까지는 받아 냈는데 다섯째가 뛰며 발을 접질렀다. 돌 구르는 소리가 아래 어둠에 울렸다.<br>젖은 숨소리가 코앞까지 왔다. 횃불을 그 숨에 던지고 다섯이 부축해 뛰었다. 불붙은 어둠에서 비명 비슷한 것이 났다. 몸집보다 겁이 많은 것이라 살았다. 다음부터는 길이부터 재기로 했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'어둠의 올 — 입고 있는 것',
  x:`그것이 또 사라졌다. 눈앞에서. 세 번째다.<br><br>
    달아난 게 아니다. 부여술사 눈에는 꼬리가 보였다. 사라지는 순간, 그것의 몸 위로 겹이 닫히는 꼬리가.<br>
    저것은 안 보임을 입고 있다. 나면서부터 입고 난 겹. 사람 손으로 짠 것보다 올이 곱다.<br><br>
    고운 올에도 솔기는 있다. 숨 쉴 때마다 옆구리 겹이 벌어졌다 닫힌다.`,
  o:[
    { l:'① 솔기가 벌어지는 박자를 응시해 일행에게 가르친다.', k:'gaze', dc:26, wake:1,
      ok:`숨을 죽이고 그것의 빈 자리를 봤다. 안 보임의 겹에도 숨길은 있다. 들숨마다 옆구리 올이 벌어지며 안쪽 비늘이 실금처럼 비친다.<br><br>그 박자를 셌다. 넉 숨에 한 번. 일행에게 가르쳤다. 아무것도 없는 데서 실금이 반짝이면 그게 옆구리다. 실금의 반 자 위가 목이다.<br>다음에 그것이 왔을 때 다섯 눈이 다 실금을 쫓았다. 보이지 않는 것이 보이는 것들에게 둘러싸였다. 그것이 처음으로 머뭇댔고, 머뭇댄 채 물러났다. 사냥감이 눈을 가진 밤이었다.<br><br>겹을 입히는 눈은 겹을 벗기는 눈이기도 하다. 태어나 입은 겹에도 솔기가 있다는 것. 그 솔기를 읽어 남에게 옮긴 것은 오늘이 처음이다.`,
      ng:`솔기를 쫓는 눈에 너무 힘이 들어갔다. 응시는 양날이다. 보는 눈은 보인다.<br><br>그것이 이쪽 눈길을 느꼈다. 안 보임 속에서 이쪽만 제 솔기를 본다는 걸 안 것이다.<br>그날 밤부터 그것은 이쪽만 노렸다. 눈을 지우러. 번을 두 배로 서고 등을 바위에만 붙이고 잤다. 보는 재주는 들키면 과녁이 된다. 그 값을 잠으로 치렀다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 실금이 비치는 순간 옆구리를 창으로 찌른다.', k:'break', dc:26,
      doom:{ title:'보이지 않는 턱', what:'안 보이는 것에게 물려 허공으로 끌려갑니다', dc:20, sec:38,
        text:`실금이 반짝였다. 넉 숨째. 창을 옆구리에 박아 넣었다.<br><br>손맛이 왔다. 뚫었다. 그런데 겹이 창을 따라 흘렀다. 안 보임이 창대로, 창을 쥔 팔로 번져 온다. 제 상처를 문 채 저것이 몸을 틀었다.<br>이쪽 팔이 팔꿈치까지 사라졌다. 보이지 않는 턱이 그 팔을 문다. 들어 올린다.<br><br>발이 땅에서 떨어진다. 허공으로 끌려 올라간다. 일행 눈에는 사람이 혼자 접혀 올라가는 것으로 보였을 것이다. 비명만 보이는 채로.`,
        dieText:`창은 사흘 뒤 숲 가장자리에 꽂혀 있었다. 창날 반 뼘이 아직 안 보였다. 겹이 밴 것이다.<br><br>넷은 그 창을 뽑아 챙겼다. 반쯤 안 보이는 창은 반쯤 보이는 적을 상대할 유일한 증거였다.<br>실금을 읽는 법은 넷 중 아무도 다 못 배웠다. 그래도 넉 숨에 한 번, 아무것도 없는 데를 보는 버릇만은 넷에게 남았다.` },
      ok:`실금이 반짝였다. 찌르기 직전에 창끝을 반 자 올렸다. 가르쳐 준 대로면 거기가 목이다.<br><br>손맛. 안 보이던 것이 한꺼번에 보였다. 겹은 숨과 같이 돈다. 숨통이 상하면 겹이 흘러내린다.<br>드러난 것은 생각보다 작았다. 안 보임이 저것의 몸집 절반이었던 셈이다. 그것은 제 몸이 보이는 걸 깨닫자 싸움을 버리고 달아났다. 보이는 제 몸을 저도 처음 보는 눈치였다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'미끼 — 살아 있음을 입힌 가죽',
  x:`길목을 지키는 그것을 비켜 갈 수가 없다. 미끼가 필요하다.<br><br>
    죽은 짐승 가죽에 짐을 채워 사람 크기로 묶었다. 문제는 저것이 영리하다는 것. 움직이지 않는 먹이는 먼저 찔러 본다.<br>
    살아 있음을 입히기로 했다. 겹 중에 제일 어려운 겹. 떨림, 온기, 숨의 오르내림.<br><br>
    셋 다는 못 입힌다. 마력이 모자라다. 하나만 고른다면 무엇인가.`,
  o:[
    { l:'① 온기도 떨림도 아닌 숨의 오르내림만 입힌다.', k:'fix', dc:26, wake:1,
      ok:`숨을 골랐다. 저들이 어둠에서 제일 먼저 읽는 것은 윤곽의 오르내림이다. 가죽 더미에 숨의 겹을 입혔다. 들숨에 부풀고 날숨에 꺼지게. 자는 것의 느린 숨으로.<br><br>길가에 미끼를 누이고 다섯은 바람 밑에 엎드렸다.<br>그것이 왔다. 한참 내려다봤다. 찌르지 않았다. 자는 먹이는 찌를 것도 없이 그냥 무는 것이다. 물었다. 짐 더미를. 입에 문 것이 가죽인 걸 안 순간 다섯은 이미 길목을 지나 있었다.<br><br>살아 있음의 겹에서 무엇이 심인지 골라낸 것이다. 전부를 입힐 수 없을 때 심만 입히는 법. 부여가 한 꺼풀 깊어졌다. 모자람이 가르친 깊이다.`,
      ng:`숨의 겹을 입혔는데 빠르기를 틀렸다. 자는 숨이 아니라 겁먹은 숨으로.<br><br>겁먹은 먹이는 저들에게 수상한 먹이다. 겁먹었는데 안 달아나니까.<br>그것이 미끼를 내려다보다가 고개를 들어 바람 밑을 봤다. 겁먹은 것 곁엔 숨긴 것이 있다는 걸 아는 눈. 다섯이 들켰다. 길목은 못 지나고 밤새 비탈을 돌았다. 숨에도 사투리가 있다. 틀리면 바로 들킨다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 미끼는 접고 저것이 먹이를 먹는 자리부터 알아낸다.', k:'sense', dc:24,
      ok:`길목 둘레를 돌며 뼈 무더기를 찾았다. 저들은 먹는 자리가 따로 있다. 뼈가 모인 데가 식탁이다.<br><br>식탁은 길목에서 바람 밑으로 반 마장. 즉 저것은 먹이를 물면 그리로 간다.<br>작은 짐승을 돌로 잡아 길목에 던져 두고 기다렸다. 그것이 물고 식탁으로 가는 반 각 사이에 다섯이 길목을 지났다. 미끼에 마력 한 톨 안 들었다. 저들의 버릇이 마력을 대신했다.`,
      ng:`식탁을 찾아 돌다가 식탁 주인과 마주쳤다. 먹는 중이었다.<br><br>먹는 자리를 들킨 짐승은 먹이를 지키는 짐승보다 사납다.<br>반 마장을 내리 쫓겼다. 바위 틈에 몸을 구겨 넣고 반 시진. 그것은 틈 앞에 먹다 만 뼈를 물어다 놓고 갔다. 경고인지 조롱인지. 다섯 다 입맛을 잃었고, 그날 저녁은 아무도 고기 얘기를 안 꺼냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S', t:'어둠 익은 눈 — 빌려주는 밤눈',
  x:`횃불이 둘 남았다. 길은 사나흘 치. 불빛은 저들에게 등대다.<br><br>
    불 없이 걷는 수가 있다. 눈에 어둠 익음을 입히는 것. 입힌 눈은 어둠을 잿빛으로 본다.<br>
    다만 다섯 눈 다 입히기엔 마력이 큰 짐이다. 하나나 둘.<br><br>
    눈 하나가 밝으면 넷은 그 눈에 매달려 걷는 줄이 된다.`,
  o:[
    { l:'① 마력으로 앞장설 두 눈에만 어둠 익음을 입힌다.', k:'fix', dc:25, cost:{ mana:36 },
      ok:`이쪽과 눈 좋은 다섯째. 둘의 눈에 어둠 익음을 입혔다. 어둠이 잿빛으로 갈라지며 길과 돌과 웅크린 것들의 윤곽이 떴다.<br><br>둘이 앞뒤에 서고 셋이 가운데서 어깨 줄을 잡았다. 불 없는 행렬.<br>이틀 밤을 그렇게 걸었다. 둘째 밤에 길가에 엎드린 큰 것 곁을 지났다. 잿빛 눈에는 보였고 불빛은 없었다. 저것은 다섯이 지나가는 걸 끝내 몰랐다. 등대를 끈 배는 암초를 보는 눈만 있으면 된다.`,
      ng:`입힌 눈이 밤에는 보검이었는데 새벽이 문제였다. 동이 트자 잿빛 눈에 햇빛이 칼처럼 박혔다.<br><br>둘이 한나절을 눈을 싸매고 걸었다. 밝은 눈 둘이 졸지에 짐이 됐다.<br>눈먼 둘을 셋이 끌고 바위 그늘을 찾아 쉬었다. 겹은 벗는 때까지 셈해서 입혀야 한다. 밤눈을 입혔으면 새벽 전에 걷어야 한다는 것. 눈물 쏙 빠지게 배웠다. 말 그대로.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 밝은 눈 하나에 넷의 손줄을 이어 밤길을 간다.', k:'bond', dc:24,
      ok:`어둠 익음은 다섯째 눈에만 입히고, 나머지는 손에서 손으로 줄을 이었다. 다섯째가 눈이고 넷은 몸이 되는 길.<br><br>다섯째가 낮게 읊었다. 왼쪽 돌. 고개 숙여. 세 걸음 뛰고 멈춰. 넷이 그 말을 몸으로 받았다.<br>밤길 내내 다섯이 한 몸으로 움직였다. 새벽에 다섯째가 말했다. 넷의 무게가 다 제 눈에 달렸던 밤이라 눈을 한 번도 깜빡인 기억이 없다고. 그날부터 다섯째 눈가에 잔금이 하나 늘었고, 넷은 그 금을 농으로라도 안 건드렸다.`,
      ng:`손줄이 바위 모퉁이에서 한 번 끊겼다. 넷째 손이 땀에 미끄러진 것이다.<br><br>끊긴 줄 뒤의 둘이 어둠에 남겨졌다. 소리도 못 내고.<br>다섯째가 되짚어 찾는 반 각 동안 둘은 어둠 속에 손을 맞잡고 서 있었다. 곁을 무언가 지나갔다고 했다. 둘레를 한 바퀴 돌고 갔다고. 줄은 땀 나기 전에 손목에 묶는 것으로 바뀌었다. 그 밤 이후로.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S', t:'문 없는 밤 — 잠김의 부여',
  x:`쉴 만한 바위굴을 찾았다. 입구가 문제다. 문이 없다. 뻥 뚫린 아가리.<br><br>
    돌로 반쯤 쌓아도 저들 앞다리면 한 번에 허문다.<br>
    잠김을 입히기로 했다. 문 없는 데 입히는 잠김은 어렵다. 잠길 것이 없으니. 허공에 문이 있다고 먼저 속이고, 그 가짜 문에 잠김을 거는 두 겹 일이다.<br><br>
    밤새 버틸지는 겹의 두께에 달렸다.`,
  o:[
    { l:'① 마력을 다해 허공에 문을 세우고 그 위에 잠김을 겹친다.', k:'fix', dc:26, cost:{ mana:38 }, wake:1,
      ok:`입구 허공에 문의 겹부터 짰다. 여기 단단한 것이 있다는 믿음의 올을 가로세로로. 그 위에 잠김을 얹었다. 열리지 않는다는 겹.<br><br>밤중에 그것이 왔다. 콧등으로 입구를 밀었다. 아무것도 없는 허공에서 콧등이 멈췄다. 쿵. 다시 밀었다. 쿵. 저것 셈에는 보이지 않는 돌문이 선 것이다.<br>세 번 밀고 돌아갔다. 새벽까지 겹은 버텼다. 걷을 때 보니 콧등 기름이 허공 한 면에 문짝 모양으로 묻어 있었다.<br><br>없는 것을 세우고 세운 것을 잠갔다. 부여 두 겹을 포개 쌓은 첫 밤. 겹 위에 겹을 쌓는 손맛을 알았다. 이제 한 겹짜리 일이 시시해질까 그게 걱정이다.`,
      ng:`문의 겹까지는 섰는데 잠김이 설익었다. 마력이 달렸다.<br><br>그것이 세 번째 밀었을 때 잠김이 터지며 문의 겹까지 같이 쏟아졌다.<br>뚫린 아가리로 콧등이 들어왔다. 다섯이 굴 안쪽 좁은 틈으로 구겨져 들어가 창으로 버텼다. 좁은 틈은 저것 어깨가 안 들어왔다. 새벽까지 콧김을 맞으며 버텼다. 겹은 반만 서면 안 선 것만 못하다. 차라리 돌이나 쌓을 걸 그랬다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 가짜 문 뒤에서 창을 겨누고 뚫리는 순간을 기다린다.', k:'steady', dc:26,
      doom:{ title:'뚫린 겹', what:'허문 겹 사이로 들어온 앞다리에 감겨 굴 밖으로 끌려 나갑니다', dc:20, sec:40,
        text:`겹을 세우고도 못 미더워 그 뒤에 섰다. 창을 겨누고. 뚫리면 첫 창은 이쪽 몫이니까.<br><br>그것이 왔다. 밀었다. 겹이 버텼다. 또 밀었다. 겹이 울었다.<br>세 번째에 겹이 터졌다. 터지는 겹은 안쪽으로 터진다. 겹의 파편이 눈앞에서 빛처럼 흩어지는 반 숨, 그 반 숨에 앞다리가 들어왔다.<br><br>창보다 빨랐다. 허리에 감긴다. 굴 밖으로 끌려 나간다. 뒤에서 넷이 다리를 잡는다. 저것이 더 세다.`,
        dieText:`굴 안의 넷은 좁은 틈으로 물러나 새벽까지 버텼다. 입구 쪽은 끝내 조용해지지 않았다.<br><br>아침에 보니 입구 허공에 겹의 조각이 아직 몇 올 걸려 반짝였다. 세운 사람은 없는데 세운 것만 남은 것이다.<br>넷은 그 올이 다 삭을 때까지 그 굴을 떠나지 못했다. 떠나던 날 넷째가 올 하나를 조심히 걷어 품에 넣었다. 아무도 말리지 않았다.` },
      ok:`겹 뒤에 창을 겨누고 섰다. 겹이 버티는 동안은 창이 놀고, 겹이 터지면 창이 일한다.<br><br>그것이 두 번 밀고 세 번째로 크게 물러났다. 받아 치려는 것이다. 겹이 못 버틸 충격.<br>달려드는 박에 맞춰 겹 가운데만 이쪽 손으로 미리 걷었다. 구멍 난 과녁. 저것 콧등이 구멍으로 들이박혔고 기다리던 창끝이 거기 있었다. 콧등을 꿰인 그것이 비명을 물고 달아났다. 겹은 방패도 되고 덫도 된다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'바위 같음 — 겹이 안 통하는 눈',
  x:`벌판 한가운데서 그것들 무리가 길을 가로질러 온다. 숨을 데가 바위 몇 덩이뿐이다.<br><br>
    다섯을 웅크리게 하고 바위 같음을 입힐 셈을 했다. 돌의 겹. 차고 고요하고 오래된 것의 겹.<br>
    그런데 손이 멈췄다. 저들 눈은 겹을 안 읽는다. 저들 코가 읽는 건 살 냄새고 눈이 읽는 건 움직임이다. 돌처럼 보여도 땀 냄새가 나면 돌이 아니다.<br><br>
    부여에도 안 통하는 상대가 있다. 그걸 아는 것도 부여다.`,
  o:[
    { l:'① 바위 같음 대신 바위 틈의 흙냄새를 몸에 입힌다.', k:'fix', dc:25,
      ok:`겉모습의 겹은 접었다. 저들이 읽는 쪽을 입혀야 한다. 바위 밑 흙을 파서 다섯 몸에 바르고, 그 위에 흙냄새 머무름의 겹을 얇게 입혔다. 바람이 쓸어도 냄새가 안 벗겨지게.<br><br>다섯이 바위 밑에 웅크렸다. 무리가 지나갔다. 코 하나가 바위 곁에 와서 킁킁댔다. 흙. 돌. 흙. 지나갔다.<br>저들이 다 지나가고도 쉰 숨을 셌다. 겹은 상대의 눈에 맞춰 고르는 것이다. 사람 눈에 통하는 겹과 코에 통하는 겹은 다른 물건이다.`,
      ng:`흙냄새를 입혔는데 넷째가 웅크린 채 땀을 쏟았다. 겁의 땀은 흙 겹을 뚫고 오른다.<br><br>무리 끝의 코 하나가 바위 앞에 멈췄다. 흙냄새 속의 짠내를 잡은 것이다.<br>앞다리가 바위를 긁는 순간 다섯이 사방으로 튀었다. 흩어진 먹이는 무리를 가른다. 그 덕에 다 살았지만 해 질 녘에야 다시 모였다. 넷째는 제 땀을 두고두고 부끄러워했다. 아무도 탓하지 않았는데도.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 바위 뒤 그늘에 포개 엎드려 움직임만 죽인다.', k:'hide', dc:25,
      ok:`겹 없이 숨기로 했다. 바위 그늘에 다섯이 포개 엎드렸다. 바람 밑 쪽으로.<br><br>움직임만 죽이면 반은 이긴다. 저들 눈은 선 것과 걷는 것을 잡지 엎드린 더미는 잘 안 잡는다.<br>무리가 바위 사이를 지나갔다. 발 하나가 둘째 손가락 한 뼘 옆을 디뎠다. 땅이 눌리는 걸 손바닥으로 느끼며 다섯이 숨을 나눠 쉬었다. 지나가고 나서 보니 서로의 손을 다 잡고 있었다. 누가 먼저랄 것도 없이.`,
      ng:`엎드린 자리가 하필 저들 길 복판이었다. 무리가 바위 양쪽으로 갈라져 지나는데 한 마리가 바위를 타 넘었다.<br><br>발톱이 셋째 등짐을 밟았다. 짐 속 솥이 우그러지는 소리.<br>저것이 제 발밑을 내려다보는 반 숨에 다섯이 튀었다. 벌판을 가로질러 숲까지. 무리는 쫓지 않았다. 길 가던 중이었던 것이다. 사냥 길이었으면 끝이었다. 운까지 셈에 넣으면 안 된다는 걸 알면서도 그날은 운뿐이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'들것 — 단단함을 먹인 나무',
  x:`다섯째가 다리가 부러졌다. 들것을 짜야 한다. 쓸 나무가 삭정이뿐이다.<br><br>
    삭정이 두 대에 단단함을 입혔다. 들것은 섰다. 문제는 길이다. 들것은 네 손을 묶는다. 창 쥘 손이 둘 준다.<br>
    그리고 저들은 안다. 무리에서 제일 좋은 먹이는 들려 가는 것이라는 걸.<br><br>
    들것이 미끼가 되는 길. 그 길을 가야 한다.`,
  o:[
    { l:'① 마력으로 들것 틀에 단단함을, 멜빵에 질김을 겹으로 입힌다.', k:'fix', dc:25, cost:{ mana:33 },
      ok:`틀에 단단함을, 어깨 멜빵에 질김을 입혔다. 그리고 하나 더. 들것 바닥에 이음의 겹을 깔아 다섯째 몸이 들것에 붙게 했다. 흔들려도 떨어지지 않게.<br><br>덕에 두 손이 자유로워졌다. 메는 둘이 창을 한 손씩 쥘 수 있었다.<br>사흘 길에 저들이 두 번 간을 봤다. 두 번 다 들것 멘 둘의 창이 먼저 마중했다. 들려 가는 먹이 곁에 날이 넷이나 있는 건 저들 셈에 없던 그림이었다. 두 번째 뒤로는 간도 안 봤다.`,
      ng:`단단함과 질김까지는 입혔는데 이음의 겹에서 마력이 달렸다. 들것이 흔들릴 때마다 다섯째가 쏠렸다.<br><br>비탈에서 크게 기우뚱하며 다섯째가 반쯤 굴러떨어졌다. 부러진 다리가 땅에 닿았다. 비명.<br>비명은 봉화다. 그 밤 번을 두 배로 섰다. 둘레를 도는 발소리가 두 종류였다. 겹은 세 벌을 계획했으면 마력도 세 벌 치를 남겨 둬야 한다. 곳간 셈이 또 한 번 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 들것을 번갈아 메는 차례를 짜 네 사람의 힘을 아낀다.', k:'bond', dc:24,
      ok:`멜 사람 차례를 짰다. 반 시진씩, 앞채와 뒤채를 어긋나게 바꿔서. 한 번에 한 사람만 갈리게.<br><br>갈리는 반 숨에도 들것은 세 손이 받치고 있었다. 빈틈이 없었다.<br>다섯째는 들것 위에서 창을 가슴에 얹고 하늘 쪽을 맡았다. 다리 부러진 사람도 눈과 손은 산다. 사흘 길을 그렇게 갔다. 도착해서 세어 보니 멘 차례가 똑같이 나눠져 있었다. 누구 어깨도 혼자 꺼지지 않은 길이었다.`,
      ng:`차례를 짰는데 둘째가 제 차례를 안 내놨다. 힘이 남았다며. 사흘째에 그 어깨가 주저앉았다.<br><br>들것이 기울고 다섯째가 땅을 짚었다. 부러진 다리 쪽 손을.<br>그 자리서 반 시진을 쉬었다. 쉬는 동안 둘레 수풀이 두 번 어른댔다. 힘이 남았다는 말은 셈이 아니라 마음이다. 마음은 고맙되 셈은 셈대로 지킬 것. 차례표가 그날 밤 더 촘촘해졌다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S1', t:'표본실 — 금 간 마개를 다시 물리다',
  x:`표본실 안쪽 선반은 아직 성하다. 병 서른 개 남짓. 그런데 마개마다 금이 가는 중이다.<br><br>
    안엣것들이 깨고 있는 것이다. 느리게, 안에서부터. 금 간 틈으로 쇳내 나는 김이 샌다.<br>
    부여술사 눈에는 마개마다 입혀졌던 맞물림의 겹이 보인다. 다 삭았다. 시설 사람들이 입혀 둔 겹이 세월에 벗겨진 것이다.<br><br>
    다시 입힐 수 있다. 서른 개 전부는 못 해도.`,
  o:[
    { l:'① 마력으로 금이 깊은 마개부터 맞물림을 다시 입힌다.', k:'fix', dc:26, cost:{ mana:36 }, wake:1,
      ok:`금이 깊은 순서로 아홉 개. 마개마다 손을 얹고 맞물림을 새로 짰다. 옛 겹의 삭은 올을 걷어 내고 새 올을 같은 결로.<br><br>옛 겹을 걷다가 알았다. 이건 사람 솜씨다. 이 시설에 부여를 아는 사람이 있었다. 올 짜는 버릇이 이쪽과 다른데, 더 낫다. 그 결을 따라 짜니 겹이 곱절로 단단했다.<br>아홉 병의 김이 멎었다. 안엣것들이 마개를 치는 소리가 한동안 나다 잠잠해졌다.<br><br>남이 짠 겹을 읽고 그 결을 이어 짠 첫날이다. 부여는 혼자 배우는 재주인 줄 알았다. 죽은 사람의 손에게 배웠다. 겹은 글이고, 글은 남는다.`,
      ng:`새 올을 짜는데 세 번째 병의 안엣것이 마개 안쪽에서 마주 밀었다. 입히는 중의 겹은 여리다.<br><br>겹이 찢기며 마개가 튀었다. 김이 뿜어 나오고 안엣것이 반쯤 몸을 내밀었다.<br>선반을 통째로 밀어 병째 깔아뭉갰다. 요란한 소리에 복도 쪽 어둠이 깼다. 나머지 병은 포기하고 자리를 떴다. 입히는 동안이 제일 약하다. 그때는 누가 등을 지켜 줘야 한다. 다음부터 입힐 땐 꼭 창 하나를 곁에 세웠다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-18 } },
    { l:'② 어느 병이 오늘 밤을 못 넘길지 금의 깊이로 가려낸다.', k:'sense', dc:25,
      ok:`금을 하나하나 짚었다. 손끝에 닿는 떨림으로 금의 깊이를 쟀다. 겉금은 울림이 맑고 속금은 둔하다.<br><br>오늘 밤을 못 넘길 병이 둘. 그 둘을 쇠 사물함에 옮겨 넣고 문을 잠갔다.<br>밤중에 사물함 안에서 유리 터지는 소리가 두 번 났다. 그리고 쇠문을 긁는 소리가 아침까지. 사물함은 버텼다. 병은 못 지켜도 병의 때를 알면 잠글 수는 있다. 아침에 사물함 앞을 지날 때 다들 발소리를 죽였다.`,
      ng:`금을 짚는 손끝이 넷째 병에서 멈칫했다. 떨림이 이상했다. 금의 떨림이 아니라 심장 같은 떨림.<br><br>들여다보는데 안엣것이 눈을 떴다. 유리 너머로 눈이 마주쳤다.<br>그것이 몸을 틀자 금이 한꺼번에 자랐다. 병을 안아 들고 빈 수조에 던져 넣는 것까지가 한 숨이었다. 수조 속에서 병이 터졌다. 물이 끓었다. 눈 마주친 것은 수조 유리 안에서 오래 이쪽을 봤다. 그 눈을 꿈에서 다시 봤다. 여러 번.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'S1', t:'산성혈 — 녹아내리는 겹과의 경주',
  x:`복도를 막은 쇳문이 반쯤 녹아 있다. 문 앞에 저들끼리 싸운 자국. 죽은 것의 피가 문을 먹은 것이다.<br><br>
    녹다 만 문틈은 사람 하나 지날 넓이. 그런데 문틀에 아직 피가 묻어 있다. 마르지 않는 피. 스치면 옷이고 살이고 끓는다.<br>
    장갑과 소매에 버팀을 입히고 피 묻은 자리를 밀어 넓히는 수. 다만 버팀의 겹도 저 피 앞에서는 녹는다. 겹이 다 녹기 전에 일을 끝내는 경주다.`,
  o:[
    { l:'① 마력으로 장갑에 버팀을 겹겹이 입히고 틈을 민다.', k:'fix', dc:26, cost:{ mana:35 },
      ok:`장갑에 버팀을 다섯 겹 입혔다. 피에 닿자 겉겹부터 녹기 시작한다. 치익. 한 겹에 다섯 숨.<br><br>스물다섯 숨 안에 끝내는 경주. 문짝을 밀어 젖히고 피 묻은 모서리를 꺾어 눕혔다. 넷이 그 사이로 빠졌다.<br>마지막 겹이 녹는 치익 소리와 함께 장갑을 벗어 던졌다. 장갑이 바닥에서 연기가 됐다. 손은 멀쩡했다. 스물세 숨. 두 숨 남긴 경주였다.`,
      ng:`다섯 겹이면 넉넉하다 셈했는데 피가 셈보다 독했다. 세 겹째가 녹을 때 이미 열다섯 숨.<br><br>문을 다 못 밀고 장갑을 던졌다. 던지는 순간 손등에 김이 스쳤다. 지렁이 한 마리 길이로 부풀어 올랐다.<br>남은 틈으로 하나씩 겨우 빠졌다. 맨 뒤 사람 등짐이 문틀 피에 닿아 멜빵 한쪽이 끊어졌다. 짐을 안고 뛰었다. 독한 것 앞에서는 셈을 배로 잡을 것. 손등의 지렁이가 아물며 가르쳐 준 말이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 문은 두고 벽의 녹슨 바람 관을 뜯어 길을 낸다.', k:'break', dc:25,
      ok:`피 묻은 문과 경주할 것 없이 옆을 봤다. 벽 위쪽 바람 관. 녹슬어 헐겁다.<br><br>창대를 지레 삼아 관 뚜껑을 뜯었다. 사람 하나 길 만한 관이 문 너머까지 이어져 있다.<br>다섯이 차례로 관을 기어 문 반대편에 내려섰다. 내려서며 보니 문틈 쪽 바닥에 피가 고여 있었다. 틈으로 지났으면 발밑이 그 피였다. 문이 길이 아니라 문 옆이 길일 때가 있다. 부여 쓸 일을 안 만드는 것도 부여술사의 재주다.`,
      ng:`관 뚜껑을 뜯는데 녹슨 쇠가 비명을 질렀다. 끼이익. 복도 두 개 너머까지 갈 소리.<br><br>관 속을 반쯤 기었을 때 뒤쪽 입구에서 쇠 긁는 소리가 따라 들어왔다. 무엇이 관으로 머리를 들이민 것이다.<br>앞사람을 발로 밀다시피 하며 내리 기었다. 반대편으로 쏟아져 나와 뚜껑을 도로 박았다. 뚜껑 너머에서 한참 긁는 소리가 났다. 관은 길이지만 저들에게도 길이다. 들어가면 문부터 세어 둘 것.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } },
    { l:'③ 마르지 않는 피를 한 방울 긁어 병에 담는다.', k:'luck', dc:25,
      ok:`유리 조각으로 바닥에 고인 피를 한 방울 떠서 깨진 표본병에 담고 마개에 맞물림을 입혔다.<br><br>무기가 될지 열쇠가 될지 모르지만, 쇠를 먹는 물은 이 시설에서 쇠문보다 귀하다.<br>이틀 뒤 잠긴 격자문 앞에서 그 한 방울이 자물쇠를 먹었다. 문이 열렸다. 적의 피가 길을 딴 것이다. 독도 담을 줄 알면 연장이다.`,
      ng:`피를 뜨다가 유리 조각이 녹아 손가락 사이로 꺾였다. 한 방울이 신발 코에 튀었다.<br><br>신발을 그 자리서 벗어 던졌다. 가죽이 연기가 되는 데 열 숨도 안 걸렸다.<br>남은 길을 한 발은 맨발로 걸었다. 짐에서 천을 꺼내 감발을 쳤다. 독을 담으려면 독보다 단단한 그릇부터 구할 것. 순서가 틀리면 그릇 대신 몸이 그릇이 된다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S1', t:'숙주 — 가슴에 적힌 제 것',
  x:`창고에서 찾은 생존자가 잠들어 있다. 고마운 사람이다. 길눈이 밝아 다섯이 몇 번을 빚졌다.<br><br>
    그런데 부여술사 눈에만 보이는 것이 있다. 그 사람 가슴께에 겹이 한 장 얹혀 있다. 사람 솜씨가 아니다. 올이 미끈하고 축축하다.<br>
    읽으면 뜻이 온다. 제 것. 아껴 둠. 익는 중.<br><br>
    안에 무엇이 들어 있고, 그것이 겉에 문패를 달아 둔 것이다. 저들 식구끼리 서로 안 건드리게.`,
  o:[
    { l:'① 겹을 끝까지 읽어 익는 때가 언제인지 알아낸다.', k:'gaze', dc:26, wake:1,
      ok:`겹의 올을 한 올씩 읽었다. 제 것, 아껴 둠, 익는 중. 그리고 맨 밑에 가는 올 하나. 보름달.<br><br>때가 적혀 있었다. 다음 보름까지 엿새.<br>엿새면 된다. 치유 아는 일행이 있는 합류 지점까지 나흘 길. 그 사람에게는 가슴이 허한 병이 있다고만 하고 길을 서둘렀다. 닷새째에 닿았고, 빼내는 일은 아는 사람 손에서 끝났다. 그 사람은 아직도 제 가슴에 뭐가 적혀 있었는지 모른다.<br><br>겹을 읽는 눈이 때까지 읽었다. 부여는 물건에 적는 글인 줄만 알았는데 저들은 산 사람에게 적는다. 적는 것들과 싸우려면 읽는 눈부터다. 눈이 글눈이 됐다.`,
      ng:`올을 읽는데 겹이 읽히는 걸 알았다. 읽는 눈길에 겹이 오므라들었다.<br><br>그리고 그 사람이 잠에서 깼다. 가슴을 쥐고. 안엣것이 겹을 당긴 것이다.<br>그날부터 안엣것이 서둘렀다. 익는 때가 당겨진 것 같았다. 길을 배로 서둘러 사흘 만에 합류 지점에 닿았다. 빼내는 데는 성공했지만 그 사람 몸이 많이 상했다. 읽는 눈길도 손길이다. 여린 데를 읽을 때는 스치듯 읽을 것.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 문패 위에 비어 있음을 덧입혀 안엣것을 속인다.', k:'fix', dc:26,
      ok:`제 것이라는 문패 위에 한 겹을 덧입혔다. 비어 있음. 이 몸에는 아무것도 안 든다는 겹.<br><br>두 겹이 서로 다퉜다. 든 것과 비었다는 것. 안엣것이 혼란에 빠졌다. 제가 든 집이 비었다고 적혀 있으니.<br>사흘째 밤, 그 사람이 긴 기침 끝에 검은 덩이를 토했다. 엄지만 한 것이 바닥에서 꿈틀대다 굳었다. 제 집이 아니라고 적힌 집에서 스스로 나온 것이다. 그 사람은 체증이 내렸다며 웃었다. 사실은 그게 맞는 말이기도 했다.`,
      ng:`비어 있음을 덧입히는데 안엣것이 겹 밑에서 요동쳤다. 속는 대신 성을 낸 것이다.<br><br>그 사람이 가슴을 쥐고 무릎을 꿇었다. 숨이 가빠졌다.<br>덧입힌 겹을 도로 걷어서야 가라앉았다. 안엣것은 문패를 더 두껍게 고쳐 적었다. 이번 올은 읽기도 어렵게 꼬여 있었다. 속임수는 한 번뿐이다. 다음은 아는 사람 손에 맡기기로 하고 길만 서둘렀다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S1', t:'에어록 창 — 흐림의 겹',
  x:`에어록 안쪽 복도에 긴 것이 자리를 잡고 있다. 비키지 않는다. 에어록 문의 둥근 창으로 이쪽이 다 보이는 탓이다.<br><br>
    보여서 안 가는 것이다. 먹이가 문 하나 너머에 줄 서 있는데 어디를 가겠는가.<br>
    창에 흐림을 입히면 된다. 유리의 겹 위에 입김의 겹을.<br>
    이쪽이 안 보이면 저것은 셈을 다시 할 것이다. 먹이가 사라진 복도를 지킬 까닭이 없으니.`,
  o:[
    { l:'① 창 안팎에 흐림을 입히고 다섯 기척을 죽여 기다린다.', k:'fix', dc:25,
      ok:`창에 흐림을 입혔다. 뿌옇게. 안에서 밖도, 밖에서 안도 안 보이게. 그리고 다섯이 문 옆 벽에 등을 붙이고 기척을 죽였다.<br><br>반 시진. 창 너머 그림자가 몇 번 창에 바짝 붙었다 떨어졌다. 뿌연 유리에 콧김 자국만 남기고.<br>한 시진째에 긴 것이 자리를 접었다. 발소리가 복도 깊이 멀어졌다. 보이던 밥상이 사라지면 짐승은 밥상을 잊는다. 문을 돌리고 빈 복도를 지났다. 바닥에 저것이 하 오래 기다려 눌린 자리만 윤이 났다.`,
      ng:`흐림을 입히는 중에 창 너머와 눈이 마주쳤다. 저것이 창에 붙어 있던 것이다.<br><br>눈앞에서 제 시야가 뿌예지는 걸 보며 저것은 셈을 다르게 했다. 숨는 먹이는 급한 먹이다.<br>문이 울리기 시작했다. 쿵. 쿵. 에어록 문은 버텼지만 다섯은 그 복도를 포기했다. 흐림은 저것이 한눈팔 때 입혔어야 했다. 부여에도 눈치가 반이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 창 아래로 기어 저것 눈을 피해 문턱을 넘는다.', k:'hide', dc:26,
      doom:{ title:'창 너머의 셈', what:'문이 돌아간 순간 긴 것에게 붙들려 안쪽 복도로 끌려갑니다', dc:20, sec:36,
        text:`창 밑으로 기어 문에 붙었다. 바퀴를 돌렸다. 소리 없이. 반 바퀴. 한 바퀴.<br><br>문이 열렸다. 복도가 비어 보였다. 저것이 안 보이는 데로 비켜 있었다. 창에서 이쪽이 사라진 순간부터 저것도 셈을 한 것이다. 숨는 먹이는 문으로 나온다고.<br>문턱을 넘는 첫 사람 목덜미를 위에서 내려온 것이 붙든다. 천장에 붙어 기다리고 있었다.<br><br>안쪽 복도로 끌려간다. 문이 등 뒤에서 저절로 돌아 닫힌다. 저것 꼬리가 바퀴를 감아 돌리고 있다.`,
        dieText:`에어록 창은 다시 맑아졌다. 입힌 사람이 없는 겹은 오래 못 간다.<br><br>넷은 그 창으로 안쪽 복도를 오래 봤다. 복도는 끝내 비어 보였다. 그게 제일 무서웠다.<br>넷은 이틀을 돌아 다른 구역으로 갔다. 그 뒤로 문을 열 때면 넷 다 버릇이 생겼다. 문턱 위 천장부터 보는 버릇.` },
      ok:`창 밑으로 기어 문에 붙었다. 바퀴에 손을 얹고— 멈췄다. 창에서 이쪽이 사라졌는데 복도가 너무 조용하다.<br><br>조용한 건 비켜 준 것이다. 문으로 나오라고.<br>바퀴에서 손을 떼고 도로 기어 돌아왔다. 반 시진 뒤 창 너머에서 긴 것이 천장에서 내려와 제자리로 가는 그림자가 비쳤다. 기다리다 지친 것이다. 그제야 흐림을 입히고 저것이 못 보는 사이 반대쪽 관로로 돌았다. 문턱은 끝내 안 밟았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'통풍구 덮개 — 무거움의 겹',
  x:`오늘 밤 쉴 방은 좋은 방이다. 문이 쇠고 벽이 두껍다. 흠은 하나. 천장과 벽에 통풍구가 넷.<br><br>
    덮개는 격자 쇠판인데 나사가 다 삭았다. 안에서 밀면 들린다. 저들이 밤에 다니는 길이 바로 저 관들이다.<br>
    덮개마다 무거움을 입히기로 했다. 바위 한 덩이 무게씩.<br><br>
    넷 다 입히면 마력이 간당간당하다. 밤에 다른 일이 없기를 빌면서 하는 셈이다.`,
  o:[
    { l:'① 마력으로 덮개 넷에 무거움을 입혀 밤을 잠근다.', k:'fix', dc:25, cost:{ mana:37 },
      ok:`덮개마다 손바닥을 대고 무거움을 입혔다. 바위 한 덩이씩. 격자 틈으로 바람은 다니되 판은 산이 눌러앉게.<br><br>밤중에 두 번, 덮개가 밑에서 밀렸다. 들썩— 도 못 하고 덜컥, 하고 말았다. 안쪽에서 미는 것이 제 셈을 의심하는 소리가 들렸다. 긁어 보고, 밀어 보고, 포기하고.<br>새벽에 겹을 걷으며 보니 격자 안쪽에 발톱 자국이 수십 줄이었다. 밤새 네 덮개가 다 그 모양이었다. 좋은 방이란 없다. 잠근 방이 있을 뿐이다.`,
      ng:`넷째 덮개까지 입히고 나니 마력이 바닥을 쳤다. 그리고 그 밤, 다른 일이 생겼다.<br><br>문 쪽이었다. 복도에서 무엇이 쇠문을 더듬었다. 문에는 아무 겹도 못 입힌 상태.<br>빗장에 돌을 괴고 다섯이 문을 등으로 받치고 밤을 샜다. 문은 버텼다. 등으로 버틴 것인지 문이 버틴 것인지는 알 수 없다. 마력은 끝까지 다 쓰는 게 아니라 한 줌 남기는 것이다. 그 한 줌이 이런 밤의 몫이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 덮개 밑마다 빈 병을 쌓아 무너지는 소리 경보를 만든다.', k:'steady', dc:24,
      ok:`마력 대신 유리를 썼다. 덮개 바로 밑마다 빈 병을 탑으로 쌓았다. 덮개가 들리면 병이 무너지게.<br><br>자정에 셋째 덮개 쪽 병 탑이 와장창 무너졌다. 다섯이 한 숨에 일어나 창을 겨눴다.<br>덮개 틈으로 들어오던 것이 쏟아진 유리와 겨눠진 창 다섯을 보고 도로 올라갔다. 잠은 설쳤지만 몸은 성했다. 경보는 적을 못 막는다. 대신 잠든 다섯을 깨어 있는 다섯으로 바꾼다. 그거면 반은 이긴 것이다.`,
      ng:`병 탑이 문제였다. 새벽에 넷째가 뒷간 가려다 제가 쌓은 탑을 찼다.<br><br>와장창. 다섯이 창을 쥐고 일어났고, 넷째가 유리 위에 주저앉아 있었다.<br>웃을 일이 아니었다. 소리는 관을 타고 갔다. 한 식경 뒤 덮개 밖에서 긁는 소리가 돌기 시작했다. 소리 경보는 적만 울리는 게 아니다. 아군용 길을 먼저 내 둘 것. 손바닥의 유리 조각을 빼며 넷째가 백번 사과했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'여왕의 올 — 시설을 꿰맨 실',
  x:`깊은 층에 내려서자 부여술사 눈이 아팠다. 겹이 너무 많다.<br><br>
    벽에, 바닥에, 둥지의 기둥마다 겹이 입혀져 있다. 사람 솜씨가 아니고 올이 다 한 방향으로 눕는다.<br>
    여왕이다. 여왕이 시설에 제 겹을 입힌 것이다. 제 것. 품 안. 길. 올들이 실처럼 한 점으로 모인다. 그 점이 여왕의 자리다.<br><br>
    거꾸로 읽으면 된다. 올이 모이는 쪽의 반대가 바깥이다.`,
  o:[
    { l:'① 올이 눕는 결을 거슬러 읽어 바깥으로 나가는 길을 긋는다.', k:'gaze', dc:26, wake:1,
      ok:`벽의 올을 손끝으로 쓸었다. 결이 눕는 쪽이 여왕, 일어서는 쪽이 바깥. 갈림마다 올을 읽으며 결을 거슬렀다.<br><br>길이 이상하게 돌았다. 곧은 복도를 두고 올은 자꾸 좁은 옆길로 눕는다. 믿고 따랐다. 곧은 복도 쪽에서 나중에 여럿의 발소리가 지나갔다. 올은 저들의 길까지 적고 있던 것이다.<br>반나절 만에 올이 다 일어선 문 앞에 섰다. 여왕의 겹이 끝나는 자리. 바깥 계단이었다.<br><br>시설만 한 생물의 겹을 읽으며 걸은 반나절. 부여가 이만한 크기로도 짜인다는 걸 알았다. 사람의 겹이 손수건이라면 저것의 겹은 바다였다. 바다에서 헤엄치는 법을 오늘 배웠다.`,
      ng:`결을 거슬러 읽는데 어느 갈림에서 올이 양쪽 다 일어서 있었다. 읽을 수 없는 자리.<br><br>한참 들여다보다 알았다. 일어선 게 아니라 곤두선 것이다. 여왕의 겹이 이쪽 읽기를 느끼고 털을 세운 것.<br>그 복도 전체의 올이 차례로 곤두서기 시작했다. 소름 돋는 살갗처럼. 읽기를 끊고 내달렸다. 등 뒤에서 깊은 데가 길게 울었다. 바다를 읽으면 바다도 읽힌 걸 안다. 그걸 알고 나서는 결을 손끝 대신 눈으로만 쓸었다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 올이 제일 성긴 샛길로 몸을 던져 빠르게 가로지른다.', k:'evade', dc:26,
      doom:{ title:'당겨지는 실', what:'곤두선 올에 얽혀 여왕의 둥지 쪽으로 끌려 들어갑니다', dc:20, sec:35,
        text:`올이 성긴 샛길을 골라 내달렸다. 성긴 데는 여왕의 눈길이 덜 가는 데니까.<br><br>반을 지났을 때 발밑 올이 출렁였다. 성긴 게 아니었다. 벌려 둔 것이다. 그물이 성긴 건 물고기 지나는 길목이라서다.<br>올들이 일제히 일어나 발목을, 팔을, 허리를 감았다. 눈에 안 보이는 실에 몸이 얽힌다.<br><br>올이 눕는 쪽으로 당겨진다. 결이 눕는 쪽. 여왕 쪽. 바닥에 끌리며 그 뜻을 뒤늦게 다 읽었다. 제 것. 품 안. 길.`,
        dieText:`샛길의 올은 다시 성기게 누웠다. 아무 일 없던 그물처럼.<br><br>넷은 올을 못 본다. 다만 그 샛길만은 돌아서 갔다. 멀어도.<br>바깥 계단에 닿았을 때 넷째가 물었다. 그 사람 눈에는 이 시설이 어떻게 보였을까. 아무도 답을 몰랐다. 다만 혼자 너무 많이 보는 사람 곁에는 꼭 하나가 붙어 있자고, 그날 정했다.` },
      ok:`올이 성긴 샛길에 몸을 던지기 전에 반 숨 멈췄다. 성긴 그물은 길목의 그물이다.<br><br>돌을 먼저 던졌다. 돌이 샛길 복판에서 허공에 반 뼘 떠올랐다 떨어졌다. 보이지 않는 실이 받은 것이다.<br>샛길을 접고 올이 촘촘하되 깊이 잠든 결의 복도로 돌았다. 촘촘한 올은 그물이 아니라 살갗이다. 살갗은 밟아도 주인이 늦게 안다. 발꿈치를 들고 반나절, 바깥 계단에 닿았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'방호복 — 찢긴 데를 맞춰 입다',
  x:`포자 안개가 깔린 구역이다. 숨 쉬면 안엣것이 생긴다는 걸 이제는 다 안다.<br><br>
    장비실에서 방호복 다섯 벌을 찾았다. 셋은 찢겼고 둘은 사람 치수가 아니다. 거인 치수.<br>
    부여로 손볼 수 있다. 찢긴 자리에 맞물림을, 큰 옷에 맞음을.<br><br>
    안개 구역은 삼백 걸음. 겹이 버텨야 하는 길이다.`,
  o:[
    { l:'① 마력으로 찢긴 자리를 맞물리고 큰 옷에 맞음을 입힌다.', k:'fix', dc:25, cost:{ mana:34 },
      ok:`찢긴 셋은 찢긴 가장자리끼리 맞물림을 입혀 꿰맸다. 실 없이 올과 올이 서로 물게. 큰 둘은 맞음을 입혀 몸에 맞게 줄였다.<br><br>다섯 벌이 다섯 몸에 맞았다. 안개 삼백 걸음을 걸었다. 뿌연 것이 낯가리개에 눈처럼 앉았다 흘러내렸다.<br>건너편에서 벗은 방호복 겉면이 곰팡이 핀 것처럼 하얬다. 겹은 안 뚫렸다. 벗은 옷은 두고 왔다. 한 번 맞물린 올은 다시 벌어지는 법이라, 미련도 같이 두고 왔다.`,
      ng:`맞물림은 성했는데 맞음에서 탈이 났다. 큰 옷을 입은 넷째 것이 걷는 중에 겹이 삭았다. 소매가 도로 거인 소매가 됐다.<br><br>헐거운 소매 끝으로 안개가 숨 쉬듯 드나들었다.<br>넷째 손목을 끈으로 세 번 감아 묶고 남은 백 걸음을 업다시피 뛰었다. 건너편에서 넷째 손만 반나절 씻기고 지켜봤다. 아무 일 없었다. 아마도. 그 뒤로 보름 동안 넷째가 기침할 때마다 다섯이 다 돌아봤다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 안개가 가라앉는 새벽 시간을 기다렸다 맨몸으로 지난다.', k:'luck', dc:25,
      ok:`안개도 자는 때가 있다. 밤새 지켜보니 새벽녘 바닥이 식을 때 안개가 무릎 밑으로 가라앉았다.<br><br>그때 지났다. 입과 코를 적신 천으로 감고, 고개를 들고, 무릎 밑은 안 보기로 하고.<br>삼백 걸음을 큰 숨 서른 번으로 끊어 건넜다. 건너편 장비실 사물함에서 밀봉된 비상 식량까지 찾았다. 기다림이 마력을 아꼈고 아낀 마력이 그날 밤 값을 했다.`,
      ng:`새벽을 기다렸는데 그날따라 바람이 돌아 안개가 안 가라앉았다. 오히려 허리까지 찼다.<br><br>하루를 더 묵었다. 묵는 방 천장에서 밤새 긁는 소리가 돌았다.<br>이튿날 새벽에야 안개가 잤다. 이틀 치 발이 묶인 셈. 공짜 길은 때를 기다리는 값을 받는다. 그 값이 쌀지 비쌀지는 지나 봐야 안다는 게 흠이다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S2', t:'죽은 울타리 — 아직 아픔',
  x:`정원 울타리 기둥에 사기 애자가 줄줄이 달려 있다. 전기 울타리였던 것이다. 지금은 죽은 지 오래다.<br><br>
    그런데 저들은 아직도 울타리를 한 번에 안 민다. 꼭 먼저 코끝으로 살짝 댄다. 옛날에 혼난 기억이 몸에 남은 것이다.<br>
    쇠줄에는 아픔의 겹이 벗겨진 자국이 남아 있다. 전기가 흐르며 입혀 두었던 겹.<br><br>
    그 겹을 다시 입힐 수 있다. 전기 없이. 기억만.`,
  o:[
    { l:'① 마력으로 쇠줄에 아픔의 기억을 다시 입힌다.', k:'fix', dc:26, cost:{ mana:38 }, wake:1,
      ok:`쇠줄을 한 뼘씩 쥐며 아픔의 겹을 입혔다. 전기의 아픔을 이쪽은 모르니, 올의 결만 옛 자국 그대로 따라 짰다. 벗겨진 겹의 흉터가 본이 됐다.<br><br>그 밤 저들이 왔다. 맨 앞 것이 코끝을 댔다. 비명. 껑충 물러나 앞발로 제 코를 비볐다. 다음 것이 못 믿고 또 댔다. 비명.<br>죽은 울타리가 다시 산 울타리가 됐다. 저들 셈에는. 사흘 밤을 아무것도 안 넘어왔다.<br><br>몸에 남은 기억을 겹으로 되살렸다. 부여가 물건만이 아니라 기억에도 걸린다는 것. 흉터를 본으로 뜨는 법. 이 손은 이제 지난 일도 입힌다.`,
      ng:`아픔의 겹을 입혔는데 결을 너무 곱게 짰다. 옛 전기는 거칠었는데.<br><br>맨 앞 것이 코를 대고— 갸웃했다. 아픈데 아픈 결이 다르다. 가짜를 안 것이다.<br>저들은 영리하다. 가짜 아픔이면 진짜 벽이 아니다. 그 밤 울타리가 세 군데서 밀렸다. 횃불로 밤을 새워 막았다. 흉내는 결까지 흉내여야 한다. 고운 솜씨가 늘 좋은 솜씨는 아니라는 걸, 부여 배운 뒤 처음 알았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 애자와 쇠줄을 소리 나게 다시 조여 저들 눈앞에서 손본다.', k:'steady', dc:25,
      ok:`해 지기 전, 저들이 수풀에서 보는 시간에 일부러 울타리를 손봤다. 애자를 닦고 쇠줄을 당겨 조이고, 망치 소리를 크게 내며.<br><br>저들 기억에 울타리를 손보는 사람 다음엔 아픈 울타리가 왔을 것이다. 기억은 순서로 남는다.<br>그 밤 코끝 하나 울타리에 안 닿았다. 수풀에서 보기만 했다. 겹 없이, 마력 없이, 망치 소리 하나로 산 하룻밤. 다만 하루짜리라는 걸 안다. 내일 밤엔 다른 수가 필요하다. 그래도 하루는 하루다.`,
      ng:`망치 소리가 너무 컸다. 울타리 너머 저들만 들으라던 소리를 벌판 건너 큰 것까지 들었다.<br><br>땅이 울리기 시작했다. 망치질 따위를 궁금해할 몸집이 아니라, 그냥 소리 난 쪽으로 걷는 것이다.<br>울타리고 뭐고 다섯이 바위 지대로 뛰었다. 큰 것은 울타리를 종잇장처럼 밟고 지나갔다. 기껏 조인 쇠줄이 발가락 사이에 끌려 반 마장을 갔다. 소리는 겨눠서 낼 것. 벌판에서는 모두가 듣는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'S2', t:'잔잔함 — 물결을 지우며 건너다',
  x:`허리까지 잠기는 양치밭을 건넌다. 물속 큰 것은 물결을 읽는다. 걸음마다 번지는 사람의 물결을.<br><br>
    물에 잔잔함을 입히는 수가 있다. 몸 둘레 한 자의 물에만. 걸어도 물결이 몸 곁에서 눕는 겹.<br>
    다섯 몸 둘레를 다 입히면 긴 길은 못 버틴다. 앞사람 하나만 입히고 넷이 그 물길을 바짝 따르는 수.<br><br>
    앞사람의 잔잔함이 지나간 물은 반 숨쯤 눕는다. 그 반 숨을 밟고 가는 것이다.`,
  o:[
    { l:'① 마력으로 맨 앞 몸 둘레에 잔잔함을 입히고 한 줄로 따른다.', k:'fix', dc:26, cost:{ mana:36 },
      ok:`맨 앞에 이쪽이 섰다. 몸 둘레 한 자의 물에 잔잔함을 입혔다. 걸어도 물이 안 운다. 물결 대신 기름 지나간 듯한 띠만 남는다.<br><br>넷이 그 띠를 한 줄로 밟았다. 띠가 눕는 반 숨 안에 다음 발이 오게. 다섯 물결이 한 줄 띠로 줄었다.<br>벌판 가운데서 물밑의 큰 것이 한 번 깼다. 띠 곁을 길게 지나갔다. 읽을 물결이 없는 물을 의아해하는 몸짓으로. 그리고 도로 가라앉았다. 띠는 물결이 아니다. 저것의 글에는 없는 글자다.`,
      ng:`잔잔함의 띠는 성했는데 넷의 줄이 흐트러졌다. 셋째가 물풀에 걸려 띠 밖으로 반 발 디딘 것이다.<br><br>물결 한 송이가 벌판에 피었다. 한 송이면 충분했다.<br>물밑이 일어났다. 다섯이 양치 무더기로 흩어져 숨고, 큰 것이 물결 핀 자리를 집채만 한 입으로 갈랐다. 빈 물만 물었다. 반 시진을 잎 사이에서 떨었다. 띠는 길이고 길은 반 발도 벗어나면 길이 아니다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 잔잔함 없이 물결이 큰 바람 날을 골라 단숨에 건넌다.', k:'evade', dc:26,
      doom:{ title:'바람이 멈춘 자리', what:'물밑의 큰 것에게 물려 양치잎 밑으로 가라앉습니다', dc:20, sec:35,
        text:`바람 큰 날을 기다렸다. 온 벌판이 물결이면 사람 물결쯤은 묻힌다. 다섯이 물을 갈랐다.<br><br>반을 건넜을 때 바람이 명치 꺼지듯 뚝 죽었다. 벌판의 물결이 일제히 누웠다. 다섯 물결만 남았다. 도드라지게.<br>물이 발밑에서 꺼진다. 큰 것이 입을 벌린 것이다. 맨 뒤의 이쪽 허리에 미끄럽고 억센 것이 감긴다.<br><br>양치잎이 머리 위에서 닫힌다. 물속으로 끌려 내려간다. 마지막으로 보인 것은 잎 사이로 부서지던 뿌연 하늘이었다.`,
        dieText:`물결이 가라앉은 벌판은 금세 처음 같아졌다. 바람도 미안한 듯 다시 불었다.<br><br>넷은 이틀을 돌아 벌판 가장자리 얕은 턱으로 건넜다.<br>그 뒤로 넷은 바람을 안 믿는다. 바람이 세게 불수록 더. 바람은 꼭 가장 깊은 데서 숨을 바꾼다는 것을, 넷은 가장 비싼 값으로 배웠다.` },
      ok:`바람 큰 날을 기다렸다. 다만 바람을 다 믿지는 않았다. 바람은 숨을 바꾼다.<br><br>건너는 길을 반으로 잘라 가운데 양치 무더기를 쉼터로 박아 뒀다. 바람이 죽으면 무더기를 안고 서기로.<br>과연 복판에서 바람이 한 번 죽었다. 다섯이 무더기에 붙어 물결이 눕기를 기다렸다 다음 바람에 마저 건넜다. 벌판을 나와서 보니 지나온 물에 긴 등줄기가 한 바퀴 돌고 있었다. 쉼터가 없었으면 그 등줄기가 마중이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'가시 울짱 — 날카로움을 벼리다',
  x:`무리가 뚫으려는 약한 기둥 앞에 밤새 가시덤불을 옮겨 쌓았다. 산 가시가 아니라 마른 가시라 억세긴 한데 무딘 데가 많다.<br><br>
    무딘 가시는 저들 가죽에 빗질이다. 날카로움을 입히면 다르다. 가시 하나하나가 송곳이 된다.<br>
    덤불 전체는 못 입힌다. 저들이 몸을 들이밀 어귀, 그 한 아름만.<br><br>
    어디로 들이밀지는 저들이 정한다. 아니, 정하게 만들 수 있다.`,
  o:[
    { l:'① 어귀 한 곳만 엉성하게 비워 유인하고 그 안쪽 가시에만 날카로움을 입힌다.', k:'fix', dc:26, cost:{ mana:35 },
      ok:`덤불 한 곳을 일부러 엉성하게 쌓았다. 눈에 띄게 허술한 어귀. 그리고 그 안쪽 가시 한 아름에만 마력을 모아 날카로움을 입혔다.<br><br>저들은 허술한 데로 온다. 셈이 빠르니까. 밤중에 맨 앞 것이 그 어귀로 어깨를 들이밀었다.<br>비명이 정원을 갈랐다. 송곳 백 개가 어깨를 문 것이다. 빼는 데도 백 번 찔리며 물러났다. 그 뒤로 저들은 허술한 데를 더 의심한다. 허술함이 덫이 된 밤 이후로. 덕분에 멀쩡한 울타리까지 든든해졌다.`,
      ng:`어귀를 비워 뒀는데 저들이 안 속았다. 전에 허술한 데서 혼이 난 적 있는 무리였는지.<br><br>엉뚱하게 덤불 반대쪽, 날카로움을 안 입힌 쪽을 밀었다. 무딘 가시가 빗질처럼 쓸려 나갔다.<br>창 셋이 달려가 어귀를 몸으로 메웠다. 횃불이 두 개 꺼질 때까지 밀고 밀리다 저들이 물러났다. 덫은 상대의 버릇을 읽고 놓는 것이다. 버릇을 모르는 상대에게는 덫이 아니라 구멍이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, spirit:-16 } },
    { l:'② 덤불에 기대지 않고 기둥 자체를 돌과 통나무로 받친다.', k:'break', dc:25,
      ok:`가시는 겉치레다. 기둥이 서야 울타리가 선다. 쓰러진 통나무를 둘이 메어다 기둥에 빗대 박고, 밑동에 돌을 쌓았다.<br><br>버팀목 박는 소리가 쿵쿵 울렸지만 해 있는 동안이라 괜찮았다. 저들은 밤의 것들이다.<br>그 밤 저들이 기둥을 밀었다. 기둥이 안 밀렸다. 어깨로 받고, 둘이 받고, 포기했다. 힘으로 세운 것은 힘으로 선다. 부여 없이 선 벽이라 아침에 걷을 것도 없었다. 그게 은근히 개운했다.`,
      ng:`통나무를 메어 오는 길이 문제였다. 둘이 나른 통나무가 무게를 못 이겨 비탈에서 굴렀다.<br><br>구르는 통나무가 울타리 아래쪽을 받았다. 지키려던 손으로 기둥 하나를 더 흔들어 놓은 꼴.<br>해 질 녘까지 두 기둥을 손봤다. 손은 발랐는데 셈이 늦어, 밤에는 결국 그 앞에 번을 겹으로 세웠다. 일은 해 지기 전에 끝나는 만큼만 벌일 것. 통나무가 가르친 산수다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'승강기 밧줄 — 녹과 함께 벗겨지는 겹',
  x:`낡은 승강기 밧줄은 쇠줄이다. 겉이 온통 녹이다. 질김을 입히려고 손을 댔다가 멈췄다.<br><br>
    녹 위에 입힌 겹은 녹과 함께 떨어진다. 쇠줄이 도르래를 감아 돌 때마다 녹이 비늘처럼 벗겨지는데, 겹도 그 비늘에 실려 벗겨진다.<br>
    입히려면 녹을 먼저 벗겨야 한다. 벗기는 소리는 정원에 울릴 것이다.<br><br>
    소리와 겹. 둘 중 하나는 값을 치러야 한다.`,
  o:[
    { l:'① 녹을 천으로 감싸 소리 죽여 벗기고 맨쇠에 질김을 입힌다.', k:'fix', dc:26, cost:{ mana:37 },
      ok:`쇠줄을 한 발씩 젖은 천으로 감아쥐고 비볐다. 녹이 천 속에서 소리 없이 벗겨졌다. 한나절 일이었다.<br><br>맨쇠가 드러난 자리마다 질김을 입혔다. 녹 없는 쇠는 겹을 깊이 문다.<br>다섯이 두 번에 나눠 올랐다. 도르래가 감길 때마다 벗겨질 녹이 없으니 겹도 안 벗겨졌다. 쇠줄이 노래하듯 팽팽했다. 부여는 바탕 손질이 반이다. 입히는 손보다 벗기는 손이 먼저라는 것. 한나절의 녹가루가 가르쳐 준 순서다.`,
      ng:`한나절이 길었다. 녹을 반쯤 벗겼을 때 해가 기울었다. 밤 일은 못 한다. 반만 벗긴 채 올라야 했다.<br><br>벗긴 반은 겹이 물었고 안 벗긴 반은 돌 때마다 겹이 비늘로 날렸다.<br>둘째 바구니가 오르는 중에 안 벗긴 자리가 도르래에 물려 삐걱 울었다. 수풀이 그 소리에 깼다. 바구니가 턱을 넘는 것과 수풀이 승강기 밑에 닿는 것이 거의 같았다. 반만 한 일은 반이 아니라 반의반이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 쇠줄의 성한 가닥 수를 세어 겹 없이 버틸지 셈한다.', k:'sense', dc:25,
      ok:`쇠줄을 풀어 보니 가는 가닥 아홉이 꼬인 줄이었다. 하나하나 당겨 봤다. 성한 가닥 여섯, 삭은 가닥 셋.<br><br>여섯이면 한 번에 둘까지. 셈이 나왔다. 세 번에 나눠 둘, 둘, 하나.<br>겹 없이 셈만으로 올랐다. 마지막 바구니가 턱을 넘을 때 삭은 가닥 하나가 톡 끊어졌지만 성한 여섯은 끄떡없었다. 마력은 한 톨도 안 들었다. 셈이 마력보다 쌀 때는 셈을 쓴다. 부여술사의 곳간 지키기다.`,
      ng:`가닥을 세느라 쇠줄을 풀었다 다시 꼬는데 꼬임이 처음 같지 않았다. 쇠줄은 꼬임이 힘이다.<br><br>첫 바구니가 오르다 줄이 늘어나며 반 길을 미끄러졌다. 안의 둘이 바닥에 나뒹굴었다.<br>다시 꼬고 매듭으로 물려서야 줄이 섰다. 반나절이 갔다. 뜯어 본 것은 뜯기 전으로 못 돌아갈 수 있다. 셈하러 뜯을 때는 되꼬을 손까지 셈에 넣을 것.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'알 곁 — 품 안의 표식',
  x:`넷째가 수풀에서 미끄러지며 알 무더기에 손을 짚었다. 가죽 알 하나가 손바닥 밑에서 출렁했다.<br><br>
    부여술사 눈에 보였다. 알의 겹 한 자락이 넷째 손에 옮겨 붙는 것이. 품 안. 어미의 겹이다.<br>
    저 표식을 단 것은 어미에게 제 알이다. 알은 어디 있든 어미가 찾아낸다.<br><br>
    넷째 손등에서 그 겹이 지금 뿌리를 내리는 중이다.`,
  o:[
    { l:'① 표식을 걷어 통나무에 옮겨 붙이고 물에 띄워 보낸다.', k:'fix', dc:26, wake:1,
      ok:`넷째 손등의 겹을 손끝으로 걷었다. 뿌리내리기 전이라 걷혔다. 걷은 겹을 품에 모셔 쥐고 개울가로 가 통나무 등걸에 옮겨 붙였다.<br><br>품 안의 겹이 등걸에 뿌리를 내렸다. 등걸을 물에 밀었다. 하류로. 정원 반대쪽으로.<br>그 밤 먼 하류 쪽에서 어미의 발소리가 벌판을 건너갔다. 제 알을 찾아. 등걸은 밤새 하류를 떠다닐 것이다.<br><br>남의 겹을 산 채로 걷어 산 채로 옮겼다. 걷는 손과 입히는 손이 한 호흡이 된 첫날. 부여가 손에서 숨처럼 나온 밤이었다. 다만 어미 생각을 하면 숨이 좀 무겁다. 그건 어쩔 수 없다.`,
      ng:`겹을 걷는데 반이 손등에 남았다. 뿌리가 생각보다 빨랐다.<br><br>반쪽 표식은 반쪽 알이다. 어미가 못 찾지는 않고 천천히 찾는다.<br>사흘 밤을 어미 발소리가 다섯 뒤를 크게 돌았다. 가까워지지도 멀어지지도 않고. 나흘째에 치유 아는 일행이 넷째 손등을 뜨거운 약초 물로 불려 남은 겹을 지웠다. 발소리가 그쳤다. 넷째는 그 사흘간 제 손을 품에 못 넣고 잤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 표식을 단 채로 밤을 숨어 어미를 그냥 보낸다.', k:'hide', dc:26,
      doom:{ title:'품으로 돌아가는 알', what:'어미에게 물려 알 무더기 쪽으로 끌려갑니다', dc:20, sec:36,
        text:`표식쯤이야 하룻밤 숨으면 될 줄 알았다. 바위 틈 깊이 들어가 넷째를 제일 안쪽에 뉘었다.<br><br>어미는 밤이 깊기 전에 왔다. 코로 찾지 않았다. 겹으로 찾았다. 표식은 어둠에서도 어미 눈에 등불이다.<br>바위 틈 입구가 뜯겨 나간다. 돌이 흙처럼 파인다. 긴 주둥이가 들어와 정확히 넷째 손등을 문다. 상하지 않게. 알을 무는 입으로.<br><br>넷째가 끌려 나간다. 알 무더기 쪽으로. 어미 셈에 저것은 제 알이고, 알은 품으로 돌아가야 한다.`,
        dieText:`알 무더기 곁에는 다음 날에도 넷째가 있었다. 멀쩡히 앉아 있었다. 다만 둘레를 어미가 돌고 있어 아무도 못 다가갔다.<br><br>어미는 넷째를 품었다. 알처럼. 먹이도 물어다 놓았다.<br>구출은 이레 뒤에야 됐다. 어미가 사냥 나간 한나절을 틈타서. 돌아온 넷째는 한동안 말을 안 했다. 따뜻했다는 말만 했다. 그게 제일 무서운 말이었다.` },
      ok:`숨기 전에 반 숨 셈했다. 표식은 겹이다. 겹은 어둠에서 더 밝다. 숨는 수로는 못 이긴다.<br><br>대신 알 무더기 곁으로 돌아갔다. 넷째 손을 알 하나에 다시 짚게 했다. 표식이 알 곁에 있으면 어미 셈에 알은 제자리다.<br>어미가 왔다. 알들을 세고, 넷째 손등의 표식도 세고, 다 제자리라 만족하고 엎드렸다. 어미가 잠든 새벽에 손을 떼고 물러났다. 표식은 알 곁에 남겨 두고. 품 안에서 빠져나오는 길은 품 안을 지나는 길뿐이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'냄새 나눠 담기 — 잎배',
  x:`무리가 다섯의 냄새를 익혔다. 사흘째 같은 무리가 따라붙는다. 냄새 줄을 쥔 것이다.<br><br>
    줄을 끊는 수로는 부족하다. 저들 코에 박힌 냄새 자체를 흩어야 한다.<br>
    다섯 몸의 냄새 겹을 걷어 잎에 나눠 담는 수. 넓은 양치잎은 좋은 그릇이다.<br><br>
    잎배 서른 척이 개울을 타면, 다섯의 냄새가 서른 갈래로 흩어진다.`,
  o:[
    { l:'① 다섯의 냄새 겹을 걷어 잎 서른 장에 나눠 싣고 물에 띄운다.', k:'fix', dc:25,
      ok:`한 사람씩 목덜미와 겨드랑이의 냄새 겹을 손끝으로 걷었다. 걷은 겹을 양치잎마다 한 자락씩 얹고 머무름을 입혔다. 바람에 안 날리게.<br><br>서른 척 잎배를 개울에 띄웠다. 물살이 배들을 하류로, 샛강으로, 웅덩이로 흩었다.<br>그 밤 무리가 개울가에서 머리를 싸맸다. 다섯이던 냄새가 서른다섯이 됐으니. 울음으로 서로 셈을 맞춰 보다가, 셈이 안 맞는 사냥을 접고 상류로 갔다. 다섯은 하류로 갔다. 서른 척 잎배보다 조용히.`,
      ng:`겹을 걷어 잎에 담는 데까지는 됐는데 머무름이 약했다. 잎배 반이 개울 초입에서 겹을 물에 흘렸다.<br><br>물에 풀린 냄새는 흩어지는 게 아니라 퍼진다. 개울 전체가 다섯 냄새가 됐다.<br>무리가 개울을 따라 양쪽 기슭을 훑기 시작했다. 다섯은 개울을 버리고 마른 비탈로 붙어 반나절을 돌았다. 그릇에 담은 것은 그릇이 깨지면 쏟아진다. 뚜껑까지가 그릇이라는 걸 잎배 열다섯 척이 가라앉으며 가르쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 무리의 똥 자리를 찾아 다섯이 그 냄새를 덮어쓴다.', k:'luck', dc:24,
      ok:`저들 뒷간 자리를 찾았다. 코가 떨어질 냄새였지만 바닥의 마른 것을 돌로 빻아 어깨와 신발에 발랐다.<br><br>사흘 익힌 다섯 냄새 위에 저들 무리 냄새가 덮였다.<br>저녁에 따라붙던 무리가 바람 밑에서 한참 코를 들고 섰다. 쫓던 냄새 끝에서 제 무리 냄새가 나니 셈이 엉킨 것이다. 저들은 제 무리를 사냥하지 않는다. 돌아갔다. 가는 길에 덤으로 저들 뒷간 곁 덤불에서 산나물 한 아름을 건졌다. 뒷간 곁 흙이 기름진 건 어디나 같았다.`,
      ng:`덮어쓴 냄새가 과했다. 저들 코에 다섯은 이제 낯선 식구였다. 무리에 없는 식구.<br><br>낯선 식구는 사냥감보다 나쁘다. 영역을 넘본 침입자니까.<br>그 밤 무리 전체가 울며 다섯을 몰았다. 사냥의 몰이가 아니라 내쫓는 몰이. 경계 밖까지 반 마장을 내리 쫓겨났다. 쫓겨난 방향이 다행히 갈 방향이었다. 그것 하나만 운이었다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'발자국 — 오래됨을 입히다',
  x:`진흙 벌을 지나왔다. 뒤를 보니 다섯 줄 발자국이 교과서처럼 찍혀 있다.<br><br>
    지울 수는 없다. 지운 자국은 더 수상하다. 저들은 지운 자국 밑의 급함까지 읽는다.<br>
    오래됨을 입히는 수가 있다. 발자국 가장자리를 마르게, 고인 물에 이끼 때깔을, 갓 찍힌 자국을 사흘 묵은 자국으로.<br><br>
    사흘 묵은 자국은 쫓아도 늦은 자국이다. 영리한 것일수록 안 쫓는다.`,
  o:[
    { l:'① 발자국마다 오래됨을 입혀 사흘 묵은 길로 바꾼다.', k:'fix', dc:25,
      ok:`맨 뒤에 걸으며 자국마다 오래됨을 입혔다. 가장자리를 바스러지게, 바닥 물에 먼지 겹을.<br><br>반 마장쯤 뒤에서 무리가 자국에 닿는 소리가 났다. 코 박는 소리, 앞발로 자국을 긁는 소리.<br>그리고 울음 한 번. 식은 자국이라는 울음이었는지 무리가 길을 꺾었다. 사흘 전에 지나간 먹이는 사흘 어치 멀리 있다. 저들 셈으로는. 실은 반 마장이었다. 반 마장이 사흘이 되는 부여. 걸으면서 하는 부여로는 제일 수지맞는 장사다.`,
      ng:`자국마다 입히다 보니 손이 바빴다. 벌 끝 몇 걸음을 빼먹었다.<br><br>사흘 묵은 자국 끝에 갓 찍힌 자국 넷. 저들 눈엔 수수께끼가 아니라 답안지였다. 자국을 꾸민 먹이라는 답.<br>꾸민 걸 들킨 다음부터 저들은 자국을 안 믿고 코만 믿었다. 더 집요해진 것이다. 결국 개울을 두 번 건너 냄새까지 끊고서야 떨궜다. 반쪽 속임수는 정직만 못하다. 끝까지 입히든가 아예 안 입히든가.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 자국이 안 남는 길로만 골라 걷는다 — 바위와 뿌리 위.', k:'sense', dc:25,
      ok:`벌을 나오자마자 길을 바꿨다. 바위 등, 드러난 뿌리, 솔가리 더미. 자국이 안 남는 바닥만 눈으로 이어 걸었다.<br><br>느렸다. 돌아가는 길이기도 했다. 대신 다섯이 지나간 자리에 아무것도 안 적혔다.<br>해 질 녘 바위 턱에서 뒤를 봤다. 무리가 진흙 벌 끝에서 맴돌고 있었다. 자국이 끊긴 자리를 몇 번이고 되밟으며. 글이 끊긴 책 앞의 독서가들이었다. 그 책의 다음 장을 다섯은 바위 위에만 적으며 걸었다. 지나는 길에 바위 틈에서 야생 버섯도 한 줌 땄다. 자국 없는 길의 덤이었다.`,
      ng:`바위 길은 자국이 안 남는 대신 발이 남아났다. 젖은 바위에서 둘째가 미끄러졌다.<br><br>구르며 짚은 손이 바위 틈에 끼어 손톱 두 개가 뒤집혔다.<br>지혈하고 싸매는 사이 해가 졌다. 바위 지대 한복판의 밤. 자국은 안 남겼지만 피 냄새를 남겼다. 바람이 도와 밤새 아무것도 안 왔다. 운이 도운 밤을 셈에 넣지 않기로 한 지 오래지만, 그 밤만은 넣어 줬다.`,
      win:{ exp:16, dream:2, item:'야생 버섯' }, lose:{ hp:-28, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 분대장 · 무력
// ------------------------------------------
kJob('squad', 'S', [

{ at:'S', t:'어둠 — 손아귀로 도는 번호',
  x:`여기서는 입을 못 연다. 목소리는 저들의 길잡이다. 번호도 손으로 돌린다.<br><br>
    손에서 손으로. 한 번 쥐면 하나, 받은 사람이 다음 손을 쥐면 둘. 다섯 번 돌아 맨 끝에서 이쪽 손을 두 번 쥐면 이상 무.<br>
    오늘 밤, 두 번 쥐는 신호가 왔다. 그런데 한 박 늦게 한 번이 더 왔다. 여섯 번째 쥠.<br><br>
    차갑고, 손가락이 길고, 쥐는 법을 방금 배운 손이었다.`,
  o:[
    { l:'① 신호를 바꾼다 — 쥐는 수가 아니라 쥐는 세기로.', k:'fix', dc:25, wake:1,
      ok:`그 자리에서 신호를 바꿨다. 쥐는 수는 흉내 낼 수 있다. 세기는 다르다. 아프기 직전까지 꽉, 이 분대만 아는 세기.<br><br>새 신호로 번호를 다시 돌렸다. 다섯 번, 다 맞는 세기. 여섯 번째 쥠이 왔다. 힘이 없다. 세기를 모르는 손.<br>그 손이 쥔 손목을 이쪽이 거꾸로 낚아 비틀었다. 가늘고 긴 것이 어둠 속에서 찢어지는 소리를 내며 빠져나갔다. 다시는 줄에 손을 넣지 않았다.<br><br>신호는 뺏기면 바꾼다. 당연한 것을 어둠 속에서 반 숨 만에 해내는 것, 그게 분대를 지키는 손이다. 손아귀가 암호가 된 밤이었다.`,
      ng:`신호를 바꾸는 사이 줄이 한 번 엉켰다. 넷째가 옛 신호로 쥐고 다섯째가 새 신호로 받고.<br><br>엉킨 줄 복판에 그 차가운 손이 끼어들었다. 누구 손인지 서로 모르는 채 손에서 손으로 넘어갔다.<br>맨 끝에서 이쪽이 쥔 손이 그 손이었다. 얼음장. 놓는 순간 어둠 저쪽에서 다섯 손가락이 바닥을 짚고 달아나는 소리가 났다. 밤새 다들 제 손을 가슴에 품고 잤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 줄을 좁혀 어깨가 닿게 세우고 손 대신 어깨로 센다.', k:'steady', dc:24,
      ok:`<span style="color:#d4af37;">"붙어."</span> 속삭임 한 번. 다섯이 어깨가 닿게 모였다.<br><br>어깨에서 어깨로 미는 신호. 끼어들려면 몸째 끼어들어야 한다. 가는 손가락 따위가 비집을 틈이 없다.<br>어둠 속에서 무엇이 줄 둘레를 오래 돌았다. 들어올 자리를 못 찾고. 새벽까지 어깨 다섯이 한 덩어리였다. 땀내가 서로 뱄지만 그 밤엔 그 냄새가 제일 사람 냄새였다.`,
      ng:`어깨를 붙였는데 좁아진 줄이 느려졌다. 벌판을 반도 못 건너 동이 트기 시작했다.<br><br>트는 빛에 다섯 덩어리가 벌판 복판에 드러났다. 멀리서 그것들이 그 덩어리를 봤다.<br>남은 반을 내리 뛰었다. 바위에 닿고 세어 보니 다섯은 맞는데 숨이 열 사람 몫으로 찼다. 붙는 것과 걷는 것, 둘 다 되는 간격이 있다. 그 간격을 찾는 게 숙제로 남았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'후미 — 맨 뒤의 자리',
  x:`사흘째 따라붙는 것이 있다. 거리를 안 좁힌다. 맨 뒤가 처지기를 기다리는 것이다.<br><br>
    저들은 늘 맨 뒤를 문다. 무리에서 반 걸음 떨어진 순간이 저들의 때다.<br>
    맨 뒤는 분대에서 제일 위험한 자리고, 제일 위험한 자리는 분대장 자리다. 다만 분대장이 뒤에 서면 앞이 빈다.<br><br>
    맨 뒤를 누가, 어떻게 서나.`,
  o:[
    { l:'① 후미를 둘씩 짝지어 반 시진마다 교대시킨다.', k:'fix', dc:25,
      ok:`맨 뒤를 혼자 세우지 않았다. 둘씩, 반 시진씩. 하나는 길을 등지고 걷고 하나는 뒷걸음으로 어둠을 보며.<br><br>혼자가 아닌 후미는 후미가 아니다. 저들 셈에는.<br>따라붙던 것이 이틀을 더 재다가 떨어져 나갔다. 마지막 날 밤 그것이 가까이 와서 후미 둘을 오래 봤다. 둘이 마주 서서 창을 겨누자, 처음으로 소리를 냈다. 혀 차는 소리 비슷한. 그러고는 끝이었다.`,
      ng:`둘씩 세웠는데 교대 때가 흠이 됐다. 교대하는 반 숨, 네 사람이 한 자리에 모이고 앞뒤가 다 빈다.<br><br>그 반 숨에 그것이 들어왔다. 무는 대신 스쳐 지나갔다. 잴 것을 다 쟀다는 듯.<br>스친 자리의 둘째 소매가 어깨까지 갈라져 있었다. 살은 안 닿았다. 경고도 사냥의 한 수다. 교대는 그날부터 걸으면서 하는 것으로 바꿨다. 멈추는 교대는 교대가 아니라 초대였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 분대장이 맨 뒤에 혼자 선다 — 늘 하던 대로.', k:'steady', dc:26,
      doom:{ title:'맨 뒤의 자리', what:'후미를 노리던 것에게 끌려 어둠 속으로 사라집니다', dc:20, sec:40,
        text:`맨 뒤에 섰다. 넷을 앞세우고. 등 뒤의 어둠은 이쪽 몫이다. 늘 그랬다.<br><br>그것도 그걸 안다. 사흘을 쟀으니. 맨 뒤가 제일 센 놈이라는 것까지.<br>그래서 저것은 제일 센 놈부터 지우기로 셈을 세운 것이다. 머리부터 지우면 몸은 흩어지니까.<br>발소리도 없었다. 턱이 어깨와 목 사이에 들어온다. 끌린다. 소리를 내면 넷이 돌아온다. 돌아오면 넷도 위험하다. 이를 악물었다.<br><br>어둠이 입을 다문다. 앞의 넷은 아직 모른 채 걷고 있다.`,
        dieText:`넷이 알아챈 것은 쉰 걸음을 더 가서였다. 뒤가 너무 조용해서.<br><br>되밟아 간 길에는 창 한 자루가 어둠을 향해 겨눠진 채 땅에 박혀 있었다. 소리 없이 싸운 자리였다.<br>넷은 그날부터 맨 뒤를 둘씩 섰다. 혼자 서겠다는 사람이 나올 때마다 넷은 같은 말을 한다. 그 자리는 혼자 서는 자리가 아니다. 그걸 가르친 사람이 그 자리에서 혼자였다.` },
      ok:`맨 뒤에 섰다. 다만 늘 하던 대로는 아니었다. 창을 거꾸로 쥐고 날을 등 뒤로 늘어뜨렸다. 등이 허술해 보이게. 실은 등이 창끝이게.<br><br>그것이 사흘의 셈을 끝내고 왔다. 허술한 등으로. 등 뒤에서 공기가 접히는 기척에 몸을 앞으로 던지며 창을 뒤로 내질렀다.<br>손맛이 묵직했다. 비명이 어둠을 찢고 멀어졌다. 맨 뒤는 미끼 자리이자 덫 자리다. 그걸 아는 놈이 서면.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 따라붙는 것의 발소리 간격으로 저것의 때를 먼저 읽는다.', k:'sense', dc:24,
      ok:`따라오는 발소리를 사흘 치 들으니 결이 잡혔다. 평소엔 느슨하고, 이쪽 줄이 늘어질 때만 발소리가 사라진다. 소리를 죽이는 것이 저것의 도움닫기다.<br><br>발소리가 사라질 때마다 구령을 넣었다. <span style="color:#d4af37;">"붙어!"</span> 줄이 당겨지고, 저것의 도움닫기가 헛돌았다.<br>세 번을 그렇게 끊자 저것이 먼저 지쳤다. 사냥은 저들에게도 셈이다. 수지가 안 맞는 사냥감 명단에 이 분대가 올랐을 것이다. 그보다 좋은 명단이 없다.`,
      ng:`결을 읽는다고 귀를 뒤에 두고 걸었더니 앞이 소홀해졌다. 앞에서 길이 꺼졌다.<br><br>둘째가 허방을 짚고 굴렀다. 다행히 얕은 구덩이. 그런데 구덩이 바닥에 뼈가 깔려 있었다.<br>저것이 이쪽을 몰아온 길이 이 구덩이였다. 뒤만 보는 분대장을 앞으로 모는 수. 둘째를 끌어 올리고 구덩이를 크게 돌았다. 뒤를 읽는 동안 앞을 맡길 눈을 세워 둘 것. 혼자 다 하려다 당할 뻔했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S', t:'구령 없는 전진 — 손의 말',
  x:`여기서 목소리는 미끼다. 구령으로 살던 분대가 벙어리가 됐다.<br><br>
    손의 말을 새로 지었다. 주먹은 정지. 손바닥은 엎드려. 두 손가락은 둘씩 전진. 사흘을 가르쳐 다섯 몸에 박았다.<br>
    오늘, 앞서 보낸 둘에게 정지 신호를 보냈는데 셋이 멈췄다. 둘 보냈는데.<br><br>
    어둠 속에서 하나가 더, 이쪽 손의 말을 배우고 있다.`,
  o:[
    { l:'① 신호 하나를 거짓으로 비워 둔다 — 그 신호에 움직이는 것이 적이다.', k:'fix', dc:26, wake:1,
      ok:`새 신호를 하나 지어 다섯에게만 알렸다. 세 손가락. 뜻은 아무것도 하지 마라. 거짓 신호다.<br><br>다음 날 어스름에 세 손가락을 크게 들었다. 다섯은 그대로 걸었다. 수풀 한 곳만 움찔 멈췄다.<br>거기다. 다섯 창이 일제히 그 수풀을 겨눴다. 신호를 훔치던 것이 제가 배운 말에 찔려 달아났다. 말을 훔치는 놈에게는 거짓말을 가르친다.<br><br>신호는 말이고, 말에는 거짓말이 있어야 말이 된다. 분대의 말에 자물쇠를 다는 법을 배웠다. 이제 이 분대의 손말은 다섯만 다 안다. 여섯째는 영원히 한 단어가 모자랄 것이다.`,
      ng:`거짓 신호를 지었는데 넷째가 헷갈렸다. 세 손가락에 넷째 혼자 엎드렸다.<br><br>엎드린 하나와 선 넷. 어둠 속의 그것 눈에 답이 적혔다. 저 신호는 엎드리라는 말이구나.<br>다음 날 그것이 수풀을 흔들어 이쪽 신호를 끌어냈다. 신호와 움직임을 잇대 보는 것이다. 공부하는 적이라니. 결국 손말을 통째로 새로 지었다. 이번엔 사흘 말고 닷새를 들여서. 가르치는 속도보다 배우는 속도가 빠른 적 앞에서는 교본을 자주 바꾸는 수밖에 없다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 손의 말을 접고 몸의 그늘에 숨어 신호 없이 간다.', k:'hide', dc:25,
      ok:`신호가 새면 신호를 끊는다. 다섯이 한 줄, 앞사람 등만 보고, 앞사람이 하는 것을 반 박 늦게 따라 하기. 말 없는 행군.<br><br>맨 앞의 이쪽이 멈추면 물결처럼 뒤가 멈췄다. 숙이면 숙여졌다.<br>신호를 훔치던 것이 훔칠 것을 잃었다. 몸짓의 물결은 어디서 시작해 어디로 가는지 밖에서는 안 읽힌다. 바위 지대까지 그 물결로 갔다. 도착해서 둘째가 말했다. 꼭 한 마리 긴 짐승이 된 것 같았다고. 그게 바로 분대라고, 이쪽은 속으로만 답했다.`,
      ng:`물결 행군은 좋았는데 반 박 늦음이 쌓이는 게 흠이었다. 맨 뒤는 이쪽보다 두 박 늦게 움직였다.<br><br>길이 꺾이는 모퉁이에서 그 두 박이 사달이 났다. 앞 넷은 꺾었는데 맨 뒤가 두 박 어치 직진한 것이다.<br>맨 뒤 다섯째가 혼자 어둠에 반 숨 노출됐다. 수풀이 그쪽으로 쏠리는 걸 넷이 되돌아 창으로 막았다. 물결은 길 전체가 곧을 때의 수다. 꺾이는 길에선 꺾임마다 사람을 박아 둘 것.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'무게의 명령 — 짐을 버려라',
  x:`들켰다. 벌판 건너까지 뛰면 바위 지대다. 뒤에는 그것들. 짐을 지고는 못 이긴다.<br><br>
    버려야 한다. 문제는 무엇을 버리느냐다. 물, 먹을 것, 연장, 약초. 버린 것은 이 어둠에서 다시 못 구할 수도 있다.<br>
    그리고 사람은 제 짐을 제일 늦게 버린다. 제 것이니까.<br><br>
    고르는 데 쓸 시간은 다섯 숨. 명령은 그래서 있다.`,
  o:[
    { l:'① 품목을 지정해 외친다 — 물과 약초만 남기고 전부 버려.', k:'fix', dc:25,
      ok:`<span style="color:#d4af37;">"물과 약초만! 나머지 전부 버려! 지금!"</span><br><br>고르게 하면 못 버린다. 품목을 찍어 주면 손이 먼저 움직인다. 네 숨 만에 짐 넷이 벌판에 떨어졌다.<br>가벼워진 다섯이 벌판을 갈랐다. 그것들이 떨어진 짐에 반 숨씩 코를 박는 사이 거리가 벌어졌다. 바위 지대에 올라 뒤를 보니 짐들이 뜯기고 있었다. 솥이, 연장이. 사람 대신 뜯기라고 버린 것들이니, 제값을 한 셈이다.`,
      ng:`품목을 외쳤는데 둘째가 연장 자루를 못 놨다. 아비가 물려준 끌이 들었다고 했다. 반 숨, 한 숨.<br><br>그 두 숨에 거리가 녹았다. 맨 뒤 둘째 발꿈치까지 그것들 숨이 닿았다.<br>이쪽이 되돌아 창을 휘둘러 길을 텄다. 둘째는 결국 자루째 버리고서야 벌판을 건넜다. 바위에 올라 둘째가 울었다. 명령은 품목보다 빨라야 한다. 마음이 짐을 쥐기 전에.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 짐을 벌판 어귀에 한 무더기로 쌓아 미끼로 삼는다.', k:'luck', dc:24,
      ok:`버릴 바엔 모아서 버린다. 벌판 어귀에 짐 넷을 한 무더기로 쌓고 맨 위에 먹을 것 자루를 풀어 헤쳤다.<br><br>냄새가 피는 무더기 하나는 흩어진 짐 넷보다 오래 붙든다.<br>그것들이 무더기에 몰린 사이 다섯은 벌판을 다 건넜다. 이튿날 새벽, 먼 길을 돌아 그 자리를 다시 지났다. 뜯긴 자루들 틈에 기름 먹인 보자기에 싼 말린 고기 꾸러미 하나가 성한 채 밟혀 있었다. 운까지 거들어 준 미끼였다.`,
      ng:`무더기를 쌓는 데 시간을 썼다. 쌓는 등 뒤로 그것들이 벌써 벌판 어귀에 닿았다.<br><br>미끼고 뭐고 뛰었다. 무더기는 공들여 쌓은 모양 그대로 버려졌다.<br>그런데 저것들이 무더기를 지나쳤다. 쌓은 짐보다 뛰는 사람이 저들 눈에 더 맛있는 것이다. 바위 지대까지 숨 한 모금 못 쉬고 뛰었다. 미끼는 던지는 때가 반이다. 적이 보기 전에 깔아 둬야 미끼지, 보는 앞에서 쌓으면 그냥 밥상 차리는 꼴이다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'업는 어깨 — 다친 하나와 벌판',
  x:`셋째 발목이 꺾였다. 걷기는 하는데 뛰지는 못한다. 그리고 오늘 넘어야 하는 것은 뛰어야 하는 벌판이다.<br><br>
    들것을 짤 나무가 없다. 업는 수밖에.<br>
    업는 등은 창을 못 쓴다. 업힌 사람도 못 쓴다. 다섯 분대가 세 창 분대가 되는 것이다.<br><br>
    누가 업고, 남은 창 셋을 어디에 세우나.`,
  o:[
    { l:'① 무력을 다해 분대장이 업고 창 셋을 세모꼴로 두른다.', k:'steady', dc:25, cost:{ might:34 },
      ok:`셋째를 업었다. 제일 무거운 짐은 분대장 등이 진다. 창 셋을 앞에 하나 양옆에 둘, 세모꼴로 둘렀다. 업은 등이 세모의 속이 되게.<br><br>벌판 복판에서 그것들이 간을 보러 붙었다. 세모가 돌면서 늘 창끝이 마중했다. 속의 등은 한 번도 안 드러났다.<br>바위 지대에 닿아 셋째를 내렸다. 등에서 땀이 김으로 올랐다. 셋째가 미안하다 했다. 이쪽은 어깨를 두드렸다. 업히는 것도 분대 일이다. 잘 업혔다.`,
      ng:`업고 뛰는데 벌판 반에서 다리가 먼저 알았다. 무게 셈이 틀렸다. 셋째에 짐까지 얹은 등이었다.<br><br>걸음이 늘어지자 세모꼴이 같이 늘어졌다. 그것들이 그 틈을 봤다.<br>옆구리로 파고드는 하나를 왼쪽 창이 받고, 그 바람에 세모가 깨지고, 남은 벌판은 전원이 이를 물고 내달렸다. 바위에 닿아 다 토했다. 업는 수는 맞았는데 짐까지는 욕심이었다. 등은 하나고 무게는 셈이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 번갈아 업되 업는 차례를 미리 벌판 길이로 나눈다.', k:'bond', dc:24,
      ok:`벌판을 눈으로 재어 넷으로 갈랐다. 한 토막에 한 사람씩 업는 차례. 바꾸는 자리도 미리 찍었다. 바위 그루터기, 마른 개울, 흰 돌.<br><br>차례를 아는 등은 지치지 않는다. 제 토막만 버티면 되니까.<br>흰 돌에서 마지막 교대를 하고 벌판을 다 건넜다. 셋째가 네 등에 업혀 온 길을 돌아보며 말했다. 벌판이 네 토막으로 기억된다고. 업힌 사람에게도 길이 토막으로 보이면, 그 분대는 잘 가고 있는 것이다.`,
      ng:`차례는 좋았는데 교대 자리가 문제였다. 마른 개울에서 바꾸는 참에 발밑 자갈이 울었다.<br><br>벌판에서 소리는 깃발이다. 멀리서 그것들 머리가 일제히 이쪽으로 돌았다.<br>남은 두 토막을 교대 없이 내리 뛰었다. 마지막 등을 맡은 다섯째가 바위에 닿자마자 무릎을 꿇었다. 교대 자리는 소리 안 나는 바닥으로 고를 것. 차례표에 바닥 칸이 하나 늘었다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'트인 땅 — 하나씩 건너라',
  x:`숲과 숲 사이 트인 땅이다. 쉰 걸음. 가릴 것이 풀 한 포기 없다.<br><br>
    다섯이 한꺼번에 건너면 다섯 배로 눈에 띈다. 하나씩 보내면 넷이 숲에서 창으로 받칠 수 있다.<br>
    다만 하나씩은 느리다. 다섯 번째 사람이 건널 때쯤 저쪽도 셈을 끝낸다.<br><br>
    순서와 간격. 분대장의 입에 다섯 목숨이 달린 쉰 걸음이다.`,
  o:[
    { l:'① 건너는 간격을 매번 다르게 불러 저쪽의 셈을 못 끝내게 한다.', k:'fix', dc:26, wake:1,
      ok:`첫째를 보내고 열 숨에 둘째. 둘째 뒤엔 세 숨 만에 셋째. 그리고 서른 숨을 묵혔다가 넷째.<br><br>지켜보는 눈이 있다면 간격으로 다음을 잰다. 간격이 셈이 안 되면 다음도 셈이 안 된다.<br>다섯째가 건널 차례, 수풀 저쪽이 미리 움직였다. 서른 숨짜리 간격에 맞춰 도움닫기를 시작한 것이다. 이쪽은 세 숨 만에 다섯째를 보냈다. 저것의 도움닫기가 허공을 갈랐다. 다섯이 다 건넌 숲에서 저것이 트인 땅 복판에 혼자 서 있는 걸 봤다. 셈이 깨진 사냥꾼처럼 머쓱한 뒷모습도 드물다.<br><br>간격은 고르게 배웠고 고른 간격으로 분대를 살려 왔다. 오늘은 어긋난 간격이 살렸다. 고름과 어긋남을 다 쥐어야 분대장이다.`,
      ng:`간격을 비트는데 넷째가 제멋대로 건넜다. 서른 숨을 묵히랬더니 다섯 숨 만에 튀어나간 것이다. 기다림이 더 무서웠던 모양이다.<br><br>비튼 간격이 도로 고른 간격이 됐다. 수풀이 그 박자를 탔다.<br>다섯째가 건널 때 저것이 정확히 마중 나왔다. 숲의 창 넷이 일제히 뻗어 겨우 밀어냈다. 간격은 분대장 혼자 비트는 게 아니다. 기다리는 사람 속도 비틀리지 않게 묶어 둬야 한다. 넷째를 탓하는 대신 다음부터 기다리는 자 옆에 한 사람을 붙였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 다 같이 한 덩어리로 단숨에 건넌다.', k:'evade', dc:26,
      doom:{ title:'트인 땅의 쉰 걸음', what:'덩어리에서 반 걸음 처진 채 낚아채여 수풀로 끌려갑니다', dc:20, sec:38,
        text:`하나씩은 느리다. 느린 것이 더 위험하다고 셈했다. <span style="color:#d4af37;">"한 덩어리로, 지금!"</span><br><br>다섯이 트인 땅을 갈랐다. 마흔 걸음까지는 셈이 맞았다.<br>마흔한 걸음째, 이쪽 발이 돌부리를 쳤다. 덩어리에서 반 걸음 처졌다. 반 걸음이면 덩어리가 아니다. 낱이다.<br>옆에서 온 것이 낱을 골라 물었다. 허리띠째. 몸이 옆으로 날아간다. 숲 반대쪽 수풀로. 넷의 비명이 트인 땅 너머에서 들린다. 멀어진다.`,
        dieText:`넷은 숲에 닿았다. 다섯째 걸음 소리가 없는 걸 그제야 알았다.<br><br>트인 땅에는 창 한 자루와 돌부리 하나뿐이었다.<br>넷은 그 뒤로 트인 땅 앞에 서면 돌부터 센다. 돌부리 하나, 두 개. 그리고 하나씩 건넌다. 느린 길이 느린 게 아니라는 걸, 넷은 가장 빠른 길에서 배웠다.` },
      ok:`<span style="color:#d4af37;">"한 덩어리로, 지금!"</span> 다만 뛰기 전에 반 숨, 트인 땅의 돌과 구덩이를 눈으로 다 짚었다.<br><br>길을 두 번 꺾어 돌부리를 다 비끼는 금을 그었다. 그 금대로 다섯이 달렸다. 덩어리가 한 번도 안 풀렸다.<br>수풀에서 저것이 튀어나왔지만 덩어리에는 낱이 없었다. 다섯 창이 고슴도치처럼 밖을 향한 채 구르듯 숲에 들었다. 저것은 쉰 걸음 내내 물 데를 못 찾았다. 덩어리는 속도가 아니라 빈틈 없음이 생명이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'무너지는 틈 — 어깨의 값',
  x:`지나야 하는 바위 틈이 숨을 쉰다. 위에 얹힌 바위 더미가 조금씩 내려앉는 중이다. 들어가면 어깨 폭, 길이는 열 걸음.<br><br>
    한 사람씩 빠르게 지나면 될— 때 천장에서 돌가루가 쏟아졌다. 내려앉음이 빨라졌다.<br>
    버팀목이 없다. 있는 것은 어깨뿐이다.<br><br>
    뒤에서는 아까부터 발소리가 좁혀 온다. 돌아갈 길은 없다.`,
  o:[
    { l:'① 무력을 다해 처진 바위를 어깨로 받치고 넷을 통과시킨다.', k:'steady', dc:26, cost:{ might:38 },
      ok:`틈 한가운데, 제일 처진 바위 밑에 어깨를 끼웠다. 무릎을 펴며 받쳤다. 산 하나가 어깨에 앉았다.<br><br><span style="color:#d4af37;">"하나씩! 뛰어!"</span> 넷이 등 뒤로, 옆구리 밑으로 빠져나갔다. 하나 지날 때마다 바위가 한 치씩 더 앉았다.<br>넷째가 빠지고 이쪽이 몸을 뺐다. 반 숨 뒤에 틈이 닫혔다. 쿵. 돌가루가 등을 덮었다. 틈 저쪽에서 쫓아오던 발소리가 닫힌 돌벽 앞에 멈추는 소리가 들렸다. 문까지 닫고 나온 셈이다. 어깨는 보름을 결렸다. 보름 값으로 산 문이면 싸다.`,
      ng:`받치는 데까지는 됐는데 발밑이 돌가루에 미끄러졌다. 받친 어깨가 한 뼘 꺼졌다.<br><br>바위가 그 한 뼘을 따라 앉았다. 틈이 좁아졌다. 마지막 넷째가 기다시피 빠져나오다 등짐이 끼었다.<br>짐을 포기하고 사람만 당겨 뺐다. 반 숨 뒤 틈이 짐째 닫혔다. 이불과 여벌옷이 바위 사이에서 한 자락 나부꼈다. 사람은 다 나왔다. 그거면 셈은 맞은 것이다. 어깨만 그렇게 셈해 주지 않았지만.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-36, mind:-14 } },
    { l:'② 처진 바위를 아예 쳐서 떨어뜨리고 길을 다시 본다.', k:'break', dc:25,
      ok:`받칠 수 없으면 떨어뜨린다. 넷을 물리고 창대로 처진 바위의 괸 점을 쳤다.<br><br>바위가 떨어졌다. 틈이 막히는 대신 위쪽이 열렸다. 얹혀 있던 더미가 쏟아지고 나니 그 위로 기어오를 비탈이 생긴 것이다.<br>다섯이 새 비탈로 바위 등을 타 넘었다. 뒤쫓던 발소리는 막힌 틈 앞에서 끝났다. 길은 지키는 것만이 아니라 다시 짓는 것이기도 하다. 부수는 것도 짓는 일의 반이다.`,
      ng:`괸 점을 쳤는데 바위가 엉뚱한 쪽으로 넘어갔다. 지나갈 틈 쪽으로.<br><br>틈이 반쯤 막혔다. 남은 반으로 다섯이 배를 긁으며 기어 지났다.<br>마지막 사람 발뒤꿈치가 빠져나온 뒤에야 나머지가 마저 무너졌다. 쫓던 것은 못 들어왔지만 등가죽이 다 쓸렸다. 부술 때는 넘어갈 방향부터 셈할 것. 돌은 명령을 안 듣는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'겁 — 뛰쳐나가려는 하나',
  x:`수풀에 엎드려 그것들 무리가 지나가기를 기다리는 중이다. 넷째 숨이 이상하다.<br><br>
    눈이 커지고 손이 땅을 긁는다. 겁이 차오르면 사람은 뛴다. 아무 데로나. 뛰는 순간 다섯이 다 드러난다.<br>
    말릴 목소리를 낼 수 없다. 소리가 곧 끝이니까.<br><br>
    소리 없이, 겁에 빠진 사람을 붙드는 법.`,
  o:[
    { l:'① 넷째를 분대 한가운데로 옮기고 양옆 허리띠에 묶는다.', k:'fix', dc:25, wake:1,
      ok:`기어가 넷째 어깨를 눌렀다. 눈을 맞췄다. 그리고 손짓으로 가운데 자리를 가리켰다. 둘째와 다섯째 사이.<br><br>넷째가 기어 옮겼다. 양옆 허리띠에 넷째 띠를 짧은 끈으로 걸었다. 묶인 게 아니라 이어진 것이라고, 손바닥으로 끈을 두 번 두드려 알렸다.<br>겁은 혼자일 때 뛴다. 양옆에 사람 체온이 닿아 있으면 겁도 앉는다. 무리가 다 지나갈 때까지 넷째는 떨면서도 엎드려 있었다. 나중에 넷째가 말했다. 그 끈이 목숨줄 같았다고.<br><br>겁먹은 사람은 혼내는 게 아니라 배치하는 것이다. 겁도 분대 안에 자리가 있다. 그 자리를 아는 것이 분대장이다.`,
      ng:`끈을 거는 손길에 넷째가 소스라쳤다. 묶인다고 느낀 것이다.<br><br>버둥대는 팔이 수풀을 쳤다. 사락. 무리 끝의 머리 하나가 돌았다.<br>다섯이 수풀 바닥에 얼어붙은 반 각이 한나절 같았다. 머리가 돌아가고 무리가 멀어진 뒤에야 숨을 쉬었다. 겁에는 손보다 눈이 먼저다. 눈으로 충분히 약조한 다음에 손이 가야 한다. 순서가 바뀌면 겁이 튄다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 넷째 손을 제 가슴에 얹고 제 숨을 세게 한다.', k:'bond', dc:24,
      ok:`넷째 손을 끌어다 이쪽 가슴에 얹었다. 그리고 일부러 느리게 숨을 쉬었다. 들이쉬고, 길게 내쉬고.<br><br>손바닥으로 남의 숨을 세는 동안은 제 겁을 셀 틈이 없다.<br>넷째 숨이 이쪽 숨에 포개졌다. 무리가 다 지나갈 때까지 넷째는 이쪽 심장만 셌다고 한다. 백아흔두 번이었다고, 숫자까지 기억했다. 겁은 셈을 시키면 반으로 준다. 세는 동안은 사람이 사람으로 돌아온다.`,
      ng:`가슴에 손을 얹게 했는데 이쪽 심장이 문제였다. 이쪽도 뛰고 있던 것이다. 겁은 분대장도 든다.<br><br>빠른 심장을 만진 넷째 겁이 되레 자랐다. 분대장도 무섭구나, 그 생각이 겁의 둑을 텄다.<br>튀어나가려는 넷째를 둘이 덮쳐 눌렀다. 수풀이 요동쳤지만 운 좋게 무리의 꼬리가 멀어진 뒤였다. 분대장의 겁은 분대장만 알아야 한다. 심장은 그걸 모르니, 다음부터는 손을 얹게 하기 전에 제 숨부터 다스리기로 했다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S', t:'밤 — 쪼개자는 말',
  x:`물이 떨어졌다. 반나절 거리에 샘이 있다. 둘이 다녀오고 셋이 자리를 지키자는 말이 나왔다.<br><br>
    맞는 말이다. 평지의 셈으로는.<br>
    여기는 평지가 아니다. 사흘 내내 다섯일 때는 아무 일 없었다. 저들은 다섯이 버거운 것이다. 쪼개지기를 기다리는 것이다.<br><br>
    목마름과 머릿수. 분대장의 저울에 둘이 올랐다.`,
  o:[
    { l:'① 쪼개지 않는다 — 다섯이 통째로 샘에 다녀온다.', k:'fix', dc:25,
      ok:`<span style="color:#d4af37;">"안 쪼갠다. 다 같이 간다. 짐도 다 지고."</span><br><br>자리를 버리는 셈이지만 자리는 다시 잡으면 된다. 사람은 다시 못 잡는다.<br>반나절 길을 다섯이 갔다. 샘가 진흙에 발자국이 어지러웠다. 샘을 지키는 것이 있던 것이다. 다섯 창이 둘러서서 번갈아 물을 떴다. 수풀이 두 번 어른댔지만 끝내 아무것도 안 나왔다. 다섯은 무겁다. 그 무거움이 방패다.`,
      ng:`다 같이 가는 길이 느렸다. 샘에 닿기 전에 해가 졌다.<br><br>밤 샘가는 낮 샘가와 다른 땅이다. 물 뜨는 반 각 내내 어둠 전체가 이쪽을 보고 있었다.<br>물은 채웠다. 돌아오는 밤길에 뒤따르는 기척이 둘로 늘었다. 쪼개지 않은 덕에 아무도 안 잃었지만, 밤길의 값으로 다들 한숨도 못 잤다. 물과 잠을 맞바꾼 셈. 다음엔 새벽에 떠나기로 했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 둘을 보내되 횃불과 호각으로 줄을 잇는다.', k:'luck', dc:26,
      doom:{ title:'쪼개진 둘', what:'샘길의 둘 중 하나가 물려 수풀로 끌려갑니다', dc:20, sec:36,
        text:`둘을 보냈다. 눈 밝은 다섯째와 발 빠른 둘째. 횃불을 들리고, 위급하면 호각을 불기로 했다.<br><br>반 시진 뒤 호각이 울렸다. 한 번. 길게. 그리고 끊겼다.<br>셋이 내달렸다. 샘길 중간, 횃불이 땅에 떨어져 타고 있었다. 다섯째가 수풀을 가리키며 소리쳤다. 둘째가, 둘째가.<br><br>수풀 안쪽에서 둘째의 외침이 멀어지고 있다. 끌려가면서도 호각을 또 분다. 제 자리를 알리려고. 분대장의 저울이 틀렸던 값을 둘째가 치르는 중이다.`,
        dieText:`호각 소리는 세 번째가 마지막이었다. 수풀 깊은 데서, 아주 짧게.<br><br>넷은 호각이 울린 자리마다 돌을 쌓으며 들어갔지만 끝내 빈 호각만 찾았다.<br>그 뒤로 이 분대는 어떤 목마름에도 쪼개지지 않는다. 물보다 머릿수. 새 규칙에는 이름이 있다. 둘째 이름이다.` },
      ok:`둘을 보내되 줄을 바꿨다. 횃불과 호각이 아니라, 반 마장마다 셋이 마중 자리를 옮기는 식으로. 쪼개되 멀어지지는 않게.<br><br>둘이 샘길을 가면 셋이 반 마장 뒤를 따라 옮겨 섰다. 늘 호각 한 번이면 닿는 거리.<br>샘길 중간에 수풀이 한 번 일렁였지만, 일렁임이 둘에게 닿기 전에 셋의 횃불이 먼저 닿았다. 다섯이 샘물을 지고 돌아왔다. 쪼개짐과 통짜 사이에 반 마장짜리 길이 있었다. 그 길을 찾는 게 분대장 일이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'모닥불 — 여섯째 그림자',
  x:`불을 피울 수 있는 바위 우묵이다. 오랜만의 불이다. 다섯이 불가에 둘러앉았다.<br><br>
    바위 벽에 그림자가 어린다. 세어 보는 것은 버릇이다. 하나, 둘, 셋, 넷, 다섯. 여섯.<br>
    다섯이 앉았는데 그림자가 여섯이다. 여섯째는 셋째와 넷째 그림자 사이에 앉아 있다. 어깨가 둥글고, 머리가 길다.<br><br>
    불가에 앉은 것은 다섯뿐이다. 그림자만 와서 앉은 것이다.`,
  o:[
    { l:'① 여섯째 그림자의 임자가 어디 서 있는지 응시로 짚는다.', k:'gaze', dc:26, wake:1,
      ok:`그림자에는 임자가 있다. 불과 벽 사이 어딘가에. 그림자의 목 기울기와 불의 자리를 눈으로 이어 선을 그었다.<br><br>선 끝은 바위 우묵 위 턱이었다. 어둠과 바위 사이, 숨도 없이 엎드린 것. 불가를 내려다보며 제 그림자를 다섯 사이에 밀어 넣고 앉은 것이다. 저녁상에 숟가락 얹듯.<br>이쪽이 정확히 저를 올려다보자 그림자가 먼저 일어섰다. 벽에서. 그리고 턱 위의 어둠이 비었다. 들킨 손님은 머물지 않는다.<br><br>그림자는 빛의 셈이다. 셈이 맞으면 임자가 나온다. 어둠을 직접 볼 수 없을 때 어둠의 그림자를 세는 법. 분대장의 머릿수 세기가 한 칸 깊어졌다.`,
      ng:`선을 긋는 눈이 벽과 불 사이를 오가는데, 여섯째 그림자가 고개를 돌렸다. 그림자가. 혼자서.<br><br>이쪽을 봤다. 그림자에는 눈이 없는데 보는 줄은 알겠는 것이, 제일 나빴다.<br>불을 즉시 껐다. 어둠 속에서 다섯이 등을 맞대고 새벽을 기다렸다. 동트고 보니 벽의 그을음에 사람 꼴 자국이 하나, 앉은 모양 그대로 남아 있었다. 그 우묵에서는 두 번 다시 불을 안 피웠다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 아무것도 모르는 척 불을 천천히 죽이고 자리를 옮긴다.', k:'steady', dc:25,
      ok:`들킨 티를 내면 저쪽도 수를 바꾼다. 하품을 하고, 기지개를 켜고, 잘 때가 됐다는 몸짓으로 불에 재를 덮었다.<br><br>불이 죽자 그림자가 다 죽었다. 여섯째도.<br>어둠 속에서 손 신호로 다섯을 일으켜 우묵을 비웠다. 반 마장 밖 다른 바위틈으로. 새벽에 멀리서 보니 비운 우묵 턱에 무엇이 오래 앉아 있다 갔다. 빈자리를 지키는 뒷모습이었다. 모르는 척은 분대장의 오랜 연장이다. 알면서 모르는 척이 제일 어렵고, 제일 쓸모 있다.`,
      ng:`재를 덮는 손이 너무 빨랐다. 모르는 척이 아니라 들킨 척이 됐다.<br><br>불이 꺼지기 전 반 숨, 여섯째 그림자가 벌떡 일어서는 게 벽에 비쳤다. 일어선 키가 벽을 다 채웠다.<br>다섯이 어둠 속을 구르듯 빠져나왔다. 등 뒤 우묵에서 바위 긁는 소리가 한참 났다. 다음 날 지나며 보니 불 피웠던 자리가 손톱자국으로 다 파헤쳐져 있었다. 재까지 뒤집어서, 무언가를 찾은 듯이. 무엇을 찾았는지는 생각 안 하기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S', t:'철수 — 등에 지는 분대',
  x:`매복이 터졌다. 셋째가 다리를, 다섯째가 어깨를 상했다. 걸을 수 있는 것은 셋.<br><br>
    여기 더 있으면 피 냄새가 어둠을 다 부른다. 철수. 당장.<br>
    성한 셋 중 둘이 다친 둘을 부축하면, 창은 하나 남는다. 창 하나로 뒤를 막으며 가는 길.<br><br>
    분대장의 등과 어깨가 얼마를 질 수 있는지, 오늘 밤 저울에 오른다.`,
  o:[
    { l:'① 짐을 다 버리고 부축 둘, 창 하나, 길잡이 하나로 짠다.', k:'fix', dc:25,
      ok:`반 숨에 짰다. <span style="color:#d4af37;">"짐 전부 버려. 둘째는 셋째를, 내가 다섯째를. 넷째 창 들고 뒤. 첫째 앞에서 길."</span><br><br>다섯 몸뚱이만 남긴 분대가 어둠을 뚫었다. 부축이 아니라 반쯤 업은 걸음으로.<br>피 냄새를 맡고 온 것들이 뒤를 밟았지만 넷째 창이 번 서듯 뒤를 막았고, 버린 짐들이 길목마다 저들 코를 반 숨씩 잡았다. 동틀 녘에 바위굴에 들었다. 다 왔다. 다섯 다. 짐은 다 잃었다. 분대는 하나도 안 잃었다. 그보다 나은 셈을 이쪽은 모른다.`,
      ng:`짐을 버리라는 명령에 첫째가 약초 자루만은 챙겼다. 다친 둘을 생각한 것이다. 마음은 맞고 셈은 틀렸다.<br><br>자루 무게만큼 첫째 길눈이 느렸다. 갈림에서 반 숨 머뭇, 그 머뭇에 뒤가 닿았다.<br>넷째 창이 밤새 세 번 울었다. 세 번 다 밀어냈지만 창대에 금이 갔다. 바위굴에 들어 세어 보니 약초 자루는 오는 길에 어차피 찢겨 반이 샜다. 버리라면 다 버릴 것. 반만 버린 철수가 제일 비싸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 무력을 다해 다친 둘을 분대장 혼자 양어깨에 걸치고 뛴다.', k:'steady', dc:26, cost:{ might:38 },
      doom:{ title:'두 사람 몫의 등', what:'둘을 짊어진 채 따라잡혀 수풀로 끌려 들어갑니다', dc:20, sec:36,
        text:`성한 셋의 창을 다 살리는 수는 하나다. 다친 둘을 이쪽이 다 진다. 왼어깨에 셋째, 오른어깨에 다섯째.<br><br>두 사람 몫 무게로 뛰었다. 창 셋이 앞뒤를 틔웠다. 반 마장은 셈이 맞았다.<br>반 마장 너머에서 등이 셈을 어겼다. 걸음이 늘어지고, 뒤따르던 것이 그 늘어짐을 쟀다.<br>수풀에서 나온 것이 무릎 뒤를 후렸다. 둘을 얹은 채 무너졌다. 어깨의 둘을 수풀 밖으로 밀어 던지는 것까지는 했다. 제 몸은 못 던졌다.<br><br>수풀로 끌려 들어가며 소리쳤다. 돌아보지 말고 뛰어.`,
        dieText:`창 셋이 수풀을 벴지만 수풀은 깊었고 어둠은 더 깊었다.<br><br>던져진 둘은 살았다. 둘은 그 뒤로 제 발로 걷게 된 날, 제일 먼저 그 수풀에 가서 창 한 자루를 땅에 박았다.<br>분대는 지금도 철수 때면 그 규칙을 왼다. 한 등에 한 사람. 분대장의 등이라도 한 사람. 두 사람 몫을 지려던 등이 남긴 규칙이다.` },
      ok:`왼어깨에 셋째, 오른어깨에 다섯째. 두 사람 몫 무게로 일어섰다. 다만 뛰지 않았다. 뛰는 등은 반 마장짜리다.<br><br>빠르게 걸었다. 숨이 끊기지 않는 가장 빠른 걸음. 창 셋에게는 뒤가 아니라 옆을 막게 했다. 뒤는 냄새가 막는다. 버린 짐의 피 묻은 천들이.<br>등이 셈을 어기기 전에 바위굴에 닿았다. 둘을 내려놓고 나서야 무릎이 꺾였다. 어깨뼈 두 쪽이 보름을 울었다. 두 사람 값이면 싼 셈이라고, 울 때마다 셈해 줬다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'에어록 — 남는 조는 누구인가',
  x:`에어록은 한 번에 셋. 두 번에 나눠야 한다. 첫 조가 넘는 쉰 숨 동안 남는 조는 어두운 복도 쪽에 선다.<br><br>
    복도 끝 어둠에서 아까부터 쇠 긁는 소리가 고르게 온다. 서두르지 않는 소리. 저쪽도 쉰 숨을 아는 것처럼.<br>
    남는 조가 버티는 조다. 분대장이 남는 것은 정해져 있다. 남은 한 자리가 문제다.<br><br>
    누구를 곁에 세우나. 제일 센 손인가, 제일 떨리는 손인가.`,
  o:[
    { l:'① 제일 떨리는 넷째를 곁에 세운다 — 혼자 두면 안 되는 손부터.', k:'fix', dc:25, wake:1,
      ok:`넷째를 곁에 세웠다. 다들 의아해했다. 제일 떨리는 손인데.<br><br>떨리는 손은 문 저쪽에서 쉰 숨을 혼자 세게 하면 안 되는 손이다. 곁에 세우면 이쪽 등을 보며 선다. 등은 떨림을 가린다.<br>쇠 긁는 소리가 복도 모퉁이까지 왔을 때 넷째가 창을 나란히 겨눴다. 떨리면서도 겨눴다. 문이 열리고 둘이 마지막으로 넘었다. 넘고 나서 넷째가 말했다. 다음에도 남는 조를 하겠다고. 떨리는 손이 그렇게 분대의 손이 된다.<br><br>남는 조는 센 순서가 아니라 혼자 두면 안 되는 순서로 짠다. 그 순서는 분대장만 안다. 알아야 한다.`,
      ng:`넷째를 곁에 세웠는데 쇠 긁는 소리가 셈보다 빨리 왔다. 모퉁이에 그것 머리가 걸렸다.<br><br>넷째 손이 창을 놓쳤다. 쨍그랑. 소리가 복도를 울렸다.<br>이쪽 창이 혼자 두 사람 몫으로 어둠을 그었다. 문이 열리는 반 숨에 넷째를 먼저 밀어 넣고 뒷걸음으로 넘었다. 문틈으로 들어오려는 머리를 문이 밀어냈다. 떨리는 손을 세울 때는 그 손의 창을 끈으로 손목에 매 둘 것. 작은 끈 하나가 큰 소리를 막는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 쉰 숨 내내 복도에 대고 창끝으로 바닥을 그어 금을 긋는다.', k:'steady', dc:25,
      ok:`남은 둘이 창끝으로 바닥에 금을 그었다. 끼이익. 듣기 싫은 쇳소리. 일부러.<br><br>저들의 쇠 긁는 소리에 쇠 긁는 소리로 답한 것이다. 여기도 발톱이 있다는 말로.<br>복도 끝 소리가 멈췄다. 재는 침묵. 쉰 숨 내내 서로 소리로 겨뤘다. 문이 열렸고, 마지막까지 저쪽은 모퉁이를 안 넘어왔다. 말이 안 통하는 상대와도 흥정은 된다. 겁의 흥정은 만국 공통이다.`,
      ng:`금을 긋는 쇳소리가 흥정이 아니라 초대가 됐다. 저쪽 긁는 소리가 둘로 늘었다.<br><br>두 방향에서 긁으며 좁혀 왔다. 흉내가 아니라 응원을 부른 꼴.<br>쉰 숨이 오백 숨 같았다. 문이 열리는 순간 둘이 뒤엉켜 넘었다. 닫히는 문에 발톱 둘이 걸렸다 잘렸다. 바닥에 떨어진 발톱이 한 뼘이었다. 소리로 겨루는 수는 상대의 머릿수부터 세고 쓸 것.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S1', t:'의심 — 열 걸음의 명령',
  x:`둘째가 사흘째 기침을 한다. 표본실 구역에서 안개를 마신 뒤부터다. 가슴이 답답하다고 한다.<br><br>
    안엣것이 들었는지 아닌지는 아직 모른다. 아는 사람이 올 때까지 이틀.<br>
    모르는 동안 분대는 어떻게 하나. 같이 걷고 같이 자면 다섯이 다 위험할 수 있다. 내치면 둘째가 죽는다.<br><br>
    분대장의 입에서 나와야 하는 명령이, 이번엔 칼이다.`,
  o:[
    { l:'① 열 걸음 간격을 명하되 그 열 걸음 곁은 분대장이 걷는다.', k:'fix', dc:26,
      ok:`아침에 분대를 세우고 말했다. <span style="color:#d4af37;">"둘째는 오늘부터 열 걸음 뒤에서 걷는다. 밥도 따로, 잠도 따로. 아는 사람 올 때까지다."</span> 둘째 낯이 하얘졌다.<br><br>그리고 한마디를 보탰다. <span style="color:#d4af37;">"그 열 걸음은 내가 같이 걷는다."</span><br>이틀을 그렇게 갔다. 본대 다섯 걸음 앞, 둘째 열 걸음 뒤, 그 사이를 분대장이. 격리는 했으되 혼자 두지는 않았다. 둘째는 멀쩡했다. 그냥 안개에 기관지가 상한 것이었다. 이틀 뒤 둘째가 대열로 돌아오며 말했다. 열 걸음이 하나도 안 멀었다고.<br><br>의심과 보살핌을 한 줄에 세우는 명령. 칼 같은 명령일수록 칼자루 쪽을 사람에게 쥐여 줄 것.`,
      ng:`열 걸음을 명했는데 말이 짧았다. 까닭을 덜 말한 것이다.<br><br>둘째가 밤에 사라졌다. 분대에 짐이 되느니 혼자 가겠다는 쪽지를 남기고.<br>밤새 뒤져 새벽에 바람 관 입구에서 찾았다. 웅크려 떨고 있었다. 기침은 그냥 기침이었다. 데려오는 길에 백번 말했다. 격리는 버림이 아니라고. 말은 명령의 반이다. 나머지 반은 까닭이다. 까닭 없는 명령이 사람을 어둠으로 보낼 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 간격 없이 그냥 간다 — 대신 둘째 가슴에 밤마다 귀를 댄다.', k:'bond', dc:25,
      ok:`격리는 안 했다. 대신 밤마다 둘째 가슴에 귀를 댔다. 심장 소리, 숨소리, 그 밑에 다른 것이 있는지.<br><br>이틀 밤 다 깨끗했다. 기침 소리뿐.<br>아는 사람이 와서 본 결과도 같았다. 안개에 상한 기관지. 둘째가 나중에 말했다. 밤마다 귀를 대 주는 게 약이었다고. 버려질까 봐 겁나던 가슴을 분대장 귀가 눌러 줬다고. 다만 이쪽은 안다. 운이 좋았을 뿐이라는 걸. 들었다면 다섯이 다 위험했다. 그 셈을 안 한 것은 아니다. 하고도 귀를 댄 것이다.`,
      ng:`간격 없이 가던 둘째 밤, 기침 끝에 둘째가 피를 비쳤다.<br><br>그제야 다들 둘째와 제 사이를 쟀다. 사흘을 어깨 맞대고 걸은 사이를.<br>남은 하루가 백 년 같았다. 아는 사람이 와서 안개에 기관지가 찢어진 것뿐이라 했을 때, 안도보다 식은땀이 먼저 났다. 이번엔 아니었다. 다음에도 아니리란 법은 없다. 정과 분대, 저울질을 미루면 저울이 녹슨다는 걸 배운 사흘이었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S1', t:'통풍구 — 간격 유지',
  x:`긴 바람 관을 기어야 한다. 다섯이 줄줄이. 앞뒤가 꽉 막힌 쇠 관.<br><br>
    관 속에서 뭉치면 한 번에 당한다. 벌어지면 하나씩 당한다. 간격이 전부다.<br>
    세 팔 길이. 창을 뻗으면 앞사람 발에 닿고, 무엇이 끼어들면 창이 먼저 닿는 간격.<br><br>
    관 어딘가에서 다른 긁는 소리가 이쪽 소리에 섞여 든다.`,
  o:[
    { l:'① 세 팔 간격을 명하고 간격마다 번호를 돌리게 한다.', k:'fix', dc:25,
      ok:`세 팔 길이 간격. 그리고 쉰 숨마다 번호. 목소리 대신 앞사람 발목을 창대로 톡 치는 번호.<br><br>톡. 톡. 번호가 관을 타고 돌아왔다. 다섯. 간격도 다섯. 긁는 소리가 옆 관에서 나란히 따라왔지만 끼어들 틈을 못 찾았다.<br>갈림에서 그 소리가 앞질러 가려고 서둘렀다. 서두르는 소리는 큰 소리다. 저것의 자리가 다 읽혔다. 다섯은 반대 관으로 꺾었다. 간격이 산 줄은 끊기지 않는다. 관 끝의 빛이 보일 때까지 번호는 스물두 바퀴를 돌았다.`,
      ng:`간격은 지켰는데 넷째 창이 관 이음매에 걸렸다. 빼느라 번호가 한 바퀴 늦었다.<br><br>늦은 번호는 뚫린 간격이다. 넷째와 다섯째 사이가 여섯 팔로 벌어졌다.<br>그 틈의 옆 관 덮개가 덜컹했다. 다섯째가 창대로 덮개를 내리눌렀고 넷째가 뒷걸음으로 간격을 메웠다. 덮개 밑에서 미는 힘이 한참 버티다 꺼졌다. 관 속의 간격은 창이 아니라 목숨의 길이다. 걸리는 창은 접어서 끌 것. 그날 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 간격을 버리고 바짝 붙어 빠르게 민다.', k:'steady', dc:26,
      doom:{ title:'한 줄에 꿴 다섯', what:'관 뒤쪽에서 들어온 것에게 맨 뒤부터 끌려 나갑니다', dc:20, sec:35,
        text:`긁는 소리가 가까웠다. 간격이고 뭐고 속도를 골랐다. <span style="color:#d4af37;">"붙어서 민다, 빨리!"</span><br><br>다섯이 염주처럼 붙어 관을 밀었다. 빨랐다. 반은 맞는 셈이었다.<br>뒤에서 들어온 것이 맨 뒤 이쪽 발목을 물기 전까지는. 붙은 줄은 창을 돌릴 틈이 없다. 창은 앞사람 등에 막혀 있다.<br><br>맨 뒤가 뒤로 끌린다. 염주 줄이 당겨지듯 넷째까지 따라 끌리다 손을 놓쳤다. 관 속을 거꾸로, 들어온 입구 쪽으로, 끌려 나간다. 쇠 바닥에 손톱이 긁히는 소리가 제 귀에도 남의 소리 같다.`,
        dieText:`넷은 앞으로 밀어 관을 빠져나왔다. 나와서야 맨 뒤가 없는 줄 알았다.<br><br>관 입구로 되돌아갔을 때 관은 비어 있었다. 쇠 바닥의 긁힌 자국 열 줄만 안쪽으로 이어졌다.<br>넷은 그 관 입구를 쇠 선반으로 막았다. 막고 나서 번호를 돌렸다. 하나, 둘, 셋, 넷. 다섯을 부르는 사람이 없는 번호가 그렇게 처음 돌았다.` },
      ok:`긁는 소리가 가까웠다. 붙어서 밀되, 맨 뒤의 이쪽만 돌아누웠다. 발이 앞, 머리가 뒤. 창을 가슴에 얹고 뒤를 보며 끌려가듯 밀렸다.<br><br>뒤에서 들어온 것과 눈이 마주쳤다. 어둠 속에서 창끝과 그것 콧등이.<br>좁은 관에서는 저쪽도 한 줄이다. 콧등을 창으로 두 번 찍자 물러났다. 관이 끝날 때까지 뒤를 본 채 밀렸다. 목이 보름을 결렸지만, 줄의 맨 뒤가 눈을 가졌던 덕에 줄이 끝까지 줄로 남았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'녹은 문 — 어깨로 여는 길',
  x:`비상 계단 문이 비틀려 끼었다. 산 먹은 경첩이 녹아 문틀에 눌어붙은 것이다.<br><br>
    이 문 하나 너머가 계단이다. 복도 반대쪽 끝에서는 발소리가 온다. 느긋하게. 길이 막힌 먹이를 아는 걸음.<br>
    쇠지레는 없다. 있는 것은 어깨와 등.<br><br>
    몇 번을 받아야 열릴지, 받는 소리가 발걸음을 얼마나 재촉할지. 둘 다 셈 밖이다.`,
  o:[
    { l:'① 무력을 다해 넷이 호흡 맞춰 한 점을 받는다.', k:'break', dc:26, cost:{ might:36 },
      ok:`혼자 백 번보다 넷이 한 번이다. 문짝의 한 점, 녹은 경첩 바로 옆을 찍고 넷이 어깨를 포갰다.<br><br><span style="color:#d4af37;">"셋에 받는다. 하나, 둘, 셋!"</span><br>쿵. 한 번에 경첩이 뜯기며 문이 안으로 넘어갔다. 소리는 컸다. 한 번뿐이라 메아리도 한 번이었다. 발소리가 달음질로 바뀌었지만 다섯은 이미 계단을 두 층 내려가고 있었다. 받는 소리 열 번은 초대장 열 장이고, 한 번은 사고 소리다. 사고 소리에는 저들도 반 숨 멈칫한다. 그 반 숨이면 된다.`,
      ng:`한 점을 찍는다고 찍었는데 녹이 겉보다 깊었다. 첫 받음에 문이 안 넘어가고 어깨만 넘어갔다.<br><br>둘째 받음, 셋째 받음. 쿵. 쿵. 초대장이 석 장 날아갔다.<br>넷째 받음에 문이 넘어갔을 때 발소리는 복도 반을 와 있었다. 계단을 구르듯 내려가 층 문을 등으로 막았다. 문 너머에서 콧김이 문틈 먼지를 밀어 넣었다. 받기 전에 녹의 깊이부터 창끝으로 쑤셔 볼 것. 겉녹과 속녹은 다른 적이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 문은 포기하고 옆 벽의 산 먹은 자리를 찾아 뚫는다.', k:'sense', dc:25,
      ok:`문틀이 녹을 만큼 산이 튄 자리면 벽도 성할 리 없다. 벽을 창대로 두드리며 훑었다. 한 자리가 둔하게 울렸다.<br><br>속이 삭은 자리. 발로 세 번 차자 벽판이 통째로 안으로 넘어갔다. 문 옆에 문이 하나 더 있던 셈이다.<br>구멍으로 다섯이 빠지고 벽판을 도로 세워 막았다. 발소리가 문 앞에서 멈추는 소리를 벽 너머로 들었다. 문만 문이 아니다. 산이 지나간 자리는 다 문 후보다. 적이 녹인 벽을 적 몰래 쓰는 맛이 썩 괜찮았다. 지나온 벽 안쪽 선반에서 밀봉된 물통 두 개도 챙겼다.`,
      ng:`벽을 두드리는 소리가 생각보다 멀리 갔다. 두드림은 느린 초대장이었다.<br><br>삭은 자리를 찾았을 때 발소리가 복도 모퉁이를 돌았다.<br>벽을 차 뚫는 것과 그것이 닿는 것이 거의 같았다. 마지막 사람 어깨가 구멍에 끼어 반 숨을 버둥댔다. 안에서 셋이 당기고 밖에서 콧김이 닿기 직전에 빠졌다. 두드려 찾는 수는 좋은 수다. 다만 한 번 두드리면 세 걸음 옮겨 두드릴 것. 소리의 출처를 흐려 가면서.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S1', t:'점호 — 명단에 없는 대답',
  x:`숙영지로 잡은 관제실에는 낡은 통신기가 있다. 버릇처럼 밤 점호를 했다. 목소리를 죽여서. 하나, 둘, 셋, 넷, 다섯.<br><br>
    대답이 여섯 왔다.<br>
    여섯째 대답은 통신기에서 나왔다. 죽은 지 오래인 기계가 지직대며 사람 목소리를 냈다. <span style="color:#8fb3bf;">"여섯."</span> 분명한 발음. 그리고 덧붙였다. <span style="color:#8fb3bf;">"일곱은 언제 옵니까."</span><br><br>
    관제실 명단판에는 당직 일곱 이름이 적혀 있다. 여섯 줄에 줄이 그어져 있다.`,
  o:[
    { l:'① 점호를 다시 하되 이번엔 이름으로 부른다 — 다섯만.', k:'fix', dc:26, wake:1,
      ok:`숫자는 아무나 받는다. 이름은 다르다. 다섯 이름을 하나씩 불렀다. 다섯 대답. 통신기는 조용했다.<br><br>그리고 이쪽 이름은 안 불렀다. 분대장 이름을 아는 것은 분대뿐이어야 한다. 여기서는.<br>통신기가 한참 지직대다 물었다. <span style="color:#8fb3bf;">"당신 이름은."</span> 대답하지 않았다. 이름 없는 목소리는 명단에 못 적힌다. 새벽까지 통신기가 가끔 지직댔지만 더는 숫자도 이름도 묻지 않았다. 아침에 떠나며 명단판을 엎어 놓았다.<br><br>점호는 수를 세는 일인 줄 알았다. 이름을 지키는 일이기도 하다. 셈과 이름, 분대장은 둘 다 쥐고 있어야 한다.`,
      ng:`이름 점호까지는 좋았는데 넷째가 대답 끝에 버릇대로 덧붙였다. 이상 무, 넷째 아무개.<br><br>성명 석 자가 통째로 나갔다. 통신기가 그 이름을 받아 적듯 되뇌었다. 지직. 아무개. 지직.<br>그 밤 넷째 꿈에 누가 자꾸 이름을 불렀다고 한다. 사흘을 그랬다. 나흘째에 관제실에서 멀어질 만큼 멀어지자 그쳤다. 이름은 여기서 돈이다. 함부로 내면 거슬러 받지 못한다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 통신기 선을 뽑고 명단판의 일곱째 이름을 확인한다.', k:'gaze', dc:25,
      ok:`선부터 뽑았다. 지직 소리가 죽었다. 그리고 명단판을 봤다.<br><br>일곱째 줄. 이름이 비어 있다. 비어 있는데 줄은 안 그어져 있다. 아직 오지 않은 일곱째. 통신기가 기다리던 자리.<br>그 빈칸에 돌가루를 문질러 아무렇게나 획을 채웠다. 읽을 수 없는 이름. 자리가 차면 기다림도 끝난다. 떠날 때 통신기는 끝까지 조용했다. 빈자리는 채워질 때까지 부른다. 사람이든 아니든. 그러니 빈자리는 보이는 족족 메꿔 둘 것.`,
      ng:`선을 뽑았는데도 통신기가 한 번 더 말했다. 전기 없이. <span style="color:#8fb3bf;">"일곱은 언제 옵니까."</span><br><br>명단판을 보던 둘째가 헛숨을 들이켰다. 일곱째 줄에 글씨가 차오르고 있었다. 한 획씩. 누가 쓰는 중인 것처럼.<br>반쯤 써진 글씨는 둘째 이름과 첫 자가 같았다. 명단판을 벽에서 뜯어 엎고 그 방을 나왔다. 복도에서 밤을 샜다. 차라리 긁는 소리가 나은 밤이었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-26 } }
  ] },

{ at:'S1', t:'여왕 앞 — 시선을 끄는 자리',
  x:`여왕의 방을 가로지르는 수밖에 없다. 바닥 길은 알 사이, 천장 그늘엔 여왕.<br><br>
    넷이 벽 쪽 그늘로 기는 동안 누군가는 여왕의 눈을 다른 데 묶어야 한다. 트인 쪽에서, 보이게.<br>
    미끼 자리다. 분대에서 미끼는 시키는 자리가 아니다. 서는 자리다.<br><br>
    분대장이 창을 고쳐 쥐었다.`,
  o:[
    { l:'① 무력을 다해 트인 쪽을 보이며 걷되 알만은 절대 안 밟는다.', k:'steady', dc:26, cost:{ might:35 },
      doom:{ title:'여왕의 눈', what:'여왕에게 들어 올려져 둥지 그늘로 끌려 올라갑니다', dc:20, sec:35,
        text:`트인 쪽을 걸었다. 보이게, 그러나 알은 한 발도 안 건드리며. 여왕의 눈이 이쪽을 따라왔다. 넷은 그 눈 바깥의 그늘을 기었다.<br><br>방 반을 지났을 때 여왕이 셈을 끝냈다. 알을 안 밟는 침입자는 알을 아는 침입자. 알을 아는 것은 위험한 것.<br>천장에서 긴 것이 내려왔다. 소리도 없이. 창을 들 새도 없이 양어깨가 잡힌다.<br><br>발이 바닥에서 떨어진다. 알밭이 아래로 멀어진다. 둥지 그늘로 끌려 올라가며 마지막으로 소리쳤다. 뛰어. 넷은 뛰었다. 그거면 됐다.`,
        dieText:`넷은 건너편 통로에서 밤새 천장 그늘을 지켜봤다. 그늘은 끝내 아무것도 돌려주지 않았다.<br><br>새벽에 넷은 통로를 올랐다. 분대장 창이 알밭 가장자리에 똑바로 박혀 있었다. 알 하나 상하지 않은 자리에.<br>넷은 그 창을 못 가져갔다. 여왕의 눈이 창을 지키고 있었다. 제 알을 지키듯. 적장에 대한 예인지 전리품인지, 아무도 알고 싶지 않았다.` },
      ok:`트인 쪽을 걸었다. 보이게. 다만 걸음을 저들 것으로 걸었다. 알 사이를 다니는 일꾼들의 박자. 멈춤, 세 걸음, 멈춤.<br><br>여왕의 눈이 이쪽에 왔다가 번번이 미끄러졌다. 보이는데 셈이 안 되는 것이다. 침입자의 걸음이 아니니까.<br>넷이 그늘을 다 건너고, 이쪽도 마지막 알 둔덕을 돌아 통로에 들었다. 여왕은 끝까지 고개만 갸웃댔다. 미끼의 일은 눈에 띄는 게 아니라 눈을 붙잡고 셈을 흐리는 것까지다. 거기까지 해야 미끼 자리가 산 자리가 된다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 미끼 없이 다섯이 다 그늘에 붙어 반나절 걸려 돈다.', k:'hide', dc:26,
      ok:`미끼 수를 접었다. 다섯이 다 벽 그늘로, 알밭을 크게 도는 긴 길로.<br><br>한 번에 한 사람, 여왕이 알 쪽을 굽어보는 숨에만 한 그늘씩. 반나절이 꼬박 걸렸다.<br>마지막 그늘에서 다섯째 다리에 쥐가 났다. 소리 나기 전에 셋이 주물러 풀었다. 통로에 다 들어서고 나서야 서로의 얼굴을 봤다. 반나절 치 땀이 다 식어 소금이 돼 있었다. 느린 길이 제일 빠른 길일 때가 있다. 여왕의 방이 그런 데다.`,
      ng:`반나절 계획이 셋째 기침 한 번에 금이 갔다. 삼킨다고 삼킨 기침이 코로 샜다.<br><br>여왕의 머리가 돌았다. 다섯이 그늘에 박제처럼 굳었다.<br>여왕은 오래 그쪽을 보다가 일꾼 하나를 보냈다. 긴 것이 그늘 바로 앞을 훑고 지나갔다. 발톱이 다섯째 소매 끝을 스쳤다. 그늘이 반 뼘만 얕았어도 끝이었다. 나머지 반은 숨도 반만 쉬며 돌았다. 여왕의 방을 나와 다들 한참을 토악질했다. 무서움도 체하는 것이었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'S1', t:'들것과 좁은 관 — 버릴 수 없는 것',
  x:`다섯째가 다리를 상해 들것 신세다. 나가는 길은 바람 관 하나. 들것은 안 들어가는 폭이다.<br><br>
    들것을 버리면 다섯째를 끌거나 업어야 한다. 좁은 관에서 업는 것은 둘 다 기지 못한다는 말이다.<br>
    관 길이는 쉰 팔. 중간에 꺾임이 둘.<br><br>
    버릴 것과 질 것을 가르는 것도 분대장 일이다.`,
  o:[
    { l:'① 무력을 다해 다섯째를 가슴에 묶고 등으로 기어 관을 지난다.', k:'steady', dc:26, cost:{ might:37 },
      ok:`들것을 뜯어 끈만 챙겼다. 다섯째를 이쪽 가슴에 배 맞대 묶고, 이쪽이 등으로 누워 팔꿈치로 기었다. 하늘 보고 기는 쉰 팔.<br><br>꺾임마다 둘이 한 몸으로 모로 돌았다. 다섯째가 위에서 관 천장을 밀어 거들었다.<br>쉰 팔이 오백 팔 같았지만 둘은 한 번도 안 걸렸다. 관을 나와 끈을 풀자 등가죽이 불에 덴 것 같았다. 다섯째가 말했다. 관 천장에 긁힌 자국이 많던데 다 손톱이더라고. 그 말은 못 들은 걸로 했다. 이미 지난 관이다.`,
      ng:`가슴에 묶고 기는데 둘째 꺾임에서 끈이 관 모서리에 쓸려 끊어졌다.<br><br>다섯째가 가슴에서 미끄러지며 관 바닥에 상한 다리를 찧었다. 비명이 관을 타고 양쪽으로 달렸다.<br>남은 스무 팔을 다섯째 멱살을 물고 기다시피 끌었다. 관 밖으로 쏟아져 나와 입구를 막자마자 관 저쪽에서 무엇이 입구까지 왔다 가는 소리가 났다. 끈은 두 겹으로 꼴 것. 모서리에 닿는 끈은 셈의 바깥이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 관 양 끝에 둘을 세우고 가운데로 다섯째를 끈으로 당겨 보낸다.', k:'bond', dc:25,
      ok:`힘보다 줄이다. 제일 가는 둘이 먼저 관을 지나 저쪽 끝에 서고, 긴 끈을 관에 꿰었다.<br><br>다섯째를 담요에 말아 끈에 걸고, 저쪽에서 당기고 이쪽에서 밀었다. 썰매처럼.<br>꺾임에서 두 번 걸렸지만 양쪽에서 호흡을 맞추니 돌아 나갔다. 다섯째는 담요 속에서 상한 다리를 품에 안고 쉰 팔을 갔다. 분대의 힘은 어깨가 아니라 양 끝을 잡은 손들이다. 그걸 다시 배웠다.`,
      ng:`끈이 꺾임에서 엇갈려 담요째 꽉 끼었다. 밀어도 당겨도 안 움직였다.<br><br>관 한가운데, 혼자, 움직이지 못하는 다섯째. 제일 나쁜 그림이다.<br>결국 제일 가는 넷째가 기어 들어가 끈을 풀어 다시 걸었다. 그 반 각 동안 관 어딘가에서 긁는 소리가 두 번 났다. 다섯째는 관을 나와서도 한참 담요를 안 놓았다. 썰매 수를 쓸 때는 꺾임마다 사람을 박을 것. 줄은 꺾임에서 거짓말을 한다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S2', t:'울타리 구멍 — 등으로 막는 시간',
  x:`밤 습격에 울타리 한 칸이 뜯겼다. 사람 하나 폭. 넷이 그물과 기둥을 손보는 데 반 각은 걸린다.<br><br>
    그 반 각 동안 구멍은 누가 막나.<br>
    들어오려는 것들은 셋. 구멍 밖 어둠에서 번갈아 어른댄다. 구멍은 좁다. 들어오려면 하나씩이다.<br><br>
    하나씩이면, 사람 하나로 막아진다. 이론은 그렇다.`,
  o:[
    { l:'① 무력을 다해 구멍에 어깨를 끼우고 창으로 반 각을 버틴다.', k:'steady', dc:26, cost:{ might:38 }, wake:1,
      ok:`구멍에 몸을 반쯤 끼웠다. 어깨와 방패가 문짝, 창이 문고리. <span style="color:#d4af37;">"반 각이다. 서둘러."</span><br><br>첫 놈이 코부터 들이밀었다. 창끝이 마중했다. 비명. 둘째 놈은 발부터 넣었다. 방패 모서리로 발목을 찍었다.<br>셋째 놈은 꾀가 있었다. 안 들어오고 구멍 밖에서 이쪽 창을 물고 당겼다. 창을 놓는 대신 같이 당겨지는 척 반 발 나가다가, 그물 수리가 끝났다는 외침에 몸을 뺐다. 새 그물이 구멍을 덮었다. 반 각. 등이 문이었던 반 각이었다.<br><br>막는 몸에도 요령이 있다. 받기만 하면 밀리고, 마주 물면 같이 뚫린다. 문이 되는 법은 문짝과 문고리를 나누는 것. 어깨는 버티고 창은 일한다.`,
      ng:`어깨를 끼웠는데 둘째 놈이 셈을 바꿨다. 구멍으로 안 오고 옆 그물을 타고 올라 위에서 떨어진 것이다.<br><br>위는 어깨가 못 막는 데다.<br>떨어지는 놈을 창대로 걷어 냈지만 그 틈에 첫 놈이 구멍을 반이나 비집었다. 수리하던 넷이 달려들어 몽둥이로 쳐내고서야 구멍이 닫혔다. 구멍을 막을 때는 구멍 위도 셈에 넣을 것. 문은 문틀까지가 문이다. 어깨가 보름을 쑤셨고, 그물 위 쪽에 가시 덤불이 새로 얹혔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 구멍 안쪽에 횃불 벽을 치고 그 뒤에서 넷이 수리한다.', k:'fix', dc:25,
      ok:`몸 대신 불. 구멍 바로 안쪽에 마른 가지를 깔고 불을 질렀다. 사람 키 반만 한 불의 문.<br><br>그것들은 불을 안 넘는다. 구멍 밖에서 불 너머로 이쪽을 보며 울기만 했다.<br>넷이 불빛에 손까지 밝게 반 각 만에 그물을 다 손봤다. 불이 잦아들 때쯤 새 그물이 서 있었다. 몸으로 막을 자리에 불을 세울 수 있으면 불을 세운다. 분대장의 몸은 분대의 마지막 연장이지 첫 연장이 아니다.`,
      ng:`불의 문은 좋았는데 바람이 울타리 안쪽으로 불었다. 불티가 수리하는 그물 쪽으로 날았다.<br><br>새로 얹은 마른 덤불에 불이 옮았다. 막자는 구멍 옆에 더 큰 불구멍이 날 판.<br>물통을 다 비워 겨우 잡았다. 그 소동에 반 각이 한 각이 됐고, 그동안 구멍은 결국 이쪽 어깨가 막았다. 불은 세울 때 바람부터 볼 것. 불은 분대 편도 적 편도 아니다. 바람 편이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'물 건너기 — 허리 줄',
  x:`가슴까지 오는 물길을 건너야 한다. 바닥은 뻘. 물밑은 안 보인다.<br><br>
    다섯 허리를 한 줄에 꿰기로 했다. 세 팔 간격. 하나가 빠지면 넷이 줄로 건진다.<br>
    대신 하나가 잡히면 줄이 넷을 끌고 들어갈 수도 있다. 줄은 양날이다.<br><br>
    줄 끝, 맨 뒤 매듭은 분대장 허리에 있다.`,
  o:[
    { l:'① 간격과 신호를 정하고 한 줄로 꿰어 건넌다.', k:'fix', dc:25,
      ok:`세 팔 간격, 줄은 당기면 정지, 두 번 당기면 전진. 맨 앞은 장대로 바닥을 짚는 첫째, 맨 뒤는 이쪽.<br><br>복판에서 첫째 장대가 쑥 꺼지는 데를 짚었다. 줄이 한 번 당겨졌다. 다섯이 섰다. 첫째가 왼쪽으로 길을 틀었고 두 번 당김에 다시 걸었다.<br>다 건너고 줄을 풀었다. 젖은 매듭이 안 풀려 끊어 낸 자리가 하나. 그 매듭 값에 다섯이 다 뭍에 서 있다. 줄은 맞게 쓰면 다섯 목숨을 한 목숨으로 만든다. 한 목숨은 다섯 목숨보다 세다.`,
      ng:`복판에서 넷째가 뻘에 무릎까지 박혔다. 줄이 당겨지고, 서라는 신호인지 빠졌다는 신호인지 뒤에서는 알 수 없었다.<br><br>신호가 섞이자 셋이 제각각 움직였다. 줄이 넷째를 돕는 게 아니라 사방에서 당겼다.<br>이쪽이 소리를 내고서야 줄이 섰다. 목소리 하나가 물 건너 숲을 깨웠을지도 모르지만 별수 없었다. 넷째를 뽑아 마저 건넜다. 신호는 둘로는 모자란다. 섰다, 간다, 빠졌다. 셋은 돼야 줄이 말을 한다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 줄 없이 분대장이 먼저 건너 길을 몸으로 그린다.', k:'steady', dc:26,
      doom:{ title:'물밑의 입', what:'물밑의 것에게 다리를 물려 뻘 속으로 끌려 들어갑니다', dc:20, sec:35,
        text:`줄의 양날이 꺼림칙했다. 혼자 먼저 건너 길을 그리기로 했다. 빠질 데, 디딜 데를 몸으로 표시하며.<br><br>복판을 지나 세 걸음, 디딜 데를 찾던 발밑에서 뻘이 열렸다.<br>뻘이 아니었다. 입이었다. 뻘 바닥에 입을 벌리고 기다리는 것. 다리가 무릎까지 물렸다.<br><br>천천히 끌려 내려간다. 뻘은 소리도 집어삼킨다. 뭍의 넷이 뒤늦게 줄을 던지지만 줄 끝이 세 팔 모자란다. 세 팔. 허리에 줄이 있었으면 닿고도 남을 길이다.`,
        dieText:`물길 복판에는 반 각 동안 거품이 올라왔다. 그리고 멎었다.<br><br>넷은 상류로 한나절을 돌아 얕은 여울로 건넜다. 허리에 줄을 꿰고. 세 팔 간격으로.<br>줄이 당겨질 때마다 넷은 걸음을 멈췄다. 신호가 아니어도 멈췄다. 줄 끝에 누가 있는 것만 같아서. 양날이라던 줄은, 없을 때 제일 깊이 벤다.` },
      ok:`혼자 먼저 건너되 맨몸으로는 안 갔다. 긴 줄 한 끝을 허리에, 다른 끝을 뭍의 바위에 묶었다.<br><br>장대로 바닥을 짚으며 길을 그렸다. 복판 세 걸음 너머에서 장대 끝이 물컹한 것을 짚었다. 뻘이 아닌 물컹함.<br>그 자리를 크게 돌아 길을 그렸다. 건너편에 줄을 매니 물길에 밧줄 다리가 섰다. 넷이 줄을 잡고 그린 길대로 건넜다. 물컹한 자리 위로는 아무도 안 지났다. 그게 뭐였는지는 끝내 몰랐고, 모르는 채가 좋았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'포위 — 등 맞대는 원',
  x:`해 질 녘 벌판에서 무리에게 둘렸다. 다섯. 저쪽은 일곱. 달아날 등이 없는 판이다.<br><br>
    등이 없으면 등을 만든다. 다섯이 등을 맞대면 원이 된다. 원에는 뒤가 없다.<br>
    문제는 유지다. 저들은 한 점을 치는 척 다른 점을 친다. 원이 출렁이면 틈이 난다.<br><br>
    원이 버티는 동안만 다섯은 다섯이다.`,
  o:[
    { l:'① 등 맞댄 원을 만들고 창은 안 따라가고 자리만 지키게 한다.', k:'fix', dc:26,
      ok:`<span style="color:#d4af37;">"원 만들어! 창은 네 앞만! 따라가지 마라!"</span><br><br>저들이 번갈아 치고 빠졌다. 동쪽을 치는 척 서쪽을 찔러 보고. 창들이 제 앞만 지키니 원이 안 출렁였다. 유인에 따라나선 창이 하나도 없었다.<br>반 시진을 재던 저들이 수지 계산을 끝냈다. 빈틈없는 원은 가시 돋친 돌이다. 돌을 깨물 이빨은 저들에게도 아깝다. 일곱이 차례로 어둠에 녹아 돌아갔다. 원을 풀 때 다섯 등이 다 땀으로 붙어 있었다. 등이 서로의 벽이었던 반 시진이다.`,
      ng:`원은 섰는데 넷째 창이 유인을 따라갔다. 눈앞에서 얼쩡대는 놈을 찌르러 반 발.<br><br>그 반 발의 틈으로 옆 놈이 파고들었다. 원이 터질 뻔한 반 숨, 둘째가 제 자리를 버리고 틈을 메웠다. 이번엔 둘째 자리가 비고.<br>원이 한 바퀴를 출렁이며 간신히 아물었다. 저들이 그 출렁임을 다 보고 갔다. 다음에 또 온다는 뜻이다. 원은 창이 아니라 자리가 지킨다. 그 말을 밤새 다섯 번 되뇌게 했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 원이 아니라 쐐기로 짜서 제일 어린 놈 쪽을 뚫는다.', k:'break', dc:26,
      ok:`지키는 원 대신 뚫는 쐐기를 골랐다. 일곱 중 서는 품이 어린 놈 하나. 몸이 작아서가 아니라 눈이 바빠서 어리다.<br><br>쐐기 끝을 그 놈에게 겨눠 다섯이 한 호흡에 밀었다.<br>어린 놈이 반 발 물러선 것이 포위의 끝이었다. 뚫린 포위는 포위가 아니다. 다섯이 그 틈으로 벌판을 빠져 바위 지대에 붙었다. 뒤에서 어린 놈이 어른들에게 혼나는 소리 같은 울음이 났다. 적의 원에도 제일 무른 돌이 있다. 그 돌을 읽는 눈이 분대를 살렸다.`,
      ng:`어린 놈이라 읽은 것이 함정이었다. 무리가 일부러 세운 미끼 자리였던 것이다.<br><br>쐐기가 그 자리를 치자 양옆이 접혀 들었다. 어른 둘이.<br>쐐기 끝에 선 이쪽 어깨가 발톱에 갈렸다. 밀던 힘 그대로 억지로 뚫고 나가긴 했다. 바위에 붙어 세어 보니 다섯은 맞는데 성한 어깨가 일곱뿐이었다. 무른 돌이 보이거든 왜 물러 보이는지부터 셈할 것. 공짜 틈은 없다. 이 벌판에서는.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, spirit:-16 } }
  ] },

{ at:'S2', t:'큰 것 — 엎드리는 명령',
  x:`벌판을 반쯤 건넜을 때 땅이 울리기 시작했다. 멀리서 양치나무 우듬지들이 차례로 꺾인다.<br><br>
    이쪽으로 온다. 숨을 데는 없다. 있는 것은 허리까지 오는 풀과, 명령 하나.<br>
    큰 것의 눈은 높다. 높은 눈은 서 있는 것과 뛰는 것을 잡는다. 엎드린 것은 땅의 일부다.<br><br>
    뛰고 싶은 다리 다섯 쌍을, 명령 하나로 땅에 붙여야 한다.`,
  o:[
    { l:'① 엎드려 명령과 함께 제일 겁 많은 등을 손으로 누른다.', k:'fix', dc:26, wake:1,
      ok:`<span style="color:#d4af37;">"엎드려! 땅이 돼라!"</span> 외침과 동시에 몸을 던지며 넷째 등부터 손으로 눌렀다. 제일 먼저 뛸 등이니까.<br><br>땅이 뛰었다. 발굽인지 발인지가 열 걸음 옆을 지날 때 풀이 다 누웠다. 넷째 등이 손바닥 밑에서 들썩이는 걸 꾹, 꾹, 눌러 줬다. 아직이다. 아직.<br>울림이 벌판 끝으로 빠지고도 쉰 숨을 더 눌렀다. 큰 것들은 가끔 되돌아본다. 일어난 다섯의 앞섶이 다 풀물이었다. 산 사람의 풀물이었다.<br><br>명령은 입에서 끝나지 않는다. 손까지가 명령이다. 제일 약한 자리에 손을 얹는 것까지. 그걸 아는 입이 분대장의 입이다.`,
      ng:`엎드려 외침은 좋았는데 이쪽이 마지막까지 서서 다섯을 세고 있었다. 버릇이다.<br><br>높은 눈이 선 하나를 잡았다. 울림이 방향을 틀었다.<br>구르듯 엎드려 풀 밑을 기었다. 발 하나가 방금 섰던 자리를 밟았다. 땅이 사발처럼 패었다. 센다고 서 있던 분대장이 제일 위험했던 셈. 머릿수는 엎드려서도 셀 수 있다. 다음부터는 그렇게 셌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-18 } },
    { l:'② 울림의 방향을 재어 직각으로 조용히 물러난다.', k:'steady', dc:25,
      ok:`울림이 오는 줄기를 발바닥으로 쟀다. 곧장 이쪽은 아니다. 벌판 가운데 물웅덩이 쪽이다. 물 마시러 가는 길.<br><br>그 길과 직각으로, 낮은 걸음으로 물러났다. 뛰지 않고. 꺾인 우듬지들이 가까워졌지만 줄기는 끝까지 웅덩이를 향했다.<br>벌판 가장자리 바위에 붙었을 때 큰 것이 웅덩이에 머리를 박는 소리가 났다. 집채가 물 마시는 소리였다. 길과 길이 안 겹치면 큰 것도 그냥 지나가는 날씨다. 날씨를 피하는 법으로 피했다.`,
      ng:`직각으로 물러난다는 셈이 벌판 지형에 먹혔다. 물러나는 쪽이 마른 개울 바닥, 울림이 가장 잘 타는 땅이었다.<br><br>다섯 걸음의 울림이 큰 것 발바닥에 닿았다. 걸음이 멎었다. 긴 목이 돌아왔다.<br>개울 바닥 턱 밑에 다섯이 끼어들 듯 엎드렸다. 콧김이 개울 바닥 모래를 두 번 쓸고 갔다. 물러날 때는 방향만 아니라 바닥도 고를 것. 땅은 울림의 길이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S2', t:'못 뛰는 하나 — 업는 순서',
  x:`무리가 붙었다. 바위 지대까지 뛰면 떨칠 수 있다. 문제는 셋째다. 아침에 삔 발목이 퉁퉁 부었다.<br><br>
    셋째가 말한다. 두고 가라고. 저 때문에 다 죽는다고.<br>
    분대에 그런 셈은 없다. 다섯이 들어왔으면 다섯이 나간다.<br><br>
    업고 뛰는 수밖에. 누가, 어떻게.`,
  o:[
    { l:'① 무력을 다해 분대장이 업고 창 셋이 길을 연다.', k:'steady', dc:26, cost:{ might:36 },
      ok:`<span style="color:#d4af37;">"두고 가라는 말은 명령 불복이다. 업혀."</span> 셋째를 둘러업었다.<br><br>창 셋이 앞과 양옆을 열고, 빈손 하나가 뒤에서 돌을 던지며 거리를 벌었다.<br>무리가 두 번 붙었다 두 번 떨어졌다. 업힌 셋째가 어깨 너머로 뒤를 봐 주며 소리쳤다. 왼쪽! 뒤! 눈이 하나 더 생긴 등이었다. 바위 지대에 올라 셋째를 내렸다. 다리가 후들거렸지만 다섯이었다. 들어온 수 그대로.`,
      ng:`업고 뛰는데 무리가 셈을 바꿨다. 업은 등은 느리다. 느린 등만 노리고 번갈아 붙었다.<br><br>창 셋이 막는 쪽보다 붙는 쪽이 번번이 빨랐다. 등에 업힌 셋째 발꿈치를 스치는 이빨 소리까지 났다.<br>결국 마른 도랑에 뛰어들어 등을 도랑 벽에 붙이고 창으로 버텼다. 반 시진. 무리가 물러간 뒤에야 마저 갔다. 업는 수는 맞다. 다만 업는 등을 가운데 두고 창이 돌아야 했다. 등이 맨 뒤면 등이 과녁이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 지름길인 양치 덤불을 가로질러 거리를 번다.', k:'luck', dc:26,
      doom:{ title:'덤불 속의 셈', what:'덤불에 숨어 있던 것에게 업힌 채로 끌려 들어갑니다', dc:20, sec:36,
        text:`벌판을 도는 길 대신 양치 덤불을 질렀다. 덤불은 무리의 속도를 깎는다. 업은 등에는 그 셈이 달았다.<br><br>덤불 복판에서 알았다. 무리가 왜 덤불 가를 돌기만 했는지.<br>덤불 속에는 먼저 온 것이 있었다. 매복이 아니라 그냥 저것의 집이었다. 집에 밥이 걸어 들어온 것이다.<br>업힌 셋째와 이쪽이 한 덩어리로 물렸다. 덤불 깊은 쪽으로 끌려 들어간다. 등에서 셋째가 이쪽 멱살을 쥐고 놓지 않는다. 떨어지면 따로 물린다는 걸 둘 다 안다.`,
        dieText:`창 셋이 덤불을 반나절 벴다. 덤불은 베어도 베어도 안이 안 보였다.<br><br>해 질 녘에 덤불이 조용해졌고, 셋은 물러났다. 물러나며 덤불 가에 창 두 자루를 나란히 박았다.<br>셋은 그 뒤로 지름길이라는 말을 쓰지 않는다. 길은 길이고, 길 아닌 데는 누군가의 집이다. 두 사람 값으로 산 지도에는 그렇게 적혀 있다.` },
      ok:`덤불을 지르기 전에 반 숨, 돌 하나를 덤불 복판에 던졌다. 버릇이다. 길 아닌 데는 묻고 들어가는 버릇.<br><br>덤불이 출렁했다. 돌이 떨어진 자리에서. 빈 덤불은 그렇게 안 출렁인다.<br>덤불을 접고 벌판 가를 돌았다. 무리와의 거리가 바짝 줄었지만 창 셋이 뒤를 번갈아 막으며 바위 지대까지 닿았다. 느린 길의 끝에 다섯이 다 있었다. 빠른 길의 복판에 뭐가 있었는지는, 던진 돌만 안다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 마지막 조의 등',
  x:`낡은 승강기 바구니는 셋이 끝이다. 두 번. 첫 조가 오르는 동안 남는 조가 바닥을 지킨다.<br><br>
    남는 조는 분대장 포함 둘. 정해져 있다. 분대장은 늘 마지막 배를 탄다.<br>
    도르래 소리가 수풀을 깨운다. 반 시진짜리 소리 봉화.<br><br>
    마지막 조의 등 뒤에는 정원 전체가 있다.`,
  o:[
    { l:'① 남는 둘의 반 시진을 미리 짠다 — 등 붙일 벽, 창의 방향, 물러날 턱.', k:'fix', dc:26, wake:1,
      ok:`오르기 전에 남는 반 시진부터 짰다. 등 붙일 바위, 창 둘이 가를 부채꼴, 밀리면 물러날 벼랑 턱, 그리고 바구니가 내려오면 타는 순서까지.<br><br>수풀이 깨어 두 번 몰려왔다. 두 번 다 부채꼴 창끝에 걸려 돌아갔다. 물러날 턱은 끝내 안 썼다. 짜 둔 수는 안 쓰는 게 제일 좋은 수다.<br>빈 바구니가 내려오고 둘이 탔다. 올라가는 바구니 밑으로 수풀이 뒤늦게 모래톱을 덮는 게 보였다. 반 시진을 미리 살아 본 사람은 반 시진이 짧다. 그게 판 짜기의 전부다.<br><br>마지막 조는 버티는 조가 아니라 짜인 조다. 버틸 일을 미리 셈해 둔 등은 떨지 않는다. 그 등을 만드는 게 분대장의 마지막 일이다.`,
      ng:`반 시진 셈은 다 짰는데 도르래가 셈을 어겼다. 첫 조가 오르다 줄이 턱에 걸려 멈춘 것이다.<br><br>반 시진이 한 시진으로 늘었다. 짜 둔 수가 바닥났다.<br>물러날 턱까지 썼다. 벼랑 턱에 등을 붙이고 창 둘로 번갈아 찌르며 줄이 풀리기를 기다렸다. 바구니가 다시 움직였을 때 창대 하나가 반으로 줄어 있었다. 수는 시간까지 짜야 한다. 연장 탓까지 셈에 넣어서. 정원의 마지막 가르침이었다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 남는 둘이 도르래 밑이 아니라 소리 밖 어둠에 숨어 기다린다.', k:'hide', dc:25,
      ok:`도르래 소리가 봉화면 봉화 밑에 서 있을 까닭이 없다. 남은 둘은 승강기에서 쉰 걸음 떨어진 바위 뒤에 숨었다.<br><br>수풀이 깨어 소리를 보고 몰려왔다. 승강기 밑으로. 아무도 없는 밑으로.<br>저들이 빈 모래톱을 뒤지는 동안 둘은 어둠 속에서 기다렸고, 빈 바구니가 내려온 순간에만 내달려 탔다. 저들이 알아챘을 때 바구니는 두 길 위였다. 발톱 하나가 바닥 널을 긁고 미끄러졌다. 소리와 몸을 떼어 놓는 것, 그게 남는 조의 셈이다.`,
      ng:`소리 밖에 숨는다고 숨었는데 바람이 배신했다. 바위 뒤의 둘 냄새가 수풀로 흘러간 것이다.<br><br>저들이 승강기 밑과 바위 뒤로 갈라져 왔다. 숨은 수가 반만 먹힌 셈.<br>빈 바구니가 내려오기 전에 들켰다. 쉰 걸음을 창을 휘두르며 뚫었고, 바구니에 구르듯 타서 서로를 끌어 올렸다. 숨을 때는 소리만 아니라 바람도 셈할 것. 이 정원에서 바람은 늘 저들 편에서 분다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } }
  ] },

{ at:'S2', t:'어린 것들 — 연습 사냥',
  x:`따라붙은 것들이 이상하다. 몸놀림이 서툴고, 거리를 자꾸 틀린다. 어리다.<br><br>
    어린 것들의 연습 사냥이다. 그리고 연습에는 꼭 참관이 있다. 수풀 너머 어딘가에서 어미들이 보고 있을 것이다.<br>
    어린 것을 다치게 하면 연습이 실전이 된다. 어미들의 실전이.<br><br>
    쫓되 다치게 하지 않는 싸움. 제일 어려운 싸움이다.`,
  o:[
    { l:'① 창을 뒤집어 창대로만 쳐서 아프게만 돌려보낸다.', k:'fix', dc:26,
      ok:`<span style="color:#d4af37;">"날 세우지 마라! 창대로만!"</span> 다섯 창이 일제히 뒤집혔다.<br><br>덤벼드는 어린 것들의 콧등과 발목을 창대로만 후렸다. 깡. 깡. 아프고, 피는 안 나는 소리.<br>어린 것들이 깨갱대며 물러났다. 수풀 너머에서 낮은 울음이 한 번 났다. 물러나라는 울음. 연습 끝.<br>다음 날부터 그 무리는 다섯을 지나쳤다. 피를 안 본 적은 적 명단에서 내려가는 모양이었다. 날을 세울 줄 알면서 안 세우는 것, 그것도 분대의 무력이다.`,
      ng:`창대로만 친다는 게 급한 순간에 안 됐다. 넷째 창이 뒤집힌 채로도 너무 셌다. 어린 것 하나가 다리를 절며 물러났다.<br><br>수풀 너머 울음이 달라졌다. 낮고 길게.<br>그 밤 어미 둘이 울타리 대신 숙영지 돌담을 넘보러 왔다. 횃불을 밤새 두 배로 밝히고 교대 없이 섰다. 사흘을 그랬다. 절던 어린 것이 다시 뛰는 게 보인 다음에야 어미들이 물러났다. 연습 상대의 예절은 뼈에 새길 것. 이 정원의 예법이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 제일 서툰 놈 쪽으로 틈을 보여 연습을 빨리 끝내 준다.', k:'evade', dc:25,
      ok:`연습은 성공해야 끝난다. 제일 서툰 꼬마 쪽으로 일부러 빈 옆구리를 보였다. 꼬마가 그 틈을 물었다. 옷자락만.<br><br>찢긴 옷자락을 물고 꼬마가 의기양양하게 물러났다. 수풀 너머에서 부르는 울음. 합격의 울음이었는지 무리가 다 걷혔다.<br>옷 한 자락으로 산 저녁이었다. 둘째가 웃었다. 분대장 옷이 교재가 됐다고. 웃으라고 뒀다. 웃는 저녁이 이 정원에 몇 없으니. 가는 길에 덤불에서 짐승 고기 반 짝도 주웠다. 저들 연습 사냥의 흘린 몫이었다.`,
      ng:`틈을 보이는 셈이 과했다. 서툰 꼬마가 아니라 그 뒤의 덜 서툰 놈이 그 틈을 물러 들어왔다.<br><br>진짜 이빨이 빈 옆구리로 왔다. 몸을 비틀어 반만 피했다. 옆구리에 세 줄이 그어졌다.<br>피 냄새에 연습의 공기가 변하는 반 숨, 다섯이 등을 맞대고 창을 세웠다. 수풀 너머 울음이 길게 나며 무리를 거뒀다. 연습에 피는 계획에 없던 모양이다. 보이는 틈은 보여 주는 상대까지 골라서 보일 것. 옆구리가 아물며 새긴 말이다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-32, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 진법가 · 내공
// ------------------------------------------
kJob('formation', 'S', [

{ at:'S', t:'방위 — 사냥꾼을 남쪽으로 삼다',
  x:`이 어둠에는 북이 없다. 별도, 이끼도, 물매도 없다. 손바닥 나침반이 허공만 긁는다.<br><br>
    방위 없는 땅에서는 진이 안 선다. 진이 안 서면 다섯은 그냥 다섯 낱이다.<br>
    딱 하나, 움직이지 않는 기가 있다. 사흘째 따라붙는 그것. 거리를 안 좁히고 늘 같은 쪽에 떠 있는 차고 끈끈한 기.<br><br>
    저것을 남쪽으로 삼으면 어떨까. 사냥꾼을 방위로 쓰는 진.`,
  o:[
    { l:'① 그것의 기를 남쪽으로 박고 나머지 방위를 세운다.', k:'fix', dc:25, wake:1,
      ok:`저것의 기를 남으로 박았다. 남이 서자 북이 서고, 팔문이 섰다.<br><br>생문은 늘 저것의 반대편, 북쪽 어귀로 났다. 사흘을 그 진으로 걸었다. 저것이 자리를 옮기면 방위째 돌려 세웠다. 진이 저것을 따라 도는 셈이지만, 도는 동안 다섯은 한 번도 저것의 어귀로 안 걸었다.<br>나흘째에 저것이 떨어져 나갔다. 사냥감이 늘 제일 먼 문으로만 다니는 까닭을 끝내 몰랐을 것이다.<br><br>방위는 땅이 주는 것도, 사람이 세우는 것만도 아니다. 적도 방위가 된다. 적을 진의 기둥으로 박아 쓴 첫날. 진법의 그릇이 한 치 넓어졌다.`,
      ng:`저것을 남으로 박았는데 저것이 밤새 세 번 자리를 옮겼다. 방위가 세 번 무너졌다.<br><br>무너질 때마다 진을 다시 세우느라 걸음이 쌓이질 않았다. 새벽에 보니 밤새 간 길이 반 마장.<br>움직이는 것은 기둥이 못 된다. 아침에 큰 바위 하나를 북으로 새로 박고서야 진이 섰다. 적은 방위로 쓰되 보조 기둥으로만. 주 기둥은 움직이지 않는 것으로. 밤새 헛걸음이 가르친 셈값이었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 그것의 기가 뜨는 쪽을 피해 기가 고요한 쪽으로만 걷는다.', k:'sense', dc:24,
      ok:`방위를 접고 기의 높낮이만 읽었다. 저것의 기가 뜨는 쪽은 버리고, 기가 바닥에 고요히 깔린 쪽으로만 길을 이었다.<br><br>고요한 기는 빈 땅의 기다. 산 것도 죽은 것도 안 머무는 땅.<br>이틀을 그 길로 갔다. 멀리 돌았지만 아무것도 안 만났다. 빈 땅만 밟는 길은 진 없이도 진이다. 다만 빈 땅이 왜 비었는지는 가끔 생각하지 않기로 했다. 이 어둠에서 빈 데는 다 까닭이 있다.`,
      ng:`기가 고요한 쪽으로 길을 이었는데, 고요가 한 군데서 너무 깊었다. 기가 빨려 들어가 고요한 것이었다.<br><br>알았을 때는 늦었다. 발밑 땅이 숨을 쉬었다. 들숨에 다섯 발이 반 치씩 가라앉았다.<br>구르고 기어 그 땅을 벗어났다. 등 뒤에서 땅이 길게 내쉬었다. 고요에도 두 가지가 있다. 빈 고요와 삼키는 고요. 손바닥이 그 차이를 외울 때까지 빈 땅도 돌을 던져 보고 디뎠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 방위 없이 운에 맡겨 큰 나무들만 이어 걷는다.', k:'luck', dc:23,
      ok:`진법가가 쓰기엔 부끄러운 수지만, 큰 나무는 어디서나 큰 나무다. 우듬지가 보이는 큰 나무에서 큰 나무로 이었다.<br><br>세 그루째 나무 밑에서 오래된 돌무더기를 찾았다. 사람 손으로 쌓은 것. 전에 이 어둠을 지난 누군가의 길 표시였다.<br>돌무더기는 다섯 개가 더 있었고, 끝에는 마른 샘과 바위굴이 있었다. 남의 진을 주운 셈이다. 운도 길눈이 있어야 줍는다고, 부끄러움은 반만 하기로 했다.`,
      ng:`큰 나무만 잇다가 알았다. 이 어둠의 큰 나무들은 유난히 둥치가 매끈하다. 긁힌 자국 하나 없이.<br><br>까닭이 있었다. 큰 나무마다 그것들이 등을 비비고 가는 기둥이었던 것이다. 짐승의 이정표.<br>네 그루째에서 등 비비러 온 것과 마주쳤다. 나무 뒤로 돌며 반 각을 숨바꼭질하고서야 떨어졌다. 남의 이정표는 남의 길이다. 그날부터 큰 나무는 멀리서 보기만 했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'다섯 돌의 울 — 밤을 두르는 진',
  x:`잘 자리를 잡았다. 문제는 이 어둠의 밤이다. 번만으로는 모자란다. 저들은 번 서는 눈의 깜빡임까지 센다.<br><br>
    다섯 돌로 울을 치기로 했다. 지키는 진. 돌마다 내공을 먹여 기의 울타리를 두르는.<br>
    기의 울은 몸을 못 막는다. 대신 들어서는 순간 울 안의 다섯이 안다. 울이 종이 되는 것이다.<br><br>
    종이 운 다음은 창의 일이다.`,
  o:[
    { l:'① 내공을 먹인 다섯 돌로 숙영지에 지키는 진을 두른다.', k:'fix', dc:25, cost:{ qi:30 },
      ok:`다섯 돌에 내공을 나눠 먹이고 다섯 자리에 박았다. 돌과 돌 사이로 기가 실처럼 이어져 울이 됐다.<br><br>삼경에 울 동쪽이 떨렸다. 종이 운 것이다. 다섯이 눈을 뜨고 창을 쥐는 데 반 숨.<br>들어서던 것은 다섯 창이 일제히 제 쪽을 겨누자 멈췄다. 자는 먹이를 기대한 걸음이었으니. 물러나서 울 밖을 한 바퀴 돌고 갔다. 울이 떨리는 자리로 저것의 길이 다 읽혔다. 아침까지 두 번 더 울었고 두 번 다 창이 마중했다. 세 번째는 없었다.`,
      ng:`돌에 내공을 먹이는데 다섯째 돌에서 기가 자꾸 샜다. 돌 속이 삭은 돌이었다.<br><br>샌 자리가 울의 구멍이 됐다. 삼경에 그 구멍으로 들어온 것이 종도 없이 넷째 발치까지 왔다.<br>넷째가 제 발 시린 것에 깨서 비명을 질렀고, 그 비명이 종을 대신했다. 창 다섯이 겨우 쫓아냈다. 진의 돌은 속까지 봐서 고를 것. 겉 멀쩡한 돌이 제일 위험한 돌이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 진 없이 등을 바위에 붙이고 번을 두 배로 선다.', k:'steady', dc:24,
      ok:`내공을 아끼고 몸으로 섰다. 등 뒤는 바위, 앞은 번 둘. 반 시진 교대.<br><br>밤새 기척이 세 번 돌았다. 세 번 다 번의 눈이 먼저 잡았다.<br>아침에 다들 눈이 퀭했지만 내공은 가득했다. 그 내공이 한낮의 고비에서 값을 했다. 진은 내공을 쓰고 번은 잠을 쓴다. 어느 쪽을 쓸지는 내일 쓸 것이 무엇인지에 달렸다. 오늘은 맞는 셈이었다.`,
      ng:`번을 두 배로 서니 잠이 반이 됐다. 이틀째에 번 서던 둘째가 선 채로 졸았다.<br><br>조는 눈 앞으로 무엇이 지나갔다. 깨어 있었으면 봤을 것이다. 아침에 숙영지 열 걸음 밖에서 발자국이 나왔다. 둘러보고 간 자국.<br>살펴 간 적은 다시 온다. 그날 밤은 결국 내공을 들여 진을 쳤다. 아낀 내공은 아낀 게 아니라 미룬 것이었다. 미룬 값에는 이자가 붙는다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S', t:'찬 기 — 온기 없는 여섯째',
  x:`기를 보는 눈에 사람은 불씨다. 다섯이 걸으면 불씨 다섯이 떠간다.<br><br>
    오늘 저녁부터 불씨 사이에 찬 것이 하나 섞였다. 온기가 없는 기. 그런데 움직임은 사람 걸음이다.<br>
    여섯째는 늘 대열의 그늘에 선다. 셋째 뒤, 짐 그림자 옆. 불씨들 사이에 숨은 재.<br><br>
    차가운 것이 사람 걸음을 배웠다면, 오래 사람을 본 것이다.`,
  o:[
    { l:'① 재의 자리를 응시로 짚어 대열의 기 흐름에서 끊어 낸다.', k:'gaze', dc:26, wake:1,
      ok:`불씨 다섯의 기는 서로 흐른다. 정이 든 사람들의 기는 이어지게 마련이다. 재는 그 흐름에 얹혀 있었다. 남의 온기를 빌려 제 찬 기를 가리고.<br><br>흐름을 읽어 재의 자리를 짚었다. 셋째와 넷째 사이. 그리고 둘 사이의 기를 일부러 끊었다. 둘을 멀리 떼어 걷게 해서.<br>빌릴 온기가 끊기자 재가 드러났다. 허옇게 찬 것이 대열 복판에 반 숨 서 있다가, 다섯 눈이 다 제게 꽂히자 연기처럼 길 밖으로 물러났다. 다시는 대열에 안 붙었다.<br><br>기의 흐름은 정의 흐름이다. 그 흐름에 얹혀 오는 것이 있다는 것. 끊어야 보이는 것이 있다는 것. 잇는 법만 알던 진법가가 끊는 법을 배웠다.`,
      ng:`재의 자리를 짚느라 대열의 기를 너무 오래 들여다봤다. 보는 기는 흔들린다.<br><br>흔들린 흐름에 다섯이 다 서늘해졌다. 누가 먼저랄 것 없이 서로를 곁눈질했다. 네가 차냐. 내가 차냐.<br>의심은 기를 더 끊는다. 재는 그 끊긴 자리마다 옮겨 다니며 하루를 더 묵었다. 저녁에 모닥불을 크게 피우고 다섯이 손을 잡고서야 흐름이 다시 이어졌고, 재가 밀려났다. 의심을 심는 것이 저것의 끼니였는지도 모른다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 모른 척 걷다가 쉴 참에 모닥불을 크게 피워 올린다.', k:'steady', dc:24,
      ok:`아는 티를 안 냈다. 쉴 참에 불을 평소 배로 피웠다. 다섯이 불가에 바짝 둘러앉아 온기 한 겹을 더 입었다.<br><br>불씨가 커지면 재는 설 자리가 없다. 온기를 빌릴 수 없을 만큼 뜨거우면.<br>여섯째 기가 불빛 가장자리를 두 바퀴 돌다 어둠으로 꺼졌다. 쫓지 않고 보냈다. 쫓으면 불에서 멀어지니까. 불은 창보다 오래된 진이다. 사람이 제일 먼저 친 진.`,
      ng:`불을 키운 것까지는 좋았는데 연기가 문제였다. 큰 불의 연기 기둥이 어둠 멀리까지 섰다.<br><br>재는 쫓았다. 대신 연기를 보고 다른 것이 왔다. 몸이 있는 것이.<br>불을 걷어차 끄고 어둠 속에서 창으로 버텼다. 그것은 불씨가 꺼진 자리를 한참 파헤치다 갔다. 불은 진이되 봉화이기도 하다. 두 얼굴을 다 셈한 다음에 피울 것.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'걷는 진 — 자리가 목숨이다',
  x:`트인 땅을 지나는 반나절. 저들이 언제 어디서 덮칠지 모른다.<br><br>
    걸으면서 치는 진을 폈다. 다섯 자리. 창 둘이 앞뒤 모서리, 눈 밝은 둘이 양옆, 가운데 짐과 다친 발.<br>
    이 진은 자리가 전부다. 누가 반 걸음만 벗어나도 모서리가 열린다. 열린 모서리는 초대장이다.<br><br>
    반나절 동안 다섯 자리를 다섯 몸에 붙여 두는 일. 그게 오늘 진법가의 일이다.`,
  o:[
    { l:'① 자리마다 밟을 간격을 발로 그어 주고 흐트러질 때마다 당겨 세운다.', k:'fix', dc:25,
      ok:`출발 전에 맨땅에 진을 실물 크기로 그렸다. 다섯이 제 자리에 서서 앞사람과의 간격을 발걸음으로 외우게 했다.<br><br>걷는 동안 자리가 눌어지면 짧게 손뼉 한 번. 그 소리에 다섯이 제 간격을 되찾았다.<br>해 질 녘에 저들이 한 번 간을 봤다. 덮치기 직전까지 왔다가 모서리가 안 열린 진을 보고 돌아갔다. 진은 창이 아니라 간격이 싸운다. 반나절 내내 닫혀 있던 네 모서리가 오늘의 전과다.`,
      ng:`반나절이 길었다. 오후에 넷째 자리가 자꾸 늘어졌다. 발이 아픈 걸 말 안 한 것이다.<br><br>손뼉으로 세 번을 당겼는데 네 번째에 늦었다. 뒷모서리가 열렸다.<br>열린 자리로 그림자 하나가 쑥 들어왔다 나갔다. 스치기만 했는데 넷째 등짐 끈이 끊겨 있었다. 경고 반, 간보기 반. 그날 밤 넷째 발의 물집을 다 같이 봤다. 자리를 지키라는 말 전에 자리를 지킬 수 있는 발인지 물을 것. 진은 몸 위에 선다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 덮치는 순간에는 진을 버리고 각자 구르게 미리 정한다.', k:'evade', dc:26,
      doom:{ title:'열린 모서리', what:'흩어진 진의 빈자리에서 낚아채여 수풀로 끌려갑니다', dc:20, sec:38,
        text:`진이 깨질 바엔 깨는 순서를 정하자는 셈. 덮치면 진을 버리고 각자 사방으로 구른 뒤 바위에서 모이기로 했다.<br><br>저들이 덮쳤다. 다섯이 약속대로 흩어졌다. 반은 맞는 수였다.<br>저들의 진이 더 빨랐던 게 틀린 반이다. 흩어지는 다섯 중 가운데 자리, 짐을 진 느린 하나를 저들 둘이 양쪽에서 접었다. 이쪽이 그 사이로 뛰어들어 하나를 창으로 밀었다.<br><br>밀어낸 값으로 이쪽이 잡혔다. 다리에 턱이 감긴다. 수풀로 끌려간다. 버린 진의 다섯 자리가 땅에 발자국으로만 남아 있는 게 끌려가며 보였다.`,
        dieText:`넷은 바위에서 모였다. 약속한 자리에서, 약속 못 한 수로.<br><br>그 뒤로 넷은 진을 안 버린다. 덮쳐도 모서리를 좁혀 등을 맞댈 뿐이다.<br>흩어지는 것은 진이 아니라고, 진을 버리자던 사람이 몸으로 적고 갔다. 넷이 치는 진의 가운데 자리는 그 뒤로 늘 비워 둔다. 짐도 안 놓는다.` },
      ok:`덮치면 흩어지는 대신 뭉치기로 정했다. 진을 버리는 게 아니라 접는 것. 네 모서리가 가운데로 좁혀들어 등을 맞댄 송곳 진.<br><br>오후에 저들이 정말 덮쳤다. 손뼉 두 번. 진이 반 숨 만에 접혔다.<br>달려들던 저들이 사방이 창끝인 덩어리 앞에서 멈칫했다. 열린 모서리를 보고 달려든 눈에 닫힌 송곳이 서 있으니. 저들은 세 바퀴를 돌다 갔다. 진은 펴는 법과 접는 법이 한 벌이다. 한 벌을 다 아는 진만 산 진이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'사문을 여는 진 — 초대장',
  x:`밤마다 저것이 온다. 쫓아도 다음 밤에 또. 숙영지를 옮겨도 따라온다.<br><br>
    끝을 내야 한다. 저것이 들어올 문을 이쪽이 정하는 걸로.<br>
    여덟 자리에 돌을 박아 팔문진을 쳤다. 일곱 문은 기로 눌러 닫고, 사문 하나만 열어 둔다. 열린 문이 저것에게는 허술한 틈으로 보일 것이다.<br><br>
    사문 안쪽에는 창 셋이 기다린다. 초대장은 보냈다. 올지는 저것이 정한다.`,
  o:[
    { l:'① 내공으로 일곱 문을 닫고 사문에 저것을 맞는다.', k:'fix', dc:26, cost:{ qi:36 }, wake:1,
      ok:`일곱 돌에 내공을 눌러 기의 벽을 세우고 사문 돌만 비워 뒀다. 빈 자리의 기가 달게 느껴지도록 그 돌에는 온기를 한 줌 발랐다.<br><br>삼경에 저것이 왔다. 울 둘레를 반 바퀴 돌더니 과연 사문으로 들어섰다. 허술한 틈으로.<br>들어선 자리는 세 창의 부채꼴 한가운데였다. 세 창이 어둠에서 일어서자 저것이 처음으로 사냥감의 소리를 냈다. 문까지 물러나는 길도 이쪽이 셈해 둔 길이었다. 좁게. 등을 긁히며 빠져나간 저것은 다시 안 왔다.<br><br>문을 닫는 진은 배웠고, 문을 여는 진은 오늘 밤 처음 쳤다. 연 문이 닫은 문보다 깊다. 사문이 왜 사문인지, 저것이 몸으로 배워서 갔다.`,
      ng:`일곱 문을 닫았는데 저것이 사문으로 안 왔다. 울 밖에서 밤새 일곱 문만 차례로 긁어 봤다.<br><br>닫힌 문을 미는 힘에 내공이 밤새 닳았다. 새벽엔 기의 벽이 종잇장이었다.<br>저것은 동틀 녘에 갔다. 문이 여덟인 것도, 하나만 연 것도 다 안다는 걸음으로. 초대장을 읽고도 안 들어오는 손님이 제일 무서운 손님이다. 다음 밤부터는 진을 접고 자리를 크게 옮겼다. 그게 맞는 수였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 진 없이 저것이 다니는 길목의 바위를 무너뜨려 끝낸다.', k:'break', dc:26,
      ok:`저것이 밤마다 오는 길은 늘 같은 벼랑 밑이었다. 낮에 그 벼랑 위 바위를 반나절 공들여 괴어 놨다.<br><br>밤에 저것이 왔다. 벼랑 밑, 괸 돌 아래. 줄을 당겼다.<br>바위가 쏟아졌다. 깔리진 않았다. 저것들은 빠르다. 대신 길이 막혔고, 쏟아진 돌에 꼬리를 밟힌 저것이 꼬리 끝을 두고 갔다. 한 뼘짜리. 그 뒤로 밤 손님이 끊겼다. 꼬리 값이 그만큼 비쌌던 모양이다.`,
      ng:`바위를 괴는 낮 동안 저것이 어디서 봤는지, 밤에 그 길로 안 왔다.<br><br>대신 괴어 둔 바위 위쪽 벼랑을 타고 넘어왔다. 이쪽 덫의 등 뒤로.<br>번 서던 둘째가 늦게 보고 소리쳤다. 한바탕 소동 끝에 쫓았지만 짐 하나가 찢겼다. 덫을 본 적은 덫을 돌아온다. 낮의 일은 밤의 적이 본다고 셈할 것. 이 어둠의 낮은 생각보다 눈이 많다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'기가 빨리는 자리 — 땅 밑의 입',
  x:`좋은 숙영지를 찾았다. 바람 막히고 물 가깝고 바닥 판판한. 그런데 손바닥이 싫다 한다.<br><br>
    이 자리, 기가 샌다. 선 자리에서 발바닥으로 기가 조금씩 빠져나간다. 땅속 어딘가로. 고인 물이 보이지 않는 틈으로 새듯.<br>
    기가 새는 땅은 기를 먹는 무엇이 밑에 있는 땅이다.<br><br>
    좋아 보이는 자리가 왜 비어 있었는지, 답은 늘 나중에 온다. 오늘은 먼저 왔다.`,
  o:[
    { l:'① 기가 새는 결을 따라가 땅 밑의 입이 어디인지 가늠한다.', k:'sense', dc:25,
      ok:`새는 결을 발바닥으로 따라갔다. 샘을 거슬러 오르듯. 결이 모이는 자리는 숙영지 복판의 판판한 바위 밑이었다.<br><br>바위 가장자리 흙이 숨구멍처럼 들락였다. 밑에 입이 있다. 판판한 바위는 뚜껑이었다.<br>자리를 조용히 물렸다. 반 마장 밖에서 보니 밤중에 그 바위가 한 번 들렸다 내려앉았다. 뚜껑이 열렸다 닫힌 것이다. 좋은 자리는 누가 좋게 만들어 둔 자리일 수 있다. 상 차려진 밥상은 차린 이가 있다.`,
      ng:`결을 따라가느라 그 땅 위를 반 각이나 서성였다. 새는 기가 그만큼 땅 밑으로 흘러 들어갔다.<br><br>기는 땅 밑의 것에게 저녁 냄새였던 모양이다. 발밑 흙이 꺼지기 시작했다.<br>구르듯 물러났다. 서성이던 자리가 사발만 하게 내려앉고, 그 밑에서 젖은 숨소리가 올라왔다. 재 볼 것을 다 재기 전에 발부터 빼는 셈도 필요하다. 궁금함은 가끔 미끼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 하룻밤쯤이야 하고 그 자리에 짐을 푼다.', k:'luck', dc:26,
      doom:{ title:'뚜껑 밑의 입', what:'잠든 채 꺼진 땅 밑으로 빨려 들어갑니다', dc:20, sec:35,
        text:`손바닥의 싫다는 소리를 피곤이 눌렀다. 하룻밤이다. 짐을 풀고 누웠다.<br><br>삼경에 땅이 비었다. 등 밑이 꺼진 것이다. 모래시계 모래 빠지듯, 바닥이 가운데로 흘러내린다.<br>이불째 미끄러진다. 가운데로. 가운데 판판한 바위가 뚜껑처럼 들려 있고 그 밑은 젖은 어둠이다.<br><br>흘러내리는 흙과 함께 빨려 들어간다. 손에 잡히는 풀이 뿌리째 같이 온다. 위에서 넷이 이불 끝을 잡는 소리가 들린다. 이불이 길기를 빌 뿐이다.`,
        dieText:`이불은 길지 않았다. 뚜껑 바위가 내려앉고 땅은 도로 판판해졌다.<br><br>넷은 그 판판한 자리를 밤새 팠다. 세 길을 파도 흙뿐이었다. 입은 제 목구멍을 옮긴 뒤였다.<br>넷은 그 뒤로 자리를 잡으면 먼저 손바닥을 땅에 댄다. 진법가가 하던 그대로. 기가 새는지는 넷 중 둘만 겨우 느끼지만, 넷 다 댄다. 대는 것부터가 배운 것이라서.` },
      ok:`하룻밤이다, 하고 짐을 풀다가 손바닥이 끝내 고집을 부렸다. 져 주기로 했다.<br><br>자리는 그대로 쓰되 눕는 데만 바꿨다. 기가 새는 복판을 피해 가장자리 바위 턱 위로. 땅이 아니라 바위에 등을 붙이고.<br>삼경에 복판 땅이 정말 꺼졌다. 소리 없이, 사발처럼. 풀어 둔 빈 자루 하나가 미끄러져 들어가 사라졌다. 다섯은 바위 턱에서 그걸 다 봤다. 아무도 아무 말 안 했다. 새벽까지 아무도 안 잤다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'S', t:'저들의 진 — 눈을 빼앗다',
  x:`저들 셋이 사냥진을 폈다. 하나는 몰고 둘이 길목을 접는, 이쪽이 쓰면 학익이라 부를 진.<br><br>
    짐승이 진을 편다. 그걸 알아본 순간 더는 짐승 셋이 아니다. 적진이다.<br>
    모든 진에는 눈이 있다. 이 진의 눈은 두 길목이 접히는 한 점. 거기가 비어 있다. 저들 셈에 먹이가 설 자리라서.<br><br>
    적진의 눈을 이쪽이 먼저 차지하면, 진은 주인을 바꾼다.`,
  o:[
    { l:'① 몰리는 척 눈 자리에 먼저 서서 창을 밖으로 세운다.', k:'fix', dc:26, wake:1,
      ok:`몰리는 척 뒷걸음질로 정확히 그 한 점에 섰다. 다섯이 등을 맞대고 창은 밖으로.<br><br>저들의 진이 셈대로 접혔다. 접히고 보니 한가운데가 먹이가 아니라 송곳이다.<br>접힌 진은 못 편다. 제 진에 제가 끼인 저들 둘이 창끝 앞에서 어쩔 줄을 몰랐다. 몰던 놈만 멀리서 울었다. 셋이 진을 버리고 흩어지는 데 반 각. 저들은 다음부터 이 다섯에게 진을 안 폈다. 진을 아는 먹이는 먹이가 아니라는 걸 안 것이다.<br><br>적진의 눈은 적이 비워 둔 자리다. 비워 둔 자리는 차지하라고 있는 자리. 남의 진을 빼앗아 쓰는 맛을 알았다. 진법가가 알면 안 되는 맛인지도 모른다. 알았지만.`,
      ng:`눈 자리라 셈한 점이 반 걸음 어긋났다. 저들의 진은 이쪽 학익보다 접히는 품이 좁았다.<br><br>어긋난 반 걸음에 넷째가 접히는 길목에 걸렸다. 발톱이 어깨를 긁었다.<br>송곳 진으로 급히 뭉쳐 밀어내긴 했다. 짐승의 진은 사람 진보다 이음새가 빡빡하다. 책에 없는 진은 책으로 재지 말 것. 어깨의 석 줄이 책 바깥의 첫 줄이 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 몰이꾼부터 창으로 받아쳐 진의 첫 수를 꺾는다.', k:'break', dc:25,
      ok:`진은 첫 수가 꺾이면 둘째 수가 없다. 이 진의 첫 수는 몰이꾼이다.<br><br>몰리는 대신 다섯이 돌아서서 몰이꾼에게 마주 달렸다. 창 다섯이 한 점으로.<br>몰이꾼은 모는 데 쓰는 몸이라 받는 데는 무르다. 두 창에 쫓겨 저들 길목 쪽으로 달아났고, 접으려고 기다리던 둘은 제 식구가 몰려오는 진을 접을 수 없었다. 진이 안에서부터 무너졌다. 적진의 급소는 눈만이 아니다. 첫 수를 쥔 놈, 그놈도 급소다.`,
      ng:`몰이꾼에게 마주 달렸는데 몰이꾼이 안 물러났다. 모는 척하던 것이 받는 몸이었다.<br><br>진을 읽은 것까지 읽힌 것이다. 가짜 몰이꾼에 막힌 사이 진짜 둘이 등 뒤에서 접혀 왔다.<br>송곳으로 뭉쳐 긴 반 각을 버티고서야 틈을 뚫었다. 다섯 다 생채기를 하나씩 나눠 가졌다. 적진을 읽으면 적도 이쪽 읽기를 읽는다. 읽기 싸움은 늘 한 수 더 있다고 셈할 것.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } }
  ] },

{ at:'S', t:'불씨 줄이기 — 기를 재로 덮다',
  x:`저들 중 눈 밝은 놈은 기를 본다. 확신하게 됐다. 불빛도 소리도 없이 세 번을 정확히 찾아왔으니.<br><br>
    기를 보는 눈에 다섯은 어둠 속 등불 다섯이다. 끄는 수는 없다. 산 사람의 기는 안 꺼진다.<br>
    줄이는 수는 있다. 불씨에 재를 덮듯, 기를 몸 깊이 가라앉혀 덮는 법. 내공으로 다섯을 다 덮어 줘야 한다.<br><br>
    덮인 기로는 창도 무뎌진다. 싸움이 나면 걷어야 한다. 걷는 데 세 숨.`,
  o:[
    { l:'① 내공으로 다섯의 기를 재 덮인 불씨로 가라앉힌다.', k:'fix', dc:26, cost:{ qi:34 },
      ok:`한 사람씩 등에 손바닥을 대고 기를 가라앉혔다. 등불 다섯이 깜부기불 다섯이 됐다.<br><br>그 밤 눈 밝은 놈이 왔다. 세 번 오던 길로, 네 번째. 그리고 길을 잃었다. 늘 보이던 등불이 없으니.<br>깜부기불 다섯 곁을 두 번이나 지나쳤다. 코앞에서. 재 덮인 기는 바위의 기와 비슷하다. 저것은 새벽까지 빈 어둠을 뒤지다 갔다. 보는 눈에는 덮는 수. 수와 수가 만나면 먼저 덮는 쪽이 이긴다.`,
      ng:`다섯을 다 덮고 나니 이쪽 내공이 얕아졌다. 덮는 자의 기는 못 덮는다는 걸 잊었다.<br><br>눈 밝은 놈이 깜부기불 다섯은 지나치고 등불 하나를 찾아냈다. 이쪽을.<br>세 숨 걸려 넷의 기를 걷는 동안 혼자 창으로 버텼다. 어깨가 긁히고서야 다섯 창이 섰다. 덮는 순서의 마지막은 늘 저 자신이어야 한다. 그러려면 제 몫의 내공을 맨 나중까지 남겨 둘 것. 셈서리 첫 줄에 새로 적었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 기를 줄이는 대신 거짓 등불을 멀리 세운다.', k:'hide', dc:25,
      ok:`숙영지에서 반 마장 밖, 마른 나무 둥치에 내공 한 줌을 박아 뒀다. 사람 기 비슷한 온기로 밤새 새어 나오게.<br><br>거짓 등불 하나, 진짜 깜부기 다섯.<br>눈 밝은 놈이 밤새 그 나무를 맴돌았다. 둥치를 긁고, 올려다보고, 파 보고. 새벽에 가 보니 나무 밑동이 반쯤 파헤쳐져 있었다. 속은 걸 안 뒤의 심통까지 고스란히. 기는 숨기는 것만이 아니라 옮겨 심는 것이기도 하다.`,
      ng:`거짓 등불에 박은 내공이 너무 진했다. 사람 하나가 아니라 사람 셋 어치.<br><br>눈 밝은 놈만 아니라 코 밝은 놈들까지 그리로 몰렸다. 그리고 거기 아무것도 없다는 걸 안 저들이 둘레를 뒤지기 시작했다.<br>거짓 등불이 길잡이가 된 꼴. 다섯이 새벽까지 두 번 자리를 옮겼다. 미끼는 한 입 크기로 만들 것. 큰 미끼는 미끼가 아니라 잔칫상 초대다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S', t:'외길 — 숨으로 잇는 다리',
  x:`벼랑 허리 외길이다. 한 사람 폭, 백 걸음. 아래는 어둠이 깊어 바닥이 안 보인다.<br><br>
    바람이 불규칙하게 치받는다. 그리고 그 어둠 속에서 가끔 날개 소리가 난다. 크고 느린 날개.<br>
    다섯이 한 줄로 서는 수밖에 없다. 문제는 외길에서는 서로를 도울 손이 없다는 것.<br><br>
    손이 안 닿으면 기로 잇는다. 다섯 숨을 한 줄기로.`,
  o:[
    { l:'① 내공으로 다섯 숨을 한 줄기로 이어 외길을 건넌다.', k:'fix', dc:26, cost:{ qi:35 },
      ok:`앞사람 날숨을 뒷사람이 들이쉬는 간격으로 세우고, 그 숨줄에 내공을 실었다. 다섯 숨이 한 줄기가 됐다.<br><br>숨이 이어지면 흔들림도 이어진다. 둘째가 바람에 휘청하는 순간 그 흔들림이 숨줄을 타고 왔고, 앞뒤 둘이 반 숨 먼저 벽에 붙어 버텨 줬다. 손 없이 손을 잡은 셈.<br>날개 소리가 두 번 올라왔지만 다섯 숨이 하나로 고르니 바위 틈 바람 소리와 다를 게 없었던 모양이다. 백 걸음이 끝나고 숨줄을 풀자 다섯이 다 같은 숨을 쉬고 있었다. 한참을.`,
      ng:`숨줄을 세웠는데 넷째가 바람에 숨을 삼켰다. 줄기가 거기서 끊겼다.<br><br>끊긴 숨은 흐트러진 기다. 흐트러진 기 다섯이 벼랑에 등불처럼 떠 있는 꼴.<br>어둠 밑에서 날개가 일어섰다. 다섯이 벽에 몸을 눌러 붙이자 큰 그림자가 외길을 한 번 쓸고 지나갔다. 바람이 사람을 벽에 박았다. 숨줄은 끊길 자리를 미리 셈해 매듭을 둘 것. 긴 줄일수록 매듭이 목숨이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 숨줄 없이 운에 맡겨 한 사람씩 바람 잔 틈에 건넌다.', k:'luck', dc:26,
      doom:{ title:'어둠 밑의 날개', what:'외길에서 낚아채여 벼랑 밑 어둠으로 끌려 내려갑니다', dc:20, sec:35,
        text:`바람 잔 틈을 골라 한 사람씩 보냈다. 넷이 건넜다. 운이 좋았다.<br><br>마지막으로 이쪽이 건너는데 바람이 생각보다 일찍 돌아왔다. 벽에 붙어 버텼다. 버티는 기가 벼랑에 홀로 떠 있는 등불이 된 것은 셈 밖이었다.<br>어둠 밑에서 날개가 일어섰다. 바람보다 큰 바람이 치받는다.<br><br>발이 외길에서 떨어진다. 발톱이 어깨를 감는다. 벼랑 밑 어둠으로 끌려 내려간다. 위에서 넷의 외침이 바람에 찢겨 흩어진다.`,
        dieText:`어둠 밑에서는 끝내 아무 소리도 올라오지 않았다. 바닥 없는 데서는 떨어지는 소리도 없다.<br><br>넷은 외길 끝에서 밤을 새우고 아침에 돌 네 개를 벼랑 끝에 쌓았다.<br>숨을 이어 건너자던 수를 넷은 그제야 배웠다. 늦게 배운 수는 비싸다. 넷이 치는 진에는 그 뒤로 혼자 건너는 자리가 없다. 어디에도.` },
      ok:`바람 잔 틈을 골라 한 사람씩 보내되, 건너는 사람의 기만은 이쪽이 멀리서 내공으로 눌러 줬다. 등불을 갓으로 가리듯.<br><br>넷이 건넜다. 마지막 이쪽 차례엔 가려 줄 손이 없다. 대신 때를 골랐다. 날개 소리가 어둠 깊이 가라앉은 직후, 바람이 도는 틈.<br>백 걸음을 쉰여섯 걸음으로 건넜다. 뛰다시피. 외길 끝에 구르듯 닿자 등 뒤에서 바람이 돌아왔다. 반 숨 차이. 운을 쓰되 운에 다 걸지는 않는 것, 그 반 숨이 수와 운의 차이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'새는 기 — 상처는 등불이다',
  x:`둘째가 허벅지를 다쳤다. 피는 멎었는데 기가 샌다. 상한 자리로 산 기가 실처럼 흘러나온다.<br><br>
    기를 보는 것들에게 새는 기는 어둠 속 등불이다. 피 냄새보다 멀리 가는.<br>
    사흘은 샐 상처다. 사흘 내내 등불을 들고 걷는 셈.<br><br>
    새는 것은 막고, 막은 것은 지켜야 한다.`,
  o:[
    { l:'① 상처 둘레에 세 돌 진을 앉혀 새는 기를 돌려 넣는다.', k:'fix', dc:25, wake:1,
      ok:`잘 때마다 둘째 상처 둘레에 작은 돌 셋을 앉혔다. 세 돌이 새는 기를 받아 둘째 몸으로 되돌리는 작은 진.<br><br>도는 기는 안 샌다. 등불이 꺼졌다.<br>사흘 밤을 그 진으로 잤다. 낮에는 셋 돌을 둘째 허리띠에 달아 두었다. 몸에 붙은 진은 처음 짜 봤다. 넷째 밤, 상처가 아물며 진이 저절로 풀렸다. 기가 더는 안 새니 돌이 받을 것이 없어진 것이다. 진이 제 일을 다하고 스스로 접히는 것을 처음 봤다.<br><br>진은 땅에만 치는 것이 아니었다. 사람 몸도 터다. 몸에 치는 진. 그 문이 열렸다. 문 너머가 넓다.`,
      ng:`세 돌 진을 앉혔는데 둘째가 잠결에 뒤척이며 돌 하나를 쳤다.<br><br>진이 깨지며 사흘 치 모은 기가 한꺼번에 샜다. 등불이 아니라 봉화가 됐다.<br>그 밤 기를 보는 것이 숙영지 코앞까지 왔다. 창 다섯이 밤을 새워 막았다. 몸에 치는 진은 몸이 움직인다는 것부터 셈할 것. 다음 밤부터 돌을 천에 싸서 상처에 동여맸다. 진이 몸과 같이 뒤척이게.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 아는 약초를 짓이겨 상처를 덮고 기는 하늘에 맡긴다.', k:'heal', dc:24,
      ok:`진보다 먼저 할 일이 있었다. 상처를 제대로 덮는 일. 짐에 남은 약초를 다 짓이겨 붙이고 천으로 감았다.<br><br>잘 덮인 상처는 기도 덜 샌다. 등불이 반으로 줄었다.<br>남은 반은 걸음으로 벌었다. 바람 거슬러, 물길 따라, 기가 흩어지는 길로만. 사흘째 저녁 상처가 마르며 기가 멎었다. 진법가도 가끔은 약초꾼이어야 한다. 진은 만능이 아니고, 만능 아닌 걸 아는 진법가가 오래 산다.`,
      ng:`약초가 모자랐다. 반만 덮인 상처는 반만 등불이다. 반짜리 등불도 등불이다.<br><br>이틀째 밤 무엇이 바람 밑에서 오래 서성였다. 창을 세우고 밤을 반 새웠다.<br>사흘째에 지나던 길가에서 약초 무더기를 찾아 마저 덮고서야 등불이 꺼졌다. 모자란 채 떠난 길의 밤은 두 배로 길다. 약초는 보일 때마다 캐 둘 것. 이 어둠의 살림 밑천이다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'꿈 — 밤에 열리는 문',
  x:`이 어둠에서 자면 다들 같은 꿈 언저리를 헤맨다. 누가 멀리서 부르고, 걸어가면 돌아오기 어려운 꿈.<br><br>
    어젯밤 넷째가 자면서 열 걸음을 걸었다. 눈 감은 채. 부르는 쪽으로.<br>
    기를 보면 안다. 잠든 사람의 기는 문이 반쯤 열린 집이다. 열린 문으로 부르는 소리가 든다.<br><br>
    다섯 집의 문단속. 오늘 밤 진법가의 일이다.`,
  o:[
    { l:'① 내공으로 잠자리 둘레에 기를 거르는 울을 두른다.', k:'fix', dc:26, cost:{ qi:33 },
      ok:`잠자리 둘레에 다섯 돌을 앉히고 내공을 둘렀다. 막는 울이 아니라 거르는 울. 바람과 숨은 들고, 부르는 것은 걸리게.<br><br>밤중에 울 가장자리가 두 번 떨렸다. 부르는 소리가 체에 걸리는 떨림.<br>울 안의 다섯은 부름 없는 잠을 잤다. 이 어둠에 들어와 처음으로. 아침에 넷째가 말했다. 간밤 꿈엔 아무도 안 불렀다고. 고향 마당만 나왔다고. 그 말이 진법가가 받은 제일 큰 삯이었다.`,
      ng:`거르는 울을 두르고 이쪽도 잠들었다. 울은 치는 자가 깨어 있을 때 온전하다는 걸 잊을 만큼 고단했다.<br><br>삼경에 울이 얇아진 틈으로 부름이 샜다. 넷째가 일어나 걸었다. 울 가장자리까지.<br>울이 떨리는 기척에 이쪽이 깼다. 넷째 허리를 잡았을 때 넷째 발끝은 울 밖에 있었다. 눈을 뜬 넷째는 마당 대문을 열려던 참이라 했다. 그 대문이 무엇이었는지는 말해 주지 않았다. 울을 치면 울지기도 세울 것. 진과 번은 한 벌이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 부르는 소리를 따라 일어나는 사람의 손목을 서로 묶고 잔다.', k:'bond', dc:26,
      doom:{ title:'같이 걷는 꿈', what:'잠든 둘이 손목이 묶인 채 나란히 어둠 속으로 걸어 들어갑니다', dc:20, sec:40,
        text:`울 대신 끈을 골랐다. 다섯 손목을 느슨한 끈으로 이어 묶고 잤다. 하나가 걸으면 다른 손목이 당겨져 깨는 셈.<br><br>삼경에 끈이 당겨졌다. 넷째가 일어나 걷는다. 그런데 깨라고 묶은 둘째가 안 깬다. 같이 일어나 걷는다. 눈 감은 둘이 나란히.<br>부름이 끈을 타고 번진 것이다. 이어진 것은 기도 잇는다.<br><br>둘이 손목을 묶인 채 어둠 쪽으로 걸어 들어간다. 남은 셋이 제 손목의 끈을 푸느라 반 숨을 먹는다. 느슨하게 묶자던 매듭이 밤새 조여 있었다. 누가 조였는지는 모른다.`,
        dieText:`셋은 끈을 끊고 쫓았다. 어둠 속에서 끈 한 토막만 주웠다. 가지런히 잘린 끈이었다. 푼 것도 끊은 것도 아니고, 잘린.<br><br>돌아온 둘은 없다.<br>셋은 그 뒤로 잘 때 손목을 안 묶는다. 대신 둘레에 돌을 두르고 한 사람은 꼭 깨어 있는다. 이어 둔 것이 늘 지켜 주지는 않는다는 것. 끈 한 토막이 가르친 것 치고는 너무 비쌌다.` },
      ok:`손목을 끈으로 잇되 매듭마다 방울 대신 숟가락을 달았다. 당겨지면 돌에 부딪혀 소리가 나게.<br><br>삼경에 쨍그랑. 넷째가 일어나 걷는 첫걸음에 숟가락이 울었다. 다섯이 다 깼다.<br>넷째를 붙잡아 눕히고, 남은 밤은 둘씩 번갈아 깨어 지켰다. 끈은 잇는 수지 깨우는 수가 아니다. 깨우는 것은 소리다. 잇기와 깨우기를 한 끈에 다는 법, 숟가락 하나가 완성한 진이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'격자 복도 — 남이 깔아 둔 판',
  x:`시설의 복도는 바둑판이다. 가로세로 반듯한 격자. 진법가 눈에는 이것부터가 진이다.<br><br>
    곧은 복도는 기가 곧게 흐른다. 곧게 흐르는 기는 멀리서도 읽힌다. 격자를 다니는 것들이 길목마다 기다릴 수 있는 까닭이다.<br>
    그런데 격자에도 죽은 칸이 있다. 기가 꺾여 못 드는 칸. 기둥 뒤, 계단 밑, 어긋난 문틀 옆.<br><br>
    죽은 칸에서 죽은 칸으로. 바둑판 위의 다른 바둑.`,
  o:[
    { l:'① 죽은 칸들을 이어 기가 안 흐르는 길을 긋는다.', k:'fix', dc:26, wake:1,
      ok:`복도마다 죽은 칸을 짚었다. 기둥 뒤 한 칸, 무너진 선반 그늘 두 칸, 계단 밑. 죽은 칸끼리 이으니 구불구불한 길이 났다.<br><br>그 길로 걸었다. 곧은 복도를 두고 자꾸 꺾고 웅크리는 길.<br>길목을 지키던 것들 곁을 세 번 지났다. 세 번 다 저들은 곧은 기의 길만 보고 있었다. 죽은 칸의 다섯은 저들 바둑판에 없는 돌이었다.<br><br>남이 깐 판에서는 남이 못 쓰는 칸을 쓴다. 격자의 주인은 격자를 깐 자가 아니라 죽은 칸을 아는 자다. 이 시설의 복도가 오늘부터 이쪽 판이다.`,
      ng:`죽은 칸을 잇는 길이 두 복도 사이에서 끊겼다. 긴 직선 복도 하나는 죽은 칸이 하나도 없었다.<br><br>별수 없이 곧은 기를 타고 건넜다. 반쯤에서 복도 끝에 그것이 섰다. 기가 곧게 닿은 것이다.<br>왔던 죽은 칸으로 되뛰어 계단 밑에 다섯이 포개 숨었다. 그것이 복도를 두 번 오가는 동안 숨도 포개 쉬었다. 죽은 칸 길은 끊긴 데를 미리 셈하고 나설 것. 끊긴 자리가 바로 저들의 사냥 칸이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 격자의 기 흐름으로 저들이 지키는 길목을 먼저 짚는다.', k:'sense', dc:25,
      ok:`곧게 흐르던 기가 어느 길목에서 막혀 고여 있다. 흐름을 막는 부피가 있다는 것. 지키는 놈이다.<br><br>복도 셋을 그렇게 짚으니 저들의 배치가 나왔다. 셋이 세모꼴로 길목을 물고 있다.<br>세모의 변을 다 피해 빈 꼭짓점 쪽 계단으로 돌았다. 지키는 적은 제 몸으로 제 자리를 적는다. 기를 읽는 눈에는 매복이 방명록이다.`,
      ng:`기가 고인 길목을 짚었는데 하나를 놓쳤다. 고임이 없는 지킴이. 천장에 붙은 놈은 기가 바닥을 안 막는다.<br><br>그 밑을 지나다 위에서 덮쳤다.<br>다섯이 사방으로 구르고 창 둘이 천장을 그었다. 놈이 관으로 달아난 뒤에야 숨을 돌렸다. 바닥의 기만 읽은 셈. 격자는 바닥만이 아니라 천장에도 깔려 있다. 그날부터 기를 읽을 때 고개를 들고 읽었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S1', t:'표본실 — 병으로 쌓은 진',
  x:`표본실 선반의 병들이 이상하게 놓여 있다. 크기도 차례도 아니다. 어긋나게, 그러나 규칙 있게.<br><br>
    진법가 눈에만 보이는 규칙이다. 이것은 진이다. 병 하나하나가 돌이고, 선반이 진의 골격이다.<br>
    기가 병에서 병으로 흘러 바닥 틈으로 내려간다. 아래로. 깊은 층으로. 병 속 것들의 기를 모아 바치는 진.<br><br>
    여왕이 이 방을 젖줄로 쓰고 있는 것이다.`,
  o:[
    { l:'① 흐름의 요석인 병 하나를 찾아 반 뼘만 틀어 놓는다.', k:'fix', dc:26,
      ok:`진에는 요석이 있다. 흐름이 다 거쳐 가는 한 점. 선반 셋째 단의 주먹만 한 병이었다.<br><br>그 병을 반 뼘 틀었다. 깨지도 옮기지도 않고, 그저 흐름이 어긋날 만큼만.<br>기의 젖줄이 끊겼다. 바닥 틈으로 내려가던 흐름이 방 안을 헛돌기 시작했다. 사흘 뒤 깊은 층을 지날 때, 여왕의 둥이 전보다 느리고 성긴 것을 다섯이 다 느꼈다. 굶긴 것이다. 창 한 번 안 대고. 반 뼘의 전과였다.`,
      ng:`요석을 틀었는데 반 뼘이 아니라 한 뼘이 틀어졌다. 흐름이 어긋나는 대신 거꾸로 섰다.<br><br>내려가던 기가 역류해 병들이 일제히 덜그럭댔다. 속엣것들이 먹던 젖이 끊기고 되올라온 기에 체한 것이다.<br>병 두 개가 금 가는 소리를 듣고 방을 떴다. 복도까지 덜그럭 소리가 따라왔다. 남의 진을 만질 때는 숨 하나 어치만 만질 것. 진은 세게 틀면 덫이 된다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 누가 병을 이렇게 쌓았는지 흐름의 손자국을 응시한다.', k:'gaze', dc:26,
      ok:`진을 짠 손을 읽었다. 병을 쥔 자국, 미는 결. 사람 손이다. 다만 손자국 위에 긴 손가락 자국이 덧눌려 있다. 사람이 쌓고, 사람 아닌 것이 고쳐 쌓은 것.<br><br>사람 손자국의 주인은 금방 짚였다. 연구복 주머니마다 바둑돌이 나오던 그 시신. 이 시설에 진을 아는 사람이 있었고, 여왕은 그 사람의 진을 빼앗아 제 젖줄로 고쳐 쓴 것이다.<br>시신의 주머니에서 남은 바둑돌 여섯 개를 거뒀다. 선배의 유품이다. 어느 별 아래서 배운 진인지는 몰라도, 진법가는 진법가를 알아본다. 돌 여섯이 그날부터 이쪽 진의 돌이 됐다.`,
      ng:`손자국을 읽느라 선반에 너무 가까이 붙었다. 숨이 병 하나에 닿았다.<br><br>병 속엣것이 눈을 떴다. 젖줄에 매달려 자던 것이 산 숨을 맡은 것이다.<br>병이 안에서부터 울기 시작했다. 옆 병이 받고, 그 옆 병이 받고. 방 전체가 보채는 아기들 방이 됐다. 그 울음이 바닥 틈으로 내려가기 전에 방을 떴다. 깊은 층의 어미가 받았을지는 생각 안 하기로 했다. 읽기는 멀리서. 숨이 닿는 거리는 읽는 거리가 아니다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'S1', t:'통풍구 — 숨 쉬는 길',
  x:`바람 관이 숨을 쉰다. 들이쉬고, 내쉬고. 시설 깊은 데서 큰 것이 숨 쉬는 대로 관 전체의 바람이 오간다.<br><br>
    내쉴 때 관을 타면 바람을 등에 업는다. 기던 길이 미끄럼이 된다.<br>
    들이쉴 때 관에 있으면 바람을 거슬러 긴다. 그리고 들이쉬는 숨은 깊은 데로 향한다. 모든 것이 빨려 드는 쪽으로.<br><br>
    숨의 길이를 재는 것이 먼저다. 날숨 몇 박, 들숨 몇 박.`,
  o:[
    { l:'① 관 어귀에서 숨의 박자를 재어 날숨에만 구간을 끊어 간다.', k:'sense', dc:25,
      ok:`관 어귀에 머리칼 한 올을 붙여 놓고 숨을 쟀다. 날숨 서른 박, 들숨 스무 박, 사이 다섯 박.<br><br>날숨 서른 박에 갈 수 있는 거리만큼씩 구간을 끊었다. 구간 끝은 늘 갈림 관, 들숨 동안 버틸 모퉁이가 있는 자리.<br>다섯이 날숨마다 미끄러지듯 가고 들숨마다 모퉁이에 박혀 버텼다. 바람이 등을 밀 때만 가는 길. 관을 다 나와 세어 보니 거리의 반을 바람이 업어다 줬다.`,
      ng:`숨의 박자를 쟀는데 숨이 박자를 바꿨다. 깊은 데 것이 잠에서 깬 것이다. 깬 숨은 빠르고 불규칙하다.<br><br>구간 복판에서 들숨이 예고 없이 왔다. 다섯이 관 바닥에 손톱을 박고 버텼다.<br>짐 하나가 손에서 뜯겨 관 깊은 쪽으로 날아갔다. 한참 뒤 아주 먼 데서 그 짐이 무언가에 닿는 소리가 났다. 씹히는 소리 같기도 했다. 잰 박자는 잠든 자의 박자다. 깨면 다시 잴 것. 숨은 산 것의 것이라 변한다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 날숨을 끝까지 타고 한 번에 관을 미끄러져 나간다.', k:'evade', dc:26,
      doom:{ title:'들이쉬는 관', what:'돌아온 들숨에 관 깊은 쪽으로 빨려 들어갑니다', dc:20, sec:35,
        text:`날숨 서른 박이면 관 끝까지 반이 남는다. 빠르게 미끄러지면 마흔 박 어치는 간다고 셈했다. 날숨 머리에 다섯이 몸을 던졌다.<br><br>서른 박에 관 끝이 안 보였다. 서른다섯 박. 바람이 죽었다. 사이 다섯 박.<br>그리고 들숨이 왔다. 관 전체가 목구멍이 됐다.<br><br>맨 뒤의 이쪽부터 바람이 끌었다. 손끝이 이음매에 걸렸다 미끄러진다. 깊은 쪽으로, 숨의 주인 쪽으로 빨려 들어간다. 앞에서 넷이 서로의 발목을 잡아 사람 사슬을 늘였지만 끝이 반 팔 모자랐다.`,
        dieText:`들숨이 끝나고 관은 아무 일 없이 다시 내쉬었다.<br><br>넷은 그 날숨을 타고 관을 나왔다. 나와서도 한참, 등 뒤의 관이 내쉴 때마다 넷은 돌아봤다. 그 바람에 무엇이 실려 올 것만 같아서.<br>숨을 타는 자는 숨의 주인을 섬기는 셈이다. 그 주인이 어떤 것인지 알기 전에는 타지 말 것. 관이 가르친 뱃사공의 법이다.` },
      ok:`날숨 머리에 몸을 던지되, 서른 박을 다 쓰지 않기로 미리 금을 그었다. 스물다섯 박째면 어디든 모퉁이를 잡는다.<br><br>미끄러지는 길이 달았다. 더 가고 싶은 스물다섯 박째, 셈대로 갈림 관 모퉁이에 다섯이 차례로 몸을 걸었다.<br>다섯 박 뒤 들숨이 왔다. 관이 목구멍처럼 당겼지만 모퉁이에 건 몸은 안 끌려갔다. 세 번을 끊어 관을 나왔다. 단 바람일수록 일찍 내린다. 뱃삯은 욕심 전에 치르는 것이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'에어록 — 두 문 사이의 덫',
  x:`쫓긴다. 긴 것 하나가 복도 셋째 모퉁이까지 붙었다. 앞에 에어록. 문 두 짝에 그 사이 좁은 방.<br><br>
    두 문이 다 닫히면 그 사이는 완전히 막힌 상자다. 기가 들고 날 틈도 없는.<br>
    진법가에게 막힌 상자는 완성된 진이다. 세우는 품이 들지 않는, 남이 지어 둔 뇌옥.<br><br>
    저것을 이 상자에 넣고 두 문을 닫으면 된다. 미끼는, 늘 그렇듯 사람이다.`,
  o:[
    { l:'① 내공을 실은 미끼 기운을 상자 안에 남기고 저것을 가둔다.', k:'fix', dc:26, cost:{ qi:38 }, wake:1,
      ok:`에어록 방 한가운데에 내공 한 덩이를 사람 꼴로 세워 두고 다섯은 안쪽 문으로 먼저 빠졌다. 문틈에 창대를 괴어 반만 닫고.<br><br>긴 것이 바깥 문으로 들이닥쳤다. 방 가운데 선 기운에게. 들어서는 순간 바깥 문의 괸 돌을 줄로 당겨 빼고, 안쪽 문의 창대도 걷었다. 두 문이 쿵, 쿵.<br>상자가 닫혔다. 안에서 내공 덩이가 흩어지는 기척, 그리고 빈 방을 깨달은 것이 문을 치는 소리. 쳐도 에어록 문이다. 시설이 지은 뇌옥에 시설의 것을 넣었다.<br><br>진을 세우지 않고 진을 썼다. 세상에 이미 서 있는 진이 얼마나 많은지, 갇힌 것의 문 두드리는 소리를 들으며 셌다. 다 셀 수 없었다.`,
      ng:`내공 덩이를 세우고 빠지는데 긴 것이 문턱에서 멈췄다. 콧김만 방 안에 들이밀고.<br><br>미끼 기운이 너무 반듯했던 것이다. 사람 기는 떨리는데 내공 덩이는 안 떨렸다.<br>저것이 미끼를 버리고 안쪽 문의 다섯을 쫓아왔다. 문을 닫는 손이 반 숨 빨랐기에 망정이지. 닫힌 문 너머의 긁는 소리를 들으며 배웠다. 미끼 기운에는 떨림까지 담을 것. 두려움 없는 미끼는 미끼가 아니다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 미끼 없이 이쪽 몸으로 상자를 지나며 문 두 개를 당긴다.', k:'steady', dc:26,
      ok:`몸이 미끼가 됐다. 혼자 에어록 방으로 들어가 바깥 문을 열어 둔 채 섰다. 긴 것이 보이는 자리에.<br><br>저것이 상자로 들이닥치는 순간 안쪽 문으로 몸을 던지며 넷이 밖에서 문을 당겼다. 쿵. 이쪽 발뒤꿈치가 문턱을 넘은 것과 문이 닫힌 것이 한 숨이었다.<br>바깥 문은 저것이 들어서며 제 꼬리로 쳐서 저절로 닫혔다. 덫이 덫 스스로 닫힌 셈. 상자 안에서 벽 치는 소리가 오래 났다. 다섯은 그 소리를 등지고 걸었다. 덫의 미끼를 몸으로 서는 것은 다시 안 하기로 했다. 효험은 있었다. 다시 안 할 뿐이다.`,
      ng:`몸으로 서는 셈까지는 섰는데 저것이 빨랐다. 상자에 들어서는 것과 이쪽 어깨를 치는 것이 같은 숨이었다.<br><br>문턱에 구르며 넘어졌다. 넷이 이쪽 다리를 끌어당기며 문을 닫았다. 문틈에 저것의 앞발이 끼었다 잘렸다.<br>어깨가 찢기고 문에는 발 하나가 남았다. 상자는 닫혔다. 안의 것이 발 하나 값을 치르고 산 세 든 셈. 몸미끼는 반 숨 싸움이다. 반 숨을 저울에 못 올리겠거든 내공을 올릴 것.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-34, mind:-14 } }
  ] },

{ at:'S1', t:'산성 웅덩이 — 죽은 돌 징검다리',
  x:`바닥이 웅덩이 밭이다. 저들끼리 싸운 자리인지, 피가 고여 쇠 바닥을 먹어 들어간 웅덩이가 수십.<br><br>
    마른 데를 밟아야 하는데 어둑해서 마른 데와 젖은 데가 안 갈린다.<br>
    기로는 갈린다. 산 기운이 도는 데는 피가 아직 산 데고, 기가 완전히 죽은 데는 피가 다 삭아 잠잠한 데다.<br><br>
    죽은 기만 밟는 징검다리. 거꾸로 된 셈이지만 여기서는 죽은 것이 안전하다.`,
  o:[
    { l:'① 기가 죽은 자리만 골라 징검다리 길을 그어 준다.', k:'sense', dc:25,
      ok:`손바닥을 바닥 가까이 쓸며 기가 잠잠한 자리를 짚었다. 죽은 기 하나, 둘, 셋. 징검돌 열여섯 개의 길이 그어졌다.<br><br>다섯이 그 돌만 밟아 건넜다. 발밑 반 뼘 옆에서 가끔 치익, 산 피가 쇠를 먹는 소리가 났지만 밟은 자리는 끝까지 잠잠했다.<br>다 건너고 돌아보니 밟아 온 길이 춤사위처럼 어지러웠다. 어지러운 길이 맞는 길일 때 어둠에서는 그게 보통이다.`,
      ng:`죽은 기만 짚는다고 짚었는데 하나가 반죽음이었다. 겉은 삭고 속은 산 웅덩이.<br><br>넷째가 밟자 삭은 껍질이 꺼지며 속엣것이 튀었다. 신발 옆구리에 한 방울.<br>넷째가 한 발로 뛰며 신발을 벗어 던졌다. 신발은 웅덩이 사이에서 연기가 됐다. 맨발 한 짝으로 남은 길을 업혀 건넜다. 반죽음은 죽음으로 세지 말 것. 기는 겉과 속을 따로 짚어야 한다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 선반 철판을 뜯어 웅덩이 위에 다리를 놓는다.', k:'luck', dc:25,
      ok:`기 읽기보다 굵은 수를 골랐다. 벽 선반의 긴 철판 두 장을 뜯어 번갈아 깔며 건너는 다리.<br><br>한 장을 딛고 다음 장을 앞에 깔고, 지난 장을 거둬 또 앞에. 자벌레 걸음.<br>철판 바닥이 서너 번 치익댔지만 뚫리기 전에 거둬 옮겼다. 다 건너고 철판을 보니 벌집처럼 얽었다. 하나는 버리고 성한 하나는 챙겼다. 이 시설에서 녹지 않은 철판은 보배다. 건넌 길에 찬장에서 밀봉된 물통도 하나 건졌다.`,
      ng:`철판을 뜯는 소리가 컸다. 끼이익. 빈 시설의 밤에 그만한 봉화가 없다.<br><br>반쯤 건넜을 때 복도 끝에서 긴 것이 왔다. 철판 다리는 빠른 길이 못 된다.<br>마지막 두 장은 깔기를 포기하고 죽은 기 자리를 어림짚어 뛰었다. 운이 받쳐 아무도 안 녹았다. 등 뒤에서 긴 것이 웅덩이 밭 앞에 멈춰 서성였다. 저것도 못 건너는 밭이었다. 그것 하나는 셈 밖의 소득이었다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S1', t:'여왕 — 거대한 진의 눈',
  x:`깊은 층 전체가 하나의 진이다. 내려서는 순간 알았다. 기가 복도마다 강처럼 흘러 한 점으로 모인다.<br><br>
    여왕. 저것이 진의 눈이다. 시설의 기, 병 속 것들의 기, 바닥을 기는 것들의 기가 다 저리로 흘러든다.<br>
    흐름을 거스르면 눈에 띈다. 강을 거슬러 오르는 고기가 눈에 띄듯.<br>
    흐름을 타면 눈 쪽으로 실려 간다.<br><br>
    남은 길은 하나. 흐름과 흐름 사이의 마른 틈을 걷는 것.`,
  o:[
    { l:'① 기의 강 사이 마른 틈을 읽어 다섯에게 걸음을 가르친다.', k:'fix', dc:26, wake:1,
      ok:`강과 강 사이에는 둑이 있다. 기가 안 흐르는 가는 틈. 그 틈을 눈으로 읽어 다섯에게 걸음마다 짚어 줬다. 여기서 두 걸음, 모로 한 걸음, 멈춤.<br><br>둑길은 좁고 구불거렸다. 반나절을 그렇게 걸었다. 흐름을 거스르지도 타지도 않는 다섯을, 눈은 끝까지 셈하지 못했다. 강만 보는 눈에 둑 위의 사람은 풍경이다.<br>승강 통로 앞에서 마지막 둑이 끝났다. 돌아보니 기의 강들이 어둠 속에서 여왕 쪽으로 번들거리며 흘렀다.<br><br>진 전체가 산 것인 진은 처음이다. 그 진 속을 걸어 지났다. 진법서 마지막 장 너머의 땅을 밟은 것이다. 거기도 길이 있었다. 둑이라는 길이.`,
      ng:`둑길을 짚는 눈이 반나절에 지쳤다. 한 걸음을 틀렸다. 넷째 발이 흐름에 반 뼘 담겼다.<br><br>강에 돌 던진 물결이 눈까지 갔다. 깊은 데서 여왕의 둥이 한 박 빨라졌다.<br>복도의 것들이 일제히 그 물결의 출처를 거슬러 왔다. 다섯이 둑길이고 뭐고 승강 통로까지 내리 뛰었다. 문을 닫고서야 둥이 다시 느려졌다. 둑길은 눈이 둘이어야 한다. 짚는 눈과 그 눈을 쉬게 할 눈. 다음부터 다섯째에게 반을 가르쳐 나눴다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 흐름을 가로질러 최단으로 승강 통로에 닿는다.', k:'hide', dc:26,
      doom:{ title:'강을 건너는 것', what:'기의 흐름에 실려 여왕의 눈앞으로 끌려갑니다', dc:20, sec:35,
        text:`둑길은 멀다. 흐름을 가로지르면 승강 통로까지 백 걸음. 몸을 낮추고 강을 건너기로 했다.<br><br>첫 강은 건넜다. 둘째 강 복판에서 알았다. 이 강은 물이 아니라 손이다. 흐르는 기가 발목을 감아 쥔다.<br>흐름이 빨라진다. 발이 바닥에서 미끄러진다. 선 채로, 걷지 않는데, 몸이 눈 쪽으로 실려 간다.<br><br>복도 끝 어둠에서 여왕의 머리가 이쪽으로 돌아 앉는 것이 보인다. 강이 사냥감을 배달하는 중이다. 눈앞까지. 뒤에서 넷이 창대를 뻗었지만 창대도 흐름에 쓸려 휜다.`,
        dieText:`흐름은 반 각 뒤에 제 속도로 돌아왔다. 강은 아무 일 없이 흘렀다.<br><br>넷은 둑길로 돌았다. 꼬박 하루가 걸렸다. 짚어 주는 눈 없이 넷이 번갈아 짚으며.<br>승강 통로에 닿았을 때 넷은 알았다. 먼 길이 먼 게 아니었다. 가까운 길이 가까운 게 아니었듯. 깊은 층의 거리는 걸음이 아니라 흐름이 잰다.` },
      ok:`흐름을 가로지르기 전에 돌 하나를 강에 던져 봤다. 돌이 바닥을 구르다, 흐름 복판에서 방향을 꺾어 눈 쪽으로 미끄러져 갔다. 구르는 돌을 끌고 가는 강.<br><br>가로지르기를 접었다. 저 강은 밟는 것을 나른다.<br>둑길로 돌았다. 멀었지만 발은 끝까지 이쪽 발이었다. 승강 통로에 닿아 돌아보니 던진 돌이 어둠 저쪽 눈 밑에 닿아 있을 시간이었다. 돌 하나가 대신 가 준 길이다. 돌에게 절할 뻔했다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'숙주 — 몸 안에 쳐진 진',
  x:`구조한 생존자의 맥을 짚다가 손이 멎었다. 기가 이상하게 돈다.<br><br>
    사람 기는 큰 줄기 하나로 돈다. 이 사람 기는 가슴께에서 작게 소용돌이친다. 나선으로, 안으로, 안으로.<br>
    진이다. 몸 안에 누가 진을 쳤다. 기를 가슴 한 점으로 모으는 진. 그 한 점에서 무엇이 모인 기를 받아먹고 있다.<br><br>
    먹고 자라는 중이다. 진법으로 기른다. 저들의 방식으로.`,
  o:[
    { l:'① 내공으로 가슴 위에 거꾸로 도는 진을 겹쳐 그린다.', k:'fix', dc:26, cost:{ qi:37 },
      ok:`안으로 도는 나선 위에, 재를 갠 물로 밖으로 도는 나선을 겹쳐 그리고 내공을 실었다. 두 소용돌이가 마주 돌면 물이 고요해지듯 기도 선다.<br><br>가슴의 소용돌이가 느려졌다. 모이던 기가 흩어져 제 줄기로 돌아간다. 젖줄 끊긴 안엣것이 사흘을 버티다 넷째 날 새벽 기침에 검불 같은 것으로 말라 나왔다.<br>그 사람은 가슴이 뚫린 듯 시원하다고 했다. 몸 안의 진을 몸 밖의 진으로 눌러 이긴 첫 싸움. 진과 진의 싸움은 돌지 않는 쪽이 진다. 사람 몸이 전장이라는 게 쓰렸을 뿐이다.`,
      ng:`거꾸로 도는 진을 겹치는데 안엣것이 제 진을 더 빨리 돌렸다. 겹친 진이 미처 서기 전에.<br><br>두 소용돌이가 마주 돌다 엉켰다. 그 사람이 가슴을 쥐고 꺾였다. 기가 엉킨 몸은 숨도 엉킨다.<br>겹친 진을 급히 지우고 반나절을 주물러 기를 풀었다. 안엣것의 진은 그대로다. 몸 안의 진은 몸이 상하면 같이 조여든다. 아는 사람 손에 닿을 때까지 거꾸로 진은 봉인했다. 겹치려거든 단숨에 완성할 것. 어설픈 겹침은 엉킴이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 나선이 모이는 한 점이 정확히 어디인지부터 응시한다.', k:'gaze', dc:25,
      ok:`맥을 짚은 채 나선의 끝점을 쫓았다. 가슴 복판이 아니다. 왼쪽 갈비 셋째 뼈 밑. 심장을 비껴 앉은 자리.<br><br>자리를 알면 싸울 판이 선다. 심장을 안 건드리고 지질 수 있는 자리, 뜸을 뜰 혈이 나왔다.<br>치유 아는 일행이 그 자리에 사흘 뜸을 떴다. 안엣것이 뜨거움을 못 견뎌 젖줄째 자리를 말았다. 진법가가 한 일은 점 하나 찍은 것뿐이다. 점 하나가 뜸 자리가 되고 뜸이 목숨이 됐다. 진법은 가끔 지도 그리는 일이다.`,
      ng:`끝점을 쫓는 응시가 길었다. 안엣것이 들여다보는 눈길을 느꼈다.<br><br>나선이 갑자기 풀렸다. 숨은 것이 몸을 옮기는 것이다. 가슴에서 어디로인지, 나선이 풀린 뒤에는 짚이지 않았다.<br>그날부터 그 사람 기는 멀쩡해 보였다. 멀쩡해 보이는 게 제일 불안했다. 아는 사람 손에 닿을 때까지 그 사람 곁에서 맥을 하루 세 번 짚었다. 숨은 적은 보이는 적보다 손이 많이 간다. 들여다볼 때는 들킬 셈까지 하고 볼 것.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'S2', t:'울타리 — 서른두 돌의 진',
  x:`정원 울타리를 한 바퀴 돌았다. 진법가 눈에는 울타리가 아니다. 기둥 서른둘이 박힌 거대한 진이다.<br><br>
    이 정원을 봉한 자들이 친 가둠의 진. 기둥마다 기가 심겨 있고 기둥끼리 기가 이어져 울을 이룬다.<br>
    그중 동쪽 아홉째 기둥의 기가 죽어 있다. 돌이 죽으면 그 변의 울이 종잇장이다.<br>
    저들이 밤마다 때리는 기둥이 바로 그 기둥인 것은, 우연이 아니다.<br><br>
    저들도 기가 죽은 돌을 아는 것이다.`,
  o:[
    { l:'① 내공을 부어 죽은 기둥의 기를 되살린다.', k:'fix', dc:26, cost:{ qi:38 }, wake:1,
      ok:`아홉째 기둥에 손을 얹고 내공을 부었다. 죽은 돌은 밑 빠진 독이라 붓는 족족 샜다. 새는 자리를 먼저 찾았다. 기둥 밑동의 금. 돌조각을 쐐기로 박아 금을 물리고 다시 부었다.<br><br>기가 고이기 시작했다. 반나절을 부어 기둥이 미지근해졌다. 양 옆 기둥과 기가 다시 이어지며 울이 닫혔다.<br>그 밤 저들이 와서 아홉째를 때렸다. 종잇장이던 변이 벽이 돼 있었다. 때리던 것들이 앞발을 털며 물러나 울타리를 다시 한 바퀴 돌았다. 죽은 돌을 찾아서. 없다. 서른둘이 다 살았다.<br><br>남이 친 진을 고쳐 살렸다. 친 자들은 없고 진만 남은 자리에서, 진은 고치는 자의 것이다. 이 정원의 울은 오늘부터 이쪽 진이다.`,
      ng:`내공을 붓는데 밑동의 금을 못 보고 부었다. 반나절 치 내공이 땅으로 다 샜다.<br><br>샌 기운이 땅을 타고 번졌는지, 그 밤 저들만 아니라 땅 밑에서도 무엇이 기둥 밑을 파기 시작했다.<br>위에서 때리고 밑에서 파는 기둥을 밤새 돌과 몸으로 지켰다. 새벽에야 둘 다 물러갔다. 독에 물을 붓기 전에 독부터 살필 것. 급한 마음이 반나절 치 내공을 땅에 묻었다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 서른두 기둥의 기를 다 짚어 다음에 죽을 돌을 미리 찾는다.', k:'sense', dc:25,
      ok:`아홉째만 문제가 아닐 수 있다. 서른둘을 다 짚었다. 산 돌 스물아홉, 비실대는 돌 둘, 죽은 돌 하나.<br><br>비실대는 둘은 서남쪽 나란한 이웃이었다. 다음 달이면 저 둘도 죽는다. 그러면 울 한 변이 통째로 열린다.<br>죽은 돌은 돌과 그물로 겹 보강하고, 비실대는 둘에는 번갈아 내공을 조금씩 부어 연명시켰다. 의원이 맥 보듯 울타리 맥을 본 하루. 정원의 밤이 그날부터 눈에 띄게 조용해졌다. 울은 한 돌이 아니라 서른두 돌이 지킨다. 다 짚어야 울이다.`,
      ng:`서른둘을 짚는 한 바퀴가 꼬박 하루였다. 그 하루 동안 울타리에 바짝 붙어 돈 것이 저들 눈에 다 보였다.<br><br>사람이 기둥을 만지고 다니는 것을 본 저들이 셈을 했다. 기둥이 중요하구나.<br>그 밤부터 저들이 기둥만 노려 때리기 시작했다. 아무 기둥이나. 울타리 순찰은 어스름에, 울 안쪽으로 붙어서 돌 것. 적 앞에서 소중한 것을 만지는 손은 지도를 그려 주는 손이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'S2', t:'수맥 — 물밑의 길',
  x:`잠긴 벌판 밑에는 수맥이 흐른다. 기가 실려 흐르는 물의 줄기. 발바닥으로 짚으면 물밑 어디가 깊고 어디가 둔덕인지 그려진다.<br><br>
    큰 줄기 하나와 가는 줄기 셋. 큰 것은 큰 줄기에 엎드려 있다. 몸집에 맞는 물이 큰 줄기뿐이라서.<br>
    가는 줄기 중 하나는 죽은 줄기다. 물이 말라 기만 남은 길.<br><br>
    죽은 줄기 위가 둔덕이다. 물이 얕고, 큰 것이 못 오는 길.`,
  o:[
    { l:'① 죽은 수맥 위 둔덕 길을 그려 다섯을 건넨다.', k:'fix', dc:26,
      ok:`발바닥으로 죽은 줄기를 짚으며 둔덕 길을 그렸다. 구불구불, 그러나 끝까지 무릎 물.<br><br>복판에서 큰 줄기 쪽 물이 한 번 크게 밀렸다. 큰 것이 돌아누운 것이다. 다섯이 둔덕에 엎드려 물결이 지나가길 기다렸다 마저 걸었다.<br>건너편 기슭에 닿아 뒤를 보니 지나온 둔덕 양옆이 다 시커먼 깊이였다. 그 사이 한 뼘 등줄기를 밟고 온 것이다. 물밑에도 길과 벼랑이 있다. 보이지 않을 뿐. 짚는 발바닥이 눈이다.`,
      ng:`죽은 줄기를 짚으며 가는데 비가 왔다. 마른 줄기에 물이 돌기 시작했다.<br><br>죽은 길이 살아나며 기가 흔들려 발바닥 지도가 지워졌다. 복판에서 길을 잃었다.<br>장대로 더듬어 가장 가까운 기슭으로 꺾었다. 가려던 데와 반대 기슭이었다. 벌판을 반 바퀴 돌아 하루를 더 썼다. 죽은 것을 길로 쓸 때는 되살아날 조건부터 셈할 것. 비 한 줄기가 지도를 지운다.`,
      win:{ exp:22, dream:3, item:'민물고기' }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 큰 줄기의 흐름으로 큰 것이 깬 때와 잠든 때를 가린다.', k:'sense', dc:25,
      ok:`큰 줄기의 기가 고요하면 저것이 잠든 때, 출렁이면 깬 때다. 기슭에 앉아 반나절 물밑 숨을 짚었다.<br><br>저것은 한낮에 깊이 잔다. 물이 데워지는 때.<br>이튿날 한낮, 큰 줄기가 제일 고요한 두 시진에 벌판을 건넜다. 복판에서 큰 줄기 바로 곁을 지날 때 물밑에서 집채만 한 등이 숨 쉬는 결이 발바닥에 닿았다. 자는 숨. 깨우지 않고 지났다. 호랑이 곁을 지나는 법은 호랑이의 낮잠 시간표다. 물밑이라고 다르지 않다.`,
      ng:`잠든 때를 골라 건너는데 복판에서 가는 줄기 하나가 갑자기 출렁였다. 큰 것 말고도 물밑에 사는 것이 있던 것이다.<br><br>작은 것들. 큰 줄기를 피해 가는 줄기에 사는 것들이 다섯 발을 간 봤다.<br>종아리를 두 번 물리고 물을 차며 건넜다. 물린 자리가 불에 덴 듯 부었다. 독은 아니었다. 큰 적의 시간표만 짚은 셈. 작은 적은 시간표도 없다. 물에서는 늘 발밑이 두 겹이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'세 점의 진 — 무리의 사냥진',
  x:`무리가 다섯을 몰기 시작했다. 셋이 세모꼴로 선다. 둘은 보이고 하나는 숨고.<br><br>
    진법가 눈에는 세모가 다 보인다. 숨은 놈의 기까지. 그리고 세모의 돌림이 보인다. 세 점이 돌면서 세모가 조금씩 조여든다.<br>
    이 진의 축은 숨은 놈이다. 보이는 둘은 축을 중심으로 도는 날개.<br><br>
    축이 꺾이면 세모는 못 돈다.`,
  o:[
    { l:'① 숨은 축의 자리를 짚어 다섯의 길을 축 위로 곧장 낸다.', k:'gaze', dc:26,
      ok:`숨은 놈의 기를 짚었다. 서남쪽 덤불, 세모의 축. 다섯의 길을 정확히 그 위로 냈다. 피하지 않고 마주.<br><br>축은 숨어서 축이다. 사냥감이 제게 곧장 걸어오면 숨은 보람이 없다. 덤불 앞 열 걸음에서 축이 못 참고 일어섰다.<br>일어선 축은 축이 아니다. 세모가 그 자리에서 풀렸다. 보이던 둘이 돌기를 멈추고 어정댔다. 다섯은 일어선 놈을 창 둘로 겨눈 채 그 곁을 당당히 지나갔다. 진은 축이 서야 돌고, 축은 숨어야 선다. 둘 다 못 하게 하면 진은 종이 그림이다.`,
      ng:`축이라 짚은 덤불이 비어 있었다. 기만 남기고 자리를 옮긴 것이다. 기를 벗어 두고 다니는 놈이라니.<br><br>빈 축을 향해 걷는 다섯의 등 뒤에서 진짜 축이 일어섰다.<br>세모가 뒤집힌 채 조여들었다. 창 다섯이 급히 송곳으로 뭉쳐 반 각을 버텼고, 저들은 조이다 말고 흩어졌다. 버리는 기로 눈을 속이는 짐승. 책에 적어 두고 두 번 다시 안 속기로 했다. 적는 것 말고는 분이 안 풀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 보이는 날개 둘 중 하나를 창으로 받아쳐 세모를 찢는다.', k:'break', dc:26,
      doom:{ title:'세 점의 셈', what:'찢긴 줄 알았던 세모에 접혀 숨은 축에게 끌려갑니다', dc:20, sec:36,
        text:`날개 하나를 꺾으면 세모가 못 돈다. 가까운 왼쪽 날개에게 창 셋이 달려들었다.<br><br>날개가 물러난다. 쫓는다. 찢었다고 셈한 순간, 물러나던 날개가 반원을 그리며 돈다.<br>유인이었다. 세모는 안 찢어졌다. 돌면서 벌어졌다 닫히는 중이었다. 쫓느라 앞으로 쏠린 이쪽과 남은 넷 사이가 벌어졌고, 그 틈 뒤에서 숨은 축이 일어선다.<br><br>발목에 턱이 감긴다. 덤불로 끌려 들어간다. 세모의 세 점이 그제야 다 보인다. 끌려가는 눈에만 보이는 각도다.`,
        dieText:`넷은 송곳으로 뭉쳐 덤불까지 창을 밀었지만 세모는 셋이 번갈아 막으며 깊이 물러났다.<br><br>해가 지고 넷은 물러났다. 물러나며 넷째가 외운 것을 읊었다. 축이 꺾이면 세모는 못 돈다.<br>맞는 말이었다. 다만 날개는 축이 아니었다. 그 한 줄을 마저 배우는 값이 사람이었다. 넷이 치는 진에는 그 뒤로 쫓는 자리가 없다. 어떤 진에도.` },
      ok:`날개 하나를 꺾으러 달리다 다섯 걸음에 멈췄다. 날개가 너무 순순히 물러났다. 물러나는 적은 끄는 적이다.<br><br>쫓는 대신 그 자리에 송곳 진으로 섰다. 세모가 닫히려다 닫을 것이 없어 어정쩡하게 벌어졌다.<br>벌어진 세모의 한 변으로 다섯이 천천히 빠져나왔다. 뒤에서 숨은 축이 덤불에서 반쯤 일어나 이쪽을 오래 봤다. 쫓지 않은 사냥감을 처음 보는 눈이었다. 쫓게 만드는 것이 저들 진의 전부다. 안 쫓으면 진은 반이 꺼진다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'양치밭 — 바람 없는 흔들림',
  x:`어깨 높이 양치가 벌판 끝까지 깔렸다. 바람이 불면 다 같이 눕고 일어선다.<br><br>
    기를 보는 눈에는 잎의 흔들림이 다 자국이다. 바람의 자국은 넓고 고르게, 산 것의 자국은 좁고 길게 남는다.<br>
    지금 벌판에 좁고 긴 자국이 둘 흐른다. 하나는 왼쪽에서 오른쪽으로. 하나는 다섯 쪽으로.<br><br>
    다섯 쪽으로 오는 자국이 바람 자국처럼 넓게 퍼지려 애쓰고 있다. 흉내다.`,
  o:[
    { l:'① 흉내 자국의 결을 짚어 저것의 머리가 어디인지 겨눈다.', k:'sense', dc:26,
      ok:`바람 흉내 자국도 머리 쪽은 좁다. 몸이 지나는 자리는 어쩔 수 없으니. 퍼지는 자국의 좁은 꼭지를 짚었다. 서른 걸음, 스물여덟.<br><br>창 다섯이 소리 없이 그 꼭지에 겨눠졌다. 스무 걸음에서 자국이 뚝 멈췄다.<br>저도 안 것이다. 겨눠진 것을. 흉내 자국이 한참 멈춰 있다가 왔던 결 그대로 물러갔다. 바람 흉내를 내며 물러가는 뒷모습은 바람 흉내가 하나도 안 됐다. 들킨 흉내만큼 어색한 것이 없다.`,
      ng:`꼭지를 짚는 사이 두 번째 자국을 잊고 있었다. 왼쪽에서 오른쪽으로 흐르던 것.<br><br>그것이 어느새 결을 꺾어 뒤로 돌아 있었다. 둘이 한 벌이었던 것이다. 한 놈이 눈을 잡고 한 놈이 등을 도는.<br>등 뒤 양치가 터지며 덮쳐 왔다. 구르고 찌르고 엉킨 끝에 쫓았다. 자국 둘이 보이면 둘 다 끝까지 셀 것. 눈은 하나고 자국은 둘일 때, 못 세는 쪽이 등이 된다.`,
      win:{ exp:20, dream:3, item:'산나물' }, lose:{ hp:-30, mind:-16 } },
    { l:'② 다섯이 양치 밑에 엎드려 바람 자국만 남을 때까지 기다린다.', k:'hide', dc:25,
      ok:`움직이면 자국이 남는다. 다섯이 양치 밑에 엎드려 돌이 됐다.<br><br>흉내 자국이 다섯이 사라진 자리를 반 시진 헤집었다. 잎 밑에 엎드린 것들의 숨까지는 잎이 가려 줬다.<br>저것이 포기하고 왼쪽 자국과 만나 벌판 끝으로 흘러간 뒤에야 일어났다. 등과 무릎이 다 젖었지만 자국 없는 반 시진이 길을 열었다. 벌판에서는 가끔 돌이 제일 빠르다.`,
      ng:`엎드린 자리가 하필 물이 고인 움푹이었다. 반 시진에 몸이 반쯤 잠겼다.<br><br>젖은 몸은 일어날 때 소리가 난다. 철벅. 흉내 자국이 멀리서 그 소리에 꺾여 돌아왔다.<br>젖은 몸으로 벌판 끝까지 내달렸다. 양치 잎이 얼굴을 수십 번 그었다. 엎드릴 자리도 골라서 엎드릴 것. 숨는 일의 반은 일어날 때를 위한 준비다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S2', t:'둥지 — 품는 나선',
  x:`알 둥지를 지나야 한다. 돌아가는 길은 큰 것의 물가뿐이니 선택이 없다.<br><br>
    둥지가 눈에 들어온 순간 소름이 돋았다. 알들이 아무렇게나 놓인 게 아니다. 나선이다. 안으로 감기는 품의 진.<br>
    어미가 본능으로 친 진이다. 나선을 따라 기가 안으로 돌며 알들을 덥힌다.<br>
    나선 안쪽으로 드는 모든 것은 품 안에 든 것으로 셈해진다. 알이든, 먹이든.<br><br>
    나선의 바깥 가장자리, 기가 밖으로 미끄러지는 한 줄만이 길이다.`,
  o:[
    { l:'① 나선의 바깥 결을 따라 미끄러지듯 둥지를 돈다.', k:'fix', dc:26,
      ok:`나선의 결을 읽었다. 안으로 감기는 결과 그 바깥에서 밖으로 밀려나는 결. 바깥 결에 다섯을 태웠다.<br><br>걸음이 이상하게 가벼웠다. 진이 미는 결이라 걷는 게 아니라 흘러가는 셈이다.<br>어미가 둥지 가운데서 한 번 고개를 들었다. 품의 진 안은 고요한데 바깥 결에 무엇이 흐르는 것은, 어미 셈에 바람이다. 품 밖은 어미의 눈 밖이다. 다섯이 바람으로 둥지를 반 바퀴 돌아 빠졌다. 품는 진은 품 안만 지킨다. 그 바깥은 진이 스스로 밀어내 주는 길이다.`,
      ng:`바깥 결을 타다 넷째 발이 안쪽 결에 반 발 걸렸다. 결과 결의 금은 눈에 안 보이니까.<br><br>안으로 감기는 기가 넷째를 반 걸음 끌어들였다. 품 안에 든 것이다.<br>어미의 고개가 바로 돌았다. 품 안의 낯선 것은 바람이 아니다. 넷이 넷째의 멜빵을 잡아 바깥 결로 뜯어내듯 당겼고, 다섯이 흐르는 결을 타고 내달렸다. 어미는 품 가장자리까지만 쫓고 멈췄다. 품을 못 비우는 것이 어미다. 그것 하나에 기대 산 하루였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 어미가 둥지를 비우는 사냥 때를 노려 가운데를 가로지른다.', k:'luck', dc:26,
      doom:{ title:'품 안의 셈', what:'돌아온 어미에게 물려 둥지 한가운데로 끌려갑니다', dc:20, sec:35,
        text:`어미가 사냥을 나갔다. 둥지가 비었다. 나선이고 뭐고 가운데를 질러가면 쉰 걸음이다.<br><br>복판에 들었을 때 알았다. 빈 둥지가 빈 게 아니다. 품의 진이 돌고 있다. 어미 없이도.<br>진이 다섯을 셌다. 품 안에 든 다섯 덩이의 온기. 알이 아닌 것들.<br>그리고 진이 어미를 불렀다. 기가 밖으로 길게 우는 것을 발바닥으로 느꼈다. 수풀이 갈라지며 어미가 돌아온다. 사냥을 끊고. 맨 뒤의 이쪽 허리를 턱이 감는다. 둥지 한가운데로, 알들 곁으로 끌려간다. 품 안의 낯선 것은 두 가지로 셈해진다. 알이거나, 알들의 끼니거나.`,
        dieText:`넷은 바깥 결을 타고 빠졌다. 진법가가 길이라 했던 그 결이었다. 그 말대로 미끄러지듯 둥지 밖까지 흘러 나왔다.<br><br>둥지 가운데서는 그날 밤 알들이 유난히 따뜻했을 것이다.<br>넷은 그 뒤로 빈 집을 안 믿는다. 주인이 없어도 진은 돈다. 집 자체가 주인의 반이라는 것. 가운데를 지르자던 사람이 바깥 결만 남기고 간 가르침이다.` },
      ok:`어미가 사냥을 나갔다. 가운데를 지르면 쉰 걸음. 발을 들이기 전에 돌 하나를 복판에 던져 봤다.<br><br>돌이 떨어진 자리의 기가 출렁, 하고 밖으로 길게 울었다. 빈 둥지의 진이 돌며 어미를 부르는 소리.<br>지르기를 접고 바깥 결로 돌았다. 반 바퀴를 돌아 나올 즈음 어미가 사냥을 끊고 돌아왔다. 돌 하나 때문에. 복판에 든 것이 다섯이었으면 어미는 끼니를 끊고 온 보람이 있었을 것이다. 돌은 보람이 없어 다행이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'승강로 — 진의 축을 타고 오르다',
  x:`낡은 승강기의 승강로는 정원 가둠 진의 축이다. 올라서 보니 알겠다. 서른두 기둥의 기가 다 이 수직 통로로 모여 위로 흐른다.<br><br>
    축을 타고 오르는 것은 진의 등뼈를 밟는 일이다. 바구니가 오르는 동안 축이 흔들리면 울 전체가 흔들린다.<br>
    울이 흔들리는 밤, 저들은 울이 약해진 것을 안다.<br><br>
    오르되, 축을 흔들지 않고 오르는 법.`,
  o:[
    { l:'① 내공으로 바구니의 기를 축의 흐름에 포개 소리 없이 오른다.', k:'fix', dc:26, cost:{ qi:36 }, wake:1,
      ok:`바구니에 손을 얹고 내공을 흘려 바구니의 기를 축의 흐름과 같은 결로 맞췄다. 흐름 속을 흐름의 빠르기로 오르는 것은 흐름을 안 흔든다.<br><br>도르래 소리는 어쩔 수 없지만 기의 축은 끝까지 고요했다. 울은 그 밤 한 치도 안 약해졌다.<br>두 번째 바구니가 턱을 넘고 정원을 내려다봤다. 서른두 기둥의 기가 발밑에서 수레바퀴 살처럼 모여 돌고 있었다. 그 바퀴의 굴대를 타고 나온 것이다.<br><br>진의 축은 건드리면 안 되는 것인 줄 알았다. 결을 맞추면 탈 수 있다. 진과 싸우지 않고 진에 올라타는 법. 이 정원이 마지막으로 가르쳐 준 수였다.`,
      ng:`결을 맞춘다고 맞췄는데 첫 바구니가 중간 턱에 걸리며 축이 한 번 크게 울렸다.<br><br>울이 출렁이는 것이 위에서도 보였다. 서른두 기둥의 기가 물결처럼 일렁이고, 그 일렁임을 저들이 못 알아볼 리 없다.<br>그 밤 울타리가 네 군데서 시험당했다. 울은 버텼다. 간신히. 축을 타는 수는 맞되 바구니 길부터 손볼 것. 결은 기계가 먼저 어긋낸다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 축이 울리든 말든 속도를 골라 단숨에 두 번으로 오른다.', k:'steady', dc:25,
      ok:`결 맞출 내공이 아까웠다. 대신 속도를 샀다. 셋, 둘, 두 번을 쉼 없이 감아올렸다.<br><br>축이 울렸다. 정원의 울이 출렁이는 게 위에서 보였다. 저들이 울타리로 몰려가는 것도.<br>다만 저들이 약해진 울을 시험하고 뚫을 즈음, 다섯은 이미 턱 위였다. 울이 약해진 정원에 남은 것은 빈 숙영지뿐이다. 뒤는 미안하지만 정원의 일이다. 올라와서 한참, 아무도 그 말에 웃지 않았다. 사실이라서.`,
      ng:`속도를 고르다 둘째 바구니 차례에 도르래가 말썽을 부렸다. 축이 두 번, 세 번 울렸다.<br><br>울이 크게 출렁였고 저들이 몰렸다. 울타리가 아니라 승강기 밑으로. 약해진 데가 어딘지 저들이 더 정확히 안 것이다.<br>마지막 바구니가 발톱 세 개를 바닥 널에 꽂은 채로 턱을 넘었다. 널을 뚫고 올라온 발톱 끝이 신발 바닥에 닿아 있었다. 축은 몇 번을 울리면 저들에게 주소가 된다. 두 번까지는 소리, 세 번부터는 주소.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S2', t:'밤 — 땅이 흔들리는 시간의 진',
  x:`정원에서의 마지막 밤, 큰 것이 숙영지 쪽 물가로 온다. 옮길 시간은 없다. 지나가기를 바라는 수뿐이다.<br><br>
    집채만 한 것이 곁을 지나면 땅이 뛰고, 뛰는 땅 위의 다섯 기가 다 흐트러진다. 흐트러진 기는 비명과 같다. 기를 보는 밤 것들에게는.<br>
    큰 것이 지나가는 반 각 동안 다섯 기를 한 덩이로 눌러 둬야 한다.<br><br>
    다섯 숨을 돌리는 진. 이 어둠에 들어온 첫날 배운 그 진이, 마지막 밤의 답이다.`,
  o:[
    { l:'① 내공을 실어 다섯 숨을 한 바퀴로 돌리고 땅울림을 넘긴다.', k:'fix', dc:26, cost:{ qi:35 },
      ok:`다섯이 손을 잡고 둥글게 앉았다. 내공을 한 바퀴 돌렸다. 들이쉬고, 내쉬고. 다섯 숨이 한 숨이 됐다.<br><br>큰 것이 왔다. 땅이 뛰었다. 몸이 들썩이고 이가 부딪혔다. 그래도 숨의 바퀴는 안 끊겼다. 바퀴 속에서 다섯 기는 한 덩이 바위였다.<br>발 하나가 숙영지 돌담 밖 세 걸음을 밟고 지나갔다. 물가에서 물 마시는 소리가 반 각. 그리고 멀어지는 땅울림.<br>바퀴를 풀자 다섯이 서로의 손을 보고 있었다. 하얗게 쥔 채 펴지지 않는 손들을. 첫날 배운 진이 마지막 밤을 건넜다. 진은 돌고 돌아 제자리로 온다. 사람도.`,
      ng:`숨의 바퀴를 돌리는데 땅이 셈보다 크게 뛰었다. 넷째와 다섯째의 잡은 손이 떨어졌다.<br><br>바퀴가 끊긴 자리로 다섯 기가 한꺼번에 샜다. 비명 다섯이 어둠에 울린 셈.<br>큰 것은 그냥 지나갔지만, 그 비명을 들은 밤 것들이 새벽까지 숙영지 둘레를 돌았다. 창을 쥔 채로 밤을 샜다. 바퀴를 돌릴 때는 손이 아니라 손목을 맞잡을 것. 떨어지는 손은 있어도 떨어지는 손목은 없다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 진 없이 다섯을 돌담 밑에 포개 엎드리게 하고 버틴다.', k:'steady', dc:25,
      ok:`진을 돌릴 내공이 바닥이었다. 몸으로 버티는 수. 돌담 제일 두꺼운 밑에 다섯을 포개 엎드리게 했다.<br><br>땅이 뛰는 반 각 동안 포갠 몸들이 서로의 떨림을 눌렀다. 혼자 떨면 비명이 되는 기도, 다섯이 포개 떨면 그냥 땅울림에 섞인다.<br>큰 것이 지나가고, 다들 한참을 그대로 포개 있었다. 아무도 먼저 일어나자고 안 했다. 포개진 무게가 그 밤엔 이불이었다.`,
      ng:`돌담 밑에 포갰는데 돌담이 땅울림을 못 버텼다. 위쪽 돌 두 개가 굴렀다.<br><br>구른 돌이 맨 위에 엎드린 이쪽 등을 쳤다. 신음을 삼켰지만 반쯤 샜다.<br>샌 소리를 들은 것이 있었는지 새벽에 돌담 밖 발자국이 평소보다 가까웠다. 등의 멍은 보름을 갔다. 몸으로 버틸 때도 머리 위부터 셈할 것. 땅이 뛰면 쌓인 것은 다 떨어진다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-30, mind:-14 } }
  ] }

]);
